INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 1, '(가) 시대의 생활 모습으로 옳은 것은?', 1, '소를 이용한 깊이갈이가 일반화되었다.', '주로 동굴이나 강가의 막집에서 살았다.', '반달 돌칼을 사용하여 곡식을 수확하였다.', '실을 뽑기 위해 가락바퀴를 처음 사용하였다.', '주먹도끼, 찍개 등의 뗀석기를 만들기 시작하였다.', 3, '김해 구산동의 무게 350톤 규모의 초대형 고인돌에서 매장 주체부가 발굴되어 무덤으로 확인되었습니다. 이 고인돌은 그 규모와 출토 유물을 통해서 사유 재산과 계급이 발생한 (가) 시대의 모습을 살펴볼 수 있는 중요한 유적으로 평가되고 있습니다.', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 2, '밑줄 그은 ''이 나라''에 대한 설명으로 옳은 것은?', 1, '백제와 연합하여 금성을 공격하였다.', '마립간이라는 왕의 칭호를 사용하였다.', '빈민을 구제하기 위해 진대법을 실시하였다.', '목지국을 압도하고 지역의 맹주로 발돋움하였다.', '살인, 절도 등의 죄를 다스리는 범금 8조가 있었다.', 5, '(한국사 묻고 답하기) 질문: 개천절에 대해 알려 주세요. 답변: 단군왕검이 우리 역사상 최초의 국가인 이 나라를 건국한 것을 기리는 뜻으로 제정된 국경일입니다. 1909년에 대종교에서 개천일로 이름 짓고 기념한 것에서 유래되었습니다. 매년 10월 3일에는 마니산 참성단에서 이 나라의 건국을 기념하는 행사가 거행됩니다.', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 3, '(가), (나) 나라에 대한 설명으로 옳은 것은?', 2, '(가) - 낙랑과 왜에 철을 수출하였다.', '(가) - 서옥제라는 혼인 풍습이 있었다.', '(나) - 연의 장수 진개의 공격을 받았다.', '(나) - 가(加)들이 별도로 사출도를 다스렸다.', '(가), (나) - 골품에 따라 관등 승진에 제한이 있었다.', 2, '(가) 그 나라에는 왕이 있고, 벼슬로는 상가·대로·패자·고추가·주부·우태·승·사자·조의·선인이 있으며, 신분의 높고 낮음에 따라 각각 등급을 두었다. …… 10월에 지내는 제천 행사는 국중대회로 이름하여 동맹이라 한다. - 『삼국지』 동이전 -
(나) 그 나라의 풍속은 산천을 중요시하여 산과 내마다 각기 구분이 있어 함부로 들어가지 않는다. …… 해마다 10월이면 하늘에 제사를 지내는데, 주야로 술을 마시고 노래를 부르며 춤추니 이를 무천이라 한다. 또 호랑이를 신으로 여겨 제사를 지낸다. - 『삼국지』 동이전 -', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 5, '(가) 왕의 업적으로 옳은 것은?', 2, '익산에 미륵사를 창건하였다.', '사비로 천도하고 국호를 남부여로 고쳤다.', '지방에 22담로를 두어 왕족을 파견하였다.', '평양성을 공격하여 고국원왕을 전사시켰다.', '동진에서 온 마라난타를 통해 불교를 수용하였다.', 3, '이 동상은 여러 번 고구려를 격파하여 다시 강국이 되었다는 내용의 국서를 양나라에 보내는 (가) 의 모습을 형상화한 것입니다. 또한 동상 앞 석상은 중국 남조의 영향을 받아 벽돌로 축조한 (가) 의 무덤에서 출토된 진묘수 모형입니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 6, '(가) 인물에 대한 설명으로 옳은 것은?', 3, '유식의 교의를 담은 해심밀경소를 저술하였다.', '외교 문서 작성에 능하여 청방인문표를 작성하였다.', '한자의 음훈을 빌려 우리말을 표기한 이두를 정리하였다.', '신라 말의 사회상을 보여주는 해인사 묘길상탑기를 남겼다.', '종파 간의 사상적 대립을 해소하기 위해 십문화쟁론을 지었다.', 4, '(대한민국 방방곡곡 - 함양 상림) 이번에 소개할 곳은 함양 상림입니다. 이 숲은 당에서 귀국한 (가) 이/가 천령군(현 함양군) 태수로 부임하였을 때 홍수 피해를 막기 위해 조성하였다고 합니다. 백성들의 삶을 직접 살펴본 (가) 은/는 개혁 방안을 담은 시무책 10여 조를 진성 여왕에게 올렸습니다.', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 7, '(가)~(다)를 일어난 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (나) - (가)', 1, '(가) 백제의 장군 윤충이 군사를 거느리고 대야성을 공격하여 함락하였다. 이때 도독인 이찬 품석과 사지(舍知) 죽죽, 용석 등이 죽었다.
(나) 신라와 당의 군사들이 의자왕의 도성을 에워싸기 위하여 소부리 벌판으로 나아갔다. 소정방이 꺼리는 바가 있어 전진하지 않자 김유신이 그를 달래어 두 나라의 군사가 용감하게 네 길로 일제히 떨쳐 일어났다.
(다) 흑치상지가 도망하여 흩어진 무리들을 모으니, 열흘 사이에 따르는 자가 3만여 명이었다. …… 흑치상지가 별부장 사타상여를 데리고 험준한 곳에 웅거하여 복신과 호응하였다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 8, '다음 정책을 실시한 왕의 재위 시기에 있었던 사실로 옳은 것은?', 2, '금관가야가 멸망하였다.', '이사부가 우산국을 복속하였다.', '조세를 관장하는 품주가 설치되었다.', '관료전이 지급되고 녹읍이 폐지되었다.', '인재 등용을 위한 독서삼품과가 실시되었다.', 4, '○ 완산주를 다시 설치하고 용원을 총관으로 삼았다. 거열주를 나누어 청주(菁州)를 두니 처음으로 9주가 되었다. 대아찬 복세를 총관으로 삼았다.
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 9, '다음 제도를 운영한 국가에 대한 설명으로 옳은 것은?', 2, '교육 기관으로 주자감을 두었다.', '신라에 침입한 왜구를 격퇴하였다.', '9서당 10정의 군사 조직을 갖추었다.', '개국, 태창이라는 연호를 사용하였다.', '왕족인 부여씨와 8성의 귀족이 지배층을 이루었다.', 1, '[그 나라의] 관제에는 선조성이 있는데, 좌상·좌평장사·시중·좌상시·간의가 소속되어 있다. 중대성에는 우상·우평장사·내사·조고사인이 소속되어 있다. 정당성에는 대내상 1명을 좌·우상의 위에 두었고, 좌·우사정 각 1명을 좌·우평장사의 아래에 배치하였다. - 『신당서』 -', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 10, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '공산 전투에서 고려군을 크게 무찔렀다.', '귀순한 김순식에게 왕씨 성을 하사하였다.', '폐정 개혁을 목표로 정치도감을 설치하였다.', '청해진을 근거지로 해상 무역을 전개하였다.', '광평성을 설치하고 광치나, 서사 등의 관원을 두었다.', 1, '(VR 전시관: 연호 정개(正開)가 새겨진 편운화상 승탑) 전북 남원 실상사 조계암터에 있는 이 승탑에는 ''정개 10년 경오(正開十年庚午)''가 새겨져 있어 건립 연도를 알 수 있다. ''정개''는 백제의 원한을 풀겠다고 선언하며 완산주에 나라를 세운 (가) 이/가 사용한 연호이다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 11, '다음 자료의 상황이 나타난 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 4, '행영병마별감 승선 최항정과 병마사 이부상서 문관이 여진 추장 거위 등에게 타일러 말하기를, "너희가 9성의 반환을 요청했으니 마땅히 이전에 했던 약속처럼 하늘에 대해 맹세하라."라고 하였다. 추장 등은 함주 성문의 밖에 단을 설치하고 하늘에 맹세하기를, "지금 이후 대대손손 악한 마음을 품지 않고 해마다 조공을 바칠 것입니다. 이 맹세에 변함이 있으면 우리 나라[蕃土]는 멸망할 것입니다."라고 하였다. …… 최홍정 등은 길주부터 시작하여 차례로 9성의 전투 장비와 군량을 내지(內地)로 들여왔다. - 『고려사』 -
(연표) 광군사 설치(947) - 귀주 대첩(1019) - 천리장성 완공(1044) - 별무반 편성(1104) - 이자겸의 난(1126) - 조위총의 난(1174). (가)=947~1019, (나)=1019~1044, (다)=1044~1104, (라)=1104~1126, (마)=1126~1174.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 12, '밑줄 그은 ''이 왕''의 재위 시기에 있었던 사실로 옳은 것은?', 2, '12목에 지방관이 파견되었다.', '쌍기의 건의로 과거제가 시행되었다.', '대장도감에서 팔만대장경이 간행되었다.', '안우, 이방실 등이 홍건적을 격파하였다.', '신돈이 전민변정도감의 책임자가 되었다.', 2, '안성 망이산성에 ''준풍 4년(峻豊四年)''이라는 글씨가 새겨진 기와가 발견되었습니다. 준풍이라는 연호를 사용하였던 이 왕은 백관의 공복을 정하고 개경을 황도로 명명하는 등 국왕 중심의 통치 체제 확립을 도모하였습니다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 13, '다음 상황이 나타난 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 1, '백동화를 주조하는 전환국의 기술자', '신해통공 시행 소식에 기뻐하는 난전 상인', '불법적인 상행위를 감독하는 경시서의 관리', '담배, 인삼 등의 상품 작물을 재배하는 농민', '물주로부터 자금을 조달받아 광산을 운영하는 덕대', 3, '왕이 명을 내리기를, "양계와 5도의 진병법석(鎭兵法席)에 사용되는 비용은 모두 백성들에게서 나오는 것이다. 이것은 부처를 섬기고 하늘을 속이는 것이니 무슨 복이 있겠는가?"라고 하였다. 이에 중사(中使)를 파견하여 내고(內庫)의 은병 300개를 내어서 여러 도에 나누어 주었다. (진병법석: 병화(兵禍)를 물리치기 위해 거행한 불교 의식)', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 14, '다음 자료에 나타난 상황 이후에 전개된 사실로 옳은 것은?', 2, '김윤후가 처인성에서 몽골군을 격퇴하였다.', '묘청이 칭제 건원과 금국 정벌을 주장하였다.', '김방경의 군대가 탐라에서 삼별초를 진압하였다.', '최충헌이 봉사 10조를 올려 시정 개혁을 건의하였다.', '경대승이 정중부 등을 제거하고 권력을 장악하였다.', 3, '지원(至元) 7년, 원종이 강화에서 송경(松京)으로 환도할 적에 장군 홍문계 등이 나라를 그르친 권신 임유무를 죽이고 왕이 정권을 되찾을 수 있도록 하였다. 권신의 가병, 신의군 등의 부대가 승화후(承化侯)를 옹립하고 반역을 도모하면서, 미처 강화를 떠나지 못한 신료와 군사들을 강제로 이끌고 남쪽으로 항해하여 가니 배의 행렬이 길게 이어졌다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 16, '밑줄 그은 ''방안''에 해당하는 내용으로 옳은 것은?', 2, '양현고를 두어 장학 기금을 마련하였다.', '서원을 세워 후진 양성과 선현 제향에 힘썼다.', '초계문신제를 시행하여 문신들을 재교육하였다.', '만권당을 설립하여 원의 학자들과 교류하게 하였다.', '경당을 설치하여 청소년에게 글과 활쏘기를 가르쳤다.', 1, '(역사 신문) 정부, 관학 진흥에 힘쓰다. 최충이 세운 문헌공도를 비롯한 사학 12도에 학생이 몰려들어 사학이 크게 융성하고 있다. 이러한 상황에서 국자감 운영에 어려움을 겪게 되자, 정부는 제술업, 명경업 등에 새로 응시하려는 사람은 국자감에 300일 이상 출석해야 한다는 규정을 만드는 등 관학을 진흥하기 위한 방안을 마련하고 있다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 17, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '과전을 혁파하고 직전을 설치하였다.', '최무선의 건의로 화통도감을 두었다.', '어영청을 중심으로 북벌을 추진하였다.', '왕권 강화를 위해 6조 직계제를 실시하였다.', '궁중 음악을 집대성한 악학궤범을 편찬하였다.', 4, '이것은 마천목을 좌명공신에 봉한다는 녹권입니다. 마천목은 제2차 왕자의 난 당시 회안군 이방간과의 치열한 전투에서 (가) 이/가 승리할 수 있도록 앞장섰습니다. 이후 왕위에 오른 (가) 은/는 마천목을 3등 공신으로 책봉하였습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 18, '(가) 사건에 대한 설명으로 옳은 것은?', 2, '계유정난의 배경이 되었다.', '조의제문이 발단이 되어 일어났다.', '반정 공신의 위훈 삭제를 주장하였다.', '윤임 일파가 제거되는 결과를 가져왔다.', '동인이 남인과 북인으로 나뉘는 계기가 되었다.', 2, '김종직의 자는 계온이고 호는 점필재이며, 김숙자의 아들로 선산 사람이다. …… 효행이 있고 문장이 고결하여 당시 유학자의 으뜸으로 추앙받았는데, 후학들에게 학문을 장려하여 많은 사람이 학문을 성취하였다. 후학 중에 김굉필과 정여창 같은 이는 도학으로 명성이 있었고, 김일손, 유호인 등은 문장으로 이름을 알렸으며 그 밖에도 명성을 얻은 이가 매우 많았다. 연산군 때 유자광, 이극돈 등이 주도한 (가) 이/가 일어났을 당시 김종직은 이미 세상을 떠났지만, 화가 그의 무덤까지 미치어 부관참시를 당하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 19, '(가) 기구에 대한 설명으로 옳은 것은?', 2, '주세붕이 처음 설립하였다.', '좌수와 별감을 선발하여 운영하였다.', '중앙에서 교수와 훈도를 파견하였다.', '대성전을 세워 성현에 제사를 지냈다.', '흥선 대원군에 의해 대부분 철폐되었다.', 2, '○ 각 지역 출신 가운데 서울에 살며 벼슬하는 자들의 모임을 경재소라고 합니다. 경재소에서는 고향에 사는 유력자 중에서 강직하고 명석한 자들을 선택하여 (가) 에 두고 향리의 범법 행위를 규찰하고 풍속을 유지하였습니다.
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 21, '밑줄 그은 ''이 전쟁'' 중에 있었던 사실로 옳은 것은?', 2, '훈련도감이 설치되었다.', '외규장각 도서가 약탈되었다.', '곽재우가 의령에서 의병을 일으켰다.', '강홍립이 이끄는 부대가 참전하였다.', '김준룡이 광교산 전투에서 승리하였다.', 5, '이 비각에는 홍명구 충렬비와 유림 대첩비가 나란히 세워져 있습니다. 홍명구와 유림은 이 전쟁 당시 남한산성에 피란해 있던 국왕을 구하기 위해 근왕병을 이끌고 김화에서 적을 크게 물리쳤습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 22, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '양재역 벽서 사건이 발생하였다.', '송시열이 관작을 삭탈당하고 유배되었다.', '자의 대비 복상 문제로 예송이 전개되었다.', '정여립 모반 사건으로 기축옥사가 일어났다.', '붕당의 폐해를 막기 위해 탕평비가 세워졌다.', 2, '(가) 임금이 전교하기를, "내 생각에는 허적이 혹시 허견의 모반 사실을 알지 못했는가 하였는데, 문안(文案)을 보니 준기를 산속 정자에 숨긴 사실이 지금 비로소 드러났으니, 알고서도 엄호한 정황이 분명하여 감출 수가 없었다. 그저께 허적에게 사약을 내려 죽인 것도 이 때문이다."라고 하였다.
(나) 임금이 명하기를, "국운이 평안하고 태평함을 회복하여 중전이 복위하였으니, 백성에게 두 임금이 없는 것은 고금을 통하는 도리이다. 장씨에게 내렸던 왕후의 지위를 거두고, 옛 작호인 희빈을 내려 주도록 하라. 다만 세자가 조석으로 문안하는 것은 폐하지 말라."라고 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 23, '밑줄 그은 ''이 법''의 영향으로 가장 적절한 것은?', 1, '관청에 물품을 조달하는 공인이 등장하였다.', '어염세, 선박세 등이 국가 재정으로 귀속되었다.', '전세를 풍흉에 따라 9등급으로 차등 과세하였다.', '양반에게도 군포를 징수하는 호포제가 시행되었다.', '재정을 보충하기 위해 지주에게 결작이 부과되었다.', 1, '(한국사 쟁점 토론 - 주제: 공납의 개혁, 어떻게 볼 것인가) 방납의 폐단으로 농민들이 고통받고 있습니다. 공물을 현물 대신 쌀, 베 등으로 납부하는 이 법이 시행되면 농민들의 부담이 크게 줄어들 것입니다. / 하지만 이 법이 시행되면 토지 결수를 기준으로 공물을 납부하게 되어 토지가 많은 지주들의 부담은 크게 늘어납니다.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 24, '(가), (나) 왕에 대한 설명으로 옳은 것은?', 2, '(가) - 청과의 국경을 정한 백두산정계비를 세웠다.', '(가) - 왕실의 위엄을 높이기 위해 경복궁을 중건하였다.', '(나) - 이종무를 파견하여 대마도를 정벌하였다.', '(나) - 국왕의 친위 부대인 장용영을 설치하였다.', '(가), (나) - 나선 정벌에 조총 부대를 파견하였다.', 4, '(조선의 법전) ■ 속대전: (가) 때 경국대전을 개정 및 증보하여 편찬한 법전이다. 경국대전의 규정이 그대로 유지된 것은 싣지 않고, 기존 규정이 변경되거나 신설된 조목만 수록하였다. ■ 대전통편: (나) 때 경국대전과 속대전 및 그 뒤의 법령을 통합하여 편찬한 법전이다. 경국대전의 내용에 원(原), 속대전의 내용에 속(續), 새로 추가된 내용에 증(增)을 붙여 구분하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 25, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '이벽 등과 교류하며 천주교를 받아들였다.', '북한산비가 진흥왕 순수비임을 고증하였다.', '동호문답에서 수취 제도의 개혁 등을 제안하였다.', '가례집람을 지어 예학을 조선의 현실에 맞게 정리하였다.', '곽우록에서 토지 매매를 제한하는 한전론을 주장하였다.', 5, '이 책은 (가) 이/가 학문과 사물의 이치를 논한 글과 제자들의 질문에 응답한 내용을 모아 엮은 성호사설입니다. (가) 은/는 노비 제도의 개혁, 서얼 차별 폐지 등 다양한 개혁안을 제시하였습니다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 26, '다음 그림이 그려진 시기의 문화에 대한 설명으로 옳지 않은 것은?', 1, '중인들이 시사(詩社)를 조직하였다.', '양반의 위선을 풍자한 탈춤이 공연되었다.', '춘향가, 흥보가 등의 판소리가 유행하였다.', '금속 활자본인 직지심체요절이 간행되었다.', '홍길동전, 박씨전 등의 한글 소설이 널리 읽혔다.', 4, '이 그림은 김득신이 대장간의 모습을 묘사한 풍속화이다. 한 명이 화덕에서 달귀진 쇳덩어리를 방울집게로 집어 모루 위에 올려놓자 두 명이 쇠망치로 두드리는 모습, 도리에 매어 놓은 그네에 상체를 기대고 어깨너머로 구경하는 아이의 모습 등이 생동감 있게 표현되어 있다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 27, '(가) 인물에 대한 설명으로 옳은 것은?', 3, '총리대신으로 갑오개혁을 주도하였다.', '베델과 함께 대한매일신보를 창간하였다.', '서양의 과학 기술을 정리한 지구전요를 저술하였다.', '강화도 조약 체결의 전말을 기록한 심행일기를 남겼다.', '유학생과 기술자들을 이끄는 영선사로 청에 파견되었다.', 1, '(우리 역사 속 인물 연대기 - 근대) 1867 문과에 급제함 / 1880 제2차 수신사로 일본에 파견, 국내에 조선책략을 가져옴 / 1884 한성 조약 체결 당시 전권대신을 맡음 / 1896 아관 파천 후 성난 군중에 의해 살해됨.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 28, '밑줄 그은 ''변란''에 대한 정부의 대책으로 옳은 것은?', 1, '군 통수권 장악을 위해 원수부를 두었다.', '각 궁방과 중앙 관서의 공노비를 해방하였다.', '개혁의 방향을 제시한 홍범 14조를 반포하였다.', '재정 문제를 해결하기 위해 당백전을 발행하였다.', '삼정의 문란을 시정하고자 삼정이정청을 설치하였다.', 5, '경상 감사 이돈영이 진주의 백성들이 변란을 일으켜 경상우병사 백낙신을 협박하고 인명을 살상하였다고 보고하니, 왕이 하교하였다. "난민들의 행동이 극에 달했으니, 만약 평시에 백성들을 잘 위로하고 달랬다면 어찌 이런 일이 있었겠는가. 대신들은 의논하여 조처할 방안을 마련하도록 하라."', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 29, '교사의 질문에 대한 학생의 답변으로 옳은 것은?', 2, '병인양요 발생의 배경이 되었어요.', '갑신정변의 영향으로 체결되었어요.', '통감부가 설치되는 결과를 가져왔어요.', '거중 조정에 대한 내용이 포함되었어요.', '메가타가 재정 고문으로 부임하는 계기가 되었어요.', 4, '(대화) 자료는 이 조약 중 최혜국 대우를 규정한 조항의 일부입니다. 조선이 서양 국가와 최초로 체결한 이 조약에 대해 말해 볼까요? / (제14관) …… 미국과 그 상인이 종래 누리지 않았거나 이 조약에 없는 것 또한 미국 관민이 일체 균점하는 것을 승인한다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 30, '(가) 종교에 대한 설명으로 옳은 것은?', 2, '정혜쌍수와 돈오점수를 주장하였다.', '포접제를 활용하여 교세를 확장하였다.', '박중빈을 중심으로 새생활 운동을 추진하였다.', '중광단을 조직하여 항일 무장 투쟁을 전개하였다.', '제사와 신주를 모시는 문제로 정부의 탄압을 받았다.', 2, '(외무부 장관께) 몇 달 전부터 서울에서는 (가) 교도들에 대한 이야기밖에 없습니다. …… 사흘 전 이들의 대표 21명이 궁궐 문 앞에 모여 엎드려 절하고 상소를 올렸으나 국왕은 상소 접수를 거부하였습니다. 교도들은 처형된 교조 최제우를 복권하고 (가) 을/를 인정해 줄 것을 정부에 청원하였습니다. …… 그러나 이는 조선 국왕이 들어줄 수 없는 사안들이었습니다. (조선 주재 프랑스 공사 H. 프랑댕)', '근대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 31, '(가) 단체에 대한 설명으로 옳은 것은?', 2, '만세보를 발행하여 민중 계몽에 앞장섰다.', '고종의 강제 퇴위 반대 운동을 전개하였다.', '여성 권리 선언문인 여권통문을 공표하였다.', '독립운동 자금 마련을 위해 독립 공채를 발행하였다.', '만민 공동회를 열어 열강의 이권 침탈을 저지하였다.', 5, '서울시는 고가도로 건설을 위해 독립문 이전을 결정하였습니다. 독립문은 서재필 등이 중심이 되어 창립한 (가) 이/가 왕실과 국민의 성금을 모아 세웠습니다. 중국 사신을 맞이하던 영은문 자리 부근에 있는 독립문은 이번 결정으로 원래 자리에서 약 70미터 떨어진 공터로 이전할 예정입니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 33, '(가)~(다) 학생이 발표한 내용을 일어난 순서대로 옳게 나열한 것은?', 2, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (나) - (가)', 4, '(한국사 주제 발표 - 위정척사 운동과 최익현의 활동) (가) 이완용 등의 역적을 처단하라는 상소를 올리고 임병찬 등과 태인에서 의병을 일으켰어요. / (나) 도끼를 들고 대궐 앞에 엎드려 개항에 반대하는 상소를 올렸어요. / (다) 일본의 간섭하에 추진된 개혁에 반발하여, 이를 주도한 박영효, 서광범 등을 처벌하라는 상소를 올렸어요.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 34, '다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?', 2, '화폐 정리 사업의 결과를 분석한다.', '산미 증식 계획의 실상을 조사한다.', '조일 통상 장정 체결의 영향을 살펴본다.', '토지 조사 사업의 추진 과정을 파악한다.', '양지아문과 지계아문을 설치한 목적을 알아본다.', 3, '이달 20일, 함경도 관찰사로부터 보고를 받았는데, 그 내용은 다음과 같았습니다. "큰 수해를 당하여 조만간 여러 곡식의 피해가 클 듯한데, 콩 등은 더욱 심하여 모두 흉작이 될 것이라고 고하고 있으니, 궁핍하여 식량난을 겪을 것이 장차 불을 보듯 훤합니다. 도내(道內)의 쌀과 콩 등의 곡물에 대해서는 내년 가을걷이할 때까지를 기한으로 삼아 잠정적으로 유출을 금지하여 백성들의 식량 사정을 넉넉하게 하는 것이 마땅할까 합니다. 바라건대 통촉하시어 유출 금지 시행 1개월 전까지 일본 공사에게 알리시어, 일본의 상민들이 일제 준수하게 해주십시오."', '근대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 35, '(가)~(라)를 작성된 순서대로 옳게 나열한 것은?', 2, '(가) - (나) - (다) - (라)', '(가) - (나) - (라) - (다)', '(나) - (가) - (라) - (다)', '(나) - (다) - (가) - (라)', '(다) - (라) - (나) - (가)', 4, '(가) 제6도 심통성정도(心統性情圖) 중에서 하도(下圖)는 이(理)와 기(氣)를 합하여 말한 것이니, …… 예를 들면 사단(四端)의 정은 이가 발하고 기가 따르니, 본래 순선(純善)하여 악이 없으나, 반드시 이의 발함이 온전하게 이루어지기 전에 기에 가려진 연후에야 선하지 않게 됩니다. 칠정(七情)은 기가 발하고 이가 그것에 타는 것이니, 역시 선하지 않음이 없으나, 만약 기가 발하는 것이 절도에 맞지 않으면 그 이를 멸하게 되어 악이 됩니다.
(나) 유·불·도 삼교(三敎)는 각각 업(業)으로 삼아 수행하는 바가 있으니, 섞어서 하나로 할 수는 없습니다. 부처의 가르침을 행하는 것은 수신(修身)의 근본이요, 유교의 가르침을 행하는 것은 나라를 다스리는 근원이니, 수신은 다음 생을 위한 바탕이 되고, 나라를 다스리는 것은 곧 오늘날에 힘쓸 일입니다.
(다) 저 불씨(佛氏)는 사람이 사악하지 정의로운지 올바른지 그른지는 가리지 않고 말하기를, "우리 부처에게 오는 자는 화를 면하고 복을 얻을 수 있다."라고 한다. 이것은 비록 열 가지의 큰 죄악을 지은 사람일지라도 부처에게 귀의하면 화를 면하게 되고, 아무리 도가 높은 선비일지라도 부처에게 귀의하지 않으면 화를 면할 수 없다는 말이다.
(라) 유교계에 3대 문제가 있는지라. 그 문제에 관해 개량하고 구신(求新)하지 않으면 우리 유교는 결코 흥왕할 수 없으리라.', '통합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 36, '(가)~(라)를 작성한 인물에 대해 탐구한 내용으로 적절한 것을 <보기>에서 고른 것은?', 3, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 4, '(35~36 자료 연계) (가) 이황이 지은 성학십도의 일부. (나) 최승로 등이 유·불의 역할을 논한 글. (다) 정도전이 지은 불씨잡변의 일부. (라) 박은식이 지은 유교구신론의 일부.', '통합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 37, '(가)의 활동으로 옳은 것을 <보기>에서 고른 것은?', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 5, '(△△ 박물관 스탬프 투어 - 제4관 국외 독립운동의 전개) 이 전시관은 국권 피탈 이후 국외에서 전개된 독립운동을 주제로 구성되어 있습니다. 특히 3·1 운동의 영향으로 수립된 (가) 의 활동에 대한 자료가 전시되어 있습니다. (스탬프: 상하이에서 (가) 의 수립 초기에 청사로 사용한 건물 모양. 이 청사에서는 임시 의정원의 회의가 개최되기도 하였습니다.)', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 38, '밑줄 그은 ''특사''가 파견된 배경으로 가장 적절한 것은?', 1, '임오군란이 일어났다.', '집강소가 설치되었다.', '을사늑약이 체결되었다.', '조선 태형령이 제정되었다.', '대한 제국의 군대가 해산되었다.', 3, '(전보 제○○○호. 발신인: 하야시 외무대신(도쿄). 수신인: 이토 통감(한성)) 헤이그에서 발행된 평화회의보는 한국 전 부총리대신 이상설 외 2명이 평화회의에 특사로 파견되었다고 보도함. 기사에는 우선 그 한국인이 평화회의 위원으로 한국 황제가 파견된 자라는 것이 기재되었고, 이어서 일본이 한국 황제의 뜻을 배반하고, 병력으로 한국의 법규 관례를 유린하고 동시에 한국의 외교권을 탈취한 점, 그 결과 자신들이 한국 황제가 파견한 위원임에도 불구하고 평화회의에 참여할 수 없음이 유감이라는 점 등이 실렸음.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 39, '밑줄 그은 ㉠ 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 3, '북학의를 저술하는 학자', '대한국 국제를 반포하는 황제', '거문도를 불법 점령하는 영국군', '집현전에서 학문을 연구하는 관리', '제너럴 셔먼호를 불태우는 평양 관민', 2, '이 자료는 우리나라 최초의 전차가 개통된 해에 한성 전기 회사가 신문에 낸 안전 주의 사항입니다. 낯선 교통수단인 전차의 운행으로 사고가 날 것을 우려하여 이러한 안내를 하였지만, 전차에 어린이가 치이는 등의 사고가 일어나 사회 문제가 되기도 하였습니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 40, '다음 자료를 활용한 탐구 주제로 가장 적절한 것은?', 1, '시전 상인의 상권 수호 운동', '급진 개화파의 정치 개혁 운동', '백정들의 사회적 차별 철폐 운동', '농촌 계몽을 위한 브나로드 운동', '일본의 황무지 개간권 요구에 대한 반대 운동', 5, '(송수만 등 체포 경위 보고) 송수만은 보안회라는 것을 설립하여 그 회장이 됨. 종로 백목전 도가에서 날마다 회원을 모집하여 집회·논의하고 있는 자임. 오늘 경부와 순사 두 사람이 출장하여 송수만에게 공사관으로 동행하기를 요구하였음. …… 이때 회원과 인민들 약 200명 정도가 떠들썩하게 모여들어 송수만의 동행을 막음.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 41, '(가), (나) 발표 사이의 시기에 있었던 사실로 옳은 것은?', 2, '육영 공원이 설립되었다.', '국문 연구소가 설치되었다.', '교육 입국 조서가 반포되었다.', '국민 교육 헌장이 발표되었다.', '조선 민립 대학 기성회가 창립되었다.', 5, '(가) 제1조 조선에 있어 조선인의 교육은 본령에 의한다. 제9조 보통학교의 수업 연한은 4년으로 한다. 단, 지방 실정에 따라 1년을 단축할 수 있다.
(나) 제2조 총장은 조선 총독의 감독을 받아 경성 제국 대학 일반 사무를 담당하며 소속 직원을 통독(統督)한다. 제4조 경성 제국 대학에 예과를 둔다.', '일제강점기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 42, '다음 자료에 나타난 사건의 영향으로 적절한 것은?', 2, '13도 창의군이 서울 진공 작전을 전개하였다.', '복벽주의를 내세운 독립 의군부가 조직되었다.', '김광제 등의 발의로 국채 보상 운동이 일어났다.', '통상 수교 거부 의지를 담은 척화비가 건립되었다.', '민족 유일당 운동의 일환으로 신간회가 창립되었다.', 5, '(판결문) 피고인: 이선호 외 10명. 주문: 피고인들을 각 징역 1년에 처한다. 이유: 피고인들은 이왕(李王) 전하 국장 의식을 거행할 즈음, 이를 봉송하기 위하여 지방에서 다수 조선인이 경성부로 모이는 기회를 이용하여 조선 독립운동을 선동하는 불온 문서를 비밀리에 인쇄하여 국장 당일 군중 가운데 살포하여 조선 독립 만세를 소리 높여 외쳐 조선 독립의 희망을 달성하고자 기도하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 43, '(가) 군사 조직에 대한 설명으로 옳은 것은?', 2, '홍범도가 총사령관으로 활약하였다.', '영릉가 전투에서 일본군을 격퇴하였다.', '대원 일부가 한국광복군에 합류하였다.', '도쿄에서 2·8 독립 선언을 계획하였다.', '상하이에서 대동단결 선언을 발표하였다.', 3, '(이달의 독립운동가) 윤세주(1901~1942). 훈격: 건국훈장 독립장. 서훈 연도: 1982년. 공훈록(요약): 경남 밀양 출생. 1919년 만주에서 김원봉과 함께 의열단을 조직하였다. 국내에 들어온 그는 의열 투쟁을 계획하다 체포되어 수년간 옥고를 치렀다. 이후 중국 관내에서 결성된 최초의 한인 무장 조직인 (가) 의 주요 간부로 활약하였다. 1942년 타이항산에서 전사하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 44, '(가) 인물의 활동으로 옳은 것은?', 3, '조선상고사를 저술하였다.', '소설 상록수를 신문에 연재하였다.', '저항시 광야, 절정 등을 발표하였다.', '영화 아리랑의 제작과 감독을 맡았다.', '별 헤는 밤, 참회록 등의 시를 남겼다.', 5, '도시샤 대학에 있는 이 시비는 민족 문학인 (가) 을/를 기리기 위해 세워졌습니다. 비석에는 ''죽는 날까지 하늘을 우러러''로 시작되는 그의 작품인 서시가 새겨져 있습니다. 북간도 출신인 그는 일본 유학 중 치안 유지법 위반 혐의로 체포되어 옥중에서 순국하였습니다.', '일제강점기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 45, '밑줄 그은 ''이 시기''에 있었던 사실로 옳은 것을 <보기>에서 고른 것은?', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 3, '(○○ 박물관 소장 자료 소개) 이 포스터는 국민 총력 조선 연맹에서 만든 것으로, 기름을 짤 각종 씨앗까지 모아서 내라고 독려하는 내용이다. 국민 총력 조선 연맹은 국가 총동원법이 시행되던 이 시기에 조직되어 일제가 전쟁에 필요한 인력과 물자를 수탈하는 데 앞장섰다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 46, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '카이로 선언이 발표되었다.', '조선 건국 동맹이 결성되었다.', '모스크바 삼국 외상 회의가 개최되었다.', '좌우 합작 위원회에서 좌우 합작 7원칙을 합의하였다.', '유엔 총회에서 인구 비례에 따른 남북한 총선거를 결의하였다.', 3, '(가) 본관(本官)은 본관에게 부여된 태평양 미국 육군 최고 지휘관의 권한을 가지고 조선 북위 38도 이남의 지역과 주민에 대하여 군정을 설립함. 따라서 점령에 관한 조건을 다음과 같이 포고함. 제1조 조선 북위 38도 이남의 지역과 동 주민에 대한 모든 행정권은 당분간 본관의 권한하에서 시행함.
(나) 대한민국 임시 정부는 28일 김구와 김규식의 명의로 ''4개국 원수에게 보내는 결의문''을 채택하고, 각계 대표 70여 명으로 신탁 통치 반대 국민 총동원 위원회를 결성하였다. 여기서 강력한 반대 투쟁을 결의하고 김구·김규식 등 9인을 위원회의 ''장정위원''으로 선정하였다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 47, '(가) 지역에 대한 설명으로 옳은 것은?', 3, '조선 형평사 창립총회가 개최된 곳이다.', '동학 농민군과 정부 사이에 화약이 체결된 곳이다.', '서희가 소손녕과의 외교 담판을 통해 확보한 곳이다.', '장수왕 때 국내성에서 천도하여 도읍으로 삼은 곳이다.', '유엔군과 공산군 사이의 첫 번째 정전 회담이 열린 곳이다.', 5, '(노래로 읽는 한국사) 황성옛터(荒城옛터): 황성 옛터에 밤이 되니 월색만 고요해 / 폐허의 설음 회포를 말하여 주노나 / 아 외로운 저 나그네 홀로 잠 못 이뤄 / 구슬픈 벌레 소리에 말없이 눈물져요. (해설) 이 곡은 전수린이 고향인 (가) 에 들렀다가 옛 궁터인 만월대를 보고 작곡한 노래로, 일제에 국권을 빼앗긴 설움을 대변하여 장안의 화제가 되었다. 이 곡의 배경인 (가) 의 만월대에서는 2007년부터 남북 공동 발굴이 이루어져 금속 활자를 비롯하여 기와 및 도자기 등 다양한 유물이 출토되었다.', '통합', '지역사', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 48, '(가) 민주화 운동에 대한 설명으로 옳은 것은?', 1, '3선 개헌 반대 범국민 투쟁 위원회가 주도하였다.', '이승만이 대통령직에서 물러나는 결과를 가져왔다.', '신군부의 비상계엄 확대와 무력 진압에 저항하였다.', '관련 기록물이 유네스코 세계 기록 유산으로 등재되었다.', '4·13 호헌 조치에 반발하며 호헌 철폐 등의 구호를 내세웠다.', 2, '(3·15 의거 기념 답사 안내) 우리 문화원에서는 (가) 의 도화선이 된 3·15 의거의 의미를 조명하는 답사를 준비하였습니다. 부정 선거에 맞서 일어난 시민과 학생들의 민주화 의지를 되새기는 이번 답사에 많은 관심과 참여 바랍니다. 답사 경로: 3·15 의거 발원지 → 3·15 의거 기념탑 → 김주열 열사 시신 인양지 → 마산의료원(구 도립마산병원).', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 49, '다음 판결이 있었던 정부 시기의 사실로 옳은 것은?', 2, '한일 월드컵 축구 대회가 개최되었다.', '농촌 근대화를 표방하는 새마을 운동이 추진되었다.', '외환 위기 극복을 위한 금 모으기 운동이 전개되었다.', '금융 거래 투명성을 실현하고자 금융 실명제가 시행되었다.', '한미 자유 무역 협정(FTA) 체결에 반대하는 시위가 벌어졌다.', 2, '○ 김○○ 씨가 모 다방에서 동석한 사람들에게 "정부가 물가 조정한다고 하면서 물가가 오르기만 하니 정부가 국민을 기만하는 것이 아니냐.", "중앙정보부에서 모 대학교수를 잡아 조사를 하다 죽이고서는 자살하였다고 거짓 발표하였다." 등의 발언을 하여 유언비어를 유포했다는 이유로 징역 5년을 선고받았다.
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (57, 50, '(가) 정부의 통일 노력으로 옳은 것은?', 2, '남북 기본 합의서를 채택하였다.', '남북한이 유엔에 동시 가입하였다.', '10·4 남북 공동 선언을 발표하였다.', '남북 조절 위원회를 운영하기로 합의하였다.', '남북 이산가족 고향 방문단의 교환 방문을 최초로 성사하였다.', 3, '(수행 과제 안내문) 과제: (가) 정부의 통일 노력 소개하기. 안내: 제2차 남북 정상 회담을 개최한 (가) 정부의 통일 노력을 카드 뉴스로 제작해 봅시다. 예시: 남북 간의 교류와 협력을 위해 경의선 철도를 시험 운행하였다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 1, '(가) 시대의 생활 모습으로 옳은 것은?', 1, '가락바퀴를 이용하여 실을 뽑았다.', '주로 동굴이나 막집에서 거주하였다.', '명도전, 반량전 등의 화폐가 유통되었다.', '거푸집을 이용하여 세형 동검을 만들었다.', '쟁기, 쇠스랑 등의 철제 농기구를 사용하였다.', 1, '부산 동삼동 유적에서 출토된 빗살무늬 토기는 농경과 정착 생활이 시작된 (가) 시대의 대표적 유물 중 하나입니다. 이 유적에서는 곡물 등을 가공하는 데 사용한 갈돌과 갈판도 출토되었습니다.', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 2, '(가) 나라에 대한 설명으로 옳은 것은?', 2, '동맹이라는 제천 행사를 열었다.', '신지, 읍차라 불린 지배자가 있었다.', '도둑질한 자에게 12배로 배상하게 하였다.', '읍락 간의 경계를 중시하는 책화가 있었다.', '왕 아래 상, 대부, 장군 등의 관직을 두었다.', 5, '○ 좌장군은 (가) 의 패수 서쪽에 있는 군사를 쳤으나 이를 격파해서 나가지는 못했다. …… 누선장군도 가서 합세하여 왕검성의 남쪽에 주둔했지만, 우거왕이 성을 굳게 지키므로 몇 달이 되어도 함락시킬 수 없었다.
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 3, '다음 상황이 전개된 배경으로 옳은 것은?', 2, '법흥왕이 금관가야를 병합하였다.', '장수왕이 한성을 공격하여 함락시켰다.', '김유신이 비담과 염종의 반란을 진압하였다.', '영양왕이 온달을 보내 아단성을 공격하였다.', '김춘추가 당으로 건너가 군사 동맹을 성사시켰다.', 2, '(대화) 자네 들었는가? 백제의 동성왕이 사신을 보내 혼인을 청하셨다더군. / 들었네. 우리 마립간께서 이벌찬 비지의 딸을 보내신다고 하네.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 4, '(가) 나라에 대한 탐구 활동으로 가장 적절한 것은?', 3, '안동도호부가 설치된 경위를 찾아본다.', '22담로에 왕족이 파견된 목적을 알아본다.', '중앙 관제가 3성 6부로 정비된 계기를 파악한다.', '최고 지배자의 호칭인 이사금의 의미를 검색한다.', '고령 지역이 연맹의 중심지로 성장하는 과정을 조사한다.', 5, '진흥왕이 이찬 이사부에게 명령하여 (가) 을/를 공격하게 하였다. 이때 사다함은 나이가 15~16세였는데 종군하기를 청하였다. …… (가) 사람들이 뜻하지 않은 병사들의 습격에 놀라 막아내지 못하였고, 대군이 승세를 타서 마침내 멸망시켰다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 5, '밑줄 그은 ''전투''가 벌어진 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 4, '(대화) 이곳은 높은 성벽과 치를 갖춘 백암성이야. / 당의 황제가 직접 대군을 이끌고 침입하여 이곳에서 전투가 벌어졌지. / 병력의 열세와 내부의 분열로 함락되었지만, 그 뒤에는 안시성이 버티고 있었어.
(연표) 관산성 전투(554) - 수의 중국 통일(589) - 살수 대첩(612) - 보장왕 즉위(642) - 고구려 멸망(668) - 발해 건국(698). (가)=554~589, (나)=589~612, (다)=612~642, (라)=642~668, (마)=668~698.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 6, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '사찬 시득이 기벌포에서 당군을 격파하였다.', '의자왕이 윤충을 보내 대야성을 함락시켰다.', '복신과 도침이 부여풍을 왕으로 추대하였다.', '계백이 이끄는 군대가 황산벌에서 항전하였다.', '안승이 신라에 의해 보덕국왕으로 책봉되었다.', 3, '(가) 백제의 남은 적군이 사비성으로 진입하여 항복해 살아남은 사람들을 붙잡아 가려고 하였으므로, 유수(留守) 유인원이 당과 신라 사람들을 보내 이를 쳐서 쫓아냈다. …… 당 황제가 좌위중랑장 왕문도를 웅진도독으로 삼았다.
(나) 손인사, 유인원과 신라왕 김법민은 육군을 거느려 나아가고, 유인궤와 별수(別帥) 두상과 부여융은 수군과 군량을 실은 배를 거느리고 백강으로 가서 육군과 합세하여 주류성으로 갔다. 백강 어귀에서 왜국 군사를 만나 …… 그들의 배 4백 척을 불살랐다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 7, '밑줄 그은 ''시기'' 신라의 경제 모습으로 옳은 것은?', 2, '벽란도가 국제 무역항으로 번성하였다.', '조세 수취를 위해 촌락 문서를 작성하였다.', '철이 많이 생산되어 낙랑군 등에 수출하였다.', '농업 생산력 증대를 위해 우경을 처음으로 시작하였다.', '수도에 도시부(都市部)라는 관청을 설치하여 시장을 관리하였다.', 2, '이것은 일본의 귀족들이 신라에서 들어온 물품을 매입하고자 그 수량과 가격을 기록하여 일본 정부에 제출한 ''매신라물해(買新羅物解)''라는 문서입니다. 통일을 이루고 9주 5소경을 설치한 이후의 시기에 일본과 교역하던 모습을 알 수 있습니다.', '고대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 8, '(가) 국가에 대한 설명으로 옳은 것은?', 1, '기인 제도를 실시하였다.', '정사암 회의를 개최하였다.', '최고 행정 관서로 집사부를 두었다.', '주자감을 설치하여 인재를 양성하였다.', '광덕, 준풍 등의 독자적인 연호를 사용하였다.', 4, '이것은 문왕의 넷째 딸인 정효 공주의 묘지(墓誌)이다. 묘지의 내용 중 문왕을 황상(皇上)이라고 부른 표현을 통해 (가) 이/가 대내적으로 황제국 체제를 표방하였음을 알 수 있다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 9, '다음 상황 이후에 전개된 사실로 옳은 것은?', 2, '김흠돌이 반란을 도모하였다.', '장문휴가 당의 등주를 공격하였다.', '궁예가 국호를 태봉으로 바꾸었다.', '원종과 애노가 사벌주에서 반란을 일으켰다.', '경순왕 김부가 경주의 사심관으로 임명되었다.', 5, '왕이 구원을 요청하자, 태조는 장수에게 명하여 정예 병사 1만 명을 보내 구원하게 하였다. 견훤은 구원병이 아직 도착하지 않은 것을 알고, 겨울 11월에 갑자기 왕경(王京)에 침입하였다. 왕은 비빈, 종실 친척들과 포석정에 가서 연희를 즐기느라 적병이 이르는 것도 깨닫지 못하였다. - 『삼국사기』 -', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 10, '밑줄 그은 ''이 시기''에 있었던 사실로 옳은 것은?', 3, '원광이 세속 5계를 제시하였다.', '김대문이 화랑세기를 저술하였다.', '김대성이 불국사 조성을 주도하였다.', '최치원이 진성여왕에게 시무책을 올렸다.', '자장의 건의로 황룡사 구층 목탑이 건립되었다.', 4, '(대화) 여기는 범일대사가 창건한 굴산사가 있던 곳이야. 거대한 당간 지주는 이 절의 규모와 위상을 잘 보여주지. / 굴산사는 가지산문 개창 이후 선종 불교가 유행하던 이 시기에 창건되었어.', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 11, '다음 시나리오에 등장하는 왕의 재위 기간에 있었던 사실로 옳은 것은?', 2, '쌍기의 건의로 과거제를 실시하였다.', '관학 진흥을 위해 양현고를 설치하였다.', '국자감을 성균관으로 개칭하고 유학 교육을 강화하였다.', '최승로의 시무 28조를 받아들여 통치 체제를 정비하였다.', '정계와 계백료서를 지어 관리가 지켜야 할 규범을 제시하였다.', 4, '(시나리오 #11. 궁궐 안) 왕: 몇 해 전 교육을 장려하기 위해 지방에 각각 경학박사 1명과 의학박사 1명을 보냈는데, 결과가 어떠하오? / 신하: 송승연, 전보인 등 박사들이 정성스레 가르쳐 성과가 있는 듯 하옵니다. / 왕: 12목을 설치하고, 지방민에게도 학문을 권장하는 과인의 뜻에 부합하였소. 고생한 송승연에게 국자박사를 제수하고, 전보인에게 공복과 쌀을 하사하시오.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 12, '다음 상황이 나타난 시기의 사회 시책으로 옳은 것은?', 2, '유랑민을 구휼하는 활인서를 두었다.', '백성들에게 곡식을 빌려주는 진대법을 실시하였다.', '국산 약재와 치료법을 소개한 향약집성방을 편찬하였다.', '기근에 대비하기 위해 구황촬요를 간행하여 보급하였다.', '기금을 모아 그 이자로 빈민을 구제하는 제위보를 운영하였다.', 5, '○ 왕이 명하였다. "도성 안의 백성들이 역질에 걸렸으니 구제도감을 설치하여 치료하고, 시신과 유골은 거두어 비바람에 드러나지 않게 매장하라."
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 13, '(가)의 침입에 대한 고려의 대응으로 옳은 것은?', 2, '김종서를 보내 6진을 개척하였다.', '서희를 보내 소손녕과 외교 담판을 벌였다.', '별무반을 조직하고 동북 9성을 축조하였다.', '강화도로 도읍을 옮겨 장기 항전을 준비하였다.', '화통도감을 설치하여 화약과 화포를 제작하였다.', 4, '병마사 박서는 김중온에게 성의 동서쪽을, 김경손에게는 성의 남쪽을 지키게 하였다. (가) 의 대군이 남문에 이르자 김경손은 12명의 용맹한 군사와 여러 성의 별초를 거느리고 성 밖으로 나가려고 하였다. …… 우별초가 모두 땅에 엎드리고 응하지 않자 김경손은 그들을 성으로 돌려 보내고 12명의 군사와 함께 나아가 싸웠다. - 『고려사』 -', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 14, '다음 대화가 이루어진 시기의 경제 상황으로 옳은 것은?', 1, '활구라고 불리는 은병이 유통되었다.', '특산품으로 솔빈부의 말이 유명하였다.', '송상이 전국 각지에 송방을 설치하였다.', '청해진을 설치하여 해상 무역을 전개하였다.', '시장을 감독하는 관청인 동시전이 설치되었다.', 1, '(대화) 몇 해 전 주전도감을 설치하고 화폐를 유통시켜 나라의 부강과 백성의 편익을 꾀하였으나, 널리 활용되지 못하고 있사옵니다. / 주현에 명령하여 주식점(酒食店)을 열고 백성들에게 화폐를 활용해 음식을 사 먹을 수 있게 하여 그 이로움을 알게 하라.', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 15, '다음 검색창에 들어갈 역사 자료에 대한 설명으로 옳은 것은?', 2, '고구려 계승 의식이 반영되었다.', '남북국이라는 용어가 처음 사용되었다.', '사초, 시정기 등을 바탕으로 편찬하였다.', '단군의 고조선 건국 이야기를 수록하였다.', '현존하는 우리나라 최고(最古)의 역사서이다.', 1, '(검색: 시대-고려 후기) 건국 영웅의 일대기를 서술한 장편 서사시로 동국이상국집에 실려있다. 왕 탄생 이전의 역사, 출생과 건국, 유리왕의 즉위 과정과 저자 이규보의 감상이 적혀 있다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 17, '(가) 시기에 있었던 사실로 옳은 것은?', 2, '집현전을 계승한 홍문관이 설치되었다.', '조준 등의 건의로 과전법이 제정되었다.', '국가의 기본 법전인 경국대전이 완성되었다.', '연분9등법을 시행하여 수취 체제가 정비되었다.', '음악 이론 등을 집대성한 악학궤범이 간행되었다.', 2, '(장면) 요동을 공격하고자 하니 경들은 마땅히 힘을 다하라. / 전하, 네 가지 이유로 불가하옵니다. → (가) → 새 도읍이 정해졌으니 도감을 설치하고 심덕부 등을 판사로 임명하여 궁궐을 조성하게 하시오. / 명을 받들겠습니다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 18, '(가)에 대한 조선의 정책으로 옳은 것은?', 2, '하정사, 성절사 등을 파견하였다.', '경성, 경원에 무역소를 설치하였다.', '광군을 조직하여 침입에 대비하였다.', '부산포, 제포, 염포의 삼포를 개항하였다.', '사절 왕래를 위하여 북평관을 개설하였다.', 4, '(이달의 인물) 우리 외교를 빛낸 인물, 이예. 생몰: 1373년~1445년. 경력: 통신부사, 첨지중추원사, 동지중추원사. 울산의 아전 출신으로 호는 학파(鶴坡), 시호는 충숙(忠肅)이다. 수십 차례 (가) 에 파견되어 외교 문제를 해결하려고 노력하였다. 특히 조선과 (가) 사이에 세견선의 입항 규모를 정한 계해약조 체결에 기여하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 19, '밑줄 그은 ''전하''의 재위 기간에 있었던 사실로 옳은 것은?', 3, '예학을 정리한 가례집람이 저술되었다.', '국가의 의례를 정비한 국조오례의가 완성되었다.', '아동용 윤리·역사 교재인 동몽선습이 간행되었다.', '효자, 충신 등의 사례를 제시한 삼강행실도가 편찬되었다.', '군주가 수양해야 할 덕목을 제시한 성학집요가 집필되었다.', 4, '우리 주상 전하께서는 오방의 풍토가 같지 아니하여 곡식을 심고 가꾸는 데 각기 적당한 방법이 있다고 하셨다. 이에 여러 도의 감사에게 명하기를, 주현의 나이든 농부들을 방문하여 농사지은 경험을 아뢰게 하시고 또 신(臣) 정초에게 그 까닭을 덧붙이게 하셨다. 중복된 것을 버리고, 요약한 것만 뽑아 한 편의 책으로 만들고 제목을 농사직설이라고 하였다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 20, '(가) 기구에 대한 설명으로 옳은 것은?', 1, '국왕 직속의 특별 사법 기구였다.', '사림의 건의로 중종 때 폐지되었다.', '사헌부, 사간원과 함께 삼사로 불리었다.', '5품 이하의 관원에 대한 서경권을 행사하였다.', '서얼 출신의 학자들이 검서관으로 기용되었다.', 1, '(이달의 책) 이 책에는 조선 시대에 왕명으로 (가) 에서 중죄인을 추국한 결과가 기록되어 있다. 조옥(詔獄)이라고도 불린 (가) 은/는 강상죄·반역죄 등을 처결하였으며 판사·도사 등의 관직이 있었다. (책 제목: 추안급국안)', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 21, '밑줄 그은 ''이 부대''에 대한 설명으로 옳은 것은?', 2, '용호군과 함께 2군으로 불렸다.', '진도에서 용장성을 쌓고 항전하였다.', '국경 지역인 북계와 동계에 배치되었다.', '포수, 살수, 사수의 삼수병으로 편제되었다.', '국왕의 친위 부대로 수원 화성에 외영을 두었다.', 4, '전시된 그림은 이 부대의 분영인 북일영과 활터의 풍경을 묘사한 김홍도의 작품입니다. 임진왜란 중 류성룡의 건의로 편성된 이 부대는 직업 군인의 성격을 띤 상비군이었습니다. (그림: 북일영도)', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 22, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '정봉수가 용골산성에서 항전하였다.', '이순신이 명량에서 대승을 거두었다.', '권율이 행주산성에서 적군을 격퇴하였다.', '서인 세력이 폐모살제를 이유로 반정을 일으켰다.', '정여립 모반 사건을 계기로 기축옥사가 발생하였다.', 1, '(가) 왕에게 이괄 부자가 역적의 우두머리라고 고해바친 자가 있었다. 하지만 왕은 "반역은 아닐 것이다."라고 하면서도, 이괄의 아들인 이전을 잡아오라고 명하였다. 이에 이괄은 군영에 있던 장수들을 위협하여 난을 일으켰다.
(나) 최명길을 보내 오랑캐에게 강화를 청하면서 그들의 진격을 늦추도록 하였다. 왕이 수구문(水溝門)을 통해 남한산성으로 향했다. 변란이 창졸 간에 일어났기에 도보로 따르는 신하도 있었고 성안 백성의 통곡 소리가 하늘을 뒤흔들었다. 초경을 지나 왕의 가마가 남한산성에 도착하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 23, '(가) 국가에 대한 조선의 대외 정책으로 옳은 것은?', 2, '박위를 파견하여 근거지를 토벌하였다.', '백두산정계비를 세워 국경을 정하였다.', '한성에 동평관을 두어 무역을 허용하였다.', '쌍성총관부를 공격하여 철령 이북의 영토를 되찾았다.', '포로 송환을 위하여 유정을 회답 겸 쇄환사로 파견하였다.', 2, '이 지도는 의주에서 연경에 이르는 경로를 표시한 것입니다. 조선 사신들은 이 경로를 따라 (가) 을/를 왕래하였는데, 이 사행에 참여한 만상은 국제 무역으로 많은 돈을 벌기도 하였습니다. (지도: 입연정도도(入燕程途圖))', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 24, '밑줄 그은 ''이 왕''의 업적으로 옳은 것은?', 2, '수도 방위를 위하여 금위영을 창설하였다.', '속대전을 편찬하여 통치 제도를 정비하였다.', '삼군부를 부활시켜 군국 기무를 전담하게 하였다.', '초계문신제를 실시하여 젊은 문신들을 재교육하였다.', '전세를 1결당 4~6두로 고정하는 영정법을 제정하였다.', 2, '이것은 정민교의 서사시 ''군정탄(軍丁歎)''입니다. 이 작품에 표현된 황구첨정 등의 폐단을 해결하고자 이 왕은 균역청을 설치하고 양역 제도를 개선하였습니다. (시 일부: 남편은 세상을 떴으나 뱃속에 아기가 있었지요 / 포대기로 싼 갓난아기 장정으로 군적에 올려 문이 닳도록 찾아와 군포를 바치라고 독촉하니)', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 25, '(가)에 들어갈 내용으로 옳은 것은?', 2, '상피제의 적용을 받았다.', '잡과를 통해 선발되었다.', '감사 또는 방백이라 불렸다.', '이방, 호방 등 6방에 소속되었다.', '공음전을 경제적 기반으로 삼았다.', 4, '(한국사 퀴즈: 조선 시대 직역(職役)을 맞히는 문제) 1단계 힌트: 단안(壇案)이라는 명부에 등록되었다. / 2단계 힌트: 연조귀감에 연혁이 수록되었다. / 3단계 힌트: 지방 행정 실무를 담당하였다. / 4단계 힌트: (가)', '조선', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 26, '(가) 종교에 대한 설명으로 옳은 것은?', 1, '미륵불이 세상을 구원한다고 예언하였다.', '동경대전과 용담유사를 경전으로 삼았다.', '박중빈을 중심으로 새생활 운동을 전개하였다.', '단군 숭배 사상을 통해 민족의식을 고취하였다.', '청을 다녀온 사신들에 의하여 서학으로 소개되었다.', 5, '(신문 기사) 해미순교성지, 국제성지로 지정. 해미순교성지가 전 세계에 30여 곳밖에 없는 국제성지 가운데 하나로 지정되었다. 병인박해 당시 (가) 신자들이 죽임을 당한 이곳은 한국 근대사에서 중요한 종교적 의미를 지닌 지역이다. 이번 지정을 계기로 남연군 묘 등 여러 역사 유적이 있는 내포 문화권은 더욱 관심을 끌 것으로 기대된다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 27, '(가) 인물의 활동으로 옳은 것은?', 2, '성호사설에서 한전론을 주장하였다.', '양반전에서 양반의 허례와 무능을 지적하였다.', '의산문답에서 중국 중심의 세계관을 비판하였다.', '북학의에서 절약보다 적절한 소비를 권장하였다.', '경세유표에서 국가 제도의 개혁 방향을 제시하였다.', 5, '(답사 보고서) 주제: 대학자 (가) 의 흔적을 찾아서. 지역: 경기도 남양주시 일대. 소개: 흠흠신서, 마과회통 등을 저술한 (가) 은/는 정치·경제 등 여러 분야에 걸쳐 방대한 학문적 업적을 남겼다. 경로: 여유당 → 문도사 → 묘소.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 28, '밑줄 그은 ''시기''에 있었던 사실로 옳은 것은?', 2, '나선 정벌에 조총 부대가 동원되었다.', '박규수의 건의로 삼정이정청이 설치되었다.', '지역 차별에 반발하여 홍경래가 봉기하였다.', '제너럴 셔먼호 사건을 구실로 미군이 침입하였다.', '시전 상인의 특권을 축소하는 신해통공이 단행되었다.', 4, '창녕의 관산 서원 터에서 매주(埋主) 시설이 발견되었습니다. 이 시설은 서원에 모셔져 있던 신주를 옹기에 넣고 기와로 둘러싼 뒤 묻은 것입니다. 이번 발굴로 만동묘 철거 이후 서원을 철폐하던 시기에 신주를 어떻게 처리했는지 알 수 있게 되었습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 29, '(가)에 들어갈 내용으로 가장 적절한 것은?', 2, '남북접이 논산에 집결하다', '황토현 전투에서 승리하다', '백산에 모여 4대 강령을 선포하다', '최시형이 동학의 2대 교주가 되다', '교조 신원을 요구하는 삼례 집회가 열리다', 1, '(영상 콘텐츠) 1894, 녹두꽃 피고 지다. 낡은 체제와 외세의 압박에 맞섰던 농민들, 그들이 이끈 변혁의 과정을 시간의 흐름에 따라 재구성해 본다. 1부 고부 민란이 일어나다 / 2부 전주성을 점령하다 / 3부 (가) / 4부 우금치에서 패배하다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 30, '다음 상황 이후의 사실로 옳은 것은?', 3, '알렌의 건의로 광혜원이 세워졌다.', '박문국에서 한성순보가 발행되었다.', '무기 제조 공장인 기기창이 설립되었다.', '서울과 부산을 연결하는 경부선이 개통되었다.', '우편 사무를 관장하는 우정총국이 처음 설치되었다.', 4, '(대화) 전화 설비 가설 및 운영권을 가진 한성 전기 회사가 설립되더니 새로운 직업이 생기는군. / 새로운 문물이 계속 들어오니 앞으로 더 많은 변화가 나타나겠군. (모집 공고: 전화를 연결해주는 교환수를 모집합니다. 지원 자격: 목소리가 분명하고 신체가 튼튼한 자. 광무 6년)', '근대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 31, '다음 상황이 전개된 배경으로 옳은 것은?', 2, '정미 7조약이 체결되었다.', '일제가 105인 사건을 조작하였다.', '초대 총독으로 데라우치가 부임하였다.', '기유각서가 일제의 강압에 의해 조인되었다.', '일진회가 한일 합방을 촉구하는 성명을 발표하였다.', 1, '박승환은 병대(兵隊)에 대한 해산 소식을 듣고 통곡하며 부하들에게 말하기를, "이제 국가가 망하였는데도 일본인 하나를 죽이지 못하였으니 죽어도 그 죄를 씻지 못할 것이다. 나는 차마 제군들이 병대를 떠나도록 놓아둘 수 없다. 차라리 내가 죽고 말겠다."라고 하면서 결국 자결하였다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 32, '밑줄 그은 ''이 개혁''의 내용으로 옳은 것은?', 2, '지계아문을 설립하였다.', '대한국 국제를 반포하였다.', '건양이라는 연호를 제정하였다.', '개혁 추진 기구로 교정청을 설치하였다.', '군제를 개편하여 5군영을 2영으로 통합하였다.', 3, '(대화) 고종실록에 1895년 12월의 기록이 없어. 1895년 11월 16일 다음 날이 1896년 1월 1일이야. 어떻게 된 거지? / 그건 당시 추진된 이 개혁으로 태양력이 도입되었기 때문이야.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 33, '밑줄 그은 ''이곳''에서 있었던 민족 운동으로 옳은 것은?', 2, '대종교 계열의 중광단이 결성되었다.', '권업회가 조직되어 권업신문을 창간하였다.', '사회주의 계열의 한인 사회당이 조직되었다.', '독립군 양성을 위한 신흥 무관 학교가 설립되었다.', '대조선 국민군단이 조직되어 무장 투쟁을 준비하였다.', 5, '(우리 가족의 역사) 옆 사진은 우리 할머니의 젊을 때 모습이에요. 할머니는 19살 때 사진만 보고 할아버지랑 결혼하기로 한 뒤 당시 포와(布?)라고 불리던 이곳으로 가셨대요. 할아버지는 이미 1903년에 갤릭호를 타고 이곳으로 가셔서 사탕수수 농장에서 일하고 계셨어요. 두 분은 고된 환경에서도 열심히 일해 호놀룰루에 터전을 잡으셨고 지금도 많은 친척이 살고 있어요.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 34, '다음 기사가 나오게 된 배경으로 적절한 것은?', 1, '3·1 운동이 전국적으로 전개되었다.', '조선 사상범 예방 구금령이 시행되었다.', '브나로드 운동이 동아일보를 중심으로 추진되었다.', '조선 노동 총동맹과 조선 농민 총동맹이 설립되었다.', '내선일체를 강조한 황국 신민 서사의 암송이 강요되었다.', 1, '(대화) 총독의 임용 범위를 확장하고, 지방 자치 제도를 실시한다. …… 이로써 관민이 서로 협력 일치하여 조선에서 문화적 정치의 기초를 확립한다. / 아무리 그럴듯하게 내세워도 이러한 통치 방식은 결국 우리 조선인을 기만하는 거야.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 35, '(가)~(다)를 작성된 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (가) - (나)', 2, '(자료로 보는 대한민국 임시 정부) (가) 국무령에 이상룡이 취임하다 / (나) 대일 선전(宣戰) 성명서를 발표하다 / (다) 창사에서 광저우로 청사를 이전하다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 36, '(가) 단체에 대한 설명으로 옳은 것은?', 1, '조선 혁명 선언을 활동 지침으로 삼았다.', '일제의 황무지 개간권 요구를 저지하였다.', '복벽주의를 내세우며 의병 전쟁을 준비하였다.', '삼균주의를 기초로 하는 건국 강령을 발표하였다.', '단원인 이봉창이 일왕의 행렬에 폭탄을 투척하였다.', 1, '(밀양 폭탄 사건 공판 기록, 1921년 6월 7일) 검사: 폭탄을 구해 숨겨 놓은 이유가 무엇인가? / 곽재기: 재작년 3월 이후로 조선 독립을 평화적으로 요청했지만 아무 소용없었다. 그래서 우리는 상하이로 가서 육혈포와 폭탄을 구해 피로써 독립을 이루려고 하였다. / 이성우: 폭탄으로 고위 관리를 죽이고 중요 건물을 파괴하여 독립을 쟁취하려고 하였다. 이것이 중국 지린성에서 김원봉과 함께 (가) 을/를 조직한 이유이다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 37, '밑줄 그은 ''시기''에 시행된 일제의 정책으로 옳은 것은?', 2, '애국반을 조직하여 한국인의 생활을 통제하였다.', '강압적 통치를 목적으로 헌병 경찰 제도를 실시하였다.', '사회주의자를 탄압하기 위한 치안 유지법을 제정하였다.', '회사 설립 시 총독의 허가를 받도록 하는 회사령을 공포하였다.', '근대적 토지 소유권 확립을 명분으로 토지 조사 사업을 시행하였다.', 1, '(신문 기사) 나가사키에 원폭 희생자 위령비 세워져. 재일본 대한민국 민단 주도로 나가사키에 위령비가 세워졌다. 국민 징용령이 공포된 이후의 시기에 노동자 등으로 끌려갔다가 원폭으로 희생된 한국인을 추모하는 이 비의 건립은 강제 동원과 전쟁의 참상을 기억하려는 노력의 일환으로 평가된다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 38, '(가)에 대한 설명으로 옳은 것은?', 2, '영릉가 전투에서 일본군에게 승리하였다.', '중국 팔로군에 편제되어 항일 전선에 참여하였다.', '국내 정진군을 편성하여 국내 진공 작전을 추진하였다.', '중국 관내(關內)에서 결성된 최초의 한인 무장 부대이다.', '간도 참변 이후 밀산에서 집결하여 자유시로 이동하였다.', 3, '(대화) 이 부부의 활동에 대해 말씀해 주시겠습니까? / 두 사람은 지청천을 총사령관으로 하여 충칭에서 창립된 (가) 에서 첩보 담당 및 주석 비서로 활동하였습니다. 특히 오희영은 부모, 동생이 모두 독립운동가이기도 합니다. (인물: 오희영, 신송식)', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 39, '다음 자료의 상황이 나타나게 된 배경으로 적절한 것은?', 2, '허정 과도 정부에서 헌법이 개정되었다.', '통일 주체 국민 회의에서 대통령이 선출되었다.', '유엔 소총회에서 남한만의 단독 총선거가 결의되었다.', '유상 매수, 유상 분배 원칙의 농지 개혁법이 제정되었다.', '국가 보안법 개정안을 통과시킨 보안법 파동이 일어났다.', 3, '우리는 조국 흥망의 관두(關頭)에서 이 위기를 극복하기 위해 오직 민족 자결 원칙에 의하여 조국의 남북통일과 민주 독립을 촉진해야겠다. 우리 민족자주연맹 중앙집행위원회는 김구 선생과 김규식 박사의 제안에 의하여 실현되는 남북 정치 협상을 전적으로 지지하며, 아울러 그 성공을 위하여 적극적으로 협력할 것을 결의한다. (관두: 가장 중요한 지점)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 40, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '좌우 합작 위원회가 출범하였다.', '여수 순천 10·19 사건이 일어났다.', '미국 의회에서 트루먼 독트린이 발표되었다.', '베트남 파병에 관한 브라운 각서가 체결되었다.', '거제도 포로 수용소에 있던 반공 포로가 석방되었다.', 5, '(가) 군사적 안전 보장의 입장에서 볼 때 태평양 지역의 정세 및 이 지역에 대한 미국의 정책은 어떤 것인가. 태평양 지역 방위선은 알류샨 열도에서 일본을 거쳐 오키나와, 필리핀 군도로 이어진다.
(나) 상호적 합의에 의하여 미합중국의 육군, 해군과 공군을 대한민국의 영토 내와 그 부근에 배치하는 권리를 대한민국은 허락해 주고 미합중국은 수락한다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 41, '밑줄 그은 ''선거'' 이후의 사실로 옳은 것은?', 3, '국회에서 국민 방위군 사건이 폭로되었다.', '평화 통일론을 내세우던 진보당이 해체되었다.', '경찰이 반민족 행위 특별 조사 위원회를 습격하였다.', '조선 건국 준비 위원회 지부가 인민 위원회로 개편되었다.', '초대 대통령에 한해 중임 제한을 폐지하는 개헌안이 통과되었다.', 2, '(대화) 이번 선거에 자유당, 민주당 후보 등 여러 명이 출마했군. / 여당은 현 대통령의 3선을, 야당은 정권 교체를 주장하고 있군.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 42, '밑줄 그은 ''집회''가 열린 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 3, '이 사진은 남북 학생 회담을 요구하는 집회 장면입니다. 당시 대학생들은 판문점에서 만나자는 구호를 외치며 협상을 통한 자주적인 통일을 주장하였으나, 정부는 남북 총선거에 의한 평화 통일 정책을 제시하였습니다.
(연표) 대한민국 정부 수립(1948) - 발췌 개헌(1952) - 4·19 혁명(1960) - 6·3 시위(1964) - 10월 유신(1972) - 부마 민주 항쟁(1979). (가)=1948~1952, (나)=1952~1960, (다)=1960~1964, (라)=1964~1972, (마)=1972~1979.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 43, '다음 명령을 실행한 정부의 경제 정책으로 옳은 것은?', 2, '제3차 경제 개발 5개년 계획을 추진하였다.', '미국과 자유 무역 협정(FTA)을 체결하였다.', '귀속 재산 처리를 위해 신한 공사를 설립하였다.', '최저 임금 결정을 위한 최저 임금 위원회를 설치하였다.', '금융 거래의 투명성을 확보하고자 금융 실명제를 실시하였다.', 1, '이것은 경제 관련 긴급 명령을 발표하는 사진입니다. 경부 고속 도로 개통 등으로 경제 발전에 힘쓰던 당시 정부는 사채에 허덕이는 기업을 구제하기 위해 사채 신고를 독려하고 그 상환을 동결시켜 주었습니다. 이로써 기업의 재무 구조가 개선되었으나 정경 유착이 심해지는 계기가 되기도 하였습니다.', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 44, '(가) 민주화 운동에 대한 설명으로 옳은 것은?', 1, '신군부의 비상계엄 확대가 원인이 되어 일어났다.', '관련 기록물이 유네스코 세계 기록 유산으로 등재되었다.', '3·15 부정 선거에 항의하며 시위대가 경무대로 행진하였다.', '3·1 민주 구국 선언을 통해 긴급 조치 철폐 등을 요구하였다.', '호헌 철폐와 독재 타도 등의 구호를 내세운 시위가 확산되었다.', 5, '((가)의 현장을 찾아서. 일시: 매주 토요일 10:00. 참가 대상: 시민 누구나) 명동 성당(박종철 고문 은폐 조작 발표 장소) → 향린 교회(민주 헌법 쟁취 국민운동 본부 발기인 대회 개최지) → 성공회 성당(6·10 국민 대회가 시작된 곳).', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 45, '다음 뉴스가 보도된 시기 정부의 통일 노력으로 옳은 것은?', 2, '민족 자존과 통일 번영을 위한 7·7 선언을 발표하였다.', '최초의 이산가족 고향 방문과 예술 공연단 교환을 실현하였다.', '남북 정상 회담을 개최하고 6·15 남북 공동 선언을 채택하였다.', '7·4 남북 공동 성명을 실천하기 위한 남북 조절 위원회를 구성하였다.', '남북 사이의 화해와 불가침 및 교류·협력에 관한 합의서를 교환하였다.', 3, '(뉴스) 한·미 정상, 도라산역 방문. 오늘 대통령은 경의선 복원 사업의 일환으로 건설된 도라산역을 미국의 부시 대통령과 함께 방문하였습니다. 정부는 이 역의 준공으로 우리나라가 유라시아와 태평양을 연결하는 물류의 중심지로 도약할 수 있을 것이라고 밝혔습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 46, '㉠~㉤에 대한 학생들의 의견으로 적절하지 않은 것은?', 2, '갑: ㉠ - 백제를 멸망시키고 통일의 기초를 마련했어요.', '을: ㉡ - 고려 건국의 위업을 이루었어요.', '병: ㉢ - 탕평책 등 여러 개혁으로 통치 체제를 재정비했어요.', '정: ㉣ - 원 황실의 부마가 되었어요.', '무: ㉤ - 중종반정으로 폐위되었어요.', 5, '(역사 속 왕의 호칭) 왕이 세상을 떠난 뒤 그 이름을 높여 부르는 호칭을 묘호라고 한다. 원칙적으로 나라를 세운 왕은 ''조''를, 그 나머지는 ''종''을 붙였다. 우리나라 역사에서 처음으로 묘호를 쓴 왕은 신라의 ㉠태종 무열왕이다. 고려 시대는 ㉡태조만 조의 묘호가 붙여졌지만, 조선 시대에는 다양한 이유로 ㉢정조처럼 조를 붙인 왕이 여럿 있었다. 그러나 고려 후기에는 ㉣충렬왕처럼 조, 종을 붙이지 못한 왕들이 있었으며, 조선 시대에는 연산군, ㉤광해군처럼 묘호를 받지 못하고 군으로 격하되어 불린 경우도 있었다.', '통합', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 47, '(가) 신분에 대한 설명으로 옳은 것은?', 2, '신라에서 승진에 제한을 받았으며, 득난이라고도 불렸다.', '고려 시대에 향, 부곡, 소에 거주하였으며, 과중한 세금을 부담하였다.', '조선 시대에 봉수, 역졸의 업무를 주로 담당하였다.', '조선 후기에 통청 운동으로 청요직 진출을 시도하였다.', '조선 순조 때 궁방과 중앙 관서에 소속된 6만여 명이 해방되었다.', 5, '(대화) 나는 방호별감 김윤후입니다. 몽골군의 침입에 맞서 충주산성을 방어할 때 (가) 의 신분 문서를 불태워 그들의 사기를 높였습니다. / 나는 군국기무처의 총재 김홍집입니다. 신분 차별 폐지에 대한 요구를 수용하여 (가) 에 관한 법을 폐지하였습니다.', '통합', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 48, '다음 세시 풍속에 대한 탐구 활동으로 가장 적절한 것은?', 2, '칠석날의 전설을 검색한다.', '한식날의 의미를 파악한다.', '삼짇날의 유래를 알아본다.', '동짓날에 먹는 음식을 조사한다.', '단오날에 즐기는 민속놀이를 찾아본다.', 3, '(이달의 세시 풍속) 푸른 새잎을 밟는 날, 답청절(踏靑節). 강남 갔던 제비가 돌아온다는 중삼일(重三日)은 본격적인 봄의 시작을 알리는 날이다. 이날에는 들에 나가 푸른 새잎을 밟는 풍습이 있어 답청절이라고 부른다. 답청의 풍습은 신윤복의 <연소답청(年少踏靑)>에 잘 나타나 있다. 날짜: 음력 3월 3일. 음식: 화전, 쑥떡. 풍속: 노랑나비 날리기, 활쏘기.', '통합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 49, '다음 지역에서 있었던 사실로 옳은 것은?', 3, '인조가 피신하여 청군과 항전하였다.', '유생 출신 유인석이 의병을 일으켰다.', '정문부가 왜군에 맞서 북관대첩을 이끌었다.', '김광제 등을 중심으로 국채 보상 운동이 시작되었다.', '왕건이 후백제를 배후에서 견제하기 위해 차지하였다.', 5, '(답사 보고서) 주제: 우리 고장의 역사. 개관: 금성산과 영산강을 끼고 있는 우리 고장은 삼한 시대부터 마한의 주요 지역 가운데 하나로 발전하였고, 후삼국 시대에는 격전지였으며, 임진왜란과 일제 강점기에는 항일의 의기가 드높았던 지역이다. ''전라도''라는 이름은 전주와 우리 고장의 앞 글자를 딴 것이다. 목차: 1. 마한 세력의 성장, 반남면 고분군 2. 목(牧)의 관아 부속 건물 3. 광주 학생 항일 운동의 도화선, ○○역.', '통합', '지역사', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (58, 50, '(가) 섬에 대한 설명으로 옳지 않은 것은?', 1, '안용복이 일본에 건너가 우리 영토임을 주장하였다.', '영국군이 러시아를 견제하기 위해 불법 점령하였다.', '러일 전쟁 때 일본이 불법으로 자국 영토로 편입하였다.', '대한 제국이 칙령을 통해 울릉 군수가 관할하도록 하였다.', '1877년 태정관 문서에 일본과는 무관한 지역임이 명시되었다.', 2, '1946년 1월에 작성된 연합국 최고 사령부 문서에는 제주도, 울릉도, (가) 이/가 우리 영토로 표시되어 있습니다. (가) 은/는 우리나라 동쪽 끝에 있는 섬입니다.', '통합', '지역사', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 1, '밑줄 그은 ''이 시대''의 생활 모습으로 옳은 것은?', 1, '철제 무기로 정복 활동을 벌였다.', '주로 동굴이나 막집에서 거주하였다.', '명도전을 이용하여 중국과 교역하였다.', '반달 돌칼을 사용하여 벼를 수확하였다.', '빗살무늬 토기를 제작하여 식량을 저장하였다.', 2, '충청북도 청주시 오송읍에서 주먹도끼, 찍개 등 이 시대의 대표적 유물인 뗀석기가 다수 발굴되었습니다. 이번 발굴로 청주시 일대에 이 시대의 유적이 다수 분포되어 있음을 알 수 있습니다.', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 2, '(가) 나라에 대한 설명으로 옳은 것은?', 2, '무천이라는 제천 행사를 열었다.', '신성 지역인 소도가 존재하였다.', '남의 물건을 훔쳤을 때는 12배로 갚게 하였다.', '왕 아래 상가, 대로, 패자 등의 관직이 있었다.', '전국 7웅 중 하나인 연과 대립할 만큼 강성하였다.', 5, '우리 역사상 최초의 국가인 (가) 을/를 건국한 단군왕검의 이야기가 뮤지컬로 탄생하였습니다. - 순서 - 1막 환웅이 신단수로 내려오다 2막 웅녀, 환웅과 혼인하다 3막 단군왕검이 나라를 세우다', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 3, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '당이 안동도호부를 설치하였다.', '나당 연합군이 사비성을 함락하였다.', '신라가 매소성 전투에서 승리하였다.', '고구려가 신라에 침입한 왜를 격퇴하였다.', '백제와 왜의 연합군이 백강 전투에서 패배하였다.', 2, '(가) 대야성에서 패하였을 때 도독인 품석의 아내도 죽었는데, 바로 춘추의 딸이었다. [김춘추가] 말하기를, "신이 고구려에 사신으로 가서 군사를 청하여 백제에 원수를 갚고자 합니다."라고 하자 왕이 허락하였다. / (나) 복신은 일찍이 군사를 거느렸는데, 이때 승려 도침과 함께 주류성에 근거하여 반란을 일으키고, 왜국에 있던 왕자 부여풍을 맞이하여 왕으로 세웠다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 4, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '천리장성 축조를 감독하였다.', '살수에서 수의 군대를 막아냈다.', '등주를 선제 공격하여 당군을 격파하였다.', '황산벌에서 계백이 이끄는 군대를 물리쳤다.', '안승을 왕으로 추대하고 부흥 운동을 전개하였다.', 1, '이 그림은 명 대 간행된 소설에 실린 「막리지비도대전」입니다. 그림에서 당 태종을 향해 위협적으로 칼을 날리고 있는 모습으로 묘사된 인물이 (가) 입니다. 이 그림을 통해 당시 중국인들이 그를 어떤 존재로 인식하고 있는지 엿볼 수 있습니다. (가) 은/는 영류왕을 시해하고 대막리지가 되어 권력을 장악한 뒤, 당의 침략을 격퇴하였습니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 5, '밑줄 그은 ''왕''의 활동으로 옳은 것은?', 2, '익산에 미륵사를 창건하였다.', '평양성 전투에서 고국원왕을 전사시켰다.', '사비로 천도하고 국호를 남부여로 고쳤다.', '북위에 사신을 보내 고구려 공격을 요청하였다.', '동진에서 온 마라난타를 통해 불교를 수용하였다.', 3, '왕 31년 7월에 신라가 동북쪽 변경을 빼앗아 신주(新州)를 설치하였다. …… [이듬해] 7월에 왕이 신라를 습격하려고 몸소 보병과 기병 50명을 거느리고 밤에 구천(狗川)에 이르렀다. 신라의 복병이 일어나 더불어 싸웠으나 [적의] 병사들에게 살해되었다. - 『삼국사기』 -', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 7, '(가) 왕의 업적으로 옳은 것은?', 3, '국가적인 조직으로 화랑도를 개편하였다.', '지방관을 감찰하고자 외사정을 파견하였다.', '이차돈의 순교를 계기로 불교를 공인하였다.', '인재 등용을 위해 독서삼품과를 실시하였다.', '자장의 건의로 황룡사 구층 목탑을 건립하였다.', 2, '답사 계획서 - 주제: (가) 의 자취를 따라서 / 개관: 삼국 통일의 위업을 달성한 (가) 의 발자취를 찾아가는 일정입니다. 주요 답사지: 월성(반월성, 왕이 거처한 궁성), 동궁과 월지(왕이 건설한 별궁), 감은사지(왕을 기리기 위해 아들 신문왕이 완성한 사찰의 터), 대왕암(왕의 수중릉으로 알려진 곳)', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 8, '다음 자료에 나타난 시기의 경제 상황으로 옳은 것은?', 2, '은병이 화폐로 제작되었다.', '낙랑과 왜에 철을 수출하였다.', '집집마다 부경이라는 창고가 있었다.', '덕대가 광산을 전문적으로 경영하였다.', '울산을 통해 아라비아 상인들이 왕래하였다.', 5, '장보고가 귀국 후 왕을 알현하여, "온 중국이 우리나라 사람을 노비로 삼고 있습니다. 바라옵건대 청해에 진을 설치하여 해적이 사람을 중국으로 잡아가는 것을 막으십시오."라고 아뢰었다. 왕이 장보고에게 군사 1만 명을 주어서 지키게 하였다.', '고대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 9, '(가) 국가에 대한 설명으로 옳은 것은?', 2, '9서당과 10정을 설치하였다.', '광평성 등의 정치 기구를 마련하였다.', '교육 기관으로 주자감을 설립하였다.', '욕살, 처려근지 등의 지방관을 두었다.', '지방에 22담로를 두어 왕족을 파견하였다.', 3, '이곳은 해동성국이라 불렸던 (가) 의 온돌 유적으로 함경남도 신포시 오매리에서 발견되었습니다. 이 유적에서는 열기가 지나가는 통로인 고래의 숫자를 늘려서 난방의 효율을 높였다는 사실을 확인할 수 있습니다. 이는 (가) 이/가 고구려의 온돌 양식을 계승하여 발전시켰다는 사실을 잘 보여줍니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 10, '(가)~(라)를 일어난 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다) - (라)', '(가) - (나) - (라) - (다)', '(나) - (가) - (라) - (다)', '(나) - (다) - (가) - (라)', '(다) - (라) - (나) - (가)', 4, '(가) 처음으로 직관(職官)과 산관(散官) 각 품의 전시과를 제정하였다. …… 과등(科等)에 미치지 못한 자는 모두 전지 15결을 지급하였다. / (나) 역분전을 제정하였는데, 통일할 때의 조신(朝臣)이나 군사들은 관계(官階)를 따지지 않고 그 사람의 성품과 행동의 선악과 공로의 크고 작음을 보고 차등 있게 지급하였다. / (다) 쌍기가 의견을 올리니 처음으로 과거를 시행하였다. 시(詩)·부(賦)·송(頌) 및 시무책으로 시험하여 진사를 뽑았으며, 겸하여 명경업·의업·복업 등도 뽑았다. / (라) 왕이 말하기를, "비록 내 몸은 궁궐에 있지만 마음은 언제나 백성에게 치우쳐 있다. …… 이에 지방 수령들의 공(功)에 의지해 백성들의 소망에 부합하고자 12목 제도를 시행한다."라고 하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 11, '다음 대화에 등장하는 왕이 추진한 정책으로 옳은 것은?', 3, '천수라는 독자적 연호를 사용하였다.', '관학을 진흥하고자 양현고를 설치하였다.', '주전도감을 설치하여 해동통보를 발행하였다.', '호족 세력을 견제하기 위해 노비안검법을 실시하였다.', '국자감을 성균관으로 개칭하고 유학 교육을 장려하였다.', 3, '신이 싸움에서 진 이유는 적들은 기병인데 우리는 보병이라 대적할 수가 없었기 때문입니다. 새로운 부대의 창설이 필요합니다. …… 그렇다면 그대의 의견대로 별무반을 창설하여 여진과 맞서도록 하라.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 12, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '김부식이 묘청의 반란을 진압하였다.', '강조가 정변을 일으켜 김치양을 제거하였다.', '망이·망소이가 공주 명학소에서 봉기하였다.', '서희가 외교 담판을 벌여 강동 6주를 확보하였다.', '최충헌이 봉사 10조를 올려 시정 개혁을 건의하였다.', 1, '(가) 이자겸과 척준경이 왕을 위협하여 남궁(南宮)으로 거처를 옮기게 하고 안보린, 최탁 등 17인을 죽였다. 이 외에도 죽인 군사가 헤아릴 수 없을 정도였다. / (나) 이의방과 이고가 정중부를 따라와 몰래 말하기를, "오늘날 문신들은 득의양양하여 술을 취하도록 마시고 음식을 배불리 먹는데, 무신들은 모두 굶주리고 고달프니 이것을 어찌 참을 수 있습니까."라고 하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 13, '밑줄 그은 ''왕''의 재위 시기에 있었던 사실로 옳은 것은?', 1, '경기에 한하여 과전법이 실시되었다.', '정지가 관음포에서 승리를 거두었다.', '국정 총괄 기구로 교정도감이 설치되었다.', '신돈을 중심으로 전민변정 사업이 추진되었다.', '만권당이 설립되어 원과 고려의 학자가 교유하였다.', 4, '얼마 전에 왕께서 기철과 그 일당들을 반역죄로 숙청하셨다고 하네. / 나도 들었네. 정동행성 이문소도 철폐하셨다고 하더군.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 14, '(가)에 대한 고려의 대응으로 옳은 것은?', 2, '처인성에서 살리타를 사살하였다.', '박위를 파견하여 근거지를 토벌하였다.', '개경을 방어하기 위해 나성을 축조하였다.', '삼수병으로 구성된 훈련도감을 설치하였다.', '강화도로 도읍을 옮겨 장기 항전을 준비하였다.', 3, '현종 2년에 (가) 의 군주가 크게 군사를 일으켜 정벌하러 오자 왕이 남쪽으로 피란하였는데, (가) 군대는 여전히 송악성에 주둔하고 물러가지 않았습니다. 이에 현종이 여러 신하와 함께 더할 수 없는 큰 바람을 담아 대장경을 새겨서 완성할 것을 맹세한 뒤에야 적의 군대가 스스로 물러갔습니다. - 『동국이상국집』 -', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 16, '(가) 기구에 대한 설명으로 옳은 것은?', 2, '역사서 편찬과 보관을 주관하였다.', '주로 국방과 군사 문제를 논의하였다.', '화폐, 곡식의 출납과 회계를 담당하였다.', '좌사정, 우사정의 이원적인 체제로 운영되었다.', '최우에 의해 설치되어 인사 행정을 처리하였다.', 2, '고려의 독자적 정치 기구인 (가) 에 대해 말해 보자. / 중서문하성의 재신과 중추원의 추밀이 참여했어. / 고려 후기에 도평의사사로 개편되었어.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 17, '다음 자료에 나타난 시기의 사회 모습으로 옳은 것은?', 2, '최충이 9재 학당을 설립하였다.', '빈민 구제를 위해 흑창이 설치되었다.', '대각국사 의천이 천태종을 개창하였다.', '만적이 개경에서 신분 해방을 도모하였다.', '지배층을 중심으로 변발과 호복이 유행하였다.', 5, '인후는 …… 처음 이름은 홀랄대였다. 제국공주의 겁령구였는데, 겁령구는 중국 말로 사적으로 소속된 사람이다. 제국공주를 따라와서 중랑장에 임명되었다. 왕이 그를 장군으로 임명하고 싶어 이름을 바꾸라고 명령하자, 홀랄대가 대장군 인공수에게 말하기를 "내가 당신과 친한 사이이니 그대의 성을 빌리면 어떻겠소?"라고 하고, 드디어 성명을 바꾸어 인후라 하였다. [인후는] 장순룡 및 차신과 더 좋은 저택을 짓기 위해 경쟁하였는데, 사치스러움과 분수에 넘치는 것이 극에 달하였다.', '고려', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 18, '밑줄 그은 ''역사서''에 대한 설명으로 옳은 것은?', 1, '편년체 형식으로 기술되었다.', '고조선의 건국 이야기가 서술되었다.', '남북국이라는 용어가 처음 사용되었다.', '왕명에 의해 고승들의 전기가 기록되었다.', '고구려 시조의 일대기가 서사시로 표현되었다.', 2, '이곳은 경상북도 군위군에 위치한 인각사로 승려 일연이 마지막 여생을 보낸 곳입니다. 그는 불교사를 중심으로 민간 설화 등을 수록한 역사서를 저술하였습니다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 19, '밑줄 그은 ''임금''의 재위 시기에 있었던 사실로 옳은 것은?', 2, '명의 신종을 제사하는 대보단이 설치되었다.', '백과사전류 의서인 의방유취가 편찬되었다.', '왕권 강화를 위해 6조 직계제가 실시되었다.', '조선의 기본 법전인 경국대전이 반포되었다.', '역대 문물제도를 정리한 동국문헌비고가 간행되었다.', 3, '얼마 전에 임금께서 원통하고 억울한 일을 당한 백성들을 위해 신문고를 설치하라고 명하셨다더군. / 뿐만 아니라 문하부를 없애고 의정부를 설치하면서 문하부 낭사를 사간원으로 독립시키셨다네.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 20, '밑줄 그은 ''이 사건'' 이후의 사실로 옳은 것은?', 2, '최영에 의해 이인임 일파가 축출되었다.', '최무선의 건의로 화통도감이 설치되었다.', '정도전 등이 요동 정벌 계획을 추진하였다.', '성삼문 등이 상왕의 복위를 꾀하다가 처형되었다.', '이종무가 왜구의 근거지인 쓰시마섬을 정벌하였다.', 4, '이 작품은 두만강 유역의 여진을 정벌하고 6진을 개척한 김종서가 지은 시조로, 장수로서의 호방한 기개를 보여주고 있습니다. 그는 수양대군, 한명회 등이 주도한 이 사건으로 죽임을 당하였습니다. (삭풍은 나모 긋틱 불고 명월은 눈 속에 찬듸 만리변성에 일장검 집고 서서 긴 프람 큰 훈 소릭에 거칠 거시 업세라)', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 21, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '서인이 반정을 일으켜 정권을 장악하였다.', '위훈 삭제를 주장한 조광조 일파가 제거되었다.', '이인좌를 중심으로 한 일부 소론 세력이 난을 일으켰다.', '폐비 윤씨 사사 사건을 빌미로 김굉필 등이 처형되었다.', '희빈 장씨 소생의 원자 책봉 문제로 환국이 발생하였다.', 4, '(가) 유자광이 김종직의 조의제문을 구절마다 풀이해서 아뢰기를, "감히 이와 같은 부도한 말을 했으니, 청컨대 법에 의하여 죄를 다스리시옵소서. 이 문집 및 판본을 다 불태워버리고 간행한 사람까지 아울러 죄를 다스리기를 청합니다."라고 하였다. / (나) 박원종 등이 궐문 밖에 진군하여 대비(大妃)에게 아뢰기를, "지금 임금이 도리를 잃어 정치가 혼란하고, 민생은 도탄에 빠지고, 종사는 위태롭습니다. 진성대군은 대소 신민의 촉망을 받은 지 이미 오래이므로, 이제 추대하고자 하오니 감히 대비의 분부를 여쭙니다."라고 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 22, '다음 기사에 나타난 시기의 경제 상황으로 옳은 것은?', 1, '금속 화폐인 건원중보가 주조되었다.', '솔빈부의 말이 특산물로 수출되었다.', '담배, 고추 등 상품 작물이 재배되었다.', '당항성, 영암이 국제 무역항으로 번성하였다.', '수도의 시전을 감독하기 위해 경시서가 설치되었다.', 3, '역사 신문 - 초량으로 왜관 이전 결정. 오늘 왕이 두모포 왜관의 초량 이전을 윤허하였다. 두모포 왜관은 일본과 국교가 재개되면서 새로 지은 왜관으로 기유약조 이후 일본과의 제한된 교역이 이루어지던 곳이다. 그러나 두모포 왜관이 협소하다며 이전을 요구하는 왜인들의 잦은 요청이 있어 마침내 오늘 초량으로 이전을 결정하였다.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 23, '(가) 국가에 대한 조선의 정책으로 옳은 것은?', 2, '어영청을 중심으로 북벌을 추진하였다.', '한성에 동평관을 두어 무역을 허용하였다.', '조약 체결에 대한 답례로 보빙사를 보냈다.', '공녀를 보내기 위해 결혼도감을 설치하였다.', '포로 송환을 위해 회답 겸 쇄환사를 파견하였다.', 1, '이 비석은 (가) 의 요청으로 나선 정벌에 참여했던 총병관 신유를 기리기 위한 신도비입니다. 이 비에는 그의 조총 부대가 흑룡강 일대에서 러시아군과의 전투를 승리로 이끌었다는 사실이 기록되어 있습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 24, '(가) 왕이 추진한 정책으로 옳은 것은?', 2, '친위 부대로 장용영을 설치하였다.', '경기도에 한해서 대동법을 실시하였다.', '한양을 기준으로 한 역법서인 칠정산을 만들었다.', '통치 체제를 정비하기 위해 대전회통을 편찬하였다.', '직전법을 제정하여 현직 관리에게만 수조권을 지급하였다.', 1, '궁궐 속 역사 이야기 - 만천명월주인옹 자서. 이것은 창덕궁 후원의 존덕정 현판에 새겨져 있는 글이다. (가) 이/가 지은 것으로 군주를 모든 하천에 비치는 달에 비유하여 국왕 중심의 정국 운영을 강조하는 내용이 담겨 있다. 그는 초계문신제를 실시하여 자신의 정책을 뒷받침하는 인재를 양성하고자 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 25, '밑줄 그은 ''이 시기''의 문화에 대한 설명으로 옳은 것은?', 1, '원각사지 십층 석탑이 건립되었다.', '인왕제색도 등 진경 산수화가 그려졌다.', '주자소가 설치되어 계미자가 주조되었다.', '표면에 백토를 바른 분청사기가 유행하였다.', '청주 흥덕사에서 직지심체요절이 간행되었다.', 2, '춘향전 등 한글 소설이 유행했던 이 시기에 대해 이야기해 볼까요? / 소설책을 빌려주는 세책가가 성행하였어요. / 저잣거리에서 한글 소설을 읽어주는 전기수가 인기를 끌었어요.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 26, '(가) 기구에 대한 설명으로 옳은 것은?', 2, '업무 일지인 내각일력을 작성하였다.', '사헌부, 사간원과 함께 3사로 불렸다.', '소속 관원은 은대 학사라고도 칭하였다.', '흥선 대원군이 집권한 시기에 혁파되었다.', '국왕 직속 사법 기구로 중죄인을 다스렸다.', 4, '역사 용어 해설 - (가). 1. 개요: 중종 때 삼포왜란을 계기로 설치되었다. 을묘왜변을 겪으면서 상설 기구화되었고, 양 난을 거치며 국정을 총괄하는 기구로 발전하였다. 2. 관련 사료: 중외(中外)의 군국 기무를 모두 관장한다. …… 도제조는 현임과 전임 의정(議政)이 겸하고, 제조는 정원에 제한이 없으며 임금에게 보고하여 임명한다. 이·호·예·병·형조 판서, 양국 대장, 양도 유수, 대제학은 당연히 겸직한다. - 『속대전』 -', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 27, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '규장각의 검서관으로 활동하였다.', '양명학을 연구해 강화학파를 형성하였다.', '의산문답에서 중국 중심의 세계관을 비판하였다.', '북한산비가 진흥왕 순수비임을 처음으로 밝혀냈다.', '체질에 따라 치료를 달리하는 사상 의학을 확립하였다.', 1, '(가) 은/는 널리 배워 시를 잘 짓고 전고(典故)에도 밝았다. …… 발해고를 지어서 인물과 군현, 왕실 계보의 연혁 등을 상세하게 잘 엮어서 두루 모아놓으니 기뻐할 만하다. 그런데 그의 말에 왕씨가 고구려의 옛 강역을 회복하지 못하였음을 탄식한 부분이 있다. 왕씨가 옛 강역을 회복하지 못하니 계림과 낙랑의 옛터가 마침내 어두워져 스스로 천하와 단절되었다는 것이다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 28, '다음 대화에 나타난 사건에 대한 설명으로 옳은 것은?', 1, '홍경래, 우군칙 등이 주도하였다.', '청군이 파병되는 결과를 가져왔다.', '제물포 조약이 체결되는 배경이 되었다.', '보국안민, 제폭구민을 기치로 내걸었다.', '박규수가 안핵사로 파견되는 계기가 되었다.', 1, '[교사 발표 조사] 19세기 초 세도 정치기에 있었던 수탈과 홍포에 대한 저항이었어요. / 서북 지방민에 대한 차별이 한 원인이었다고 합니다. / 한 때 청천강 이북 지역을 차지할 정도로 위세를 떨쳤지만 정주성에서 관군에게 진압되었습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 29, '(가)~(라) 사건에 대한 설명으로 옳은 것을 <보기>에서 고른 것은? ㄱ.(가)-삼정이정청이 설치되는 계기가 되었다. ㄴ.(나)-무신 집권기 지배층의 수탈에 대한 저항이었다. ㄷ.(다)-윤원형 일파가 정국을 주도한 시기에 발생하였다. ㄹ.(라)-주모자가 드러나지 않기 위해 사발통문을 작성하였다.', 3, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 4, '(가) 나라 안의 모든 주군(州郡)에서 공물과 부세를 보내지 않아 창고가 비고 재정이 궁핍해졌다. 왕이 관리를 보내 독촉하니 곳곳에서 도적이 벌떼처럼 일어났다. 이때 원종, 애노 등이 사벌주를 근거지로 반란을 일으켰다. / (나) 남쪽에서 적(賊)들이 봉기하였다. 가장 심한 자들은 운문을 거점으로 한 김사미와 초전을 거점으로 한 효심이었다. 이들은 유랑민을 불러 모아 주현(州縣)을 습격하여 노략질하였다. / (다) 임술년 2월 19일, 진주 백성 수만 명이 머리에 흰 수건을 두르고 손에는 나무 몽둥이를 들고 무리를 지어 진주 읍내에 모여 서리들의 가옥 수십 호를 불사르고 부수니, 그 움직임이 심상치 않았다. / (라) 군수 조병갑이 탐학이 심하여 군민들이 그 주구에 시달려왔다. …… 전봉준은 백성을 이끌고 일어나 관아를 습격하고 관청에서 쌓은 보를 허물어 버렸다.', '복합', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 30, '다음 상황이 나타난 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 1, '북경 주재 프랑스 공사가 청에 보내온 문서에 의하면, "조선에서 프랑스 주교 2명 및 선교사 9명과 조선의 많은 천주교 신자가 처형되었다. 이에 제독에게 요청하여 며칠 안으로 군대를 일으키도록 할 것이다."라고 되어 있습니다. (연표) 고종 즉위(1863) - 오페르트 도굴 사건(1868) - 신미양요(1871) - 운요호 사건(1875) - 조미 수호 통상 조약(1882) - 조프 수호 통상 조약(1886). (가)=1863~1868, (나)=1868~1871, (다)=1871~1875, (라)=1875~1882, (마)=1882~1886.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 31, '다음 검색창에 들어갈 조약에 대한 설명으로 옳은 것은?', 1, '최혜국 대우를 최초로 규정하였다.', '통감부가 설치되는 계기가 되었다.', '천주교 포교 허용의 근거가 되었다.', '일본 경비병의 공사관 주둔을 명시하였다.', '부산 외 2곳에 개항장이 설치되는 결과를 가져왔다.', 5, '한국사 사전 - 조약. 이칭: 조일 수호 조규. 체결 연도: 1876년. 협상 대표: 신헌, 구로다 기요타카. 주요 조항 - 제1관 조선국은 자주국이며 일본국과 평등한 권리를 가진다. 제7관 조선국 연해를 일본국의 항해자가 자유롭게 측량하도록 허가한다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 32, '다음 상황 이후에 전개된 사실로 옳은 것은?', 2, '신식 군대인 별기군이 폐지되었다.', '김기수를 수신사로 일본에 파견하였다.', '이항로와 기정진이 척화주전론을 주장하였다.', '왕비가 궁궐을 빠져 나와 장호원으로 피신하였다.', '개화당 정부가 수립되고 개혁 정강이 발표되었다.', 5, '17일에 홍 참판이 우정총국에서 개국 연회를 열었다. 그동안에 [담장 밖에서] 화재가 발생했다. 민 참판은 양해를 구한 뒤 화재 진압을 돕기 위해 밖으로 나갔다. 바깥에는 연회에 참석한 일본 공사를 호위하기 위해 온 일본 병사들이 두 줄로 늘어서 있었고, 그는 그들을 지나쳤다. 민 참판은 양쪽에서 공격을 받았고, …… 몸 여러 군데에 자상을 입었다. - 『조지 클레이튼 포크의 일기』 -', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 33, '밑줄 그은 ''개혁''의 내용으로 옳은 것은?', 2, '원수부를 설치하였다.', '기기창을 설립하였다.', '공사 노비법을 혁파하였다.', '태양력을 공식 채택하였다.', '한성 사범 학교 관제를 반포하였다.', 5, '김홍집과 박영효를 중심으로 구성된 내각에서 여러 개혁을 추진했다더군. / 수령의 권한을 축소시키고 재판소를 설치했다고 들었네.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 34, '밑줄 그은 ''그''의 활동으로 옳은 것은?', 2, '5적 처단을 위해 자신회를 조직하였다.', '명동 성당 앞에서 이완용을 습격하였다.', '하얼빈에서 이토 히로부미를 사살하였다.', '타이완에서 일본 육군 대장을 저격하였다.', '동양 척식 주식회사에 폭탄을 투척하였다.', 1, '저는 지금 전라남도 보성군에 와 있습니다. 이 기념관은 오기호 등과 함께 대종교를 창시하고 일생을 독립운동에 바친 그를 기리기 위해 조성되었습니다. 이곳에는 그의 호를 딴 홍암사라는 사당이 있습니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 35, '(가) 단체에 대한 설명으로 옳은 것은?', 2, '일본 도쿄에서 독립 선언서를 발표하였다.', '일제가 제정한 치안 유지법으로 탄압받았다.', '서간도에 신흥 강습소를 세워 독립군을 양성하였다.', '독립운동 자금을 모으기 위해 독립 공채를 발행하였다.', '조선 총독에게 제출하기 위해 국권 반환 요구서를 작성하였다.', 5, '이것은 고종이 임병찬에게 내린 밀지의 일부입니다. 그는 이 밀지를 받고 복벽주의를 내건 (가) 을/를 조직하였습니다. (애통하다! 일본 오랑캐가 배신하고 함병하니 종사가 폐허가 되고 국민은 노예가 되었다. …… 짐이 믿는 것은 너희들이니, 너희들은 힘써 광복하라.)', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 36, '다음 상황이 나타나게 된 배경으로 가장 적절한 것은?', 2, '조선 의용대가 호가장 전투에서 활약하였다.', '대한 독립군 등이 봉오동에서 일본군을 격파하였다.', '조선 혁명군이 영릉가에서 일본군에 승리를 거두었다.', '한국 독립군이 대전자령 전투에서 일본군을 격퇴하였다.', '대한민국 임시 정부가 직할 부대로 참의부를 결성하였다.', 2, '경신년 시월에 일본 토벌대들이 전 만주를 휩쓸어 애국지사들은 물론이고 농민들도 무조건 잡아다 학살하였다. …… 독립군의 성과가 컸기 때문에 그에 대한 보복으로 일본군이 대학살을 감행한 것이었다. 이것이 이른바 경신참변이다. 그래서 애국지사들은 가족들을 두고 단신으로 길림성 오상현, 흑룡강성 영안현 등으로 흩어졌다. - 『아직도 내 귀엔 서간도 바람소리가』 -', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 37, '밑줄 그은 ''이 시기''에 볼 수 있는 모습으로 적절한 것은?', 2, '영선사 일행으로 청에 가는 생도', '육영 공원에서 영어를 공부하는 학생', '거문도를 불법 점령하고 있는 영국 해군', '양전 사업을 실시하고 지계를 발급하는 관리', '보은 집회에서 교조 신원을 주장하는 동학교도', 4, '별빛 석조전 야행 - 황제로 즉위한 고종이 부국강병을 위해 개혁을 추진하며 이 시기에 황궁의 정전으로 만들어 사용하고자 하였던 석조전에 초대합니다. 별빛이 내려앉은 석조전에서 색다른 정취를 느껴 보시기 바랍니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 38, '다음 자료에 나타난 상황 이후의 사실로 옳은 것은?', 3, '메가타가 재정 고문으로 부임하였다.', '고종이 러시아 공사관으로 거처를 옮겼다.', '베델과 양기탁이 대한매일신보를 창간하였다.', '관민 공동회가 개최되어 헌의 6조를 결의하였다.', '민종식이 이끄는 의병 부대가 홍주성을 점령하였다.', 5, '오늘 신문에 강화(講和) 조약 전문이 공개되었다. 러시아는 일본이 조선에서 갖고 있는 막대한 정치적·군사적·경제적 이익을 인정하고, 일본이 조선의 내정을 지도·보호 및 감리(監理)하는 데 필요하다고 여기는 어떠한 조치도 방해하거나 간섭하지 않을 것을 약속하였다. …… 러시아는 전쟁으로 교훈을 얻었다. 일본은 전쟁으로 영예를 얻었다. 조선은 전쟁으로 최악의 것을 얻었다. - 『윤치호 일기』 -', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 39, '(가) 종교에 대한 설명으로 옳은 것은?', 1, '만세보를 발행하여 민중 계몽에 힘썼다.', '중광단을 조직하여 무장 투쟁을 전개하였다.', '배재 학당을 세워 신학문 보급에 기여하였다.', '박중빈을 중심으로 새생활 운동을 추진하였다.', '일제의 통제에 맞서 사찰령 폐지 운동을 주도하였다.', 1, '이곳은 동학에서 시작된 종교인 (가) 소속의 방정환, 김기전 등이 인내천 사상을 바탕으로 1922년 ''어린이날''을 선포한 장소입니다. 그들은 어린이들과 함께 이곳에서 출발하여 거리 행진을 하며 선전문을 배포한 뒤 어린이날 제정 축하 기념회를 열었습니다.', '일제', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 40, '(가) 인물에 대한 설명으로 옳은 것은?', 3, '일본의 침략 과정을 담은 한국통사를 저술하였다.', '조선학 운동을 주도하여 여유당전서를 간행하였다.', '백산 상회를 설립하여 독립운동 자금을 마련하였다.', '친일 인사 스티븐스를 샌프란시스코에서 사살하였다.', '대한민국 임시 정부에서 내무총장 겸 국무총리 대리로 취임하였다.', 5, '여행권(여권)을 통해 본 독립운동가의 삶 - 위 자료들은 독립운동가 (가) 이/가 사용한 여행권으로 미국, 중국, 멕시코 등 많은 국가들을 방문한 기록이 남아 있다. (가) 은/는 여러 국가들을 이동하면서 공립 협회, 대한인 국민회, 흥사단 등을 조직하는 데 주도적인 역할을 담당하였다. 1937년 동우회 사건으로 옥고를 치른 후 지병이 악화되어 이듬해 사망하였다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 41, '밑줄 그은 ''시기''에 시행된 일제의 정책으로 옳은 것은?', 2, '회사령을 제정하였다.', '미쓰야 협정을 체결하였다.', '경성 제국 대학을 설립하였다.', '토지 조사 사업을 실시하였다.', '조선 사상범 예방 구금령을 공포하였다.', 5, '이 자료는 중일 전쟁 이후 일제가 침략 전쟁을 확대하던 시기에 만든 황국 신민 제조 실시 요령입니다. 일제는 이 제조를 보급하기 위해 ''황국 신민 제조의 날''을 정하고 전국 곳곳에서 강습회를 개최하였습니다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 42, '(가) 지역에 대한 탐구 활동으로 가장 적절한 것은?', 1, '정약전이 자산어보를 저술한 곳을 알아본다.', '프랑스군이 외규장각 도서를 약탈한 장소를 살펴본다.', '지주 문재철에 맞서 소작 쟁의가 일어난 곳을 찾아본다.', '4·3 사건으로 많은 주민이 희생된 주요 장소를 조사한다.', '러시아가 저탄소 설치를 위해 조차를 요구한 곳을 검색한다.', 4, '역사를 품은 섬, (가) 다크 투어를 떠나볼까요? - 황파두리 항몽 유적, 알뜨르 비행장 비행기 격납고(출발), 송악산 해안 동굴 진지, 섯알 오름 일제 고사포 진지(도착). 일시: 매월 첫째 주 토요일 10시. 출발 장소: 관덕정 앞 광장. 유의 사항: 마스크, 도시락 지참 필수. ※다크 투어: 전쟁이나 테러, 인종 말살, 재난처럼 비극적인 역사의 현장을 방문하여 반성과 교훈을 얻는 여행.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 43, '(가) 부대에 대한 설명으로 옳은 것은?', 2, '청산리에서 일본군에 맞서 대승을 거두었다.', '미군과 연계하여 국내 진공 작전을 계획하였다.', '쌍성보 전투에서 한중 연합 작전을 전개하였다.', '중국 의용군과 연합하여 흥경성에서 승리하였다.', '동북 항일 연군으로 개편되어 유격전을 펼쳤다.', 2, '인도 전선에서 (가) 이/가 활동에 나선 이래, 각 대원은 민족의 영광을 위해 빗발치는 탄환도 두려워하지 않고 온갖 고초를 겪으며 영국군의 작전에 협조하였다. (가) 은/는 적을 향한 육성 선전, 방송, 전단 살포, 포로 신문, 정찰, 포로 훈련 등 여러 부분에서 상당한 성과를 거두었다. 그 결과 영국군 당국은 우리를 깊이 신임하고 있으며, 한국 독립에 대해서도 동정을 아끼지 않고 있다. 충칭에 거주하고 있는 한국 청년 동지들이 인도에서의 공작에 다수 참여하기를 희망한다. - 『독립신문』 -', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 44, '밑줄 그은 ''이 전쟁'' 중에 있었던 사실로 옳은 것은?', 3, '한미 상호 방위 조약이 체결되었다.', '반민족 행위 특별 조사 위원회가 해체되었다.', '통일 주체 국민 회의에서 대통령이 선출되었다.', '비상 계엄이 선포된 가운데 발췌 개헌안이 통과되었다.', '국가보안법 개정안을 통과시킨 이른바 보안법 파동이 일어났다.', 4, '노래로 읽는 한국사 - 이별의 부산 정거장. (해설) 이 곡은 이 전쟁의 정전 협정이 체결된 이듬해에 발표된 노래로, 낯선 부산에서의 판잣집 피란살이를 마치고 서울로 떠나는 피란민의 심정을 애절하게 묘사하였습니다. 피란살이는 힘들었지만 부산에서 만난 사람들과의 인연이 힘이 되었다는 가사를 담고 있습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 45, '밑줄 그은 ''이 사건''이 일어난 시기를 연표에서 옳게 고른 것은?', 3, '(가)', '(나)', '(다)', '(라)', '(마)', 2, '1. 이 사건은 검찰이 아무런 증거도 없이 공소 사실도 특정하지 못한 채 조봉암 등 진보당 간부들에 대해 국가 변란 혐의로 기소하였고 …… 5. 이 사건은 정권에 위협이 되는 야당 정치인을 제거하려는 의도에서 표적 수사에 나서 극형에 처한 것으로 민주국가에서 있어서는 안 될 비인도적, 반인권적 인권 유린이자 정치 탄압 사건이다. 6. 국가는 …… 피해자와 유가족에게 총체적으로 사과하고 화해를 이루는 등 적절한 조치를 취하여야 하며, 명예를 회복시키기 위해 형사소송법이 정한 바에 따라 재심 등 상응한 조치를 취하는 것이 필요하다. - 『진실·화해를 위한 과거사 정리 위원회 조사보고서』 - (연표) 대한민국 정부 수립(1948) - 사사오입 개헌(1954) - 4·19 혁명(1960) - 한일 기본 조약(1965) - 3선 개헌(1969) - 인민 혁명당 재건위 사건(1974). (가)=1948~1954, (나)=1954~1960, (다)=1960~1965, (라)=1965~1969, (마)=1969~1974.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 46, '밑줄 그은 ''이 정권'' 시기에 있었던 사실로 옳지 않은 것은?', 2, '신민당사에서 YH 무역 노동자들이 농성을 하였다.', '민주 회복을 위한 개헌 청원 백만인 서명 운동이 전개되었다.', '호헌 철폐, 독재 타도를 내세운 6·10 국민 대회가 개최되었다.', '야당 총재의 국회의원직 제명을 계기로 민주 항쟁이 일어났다.', '긴급 조치 철폐를 요구하는 3·1 민주 구국 선언이 발표되었다.', 3, '양심 선언문 - 들으라! 우리는 유신 헌법의 잔인한 폭력성을, 합법을 가장한 유신 헌법의 모든 부조리와 악을 고발한다. 우리는 유신 헌법의 비민주적 허위성을 고발한다. …… 우리 대한 학도는 민족과 역사 앞에 분연히 선언한다. 이 정권이 끝날 때까지 후퇴치 못하고 이 민족을 끝까지 못살게 군다면 자유와 평등과 정의를 뜨겁게 외치는 이 땅의 모든 시민의 준엄한 피의 심판을 면치 못하리라.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 47, '㉠~㉤에 대한 탐구 활동으로 적절하지 않은 것은?', 2, '㉠ - 해동제국기의 작성 목적을 파악한다.', '㉡ - 하멜 표류기의 내용을 분석한다.', '㉢ - 프랑스 파리 외방 선교회의 활동을 알아본다.', '㉣ - 혼일강리역대국도지도가 제작된 과정을 조사한다.', '㉤ - 제너럴 셔먼호 사건 관련 자료를 찾아본다.', 4, '역사 돋보기 - 조선이 만난 이방인. 조선 전기에는 외부 세계와의 관계가 중국과 일본을 중심으로 류큐 등의 아시아 국가에 주로 국한되어 있었다. ㉠조선인의 외부에 대한 인식은 이들 국가에 집중되어 있었고, 조선은 중국을 비롯한 주변 국가 이외의 세계에서는 낯선 존재였다. 조선 후기에 들어 지리 지식의 확대와 더불어 조선인의 외부 세계에 대한 인식이 점차 넓어져 갔다. 첫째, 중국과 일본을 오가던 ㉡서양 선박이 난파하여 조선에 표착한 경우이다. 둘째, 크리스트교 선교를 목적으로 ㉢선교사가 직접 조선에 파견되는 경우이다. 셋째, 서양인이 ㉣조선의 해안 측량을 목적으로 해안을 탐사하는 과정에서 접촉한 경우이다. 넷째, 조선과의 ㉤교역을 목적으로 서양의 상선이 접근하는 경우이다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 48, '교사의 질문에 대한 학생의 답변으로 옳은 것은?', 2, '인조가 이괄의 난으로 피란했어요.', '견훤이 후백제의 도읍으로 삼았어요.', '김윤후와 함께 관노들이 몽골군에 항전했어요.', '강주룡이 을밀대 지붕에서 고공농성을 벌였어요.', '박재혁이 경찰서에서 폭탄을 터뜨리는 의거를 일으켰어요.', 3, '이것은 1872년에 제작된 우리 고장의 지방도입니다. 임진왜란 때 신립 장군이 왜군과 맞서 싸우다 투신한 장소인 탄금대와 임경업 장군의 충절을 기리기 위해 세운 충렬사 등이 표시되어 있습니다. 우리 고장에서 있었던 사실을 말해 볼까요?', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 49, '다음 뉴스가 보도된 정부 시기에 있었던 사실로 옳은 것은?', 3, '서울 올림픽 대회가 개최되었다.', '국가 인권 위원회가 설립되었다.', '전국 민주 노동조합 총연맹이 창립되었다.', '중국과 자유 무역 협정(FTA)이 체결되었다.', '친일 반민족 행위 진상 규명 위원회가 출범하였다.', 5, '오늘 헌법 재판소는 헌정 사상 초유의 대통령 탄핵 소추 심판 청구에 대해 기각을 결정하였습니다. 국회가 제기한 탄핵 사유는 대통령을 파면시킬 만한 ''중대한 직무상 위배''라고 보기 어렵다는 판단입니다. (대통령, 63일 만에 직무 복귀)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (59, 50, '다음 연설이 있었던 정부의 통일 노력으로 옳은 것은?', 2, '남북 조절 위원회를 구성하였다.', '남북한이 유엔에 동시 가입하였다.', '판문점에서 남북 정상 회담을 개최하였다.', '남북한 교류 협력을 위한 개성 공단 조성에 합의하였다.', '남북 이산가족 고향 방문단의 교환 방문을 최초로 실현하였다.', 4, '저는 지난 6월 13일 역사적인 평양 방문을 이룩했습니다. 평양을 방문할 때 저는 참으로 만감이 교차하였습니다. 분단된 조국의 땅을 처음으로 가게 된 것도 그렇고, 또 과연 이 회담에서 성공을 거둘 수 있을지 많은 염려도 갖고 북한을 방문했던 것입니다. …… 지난 6월의 평양 회담 이후 우리 한국은 두 가지를 당면 목표로 추진하고 있습니다. 첫째는 남북 간의 긴장을 완화시키는 것입니다. …… 두 번째 당면 목표는 50년간의 단절과 불신과 적대로부터, 다시 교류와 신뢰와 동족애를 회복하는 것입니다. - ○○○ 대통령 스웨덴 의회 연설 -', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 1, '(가) 시대의 생활 모습으로 옳은 것은?', 1, '소를 이용하여 깊이갈이를 하였다.', '주로 동굴이나 바위 그늘에서 살았다.', '반달 돌칼을 사용하여 곡물을 수확하였다.', '빗살무늬 토기를 제작하여 식량을 저장하였다.', '주먹도끼, 찍개 등 뗀석기를 만들기 시작하였다.', 3, '이곳은 유네스코 세계유산으로 등재된 화순 고인돌 유적입니다. 여기에는 계급이 발생한 (가) 시대의 고인돌이 밀집되어 있고, 인근에서는 덮개돌을 캐낸 채석장이 발견되어 고인돌의 축조 과정을 살펴볼 수 있습니다.', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 2, '밑줄 그은 ''이 나라''에 대한 설명으로 옳은 것은?', 2, '신성 구역인 소도를 두었다.', '읍락 간의 경계를 중시하는 책화가 있었다.', '여러 가(加)들이 각각 사출도를 주관하였다.', '정사암 회의에서 국가의 중대사를 결정하였다.', '사회 질서를 유지하기 위해 범금 8조를 만들었다.', 3, '이것은 쑹화강 유역에 위치했던 이 나라의 유물로 고대인의 얼굴을 추정해 볼 수 있는 귀중한 자료입니다. 이 나라에는 영고라는 제천 행사와 형사취수제라는 풍속이 있었다고 전해집니다. (금동 얼굴 모양 장식)', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 3, '(가) 나라에 대한 설명으로 옳은 것은?', 2, '법흥왕 때 신라에 복속되었다.', '유학 교육 기관으로 주자감을 두었다.', '지방에 22담로를 두어 왕족을 파견하였다.', '화백 회의에서 국가의 중대사를 논의하였다.', '단궁, 과하마, 반어피 등의 특산물이 있었다.', 1, '국가문화유산포털 - 김해 양동리 고분군. 수로왕이 건국했다고 전해지는 (가) 의 유적이다. 발굴 조사 결과 널무덤, 독무덤 등 600여 기의 유구와 토기, 청동기, 철기 등 5,200여 점에 이르는 유물이 출토되었다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 4, '다음 상황 이후에 전개된 사실로 옳은 것은?', 3, '을지문덕이 살수에서 승리하였다.', '안승이 보덕국의 왕으로 임명되었다.', '관구검의 공격으로 환도성이 함락되었다.', '의자왕이 윤충을 보내 대야성을 함락하였다.', '계백이 이끄는 결사대가 신라군에 맞서 싸웠다.', 2, '소정방이 백제를 평정하자 흑치상지는 휘하의 무리를 이끌고 항복하였다. 소정방이 연로한 왕을 가두고 병사를 풀어 가혹하게 약탈하자, 이를 두려워한 흑치상지는 추장 10여 인과 함께 도망하여 임존산을 거점으로 반란을 일으켰다. 열흘 만에 휘하에 3만여 명이 모였으며 곧 200여 성을 되찾았다. 소정방이 병사를 이끌고 흑치상지를 공격하였지만 이기지 못하였다. - 『삼국사기』 -', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 5, '다음 검색창에 들어갈 왕에 대한 설명으로 옳은 것은?', 2, '도읍을 국내성에서 평양으로 옮겼다.', '낙랑군을 몰아내고 영토를 확장하였다.', '을파소의 건의로 진대법을 실시하였다.', '영락이라는 독자적 연호를 사용하였다.', '전진의 순도를 통해 불교를 수용하였다.', 1, '삼국사기 데이터베이스 - 고구려본기. 56년 신라의 실직주성을 빼앗다 / 60년 북위에 사신을 파견하다 / 63년 백제 도성을 함락시키다', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 6, '(가) 국가에 대한 설명으로 옳은 것은?', 1, '중정대를 두어 관리를 감찰하였다.', '군사 조직으로 9서당 10정을 편성하였다.', '내신 좌평 등 6좌평의 관제를 정비하였다.', '상수리 제도를 시행하여 지방 세력을 견제하였다.', '왕족인 부여씨와 8성의 귀족이 지배층을 이루었다.', 1, '□□ 박물관 VR 온라인 전시실 - 해동성국이라 불린 (가) 의 문화유산을 VR 파노라마로 체험하는 공간입니다. (영광탑, 정효 공주묘, 석등)', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 7, '밑줄 그은 ''이 승려''의 활동으로 옳은 것은?', 2, '무애가를 지어 불교 대중화에 기여하였다.', '화랑도의 규범으로 세속 5계를 제시하였다.', '구법 순례기인 왕오천축국전을 저술하였다.', '승려들의 전기를 담은 해동고승전을 집필하였다.', '화엄일승법계도를 지어 화엄 사상을 정리하였다.', 5, '부석사는 당에서 유학하고 돌아온 이 승려가 왕명을 받들어 창건한 유서 깊은 사찰입니다. 여름밤 달빛 아래 문화유산의 정취를 느껴 보시기 바랍니다. (달빛 야행 특별 프로그램: 선묘 설화 미디어 아트 영상 관람, 무량수전 배흘림 기둥 열쇠고리 제작. 장소: 경상북도 영주시 부석사 경내)', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 8, '밑줄 그은 ''이 왕''의 업적으로 옳은 것은?', 2, '거칠부에게 국사를 편찬하게 하였다.', '이사부를 보내 우산국을 복속하였다.', '건원이라는 독자적 연호를 사용하였다.', '관료전을 지급하고 녹읍을 폐지하였다.', '관리 선발을 위해 독서삼품과를 실시하였다.', 4, '이 왕은 김흠돌의 난을 진압하고 왕권을 강화했어. / 아버지인 문무왕을 위하여 감은사를 완공했지. / 완산주와 청주를 설치하여 9주를 갖추었어.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 9, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '금마저에 미륵사를 창건하였다.', '후당과 오월에 사신을 파견하였다.', '일리천 전투에서 신검의 군대를 격파하였다.', '폐정 개혁을 목표로 정치도감을 설치하였다.', '광평성을 비롯한 각종 정치 기구를 마련하였다.', 5, '이 사진은 (가) 이/가 세운 태봉의 철원 도성 터에서 촬영된 석등입니다. 일제 강점기에 보물로 지정되기도 했으나 지금은 비무장지대 안에 있어 존재를 확인하기 어렵습니다. 관련 연구의 진전을 위해서는 남북한의 협력이 필요합니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 11, '(가)~(다)를 일어난 순서대로 옳게 나열한 것은?', 2, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (가) - (나)', 2, '(가) 백관을 소집하여 금을 섬기는 문제에 대한 가부를 의논하게 하니 모두 불가하다고 하였다. 이자겸, 척준경만이 "사신을 보내 먼저 예를 갖추어 찾아가는 것이 옳습니다."라고 하니 왕이 이 말을 따랐다. / (나) 나세·심덕부·최무선 등이 왜구를 진포에서 공격해 승리를 거두고 포로 334명을 구출하였으며, 김사혁은 패잔병을 임천까지 추격해 46명을 죽였다. / (다) 몽골군이 쳐들어와 충주성을 70여 일간 포위하니 비축한 군량이 거의 바닥났다. 김윤후가 괴로워하는 군사들을 북돋우며, "만약 힘을 다해 싸운다면 귀천을 가리지 않고 모두 관작을 제수할 것이니 불신하지 말라."라고 하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 12, '㉠~㉤ 기구에 대한 설명으로 옳은 것은?', 2, '㉠ - 학술 기관으로 경연을 관장하였다.', '㉡ - 실록을 보관하고 관리하는 업무를 맡았다.', '㉢ - 관리의 비리를 감찰하고 풍기를 단속하였다.', '㉣ - 수도의 치안과 행정을 주관하였다.', '㉤ - 화폐와 곡식의 출납에 대한 회계를 담당하였다.', 3, '인물의 생애로 보는 고려의 정치 기구 (윤관) - 출생년 미상 / 1095년 ㉠삼사 좌사낭중 / 1101년 ㉡추밀원(중추원) 지주사 / 1102년 ㉢어사대 어사대부 / 1103년 ㉣한림원 학사승지 / 1108년 ㉤중서문하성 문하시중 / 1111년 별세', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 13, '밑줄 그은 ''시기''의 경제 상황으로 옳은 것은?', 1, '모내기법이 전국적으로 확산되었다.', '초량 왜관을 통해 일본과 무역하였다.', '감자, 고구마 등의 작물이 재배되었다.', '광산을 전문적으로 경영하는 덕대가 활동하였다.', '경시서의 관리들이 시전의 상행위를 감독하였다.', 5, '이달의 책 - 원의 간섭을 받던 시기에 이암이 우리나라에 소개했다고 전해지는 농서입니다. 원에서 편찬한 이 책은 경간(耕墾)·파종 등 10문(門)으로 구성되어 있으며, 화북 지방의 농법을 수록하고 있습니다. 특히 누에, 면화, 저마의 생산을 장려하고 있어 주목할 만합니다.', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 14, '(가) 시기에 있었던 사실로 옳은 것은?', 3, '화통도감이 설치되어 화포가 제작되었다.', '신돈이 전민변정도감의 설치를 건의하였다.', '거란이 침입하여 왕이 나주까지 피난하였다.', '노비안검법의 실시로 국가 재정이 확충되었다.', '신기군, 신보군, 항마군 등으로 구성된 별무반이 조직되었다.', 3, '이주정이 김지앙과 결탁한 것 같소. 그를 서북면 도순검사로 보내고 강조를 개경으로 불러 짐을 호위하게 하시오. / 귀주에서 외척을 크게 무찌른 강감찬과 장수들을 맞이할 연회를 준비하라. (가)', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 15, '다음 상황 이후에 전개된 사실로 옳은 것은?', 2, '삼별초가 용장성에서 항전하였다.', '정중부 등이 김보당의 반란을 진압하였다.', '빈민 구제를 위한 흑창을 처음 설치하였다.', '공주 명학소에서 망이·망소이가 봉기하였다.', '최충헌이 교정별감이 되어 국정을 총괄하였다.', 1, '백관이 최우의 집에 나아가 정년도목(政年都目)을 올리니, 최우가 청사에 앉아 받았다. 6품 이하는 당하(堂下)에서 두 번 절하고 땅에 엎드려 감히 고개를 들지 못하였다. 이때부터 최우는 정방을 자기 집에 두고 백관의 인사 행정을 처리하였다. - 『고려사절요』 -', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 16, '(가), (나)에 해당하는 토지 제도에 대한 설명으로 옳은 것은?', 3, '(가) - 조준 등의 건의로 제정되었다.', '(가) - 관등과 인품을 기준으로 수조권을 주었다.', '(나) - 개국 공신에게 역분전을 지급하였다.', '(나) - 지급 대상 토지를 원칙적으로 경기 지역에 한정하였다.', '(가), (나) - 수조권 외에 노동력을 징발할 수 있는 권한을 주었다.', 4, '(가) 문종 30년 양반 전시과를 다시 개정하였다. 제1과는 전지 100결, 시지 50결(중서령·상서령·문하시중) …… 제18과는 전지 17결(한인·잡류)로 한다. / (나) 공양왕 3년 도평의사사에서 글을 올려 과전의 지급에 관한 법 제정을 건의하니 왕이 허락하였다. …… 1품부터 9품의 산직까지 나누어 18과로 하였다.', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 17, '(가)에 들어갈 내용으로 옳은 것은?', 1, '불씨잡변을 지어 불교를 비판함', '인재 등용을 위해 현량과 실시를 제안함', '시무 28조를 올려 국가 운영 방안을 제시함', '지부복궐척화의소를 올려 왜양일체론을 주장함', '해주 향약을 시행하여 향촌 교화를 위해 노력함', 3, '고려 시대 유학자 - 최승로: (가) / 최충: 9재 학당을 설립하여 유학 교육에 힘씀 / 김부식: 유교 사관에 입각하여 삼국사기를 편찬함 / 안향: 고려에 처음으로 성리학을 도입함 / 이제현: 만권당에서 원의 학자들과 교류함', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 18, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '최윤덕이 4군을 개척하였다.', '일본 원정을 위해 정동행성이 설치되었다.', '몽골 사신 저고여가 귀국길에 피살되었다.', '철령위 설치 문제로 요동 정벌이 추진되었다.', '서희가 외교 담판으로 강동 6주를 획득하였다.', 2, '(가) 용진현 출신 조휘와 정주 출신 탁청이 화주 이북 지방을 몽골에 넘겨주었다. 몽골은 화주에 쌍성총관부를 설치하고 조휘를 총관으로, 탁청을 천호(千戶)로 임명하였다. / (나) 동북면 병마사 유인우가 쌍성을 함락시키자 총관 조소생, 천호 탁도경이 도망치니 화주, 등주, 정주 등이 수복되었다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 19, '(가) 궁궐에 대한 설명으로 옳은 것은?', 2, '근정전을 정전으로 하였다.', '일제에 의해 동물원 등이 설치되었다.', '후원에 왕실 도서관인 규장각이 있었다.', '도성 내 서쪽에 있어 서궐이라고 불렸다.', '인목 대비가 광해군에 의해 유폐된 장소이다.', 1, '대왕대비가 전교하였다. "(가) 은/는 우리 왕조에서 수도를 세울 때 맨 처음 지은 정궁이다. …… 그러나 불행하게도 전란에 의해 불타버린 후 미처 다시 짓지 못하여 오랫동안 뜻있는 선비들의 개탄을 자아냈다. …… 이 궁궐을 다시 지어 중흥의 큰 업적을 이루려면 여러 대신과 함께 의논해보지 않을 수 없다." - 『고종실록』 -', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 20, '밑줄 그은 ''전하''의 재위 기간에 있었던 사실로 옳은 것은?', 2, '국가의 기본 법전인 경국대전이 완성되었다.', '성삼문 등이 상왕의 복위를 꾀하다가 처형되었다.', '육의전을 제외한 시전 상인의 금난전권이 폐지되었다.', '반정 공신의 위훈 삭제를 주장한 조광조가 사사되었다.', '이조 전랑 임명을 둘러싸고 김효원과 심의겸이 대립하였다.', 1, '세종 대왕께서는 집현전 유신(儒臣)들에게 명하여 오례의를 상세히 정하게 하셨다. …… 예종 대왕과 우리 주상 전하께서 선왕의 뜻을 이어 이 방대한 책을 완성하게 하셨다. …… 예(禮)를 기술한 것은 3,300가지나 되지만, 그 요점은 길례·흉례·군례·빈례·가례 다섯 가지일 뿐이다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 21, '(가) 기구에 대한 설명으로 옳은 것은?', 2, '사간원, 홍문관과 함께 삼사로 불렸다.', '외국으로 가는 사신의 통역을 전담하였다.', '천문, 지리, 기후 등에 관한 사무를 맡았다.', '왕명 출납을 담당하는 왕의 비서 기관이었다.', '국왕 직속 사법 기구로 반역죄 등을 처결하였다.', 4, '은대계회도 - 이것은 우부승지 이헌보와 그가 속한 (가) 관원들의 친목 모임을 그린 그림이다. 상단에는 계회 모습이 그려져 있고, 중단에는 축하 시, 하단에는 도승지 등 계원의 관직과 성명이 기록되어 있다. 은대는 (가) 의 별칭이며, 정원으로 약칭되기도 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 22, '(가)~(마)에 대한 설명으로 옳지 않은 것은?', 2, '(가) - 권율이 후금군을 맞아 큰 전과를 거둔 곳이다.', '(나) - 병인박해 때 많은 천주교 신자가 처형된 장소이다.', '(다) - 6·25 전쟁 이후 조성된 국군 묘지에서 시작되었다.', '(라) - 판축 기법을 활용하여 성벽을 쌓은 백제 토성이다.', '(마) - 갈돌과 갈판 등이 출토된 신석기 시대 유적이다.', 1, '답사 계획서 - 주제: 한강을 따라 만나는 역사. 경로: 행주산성 → 절두산 순교 성지(잠두봉 유적) → 국립서울현충원 → 풍납동 토성 → 암사동 유적', '복합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 23, '(가) 인물에 대한 설명으로 옳은 것은?', 3, '기대승과 사단칠정 논쟁을 전개하였다.', '일본에 다녀와서 해동제국기를 편찬하였다.', '양명학을 연구하여 강화 학파를 형성하였다.', '기축봉사를 올려 명에 대한 의리를 내세웠다.', '무오사화의 발단이 된 조의제문을 작성하였다.', 1, '성학십도에 담긴 경(敬) 사상 특별전 - 〈연보〉 1501년 경상도 예안현 출생 / 1534년 문과 급제 / 1552년 성균관 대사성에 임명 / 1561년 도산 서당 설립 및 제자 양성 / 1570년 별세', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 24, '다음 검색창에 들어갈 인물의 활동으로 옳은 것은?', 2, '지봉유설에서 천주실의를 조선에 소개하였다.', '의산문답에서 중국 중심의 세계관을 비판하였다.', '양반전을 지어 양반의 허례와 무능을 풍자하였다.', '경세유표를 집필하여 국가 제도의 개혁 방향을 제시하였다.', '금석과안록에서 북한산비가 진흥왕 순수비임을 고증하였다.', 4, '한국사 강의 검색 결과 - 마진으로 죽을 뻔한 아이, 마과회통을 편찬하다(조선 시대 홍역과 천연두 치료법) / 강진 유배지에서 편지를 보내다(가족에 대한 각별한 사랑) / 목민심서를 저술하여 목민관의 자세를 논하다(지방관의 청렴과 근검, 애민 정신)', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 25, '다음 전쟁 중 있었던 사실로 옳은 것은?', 2, '김상용이 강화도에서 순절하였다.', '임경업이 백마산성에서 항전하였다.', '최영이 홍산 전투에서 크게 승리하였다.', '곽재우가 의병장이 되어 의령 등에서 활약하였다.', '신류가 조총 부대를 이끌고 흑룡강에서 전투를 벌였다.', 4, '적군은 세 길로 나누어 곧장 한양으로 향했는데, 산을 넘고 물을 건너 마치 사람이 없는 곳에 들어가듯 했다고 한다. 조정에서 지킬 수 있다고 믿은 신립과 이일 두 장수가 병권을 받고 내려와 방어했지만 중도에 패하여 조령의 험지를 잃고, 적이 중원으로 들어갔다. 이로 인해 임금의 수레가 서쪽으로 몽진하고 도성을 지키지 못하니, 불쌍한 백성들은 모두 흉적의 칼날에 죽어가고 노모와 처자식은 이리저리 흩어져 생사를 알지 못해 밤낮으로 통곡할 뿐이었다. - 『쇄미록』 -', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 26, '다음 지역에 대한 탐구 활동으로 옳은 것은?', 2, '장용영의 외영이 설치된 위치를 파악한다.', '홍경래가 난을 일으켜 점령한 지역을 알아본다.', '인조가 피신하여 청군과 항전을 벌인 곳을 찾아본다.', '태조의 어진을 모신 경기전이 건립된 장소를 조사한다.', '유계춘이 백낙신의 수탈에 맞서 봉기한 지역을 검색한다.', 4, '○○시 문화유산 홍보 채널 - 동고산성에서 찾아보는 후백제의 흔적 / 6·25 전쟁 중 소실된 전라 감영 복원 / 손교회에 세워진 전동 성당', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 27, '(가)~(라) 교육 기관에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은? ㄱ.(가)-신문왕이 인재 양성을 위해 설치하였다. ㄴ.(나)-전국의 부·목·군·현에 하나씩 설립되었다. ㄷ.(다)-공자 등 성현을 기리는 석전대제를 거행하였다. ㄹ.(라)-교육 입국 조서 반포를 계기로 세워졌다.', 3, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 2, '(가) 학생의 재학 연한은 9년으로 하되 우둔하여 깨우치지 못하는 자는 퇴학시키고, 재주와 기량은 있으나 아직 미숙한 자는 9년이 넘더라도 재학을 허락하였다. 관등이 대나마, 나마에 이르면 졸업하였다. / (나) 7재를 두었는데, 주역을 공부하는 여택재, 상서를 공부하는 대빙재, 모시(毛詩)를 공부하는 경덕재, 주례를 공부하는 구인재, 대례(戴禮)를 공부하는 복응재, 춘추를 공부하는 양정재, 무학을 공부하는 강예재이다. / (다) 입학생은 생원·진사인 상재생과 유학(幼學) 중에서 선발된 기재생으로 구분되었다. 이들은 동재와 서재에 기숙하면서 공부하였으며, 아침·저녁 식당에 들어가 서명하면 원점 1점을 얻었다. 원점 300점을 얻으면 관시(館試)에 응시할 수 있었다. / (라) 좌원과 우원을 두었는데, 좌원에는 젊은 현직 관리를, 우원에는 관직에 나아가지 않은 명문가 자제들을 입학시켰다. 외국인 3명을 교사로 초빙하였으며, 학생들은 졸업할 때까지 공원(公院)에서 학습에 전념하도록 하였다.', '복합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 28, '다음 상황이 나타난 시기에 볼 수 있는 모습으로 적절하지 않은 것은?', 1, '한글 소설을 읽어주는 전기수', '시사를 조직하여 활동하는 역관', '주전도감에서 해동통보를 만드는 장인', '왕조 교체를 예언한 정감록을 읽는 양반', '한강을 무대로 상업에 종사하는 경강상인', 3, '○ 집집마다 인삼을 심어서 돈을 물 쓰듯이 한다고 하는데, 재산을 만드는 방법으로는 이보다 나은 것이 없다고 한다. ○ 어제 울타리 밖의 몇 되지기 밭에 담배를 파종하였다. ○ 금년에는 목화가 풍년이 들었는데, 어제는 시장에서 25근에 100전이었다고 한다. - 『노상추일기』 -', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 29, '(가) 시기에 있었던 사실로 옳은 것은?', 3, '이괄이 반란을 일으켜 도성을 장악하였다.', '자의 대비의 복상 문제로 예송이 전개되었다.', '왕위 계승을 둘러싸고 왕자의 난이 발생하였다.', '이인좌를 중심으로 소론 세력 등이 난을 일으켰다.', '희빈 장씨 소생의 원자 책봉 문제로 환국이 발생하였다.', 4, '목호룡의 고변으로 조정이 떠들썩하는군. / 왕세제와 노론이 곤경에 처할지도 모르겠네. (가) / 대신들의 뜻을 헤아려 세자의 지위를 회복하고 시호를 사도라 하라.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 30, '다음 사건이 일어난 이후의 사실로 옳은 것은?', 2, '김기수가 일본에 수신사로 파견되었다.', '평양 관민이 제너럴 셔먼호를 불태웠다.', '일본 군함 운요호가 영종도를 공격하였다.', '박규수가 삼정이정청의 설치를 건의하였다.', '청과 일본 사이에 톈진 조약이 체결되었다.', 5, '우정국 총판 홍영식이 우정국의 개국 축하연을 열면서 각국의 공사도 초청했다. …… 8시를 알리는 종이 울리자 담장 밖에서 불길이 치솟았다. …… 우영사 민영익이 불을 끄려고 먼저 일어나서 문밖으로 나왔는데, 자객 다섯 명이 잠복하고 있다가 칼을 휘두르며 습격했다. 민영익이 중상을 입고 되돌아와서 대청 위에 쓰러졌다. - 『대한계년사』 -', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 31, '밑줄 그은 ''이 사건''에 대한 설명으로 옳은 것은?', 1, '청군의 개입으로 종결되었다.', '제물포 조약의 체결로 이어졌다.', '오페르트 도굴 사건이 계기가 되었다.', '양헌수 부대가 정족산성에서 적군을 물리쳤다.', '영국 함대가 거문도를 점령하는 배경이 되었다.', 4, '사료로 보는 한국사 - 매우 가난하게 보이는 강화도에서 각하에게 보내드릴 만한 것은 아무것도 없습니다. 그러나 조선 임금이 소유하고 있지만 거처하지 않는 저택의 도서관에는 매우 중요한 서적이 많이 소장되어 있습니다. 세심하게 공들여 꾸며진 340권을 수집하였으며 기회가 되는 대로 프랑스로 보내겠습니다. - G. 로즈 - [해설] 로즈 제독이 해군성 장관에게 보낸 서신의 일부이다. 프랑스군이 강화도를 침략한 이 사건 당시 외규장각 도서 등이 약탈되는 상황이 기록되어 있다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 32, '(가) 시기에 있었던 사실로 옳지 않은 것은?', 2, '대한국 국제를 반포하였다.', '황제 직속의 원수부를 설치하였다.', '이범윤을 간도 관리사로 파견하였다.', '지계아문을 설립하여 지계를 발급하였다.', '통역관 양성을 목적으로 동문학을 설립하였다.', 5, '고종은 이곳 환구단에서 황제 즉위식을 거행하고, 경운궁으로 국호를 (가) (으)로 선포했습니다. 환구단은 일제에 의해 철거되었고 지금은 황궁우가 외로이 남아 있습니다. (환구단, 황궁우)', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 33, '다음 자료에 나타난 사업에 대한 설명으로 옳은 것은?', 1, '독립 협회가 반대 운동을 전개하였다.', '재정 고문 메가타의 주도로 시행되었다.', '동양 척식 주식회사가 중심이 되어 실시하였다.', '은본위제가 본격적으로 실시되는 배경이 되었다.', '함경도 관찰사 조병식이 방곡령을 선포하는 계기가 되었다.', 2, '한국에서 유통되는 백동화에 대한 처분안을 들어보면, 갑(甲) 구 백동화는 1개당 신화폐 2전 5리의 비율로 교환한다. 을(乙) 부정한 구 백동화는 1개당 신화폐 1전의 비율로 매수한다. 매수를 바라지 않는 것은 정부가 그것을 절단하여 소유자에게 환부한다. 병(丙) 형체와 품질이 화폐라고 인정하기 어려운 것은 정부가 매수하지 않는다. …… 이른바 폐제(幣制) 개혁은 통화를 금절(禁絶)하여 소의 뿔을 바로잡으려다가 소를 죽이는 결과를 가져왔습니다. - 『한국 폐제 개혁에 관한 진정서』 -', '근대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 34, '다음 가상 뉴스에서 보도하는 사건이 일어난 시기를 연표에서 옳게 고른 것은? (연표) 1882 임오군란 - 1894 갑오개혁 - 1896 아관파천 - 1904 러일 전쟁 발발 - 1905 을사늑약 - 1910 국권 피탈. (가)=1882~1894, (나)=1894~1896, (다)=1896~1904, (라)=1904~1905, (마)=1905~1910.', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 5, '군대 해산에 대한 반발이 거세지고 있습니다. 오늘 시위대 대대장 박승환이 자결한 데 이어 시위대 부대원들이 해산을 거부하고 무장 봉기해 일본군과 남대문 일대에서 치열한 총격전을 벌이고 있습니다. (뉴스 속보: 군대 해산에 맞서 시위대 봉기)', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 35, '밑줄 그은 ''나''의 활동으로 옳은 것은?', 2, '여유당전서를 간행하고 조선학 운동을 주도하였다.', '유교의 개혁을 주장하는 유교 구신론을 제창하였다.', '조선사 편수회에 들어가 조선사 편찬에 참여하였다.', '조선사회경제사에서 식민 사학의 정체성론을 반박하였다.', '민중의 직접 혁명을 주장한 조선 혁명 선언을 작성하였다.', 5, '나는 일제 침략에 맞서 민족의식을 고취하기 위해, 국난을 극복한 영웅의 전기인 이순신전과 을지문덕전을 집필하였습니다. 또 조선상고사에서는 역사를 아(我)와 비아(非我)의 투쟁으로 정의하였습니다. (조선상고사, 이순신전)', '일제', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 36, '다음 기사가 보도된 이후의 사실로 옳은 것은?', 2, '미국에 보빙사를 파견하였다.', '베델이 대한매일신보를 창간하였다.', '이만손 등이 영남 만인소를 올렸다.', '신식 군대인 별기군(교련병대)이 창설되었다.', '통리기무아문을 설치하여 개혁을 추진하였다.', 2, '역사 신문 - 전차 운행 중 사망 사고 발생. 오늘 종로 거리를 달리던 전차에 다섯 살 난 아이가 치여 죽는 사고가 발생하였다. 이를 목격한 사람들이 격노하여 전차를 부수었고, 이어 달려오던 전차까지 전복시켜 파괴하고 기름을 뿌려 불태웠다. 동대문에서 성대한 개통식을 열고 전차를 운행한 지 한 달도 되지 않아 참혹한 사건이 발생한 것이다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 37, '밑줄 그은 ''이 시기''에 시행된 일제의 정책으로 옳은 것은?', 1, '애국반을 조직하였다.', '회사령을 시행하였다.', '치안 유지법을 제정하였다.', '미곡 공출제를 실시하였다.', '국가 총동원법을 공포하였다.', 2, '문학으로 만나는 한국사 - 선생님이 사벨(환도)을 차고 교단에 오르는 나라가 있는 것을 보셨습니까? 나는 그런 나라의 백성이외다. …… 교원의 허리에서 그 장난감 칼을 떼어놓을 언제일지? 숨이 막힙니다. - 『만세전』 - [해설] 이 소설에는 교원이 제복을 입고 칼을 차고 수업을 하던 이 시기의 모습이 담겨 있다. ''만세전''은 제목에서 알 수 있듯이 3·1운동 이전 식민지의 사회 현실을 담고 있다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 38, '(가) 민족 운동에 대한 설명으로 옳은 것은?', 2, '통감부의 탄압으로 중단되었다.', '국채 보상 기성회를 중심으로 전개되었다.', '자작회, 토산 애용 부인회 등이 활동하였다.', '한성 은행, 대한 천일 은행 등이 설립되는 계기가 되었다.', '일본, 프랑스 등지의 노동 단체로부터 격려 전문을 받았다.', 3, '이것은 경성 방직 주식회사의 광목 신문 광고야. ''우리가 만든 것 우리가 쓰자''라는 문구가 인상적이야. / 그래, 이 광고는 민족 기업을 육성해 경제적 자립을 이루려는 (가) 중에 등장했지.', '일제', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 39, '(가) 부대에 대한 설명으로 옳은 것은?', 3, '봉오동 전투에서 일본군을 격파하였다.', '총사령 양세봉의 지휘 아래 활동하였다.', '미군과 연계하여 국내 진공 작전을 계획하였다.', '조선 독립 동맹 산하의 군사 조직으로 개편되었다.', '간도 참변 이후 조직을 정비하고 자유시로 이동하였다.', 4, '이달의 독립운동가 - 호가장 전투에서 순국한 열사들. 중국 우한(武漢)에서 창설된 한인 무장 부대의 일부는 화북으로 이동하여 1941년 7월 타이항산에서 (가) 을/를 결성하였다. (가) 의 무장선전대로 활동하던 손일봉, 최철호, 박철동, 이정순은 호가장 전투에서 다른 대원들이 포위망을 벗어날 때까지 일본군과 싸우다 장렬히 순국하였다. 정부는 이들의 공훈을 기려 1993년 애국장을 추서하였다. (손일봉, 최철호, 박철동, 이정순)', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 40, '(가) 단체에 대한 설명으로 옳은 것은?', 2, '중일 전쟁 발발 이후에 조직되었다.', '조선 혁명 간부 학교를 설립하였다.', '이봉창, 윤봉길 등이 단원으로 활동하였다.', '대전자령 전투에서 일본군을 상대로 승리하였다.', '일제가 조작한 105인 사건으로 조직이 해체되었다.', 3, '이것은 (가) 소속 최익식이 관동군 사령관 등을 처단하기 위해 만주로 와 활동하던 중 김구에게 보낸 편지라고 하는데, 어떤 역사적 가치가 있나요? / 김구가 일제의 요인들을 제거하기 위해 만든 (가) 이/가 다양한 의거를 시도하였음을 보여주는 중요한 문서입니다. 그 가치를 인정받아 국가 등록문화재로 지정되었습니다. (약윤(김구의 가명))', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 41, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '여수·순천 10·19 사건이 일어났다.', '모스크바 3국 외상 회의가 개최되었다.', '반민족 행위 특별 조사 위원회가 출범하였다.', '좌우 합작 위원회가 좌우 합작 7원칙을 발표하였다.', '유엔 총회에서 인구 비례에 의한 남북 총선거가 의결되었다.', 4, '(가) □□ 일보 - 하지 중장, 특별 성명 발표. 오늘 오전 조선 주둔 미군 최고 사령관 하지 중장은 미소 공동 위원회 무기 휴회에 관한 중대 성명서를 발표하였다. 이는 덕수궁 석조전에서의 역사적인 개막 이후 49일 만의 일이다. / (나) □□ 일보 - 제2차 미소 공동 위원회 개막. 미소 공동 위원회는 제1차 회의가 무기 휴회 된 지 만 1년 16일 만인 오늘 오후 2시 정각에 시내 덕수궁 석조전에서 고대하던 제2차 회의의 역사적 막을 열었다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 42, '다음 사건이 일어난 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 1, '이날 본회의는 하오 8시 정각에 개의되어 전원 위원회의 ''발췌 조항 전원 합의'' 보고를 접수한 후 김종순 의원의 각 조항 설명이 있은 다음, 질의도 대체 토의도 아무것도 없이 …… 표결은 기립 표결로 작성하여 재석 166인 중 163표로써 실로 역사적인 결정을 보았다. 표결이 끝나자 신익희 임시 의장은 정중 침통한 태도로써 "본 헌법 개정안은 헌법 제98조 제3항에 의하여 결정된 것을 선포한다."고 최후의 봉을 힘있게 3타 하였으며 그 음성은 몹시도 떨렸다. (연표) 1948 5·10 총선거 - 1953 정전 협정 체결 - 1959 경향신문 폐간 - 1964 6·3 시위 - 1976 3·1 민주 구국 선언 - 1987 6·29 민주화 선언. (가)=1948~1953, (나)=1953~1959, (다)=1959~1964, (라)=1964~1976, (마)=1976~1987.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 43, '(가) 민주화 운동에 대한 설명으로 옳은 것은?', 2, '장면 내각이 출범하는 배경이 되었다.', '유신 체제가 붕괴되는 결과를 가져왔다.', '한일 국교 정상화에 반대하여 일어났다.', '신군부의 비상 계엄 확대가 원인이 되었다.', '호헌 철폐와 독재 타도 등의 구호를 내세웠다.', 1, '(가), 역사의 현장을 찾아서 - 답사 장소: 옛 경무대 앞(효자동 삼거리) → 옛 수송초등학교(종로구청) → 옛 국회의사당(서울시의회) → 옛 서울대 문리대(마로니에 공원). (경무대 앞 경찰의 발포, 시위에 참여한 수송초 학생, 고려대 학생 시위, 교수단 시위)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 44, '밑줄 그은 ''현행 헌법''에 대한 설명으로 옳은 것은?', 3, '내각 책임제를 채택하였다.', '대통령의 연임을 3회로 제한하였다.', '대통령에게 국회 해산권을 부여하였다.', '대통령의 임기를 7년 단임제로 정하였다.', '국회를 참의원과 민의원의 양원제로 규정하였다.', 3, '오늘의 헌법은 그 개정의 발의권이 사실상 대통령에게만 속해 있는 것이다. 이에 우리 국민은 이와 같이 헌법 개정 발의권으로부터의 소외를 극복하고 우리들의 천부의 권리를 제시하는 방법으로 대통령에게 현행 헌법의 개정을 요구하는 100만인 청원 운동을 전개하는 바이다. (장준하)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 45, '(가) 정부 시기의 경제 상황으로 옳은 것은?', 1, '한미 자유 무역 협정(FTA)이 체결되었다.', '저유가·저금리·저달러의 3저 호황이 있었다.', '원조 물자를 가공하는 삼백 산업이 발달하였다.', '대통령 긴급 명령으로 금융실명제가 실시되었다.', '농촌의 근대화를 표방한 새마을 운동이 전개되었다.', 5, '(가) 정부 발행 우표 모음첩 - 포항 종합 제철 준공, 경부 고속 도로 준공, 100억 달러 수출 달성', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 46, '(가)~(마)에 대한 설명으로 옳지 않은 것은?', 3, '(가) - 주자소를 설치하여 인쇄하였다.', '(나) - 대장도감에서 판각한 목판으로 찍었다.', '(다) - 청주 흥덕사에서 금속 활자로 간행하였다.', '(라) - 이천, 장영실 등이 제작한 활자로 인쇄하였다.', '(마) - 납으로 만든 활자를 사용해 박문국에서 발행하였다.', 1, '우리나라 인쇄 문화의 역사 - (가) 무구정광대다라니경 / (나) 팔만대장경 / (다) 직지심체요절 / (라) 자치통감(갑인자본) / (마) 한성순보', '복합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 47, '밑줄 그은 ''이 정부'' 시기에 있었던 사실로 옳지 않은 것은?', 2, '서울 올림픽이 개최되었다.', '야간 통행 금지가 해제되었다.', '박종철 고문 치사 사건이 발생하였다.', '프로 야구가 6개 구단으로 출범하였다.', '남북 이산가족 고향 방문이 최초로 이루어졌다.', 1, '천주교 정의 구현 전국 사제단과 민주 언론 운동 협의회가 이 정부에서 각 언론사에 하달한 보도지침 자료를 공개하는 기자회견 장면입니다. 이후 이 사건의 관련자들은 남영동 치안본부 대공분실로 연행되었고, 국가보안법 위반 등의 죄목으로 기소되어 고초를 겪었습니다. (보도지침 자료공개 기자회견)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 48, '다음 뉴스가 보도된 정부 시기에 있었던 사실로 옳은 것은?', 3, '제2차 남북 정상 회담이 개최되었다.', '경제 협력 개발 기구(OECD)에 가입하였다.', '남북 조절 위원회가 설치되어 통일 방안이 논의되었다.', '북방 외교를 추진하여 중국 등 사회주의 국가들과 수교하였다.', '남북한의 교류 협력을 위한 개성 공업 지구 건설에 합의하였다.', 4, '대통령은 오늘 남북 고위급 회담 타결 상황을 보고받고, 내일 북한 대표단을 접견하기로 했습니다. 청와대 고위 관계자는 남북 사이의 화해와 불가침 및 교류 협력에 관한 합의서 채택에 완전히 합의한 것은 남북 관계의 큰 전환을 이룬 것이라고 평가했습니다. (대통령, 내일 북한 대표단 접견)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 49, '(가)~(마)에 들어갈 내용으로 옳지 않은 것은?', 2, '(가) - 첨성대와 황룡사 구층 목탑을 세우다', '(나) - 가정 생활의 지혜를 담은 규합총서를 저술하다', '(다) - 재산을 기부하여 흉년에 굶주린 백성들을 구제하다', '(라) - 한국 광복군의 기관지 광복을 발행하다', '(마) - 임금 삭감에 저항하여 을밀대 지붕에서 농성하다', 4, '우리 역사 속의 여성들 〈차례〉 - 선덕 여왕, 우리나라 최초의 여왕 (가) / 이빙허각, 살림을 학문화한 실학자 (나) / 김만덕, 제주의 거상이자 자선가 (다) / 남자현, 의열 투쟁을 전개한 독립운동가 (라) / 강주룡, 일제 강점기의 노동 운동가 (마)', '복합', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (60, 50, '밑줄 그은 ''이날''에 해당하는 세시풍속으로 옳은 것은?', 1, '단오', '칠석', '백중', '동지', '한식', 2, '이곳은 남원 광한루원의 오작교입니다. 조선 시대 남원 부사 장의국이 헤어져 있던 견우와 직녀가 만난다는 전설을 형상화하여 만들었습니다. 음력 7월 7일인 이날에는 여인들이 별을 보며 바느질 솜씨가 좋아지기를 비는 풍속이 있었습니다.', '세시풍속', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 1, '(가) 시대의 생활 모습으로 옳은 것은?', 1, '주로 동굴이나 막집에 거주하였다.', '고인돌, 돌널무덤 등을 축조하였다.', '명도전을 이용하여 중국과 교역하였다.', '농경과 목축을 통하여 식량을 생산하였다.', '비파형 동검과 거친무늬 거울 등을 제작하였다.', 4, '강원도 양양군 오산리에서 (가) 시대 마을 유적이 발굴되었습니다. 약 8천 년 전에 형성된 집터에서는 (가) 시대를 대표하는 유물인 빗살무늬 토기와 덧무늬 토기를 비롯한 이음낚시, 그물추 등이 출토되었습니다.', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 2, '(가) 나라에 대한 설명으로 옳은 것은?', 1, '신성 지역인 소도가 존재하였다.', '연의 장수 진개의 공격을 받았다.', '혼인 풍속으로 민며느리제가 있었다.', '여러 가(加)들이 별도로 사출도를 주관하였다.', '특산물로 단궁, 과하마, 반어피가 유명하였다.', 1, '한국사 발표 대회 - 여러 나라의 성장: (가). 5월과 10월에 제천 행사를 지냈습니다. / 신지, 읍차 등으로 불리는 지배자가 있었습니다. / 목지국, 사로국, 구야국 등 여러 소국으로 이루어졌습니다.', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 3, '다음 자료에 해당하는 국가에 대한 설명으로 옳은 것은?', 2, '골품에 따라 관등 승진에 제한을 두었다.', '제가 회의에서 국가 중대사를 결정하였다.', '지방 장관으로 욕살, 처려근지 등이 있었다.', '위화부, 영객부 등의 중앙 관서를 설치하였다.', '왕족인 부여씨와 8성 귀족이 지배층을 이루었다.', 5, '○ 벼슬은 16품계가 있다. 좌평은 5명으로 1품, 달솔은 30명으로 2품, 은솔은 3품, 덕솔은 4품, 한솔은 5품, 나솔은 6품이다. 6품 이상은 관(冠)을 은으로 만든 꽃으로 장식하였다. ○ 그 나라의 지방에는 5방이 있다. 중방은 고사성, 동방은 득안성, 남방은 구지하성, 서방은 도선성, 북방은 웅진성이라 한다. - 『주서』 -', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 4, '다음 검색창에 들어갈 왕에 대한 설명으로 옳은 것은?', 2, '영락이라는 연호를 사용하였다.', '태학을 설립하여 인재를 양성하였다.', '낙랑군을 축출하여 영토를 확장하였다.', '을파소를 등용하여 진대법을 시행하였다.', '당의 침입에 대비하여 천리장성을 축조하였다.', 1, '한국사 전자 사료관 - 고구려 왕대별 보기: 원년 백제의 관미성을 빼앗다 / 10년 신라에 침입한 왜를 격퇴하다 / 13년 후연을 공격하다 / 18년 왕자 거련(巨連)을 태자로 삼다', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 5, '(가) 인물의 활동으로 옳은 것은?', 1, '일심 사상과 화쟁 사상을 주장하였다.', '구법 순례기인 왕오천축국전을 남겼다.', '황룡사 구층 목탑의 건립을 건의하였다.', '왕명으로 수에 군사를 청하는 걸사표를 지었다.', '승려들의 전기를 정리한 해동고승전을 편찬하였다.', 1, '이곳은 (가) 의 생애와 활동을 주제로 한 전시실입니다. 그는 금강삼매경론, 대승기신론소 등을 저술하며 불교 교리 연구에 힘썼으며, 무애가를 짓고 정토 신앙을 전파하여 불교 대중화에 앞장섰습니다.', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 6, '다음 상황이 나타난 배경으로 옳은 것은?', 3, '을지문덕이 살수에서 승리하였다.', '동성왕이 나제 동맹을 강화하였다.', '성왕이 관산성 전투에서 전사하였다.', '계백의 결사대가 황산벌에서 패배하였다.', '장수왕이 평양으로 천도하고 남진을 추진하였다.', 5, '연흥 2년에 여경[개로왕]이 처음으로 사신을 보내 표를 올렸다. "신의 나라는 고구려와 함께 부여에서 나왔으므로 우호를 돈독하였는데, 고구려의 선조인 쇠[고국원왕]가 우호를 가볍게 깨트리고 직접 군사를 지휘하여 우리의 국경을 짓밟았습니다. 신의 선조인 수[근구수왕]는 군대를 정비하고 공격하여 쇠의 머리를 베어 높이 매다니, 이후 감히 남쪽을 엿보지 못하였습니다. 그런데 고구려가 점점 강성해져 침략하고 위협하니 원한이 쌓였고 전쟁의 참화가 30여 년 이어졌습니다. …… 속히 장수를 보내 구원하여 주십시오." - 『위서』 -', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 7, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '윤충이 대야성을 공격하여 함락하였다.', '문무왕이 안승을 보덕왕으로 책봉하였다.', '김춘추가 당과의 군사 동맹을 성사시켰다.', '연개소문이 정변을 일으켜 권력을 장악하였다.', '부여풍이 왜군과 함께 백강에서 당군에 맞서 싸웠다.', 2, '(가) 고구려의 대신 연정토가 12성과 3,500여 명의 백성을 거느리고 [신라에] 항복해 왔다. 왕이 연정토와 그를 따르는 관리 24명에게 의복·물품·식량·집을 주었다. / (나) 이근행이 군사 20만 명을 이끌고 매소성에 주둔하였다. 신라 군사가 공격하여 달아나게 하고 말 3만여 필을 얻었는데, 남겨 놓은 병장기의 수도 그 정도 되었다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 8, '다음 가상 대화 이후에 있었던 사실로 옳은 것은?', 2, '거칠부가 국사를 편찬하였다.', '이사부가 우산국을 정복하였다.', '관료전이 지급되고 녹읍이 폐지되었다.', '원종과 애노가 사벌주에서 봉기하였다.', '이차돈의 순교를 계기로 불교가 공인되었다.', 4, '며칠 전에 웅천주 도독 김헌창이 난을 일으켜 나라 이름을 장안이라 하고 연호를 경운으로 정했다더군. / 그의 아버지가 왕이 되지 못한 것에 불만을 품은 모양이야.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 9, '밑줄 그은 ''왕''의 정책으로 옳은 것은?', 1, '빈민 구제를 위해 흑창을 설치하였다.', '12목에 지방관을 처음으로 파견하였다.', '외침에 대비하여 개경에 나성을 축조하였다.', '관학 진흥을 목적으로 양현고를 운영하였다.', '쌍기의 건의를 수용하여 과거제를 시행하였다.', 1, '저는 지금 신숭겸 장군의 충절을 기리는 대구 표충단에 나와 있습니다. 그는 공산 전투 당시 위기에 빠진 왕을 구하기 위해 싸우다 이곳에서 전사하였다고 합니다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 10, '다음 시나리오에 등장하는 왕의 업적으로 옳은 것은?', 2, '장문휴를 보내 등주를 공격하였다.', '9서당 10정의 군사 조직을 갖추었다.', '사비로 천도하고 국호를 남부여로 고쳤다.', '지방관을 감찰하고자 외사정을 파견하였다.', '고구려 유민을 모아 동모산에서 나라를 세웠다.', 1, '#36. 궁궐 안. 왕이 분노에 찬 표정으로 대문예에게 말하고 있다. 왕: 흑수 말갈이 몰래 당에 조공하였으니, 이는 당과 공모하여 앞뒤로 우리를 치려는 것이다. 군대를 이끌고 가서 흑수 말갈을 정벌하라. 대문예: 당에 조공하였다 하여 그들을 바로 공격한다면 이는 당에 맞서는 것입니다. 하루아침에 당과 원수를 지면 멸망을 자초할 수 있습니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 11, '(가)에 들어갈 인물에 대한 설명으로 옳은 것은?', 2, '발해를 멸망시킨 거란을 적대시하였다.', '미륵불을 자처하며 왕권을 강화하였다.', '신라를 공격하여 경애왕을 죽게 하였다.', '노비안검법을 시행하여 재정을 확충하였다.', '청해진을 설치하여 해상 무역을 장악하였다.', 2, '천 백년 태봉의 이음, 태봉제 - 신라 왕족 출신으로 알려진 (가) 이/가 세운 나라 태봉! 태봉의 도읍 철원에서 역사의 숨결을 느낄 수 있는 태봉제가 다채롭게 진행됩니다. 주요 행사: 태봉 제례, 어가 행렬. 장소: 강원도 철원군 종합 운동장 및 철원읍 일원', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 12, '밑줄 그은 ''이 사건''이 일어난 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 3, '문학으로 만나는 한국사 - ''송인(送人)''으로, 고려 시대의 문인 정지상이 서경을 배경으로 지은 작품이다. 서경 출신인 그는 묘청 등과 함께 수도를 서경으로 옮길 것을 주장하였다. 이로 인해 개경 세력과 정치적으로 대립하던 중 이 사건이 일어나자 김부식에 의해 죽임을 당하였다. (연표) 918 고려 건국 - 1019 귀주 대첩 - 1126 이자겸의 난 - 1270 개경 환도 - 1351 공민왕 즉위 - 1392 고려 멸망. (가)=918~1019, (나)=1019~1126, (다)=1126~1270, (라)=1270~1351, (마)=1351~1392.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 13, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '강조가 정변을 일으켜 김치양을 제거하였다.', '배중손이 이끄는 삼별초가 진도에서 항전하였다.', '만적이 개경에서 노비를 모아 반란을 모의하였다.', '조위총이 군사를 일으켜 정중부 등의 제거를 도모하였다.', '김보당이 의종 복위를 주장하며 동계에서 군사를 일으켰다.', 3, '(가) 최충헌 형제가 왕을 협박하여 창락궁에 유폐하고 태자 왕숙은 강화도로 유배 보냈다. / (나) 유경이 최의를 죽인 뒤, 왕에게 아뢰어 정방을 편전 옆에 두어 인사권을 장악하고, 국가의 주요 사무를 모두 결정하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 14, '밑줄 그은 ''이 시기''에 볼 수 있는 모습으로 옳은 것은?', 1, '농사직설을 편찬하는 학자', '초조대장경을 조판하는 장인', '정동행성에서 회의하는 관리', '삼국사기를 읽고 있는 양반', '백운동 서원에서 공부하는 유생', 3, '이것은 수령 옹주 묘지명입니다. 왕족인 왕온의 부인이었던 그녀는 남편을 일찍 잃고 3남 1녀를 홀로 키웠으나, 딸이 공녀로 원에 끌려가자 그 슬픔으로 병을 얻어 세상을 떠났습니다. 수령 옹주가 살았던 이 시기에는 많은 여성이 공녀로 끌려갔습니다.', '고려', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 15, '(가)~(라) 승려에 대한 설명으로 옳은 것은?', 3, '(가) - 심성의 도야를 강조한 유불 일치설을 주장하였다.', '(나) - 정혜쌍수와 돈오점수를 수행 방법으로 제시하였다.', '(다) - 불교 경전에 대한 주석서를 모아 교장을 편찬하였다.', '(라) - 9산 선문 중 하나인 가지산문을 개창하였다.', '(가)~(라) - 승과에 합격하고 왕사에 임명되었다.', 3, '○ (가) 은/는 화엄 사상의 요지를 정리한 화엄일승법계도를 저술하였다. 또한 부석사를 비롯한 여러 사원을 건립하였고, 현세의 고난에서 구제받고자 하는 관음 신앙을 강조하였다. / ○ (나) 은/는 귀법사의 주지로서, 왕명에 따라 민중을 교화하고 불법을 널리 펴기 위해 노력하였다. 또한 향가인 「보현십원가」 11수를 지어 화엄 사상을 대중에게 전파하였다. / ○ (다) 은/는 문종의 아들로 태어나 11세에 출가하였다. 31세에 송으로 건너가 고승들과 불법을 토론하고 불교 서적을 수집하여 귀국하였다. 국청사를 중심으로 천태종을 창시하였으며, 교선 통합을 사상적으로 뒷받침하기 위해 교관겸수를 제창하였다. / ○ (라) 은/는 12세에 출가하였다. 수행상의 제약을 넘어서기 위해서는 천태의 교리에 의지해야 한다는 깨달음을 얻었다. 법화 신앙을 바탕으로 강진 만덕사에서 백련 결사를 결성하였다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 16, '(가) 국가의 경제 상황으로 옳은 것은?', 1, '송상이 전국 각지에 송방을 두었다.', '활구라고 불리는 은병을 주조하였다.', '동시전을 설치하여 시장을 감독하였다.', '담배, 면화, 생강 등 상품 작물을 널리 재배하였다.', '일본과 교역을 위해 부산포, 염포, 제포를 개항하였다.', 2, '이 작품은 이규보가 예성강 하구의 정경을 묘사한 시입니다. 이곳에 있던 벽란도는 (가) 의 국제 무역항으로 송과 아라비아 상인들이 왕래할 정도로 번성했습니다. (조수가 들고나니 오고 가는 배의 꼬리가 이어졌구나 …… 바람처럼 달리는 준마도 이보다 빠르지는 못하리)', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 17, '(가)에 대한 고려의 대응으로 옳은 것은?', 2, '윤관을 보내 동북 9성을 축조하였다.', '박위로 하여금 쓰시마섬을 정벌하게 하였다.', '서희가 외교 담판을 통해 강동 6주를 획득하였다.', '최우가 강화도로 수도를 옮겨 장기 항전에 대비하였다.', '최영이 철령위 설치에 반발하여 요동 정벌을 추진하였다.', 4, '김윤후가 충주산성 방호별감이 되었는데 (가) 의 군대가 쳐들어 와 충주성을 70여 일간 포위하였다. 군량이 거의 바닥나자 김윤후가 군사들에게 "만약 힘내 싸운다면 귀천을 가리지 않고 모두 관작을 내리겠다."라고 하였다. 마침내 관노비의 문서를 불태우고 노획한 소와 말을 나누어 주었다. 사람들이 모두 죽음을 무릅쓰고 싸우니 적의 기세가 꺾여 남쪽으로 침략하는 것을 막을 수 있었다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 19, '(가)에 들어갈 내용으로 가장 적절한 것은?', 2, '신기전과 화차를 개발하다', '화통도감의 설치를 건의하다', '불랑기포를 활용하여 평양성을 탈환하다', '조총 부대를 이끌고 나선 정벌에 참여하다', '발화 장치를 활용한 비격진천뢰를 발명하다', 2, '역사 인물 다큐멘터리 기획안 - 화약 무기 연구의 선구자, ○○○. 1. 기획 의도: 중국의 군사 기밀이었던 화약 제조 기술을 습득해 우리나라 최초로 화약의 자체 생산에 성공한 ○○○. 그의 활동을 통해 국방 과학 기술의 중요성을 되새겨 본다. 2. 장면: #1 중국인 이원에게 염초 제조법을 배우다 / #2 (가) / #3 나세, 심덕부 등과 함께 진포에서 왜구를 크게 격퇴하다', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 20, '다음 대화에 등장하는 왕의 재위 시기에 있었던 사실로 옳은 것은?', 2, '주자소가 설치되어 계미자가 주조되었다.', '전통 한의학을 집대성한 동의보감이 완성되었다.', '통치 체제를 정비하기 위해 속대전이 간행되었다.', '한양을 기준으로 역법을 정리한 칠정산이 제작되었다.', '전국의 지리, 풍속 등이 수록된 동국여지승람이 편찬되었다.', 5, '전하께서 명하신 대로 장악원에 소장된 의궤와 악보를 새로이 교감하여 악학궤범을 완성하였습니다. / 예조 판서 성현을 비롯하여 편찬에 공을 세운 이들에게 차등을 두어 상을 내리도록 하라.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 21, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '성삼문 등이 단종의 복위를 꾀하였다.', '외척 간의 대립으로 윤임이 제거되었다.', '이괄이 난을 일으켜 한양을 점령하였다.', '성희안 일파가 반정을 통해 연산군을 몰아내었다.', '조의제문이 발단이 되어 김일손 등이 화를 입었다.', 4, '(가) 윤필상, 유순 등이 폐비(廢妃) 윤씨의 시호를 의논하며 "시호와 휘호를 함께 의논하겠습니까?"라고 아뢰니, "시호만 정하는 것이 합당하겠다."라고 하였다. …… 승정원에 전교하기를 "폐비할 때 의논에 참여한 재상, 궁궐에서 나갈 때 시위한 재상, 사약을 내릴 때 나가 참여한 재상 등을 승정원에서 조사하여 아뢰라."라고 하였다. / (나) 의정부에 하교하기를 "조광조 등이 서로 결탁하여, 자신들에게 붙는 자는 천거하고 자신들과 뜻이 다른 자는 배척해서 …… 후진을 유인하여 궤격(詭激)이 버릇되게 하고, 일을 의논할 때에도 조금만 이의를 세우면 반드시 극심한 말로 배척하여 꺾어서 따르게 하였다. …… 조광조·김정 등을 원방(遠方)에 안치하라."라고 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 22, '(가) 기구에 대한 설명으로 옳은 것은?', 2, '업무 일지인 내각일력을 작성하였다.', '고려의 삼사와 같은 기능을 수행하였다.', '은대(銀臺), 후원(喉院)이라고도 불렸다.', '임진왜란을 거치면서 국정 전반을 총괄하였다.', '5품 이하의 관리 임명에 대한 서경권을 행사하였다.', 5, '역사 용어 해설 - (가). 1. 개요: 조선 시대에 언론 활동, 풍속 교정, 백관에 대한 규찰과 탄핵 등을 관장하던 기구이다. 대사헌, 집의, 장령, 감찰 등의 직제로 구성되어 있다. 2. 관련 사료: 건국 초기에 고려의 제도에 따라 설치하였다. …… 『경국대전』에는 "정사를 논평하고, 백관을 규찰하고, 풍속을 바로잡고, 억울함을 풀어주고, 허위를 금지하는 등의 일을 관장한다."라고 하였다. - 『순암집』 -', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 23, '(가)~(다)를 일어난 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (나) - (가)', 2, '(가) 임금이 궐내에 있던 기름 먹인 장막을 허적이 벌써 가져갔음을 듣고 노하여 이르길, "궐내에서 쓰는 것을 마음대로 가져가는 것은 한명회도 못하던 짓이다."라고 하였다. …… 임금이 허적의 당파가 많아 기세가 당당하다는 말을 듣고 그들을 제거하고자 결심하였다. / (나) 비망기를 내려, "국운이 안정되어 왕비가 복위하였으니, 백성에게 두 임금이 없는 것은 고금을 통한 의리이다. 장씨의 왕후 지위를 거두고 옛 작호인 희빈을 내려 주되, 세자가 조석으로 문안하는 예는 폐하지 않도록 하라."라고 하였다. / (다) 임금이 말하기를, "송시열은 산림의 영수로서 나라의 형세가 험난한 때에 감히 원자(元子)의 명호를 정한 것이 너무 이르다고 하였으니, 삭탈 관작하고 성문 밖으로 내쳐라. 반드시 송시열을 구하려는 자가 있겠지만, 그런 자는 비록 대신이라 하더라도 용서하지 않을 것이다."라고 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 24, '밑줄 그은 ''전란'' 중에 있었던 사실로 옳은 것은?', 2, '정문부가 길주에서 의병을 이끌었다.', '강홍립이 사르후 전투에 참전하였다.', '김시민이 진주성에서 적군을 크게 물리쳤다.', '임경업이 백마산성에서 적의 침입에 대비하였다.', '최윤덕이 올라산성에서 이만주 부대를 정벌하였다.', 4, '일기로 본 역사 - 이 책은 조선 시대 문신 어한명이 작성한 강도일기(江都日記)이다. 전란을 피해 봉림 대군과 인평 대군 등이 강화로 이동할 때 당시 경기좌도 수운판관이었던 저자가 왕실을 보호하고 강화 앞바다를 건너게 한 과정을 기록하고 있다. 당시 국왕과 세자는 강화로 가는 길이 막혀 남한산성으로 피란하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 25, '다음 기사에 나타난 시기의 경제 상황으로 옳은 것은?', 2, '삼한통보, 해동통보가 발행되었다.', '솔빈부의 말이 특산물로 수출되었다.', '초량 왜관을 통해 일본과 교역하였다.', '당항성, 영암이 국제 무역항으로 번성하였다.', '경시서의 관리들이 수도의 시전을 감독하였다.', 3, '역사 신문 - 거상(巨商) 임상옥, 북경에서 인삼 무역으로 큰 수익. 연행사의 수행원으로 북경에 간 만상 임상옥이 인삼 무역으로 큰 수익을 거두었다. 북경 상인들이 불매 동맹을 통해 인삼을 헐값에 사려 하자, 그는 가져간 인삼 보따리를 태우는 기지를 발휘해 북경 상인에게 인삼을 높은 가격에 매각하여 막대한 이익을 얻은 것이다.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 26, '(가) 왕이 추진한 정책으로 옳은 것은?', 1, '경기도에 한하여 대동법을 시행하였다.', '군역 부담을 줄이기 위해 균역법을 제정하였다.', '육의전을 제외한 시전 상인의 금난전권을 폐지하였다.', '제한된 규모의 무역을 허용한 계해약조를 체결하였다.', '현직 관리에게만 수조권을 지급하는 직전법을 실시하였다.', 3, '서호천을 따라 (가) 의 자취를 느끼다 - 우리 역사 동아리에서는 (가) 와/과 관련된 유적을 돌아보는 답사 프로그램을 마련하였습니다. 축만제(왕이 수원 화성 및 장용영 운영을 위해 조성한 둔전의 수리 시설) → 노송지대(왕이 ''현륭원'' 식목관에 내탕금을 내려 소나무 등을 심도록 한 곳) → 지지대비(왕의 효심을 기리기 위해 아들 순조 때 건립한 비). 출발 장소: 서호 공원', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 27, '다음 자료에 나타난 사건에 대한 설명으로 옳은 것은?', 2, '홍경래, 우군칙 등이 주도하였다.', '남접과 북접이 연합하여 전개되었다.', '삼정이정청이 설치되는 계기가 되었다.', '우정총국 개국 축하연을 이용하여 일어났다.', '윤원형 일파가 정국을 주도한 시기에 발생하였다.', 3, '진주 안핵사 박규수에게 하교하기를, "얼마 전에 있었던 진주의 일은 전에 없던 변괴였다. 관원은 백성을 달래지 못하였고, 백성은 패악한 습관을 버리지 못하였다. 누가 그 허물을 책임져야 하겠는가. 신중을 기하여 혹시 한 사람이라도 억울하게 처벌 받는 일이 없게 하라. 그리고 포리(逋吏)를 법에 따라 처벌할 경우 죄인을 심리하여 처단할 방법을 상세히 구별하라."라고 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 28, '(가) 인물의 작품으로 옳은 것은? (선택지는 회화 이미지)', 2, '금강전도', '인왕제색도', '무동(풍속화)', '송하맹호도', '파적도', 2, '이 작품은 단원 (가) 이/가 그린 추성부도(秋聲賦圖)로, 인생의 허망함과 쓸쓸함을 묘사한 글인 추성부를 그림으로 표현했습니다. 죽음을 앞둔 노년에 자신의 심정을 나타낸 것으로 보입니다. 도화서 화원 출신인 그는 풍속화, 산수화, 인물화 등 다양한 분야에서 뛰어난 작품을 남겼습니다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 29, '(가)~(라) 역사서를 편찬한 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다) - (라)', '(가) - (다) - (나) - (라)', '(나) - (가) - (라) - (다)', '(나) - (다) - (가) - (라)', '(다) - (라) - (나) - (가)', 2, '(가) 우리 해동의 삼국도 역사가 오래되었으니 마땅히 책을 써야 합니다. 그러므로 폐하께서 이 늙은 신하에게 편찬하도록 하셨습니다. …… "삼국은 중국과 통교하였으므로 『후한서』나 『신당서』에 모두 삼국의 열전이 있지만, 상세히 실리지 않았다. …… 뛰어난 역사서를 완성하여 물려주고 싶다."라고 하셨습니다. / (나) 삼가 삼국 이후의 여러 역사서를 모으고 중국의 역사서에서 가려내어 연도에 따라 사실을 기록하였습니다. 범례는 『자치통감』에 의거하였고, 『자치통감강목』의 취지에 따라 번잡한 것은 줄이고 요령만 남겨두도록 힘썼습니다. …… 삼한 이전은 외기라고 하였습니다. / (다) 옛 성인은 예악으로 나라를 일으켰고 인의로 가르침을 폈으니 괴력난신은 말하지 않았다. …… 삼국의 시조가 모두 신이한 데서 나왔다고 해서 무엇이 괴이하다고 하겠는가. 이것이 책 첫머리에 기이편이 실린 까닭이다. / (라) 옛날에 고씨가 북쪽에 살면서 고구려라 하였고, 부여씨가 서남쪽에 살면서 백제라 하였으며, 박·석·김씨가 동남쪽에 살면서 신라라 하였으니, 이것이 삼국이다. …… 부여씨가 망하고 고씨가 망하니 김씨가 그 남쪽 땅을 차지하고 대씨가 그 북쪽 땅을 차지하여 발해라 하였다. 이것을 남북국이라 한다.', '복합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 30, '(가)~(라) 역사서에 대한 설명으로 옳은 것을 <보기>에서 고른 것은? ㄱ.(가)-유교 사관에 입각하여 기전체 형식으로 저술하였다. ㄴ.(나)-사초와 시정기를 바탕으로 실록청에서 편찬하였다. ㄷ.(다)-불교사를 중심으로 민간 설화 등을 수록하였다. ㄹ.(라)-고조선부터 고려까지의 역사를 편년체로 정리하였다.', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 2, '(위 29번과 동일 자료: (가) 삼국사기, (나) 동국통감, (다) 삼국유사, (라) 발해고)', '복합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 31, '(가) 사건 이후에 전개된 사실로 옳은 것은?', 2, '종로와 전국 각지에 척화비가 세워졌다.', '평양 관민이 제너럴 셔먼호를 불태웠다.', '한성근 부대가 문수산성에서 항전하였다.', '신유박해로 많은 천주교도가 처형되었다.', '오페르트가 남연군 묘 도굴을 시도하였다.', 1, '이곳은 어재연 장군과 그의 군사를 기리기 위해 조성된 충장사입니다. 어재연 장군의 부대는 (가) 때 광성보에서 로저스 제독이 이끄는 미군에 맞서 결사 항전하였지만 끝내 함락을 막지 못하였습니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 32, '(가), (나) 조약 체결 사이의 시기에 있었던 사실로 옳은 것은?', 3, '공사 노비법이 혁파되었다.', '통리기무아문이 설치되었다.', '한성 전기 회사가 설립되었다.', '건양이라는 독자적인 연호가 채택되었다.', '지방 행정 구역이 8도에서 23부로 개편되었다.', 2, '(가) 제1관 조선국은 자주 국가로서 일본국과 평등한 권리를 보유한다. …… 제10관 일본국 인민이 조선국 지정의 각 항구에 머무르는 동안 죄를 범한 것이 조선국 인민에게 관계되는 사건은 모두 일본국 관원이 심리하여 판결한다. …… / (나) 제1관 앞으로 대조선국 군주와 대미국 대통령 및 그 인민은 각각 모두 영원히 화평하고 우애 있게 지낸다. …… 제5관 …… 미국 상인과 상선이 조선에 와서 무역을 할 때 입출항하는 화물은 모두 세금을 바쳐야 하며, 세금을 거두는 권한은 조선이 자주적으로 행사한다. ……', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 33, '다음 자료에 나타난 사건에 대한 설명으로 옳은 것은?', 2, '전주 화약이 체결되는 계기가 되었다.', '입헌 군주제 수립을 목표로 전개되었다.', '김기수가 수신사로 파견되는 결과를 가져왔다.', '구식 군인에 대한 차별 대우가 발단이 되어 일어났다.', '3일 만에 실패로 끝나 주동자들이 해외로 망명하였다.', 4, '발신: 조선 주재 공사 하나부사 요시모토(花房義質) / 수신: 외무경 이노우에 가오루(井上馨). 이달 23일 오후 5시 성난 군중 수백 명이 갑자기 공사관을 습격하여 돌을 던지고 총을 쏘며 방화함. 전력으로 방어한 지 7시간이 지났지만 원병이 오지 않았음. 한쪽을 돌파하여 왕궁으로 가려 해도 성문이 열리지 않았음. …… 성난 군중이 왕궁 및 민태호와 민겸호의 집을 습격했다고 들었음. …… 교관 호리모토 외 8명의 생사는 알 수 없음.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 34, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '국문 연구소의 연구위원으로 활동하였다.', '조선어 학회 사건으로 구속되어 옥고를 치렀다.', '국권 피탈 과정을 정리한 한국통사를 집필하였다.', '세계지리 교과서인 사민필지를 한글로 저술하였다.', '여유당전서를 간행하고 조선학 운동을 전개하였다.', 1, '국어 연구에 앞장선 (가) 에 대해 알려 주세요. / 호는 한힌샘으로, 독립신문사의 교보원으로 활동하였습니다. 큰 보자기에 책을 넣고 다니며 학생들에게 국어를 가르쳐 ''주보따리''라는 별명을 얻었습니다.', '근대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 35, '다음 자료에 나타난 민족 운동에 대한 설명으로 옳은 것은?', 2, '일제가 치안 유지법을 적용하여 탄압하였다.', '백정에 대한 사회적 차별 철폐를 요구하였다.', '독립문 건립을 위한 모금 활동을 전개하였다.', '자작회, 토산 애용 부인회 등의 단체가 활동하였다.', '대한매일신보 등 당시 언론이 적극적으로 참여하였다.', 5, '우리나라가 채무를 지고 우리 백성이 채노(債奴)가 된 것이 여러 해가 되었습니다. …… 대황제 폐하께서 진 외채가 1,300만 원이지만 채무를 청산할 방법이 없어 밤낮으로 걱정하시니, 백성된 자로서 있는 힘을 다하여 보상하려고 해도 겨를이 없습니다. …… 우리 동포는 빨리 단체를 결성하여 열성적으로 의연금을 내어 채무를 상환하고 채노에서 벗어나, 머리는 대한의 하늘을 이고, 발은 대한의 땅을 밟도록 해 주시기를 눈물을 머금고 간절히 요구합니다. (채노: 빚을 갚지 못해 노비가 된 사람)', '근대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 36, '밑줄 그은 ''이 단체''에 대한 설명으로 옳은 것은?', 2, '정우회 선언의 영향으로 결성되었다.', '조선 혁명 선언을 활동 지침으로 삼았다.', '일제의 황무지 개간권 요구를 저지하였다.', '중추원 개편을 통해 의회 설립을 추진하였다.', '계몽 서적의 보급을 위해 태극 서관을 운영하였다.', 5, '이 편지는 비밀 결사인 이 단체의 재무를 총괄한 전덕기가 안창호에게 보낸 것이다. 105인 사건으로 이 단체의 주요 회원인 양기탁, 이승훈 등이 형을 선고받은 사실과 대성 학교가 재정적으로 어려움을 겪고 있는 상황 등을 전하고 있다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 37, '밑줄 그은 ''시기''에 볼 수 있는 모습으로 옳은 것은?', 1, '경성 제국 대학에서 공부하는 학생', '근우회의 창립 기사를 작성하는 기자', '보빙사 일행으로 미국에 파견되는 관리', '조선인에게 태형을 집행하는 헌병 경찰', '거문도를 불법 점령하고 있는 영국 해군', 4, '이것은 일제가 임시 토지 조사국을 설치하고 토지 조사 사업을 진행하던 시기에 작성한 지적 원도의 일부입니다. 토지를 측량해 그 위치와 경계 및 지번 등을 표시하였습니다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 38, '(가) 단체에 대한 설명으로 옳은 것은?', 2, '고종 강제 퇴위 반대 운동을 전개하였다.', '공화정체의 국민 국가 수립을 목표로 삼았다.', '파리 강화 회의에 독립 청원서를 제출하였다.', '미군과 연합하여 국내 진공 작전을 계획하였다.', '만민 공동회를 개최하여 민권 신장을 추구하였다.', 2, '□□ 신문 - 박상진 의사 유물, 국가등록문화재 등록. 군자금 모집과 친일파 처단 등의 활동을 전개한 (가) 의 총사령 박상진 의사의 유물이 국가등록문화재로 등록되었다. 이 유물은 친일 부호 처단 사건으로 체포된 박상진의 옥중 상황과 (가) 의 비밀 연락 거점이었던 상덕태상회의 규모 등을 보여준다는 점에서 귀중한 가치를 지니고 있다. (옥중 편지 및 상덕태상회 청구서)', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 39, '(가) 운동에 대한 설명으로 옳은 것은?', 1, '신간회에서 진상 조사단을 파견하여 지원하였다.', '순종의 인산일을 기회로 만세 운동을 전개하였다.', '일제가 이른바 문화 통치를 실시하는 배경이 되었다.', '한국인 학생과 일본인 학생 간의 충돌에서 비롯되었다.', '시위를 준비하는 과정에서 사회주의자들이 대거 검거되었다.', 3, '서울 앨버트 테일러 가옥(딜쿠샤) - ''기쁜 마음의 궁전''을 뜻하는 딜쿠샤는 미국인 앨버트 W. 테일러가 지은 벽돌집으로, 테일러와 그의 가족이 미국으로 추방되기 전까지 거주한 곳이다. 미국 연합통신(AP)의 임시 특파원으로 활동한 테일러는 세브란스 병원에서 독립 선언서를 발견하고 외신을 통해 전 세계에 알렸으며, (가) 당시 일제가 자행한 제암리 학살 사건 등을 취재해 보도하였다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 40, '(가)에 대한 설명으로 옳은 것을 <보기>에서 고른 것은? ㄱ.만세보를 발행하여 민중 계몽에 힘썼다. ㄴ.신흥 강습소를 세워 독립군을 양성하였다. ㄷ.구미 위원부를 조직하여 외교 활동을 전개하였다. ㄹ.이륭양행에 교통국을 설치하여 국내와 연락을 취하였다.', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 5, '저는 이동녕으로 이곳 충남 천안에서 태어났습니다. 저는 임시 의정원 초대 의장으로 삼권 분립에 기초한 (가) 의 헌법 제정에 기여하였습니다. 또한 국무총리와 주석 등을 역임하였고, (가) 이/가 상하이를 떠나 이동하는 과정을 함께하며 독립운동에 전념하였습니다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 41, '밑줄 그은 ''시기''에 있었던 사실로 옳은 것은?', 2, '메가타의 주도로 화폐 정리 사업이 실시되었다.', '만주 군벌과 일제 사이에 미쓰야 협정이 체결되었다.', '여자 정신 근로령으로 한국인 여성이 강제 동원되었다.', '지주 문재철의 횡포에 맞서 암태도 소작 쟁의가 전개되었다.', '회사 설립 시 총독의 허가를 받도록 하는 회사령이 공포되었다.', 3, '○○ 박물관 사이버 전시실 - 이 포스터는 일제가 미국과 영국 등 연합국을 상대로 한 전쟁을 벌였던 시기에 만들어졌다. 전쟁에 필요한 쌀을 강제로 공출하기 위한 홍보용으로 제작되었다. (쌀 공출 선전 포스터)', '일제', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 42, '(가)~(마)에 들어갈 내용으로 옳은 것은?', 2, '(가) - 단군 숭배 사상을 통해 민족의식을 높이다', '(나) - 의민단을 조직하여 무장 투쟁을 전개하다', '(다) - 간척 사업을 진행하고 새생활 운동을 펼치다', '(라) - 배재 학당을 세워 신학문 보급에 기여하다', '(마) - 어린이날을 제정하고 소년 운동을 추진하다', 3, '○○○ 한국 근대사 강의실 - 일제 강점기 종교계의 활동을 주제로 보고서를 작성한 후 제목과 함께 게시판에 올려주세요. 1조 개신교 (가) / 2조 대종교 (나) / 3조 원불교 (다) / 4조 천도교 (라) / 5조 천주교 (마)', '일제', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 43, '(가) 부대에 대한 설명으로 옳은 것은?', 3, '자유시 참변으로 큰 타격을 입었다.', '대전자령 전투에서 일본군을 격퇴하였다.', '동북 항일 연군으로 개편되어 유격전을 펼쳤다.', '김원봉, 윤세주 등이 중국 관내(關內)에서 창설하였다.', '홍범도 부대와 연합하여 청산리에서 일본군과 교전하였다.', 4, '조선 민족 혁명당 창립 제8주년 기념 선언 - 우리는 중국의 난징에서 5개 당을 통합하여 전체 민족을 대표하는 유일한 정당인 조선 민족 혁명당을 창립하였다. …… 아울러 중국과 한국의 연합 항일 진영을 건립하여야 했다. …… 이 때문에 우리는 1938년 (가) 을/를 조직하고 조선의 혁명 청년들을 단결시켜 장제스 위원장의 영도 아래 직접 중국의 항전에 참가하고, 각 전쟁터에서 찬란한 전투 성과를 만들어냈다. …… 지난해 가을 (가) 와/과 한국 광복군의 통합 편성을 기반으로 전 민족의 통일을 성공적으로 구현하였다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 44, '(가) 지역에서 있었던 민족 운동으로 옳은 것은?', 2, '권업회가 설립되어 권업신문을 발간하였다.', '이봉창이 일왕의 행렬에 폭탄을 투척하였다.', '박용만의 주도로 대조선 국민군단이 창설되었다.', '북로 군정서가 조직되어 독립 전쟁을 전개하였다.', '유학생들이 중심이 되어 2·8 독립 선언서를 발표하였다.', 4, '해외 독립운동 유적 조사 보고서 - 주제: (가) 지역에 서린 항일 독립 정신을 찾아서. 조사 내용: 1. 김약연의 명동 학교 설립과 교육 활동 / 2. 이상설이 세운 민족 교육의 요람, 서전서숙 / 3. 윤동주와 송몽규의 민족의식이 싹튼 용정촌. 유적 사진: 명동 학교, 서전서숙 기념비, 용정촌 윤동주 생가', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 45, '밑줄 그은 ''군정청''이 있었던 시기의 사실로 옳은 것은?', 2, '한미 상호 방위 조약이 체결되었다.', '제1차 경제 개발 5개년 계획이 추진되었다.', '반민족 행위 특별 조사 위원회가 설치되었다.', '신한 공사가 설립되어 귀속 재산을 관리하였다.', '국가 보안법 개정안을 통과시킨 보안법 파동이 일어났다.', 4, '□□ 신문 - 서윤복 선수 환영회, 중앙청 광장에서 개최. 제51회 보스턴 세계 마라톤 대회에서 세계 신기록을 세우며 우승한 서윤복 선수의 환영회가 중앙청 광장에서 열렸다. 하지 중장, 헬미크 준장 등 군정청의 주요 인사와 김규식, 여운형, 안재홍 등 정계 인사를 비롯한 수많은 군중이 참석하여, 우리 민족의 의기를 세계에 과시한 서윤복 선수의 우승을 함께 기뻐하였다. (중앙청 광장에 모인 환영 인파)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 46, '(가) 전쟁 중에 있었던 사실로 옳지 않은 것은?', 1, '애치슨 선언이 발표되었다.', '부산이 임시 수도로 정해졌다.', '흥남 철수 작전이 전개되었다.', '인천 상륙 작전 이후 서울을 수복하였다.', '국회에서 국민 방위군 사건이 폭로되었다.', 1, '(가) 대성동 마을은 경기도 파주시에 있으며, 군사 분계선 남쪽 비무장 지대에 위치한 민간인 마을입니다. / (가) 의 정전 협정 체결 직후 비무장 지대에 남북이 민간인 마을을 하나씩 남긴다는 후속 합의에 따라 마을로 조성되었습니다. / ''자유의 마을''로 불리는 대성동 마을은 유엔군 사령부의 관할 지역으로, 외부인은 허락 없이 들어가지 못합니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 47, '다음 대화에 나타난 사건 이후의 사실로 옳은 것은?', 3, '내각 책임제 형태의 정부가 출범하였다.', '정부에 비판적이던 경향신문이 폐간되었다.', '최고 통치 기구인 국가 재건 최고 회의가 구성되었다.', '평화 통일론을 주장한 진보당의 조봉암과 간부들이 구속되었다.', '국회 해산, 헌법의 일부 효력 정지를 담은 10월 유신이 선포되었다.', 5, '당시 정부와 여당인 민주 공화당이 3선 개헌을 추진하자 학생들이 반대 시위를 벌이는 모습이네요. / 아당인 신민당과 재야 세력도 3선 개헌 반대 범국민 투쟁 위원회를 결성해서 이를 막아내려 했지요. (현대사 사진전: 3선 개헌 반대 시위)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 48, '다음 자료에 나타난 민주화 운동에 대한 설명으로 옳은 것은?', 2, '허정 과도 정부가 출범하는 계기가 되었다.', '굴욕적인 한일 국교 정상화에 반대하였다.', '호헌 철폐, 독재 타도 등의 구호를 외쳤다.', '3·15 부정 선거에 항의하며 시위가 시작되었다.', '관련 기록물이 유네스코 세계 기록 유산으로 등재되었다.', 5, '전국의 언론인 여러분! 지금 광주에서는 젊은 대학생들과 시민들이 피를 흘리며 싸우고 있습니다. 대학생들의 평화적 시위를 질서 유지, 진압이라는 명목 아래 저 잔인한 공수 부대를 투입하여 시민과 학생을 무차별 살육하였고 더군다나 발포 명령까지 내렸던 것입니다. …… 그러나 일부 언론은 순수한 광주 시민의 의거를 불순배의 선동이니, 폭도의 소행이니, 난동이니 하여 몰아붙이고만 있습니다. …… 이번 광주 의거를 몇십 년 뒤의 ''사건 비화''나 ''남기고 싶은 이야기''들로 만들지 않기 위해, 사실 그대로 보도하여 주시기를 수많은 사망자의 피맺힌 원혼과 광주 시민의 이름으로 간절히, 간절히 촉구하는 바입니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 49, '다음 연설이 있었던 정부 시기의 경제 상황으로 옳은 것은?', 2, '처음으로 수출액 100억 달러가 달성되었다.', '대통령 긴급 명령으로 금융 실명제가 실시되었다.', '개성 공단 건설을 통해 남북 간 경제 교류가 이루어졌다.', '한국과 미국 사이에 자유 무역 협정(FTA)이 체결되었다.', '경제적 취약 계층을 위한 국민 기초 생활 보장법이 시행되었다.', 2, '오늘 우리나라는 OECD 회원국이 되게 되었습니다. …… 한국은 수많은 어려움이 있었음에도 시장 경제 체제의 장점을 살리는 경제 개발 전략을 추진해 왔습니다. 이를 통해 폐허 속에서 한 세대 만에 세계 10위권의 경제 규모를 가진 나라로 성장하였습니다.', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (61, 50, '다음 뉴스가 보도된 정부 시기의 통일 노력으로 옳은 것은?', 2, '남북 조절 위원회를 구성하였다.', '남북한이 유엔에 동시 가입하였다.', '6·15 남북 공동 선언을 채택하였다.', '한반도 비핵화 공동 선언을 발표하였다.', '남북 이산가족의 교환 방문을 최초로 실현하였다.', 3, '정주영의 소 떼 방북을 계기로 남북한의 교류와 협력이 본격화되면서 금강산 관광 사업이 시작되었습니다. 이 사업은 남북 교류 활성화에 크게 기여할 것으로 보입니다. (금강산 관광객 실은 크루즈, 동해항에서 첫 출항)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 1, '(가) 시대의 생활 모습으로 옳은 것은?', 1, '반달 돌칼로 벼를 수확하였다.', '주로 동굴이나 막집에서 거주하였다.', '소를 이용한 깊이갈이가 일반화되었다.', '호미, 쇠스랑 등의 철제 농기구를 제작하였다.', '가락바퀴와 뼈바늘을 이용하여 옷을 만들기 시작하였다.', 1, '(가) 시대 문화상품 공모 - 사유 재산과 계급이 발생한 (가) 시대의 유물을 활용한 문화상품을 공모하오니 많은 참여 바랍니다. (민무늬 토기, 비파형 동검, 고인돌)', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 2, '(가)에 들어갈 내용으로 옳은 것은?', 2, '정사암에 모여 재상을 선출하였어요.', '여러 가(加)가 별도로 사출도를 다스렸어요.', '읍락 간의 경계를 중시하는 책화가 있었어요.', '사회 질서를 유지하기 위해 범금 8조를 두었어요.', '제사장인 천군과 신성 지역인 소도가 존재하였어요.', 2, '과거로 떠나는 역사 여행 생방송 - 지도에 표시된 쑹화강 유역을 중심으로 성장한 이 나라는 평원과 구릉, 넓은 못이 많았습니다. 농업과 목축을 생업으로 하며 12월에 영고라는 제천 행사를 열었습니다. (대화창: 명마, 적옥, 담비 가죽 등이 생산되었어요 / 형이 죽으면 형수를 아내로 삼는다는 기록도 있어요 / (가))', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 3, '(가) 나라에 대한 설명으로 옳은 것은?', 2, '덩이쇠를 화폐처럼 사용하였다.', '한 무제의 공격으로 멸망하였다.', '혼인 풍속으로 민며느리제가 있었다.', '골품에 따라 관등 승진에 제한이 있었다.', '빈민을 구제하기 위해 진대법을 시행하였다.', 1, '길 위에서 만나는 (가) 의 역사 - 도시를 가로지르는 해반천을 따라 주변을 걸으면서 역사 여행을 떠나 봅시다. (가) 의 유적과 유물이 여러분을 역사 현장으로 안내할 것입니다. 답사 경로: 봉황동 유적 → 수로왕릉 → 대성동 고분군 → 파사석탑 → 구지봉', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 4, '밑줄 그은 ''왕''에 대한 설명으로 옳은 것은?', 2, '평양으로 수도를 옮겼다.', '병부와 상대등을 설치하였다.', '22담로에 왕족을 파견하였다.', '고흥에게 서기를 편찬하게 하였다.', '율령을 반포하여 통치 체제를 정비하였다.', 5, '다큐멘터리 기획안 - 위기에 빠진 고구려를 구하라! 기획 의도: 평양성 전투에서 전사한 고국원왕의 뒤를 이어 즉위한 왕의 위기 극복 노력을 살펴본다. 구성: 1부 전진으로부터 불교를 수용하다. 2부 태학을 설립하여 인재를 양성하다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 6, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '당이 안동도호부를 요동으로 옮겼다.', '성왕이 관산성 전투에서 전사하였다.', '신라군이 기벌포에서 당군을 격파하였다.', '김춘추가 당과의 군사 동맹을 성사시켰다.', '복신과 도침이 부여풍을 왕으로 추대하였다.', 5, '(가) 왕은 당과 신라 군사들이 이미 백강과 탄현을 지났다는 소식을 듣고 장군 계백을 시켜 결사대 5천 명을 거느리고 황산으로 가서 신라 군사와 싸우게 하였다. 네 번 싸워서 모두 이겼으나 군사가 적고 힘이 모자라서 마침내 패하고 계백이 사망하였다. / (나) 검모잠이 국가를 부흥하려고 하여 당을 배반하고 왕의 외손 안승을 세워 왕으로 삼았다. 당 고종이 대장군 고간을 보내 동주도 행군총관으로 삼고 병력을 내어 그들을 토벌하게 하니 안승이 검모잠을 죽이고 신라로 달아났다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 7, '(가) 국가에 대한 설명으로 옳은 것은?', 1, '후당과 오월에 사신을 파견하였다.', '주자감을 설치하여 인재를 양성하였다.', '9서당과 10정의 군사 조직을 운영하였다.', '화백 회의에서 국가의 중대사를 논의하였다.', '내신좌평, 위사좌평 등 6좌평의 관제를 마련하였다.', 2, '기획 전시 - (가), 다양한 문화를 융합하다. 우리 박물관에서는 (가) 의 문화에 대해 깊이 이해할 수 있는 전시회를 개최합니다. 전시관 안내: [1관] 고구려 문화의 계승(연꽃무늬 수막새와 치미) / [2관] 당 문화의 수용(상경성 평면도) / [3관] 말갈 문화의 요소(말갈계 토기) / [4관] 서역과의 교류(청동 낙타상)', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 8, '(가)에 들어갈 내용으로 옳은 것은?', 2, '관료전을 지급하고 녹읍을 폐지하다.', '마립간이라는 칭호를 처음 사용하다.', '이사부를 보내 우산국을 복속시키다.', '화랑도를 국가적 조직으로 개편하다.', '이차돈의 순교를 계기로 불교를 공인하다.', 1, '한국사 웹툰 기획안 - 제목: ○○왕, 왕권을 강화하다. 구성 내용: 1화 진골 귀족 김흠돌의 반란을 진압하다. / 2화 국학을 설치하여 인재를 양성하다. / 3화 9주를 정비하여 지방 통치 체제를 갖추다. / 4화 (가). 주의 사항: 사료에 기반하여 제작한다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 9, '밑줄 그은 ''이 인물''에 대한 설명으로 옳은 것은?', 2, '구법 순례기인 왕오천축국전을 지었다.', '진성 여왕에게 시무책 10여 조를 올렸다.', '청해진을 중심으로 해상 무역을 전개하였다.', '9산 선문 중의 하나인 가지산문을 개창하였다.', '한자의 음과 훈을 차용한 이두를 체계적으로 정리하였다.', 3, '적산 법화원은 산둥반도에 있었던 신라인 집단 거주지에 세워진 절이다. 이 절을 창건한 이 인물은 당에 건너가 무령군 소장이 되었다가 흥덕왕 때 귀국하여 활발히 활동하였다. 그러나 왕위 쟁탈전에 휘말려 암살당했다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 10, '밑줄 그은 ''왕''의 정책으로 옳은 것은?', 2, '빈민 구제 기관인 흑창을 설치하였다.', '12목을 설치하고 지방관을 파견하였다.', '국자감에 7재라는 전문 강좌를 운영하였다.', '광덕, 준풍 등의 독자적 연호를 사용하였다.', '전시과 제도를 마련하여 관리에게 토지를 지급하였다.', 1, '왕이 천덕전에 거둥하여 백관을 모아놓고 말하기를, "내가 신라와 굳게 동맹을 맺은 것은 두 나라가 길이 우호를 유지하고 각자의 사직(社稷)을 보전하기 위해서였다. 지금 신라왕이 굳이 신하로 있겠다고 요청하고 그대들도 그것이 옳다고 하니, 나의 마음이 매우 부끄러우나 여러 사람의 뜻을 거스르기가 어렵다."라고 하였다. …… 신라국을 없애 경주라 하고, 그 지역을 김부의 식읍으로 하사하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 11, '(가)에 대한 역대 왕조의 대응으로 옳은 것은?', 2, '신라 문무왕 때 청방인문표를 보내어 인질의 석방을 요구하였다.', '고려 우왕 때 나세, 심덕부 등이 진포에서 크게 물리쳤다.', '고려 창왕 때 박위를 파견하여 근거지를 토벌하였다.', '조선 태종 때 경성과 경원에 무역소를 설치하여 회유하였다.', '조선 광해군 때 기유약조를 체결하여 무역을 재개하였다.', 4, '함길도 도절제사 김종서에게 전지하기를, "동북 지역의 경계는 공험진(公?鎭)으로 삼았다는 말이 전하여 온 지가 오래다. …… 고려사에 이르기를, ''윤관이 공험진에 비를 세워 경계를 삼았다.''고 하였다. …… 윤관이 (가) 을/를 쫓고 9성을 설치하였는데, 그 성이 지금 어느 성이며, 공험진의 어느 쪽에 있는가."라고 하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 12, '(가) 국가의 경제 상황으로 옳은 것은?', 2, '삼한통보, 해동통보 등이 발행되었다.', '특산품으로 솔빈부의 말이 유명하였다.', '만상이 대청 무역으로 부를 축적하였다.', '시장을 감독하는 관청인 동시전이 설치되었다.', '광산을 전문적으로 경영하는 덕대가 등장하였다.', 1, '이것은 양산 통도사 국장생 석표입니다. 통도사의 경계를 표시하기 위해 세운 석표 중 하나로 ''상서호부(尙書戶部)의 승인으로 세웠다''는 내용이 새겨져 있습니다. 국사·왕사 제도를 두어 불교를 장려했던 (가) 시대에 국가와 사찰의 관계를 파악할 수 있는 문화유산입니다.', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 13, '(가) 국가의 문화유산으로 옳은 것을 <보기>에서 고른 것은? (ㄱ.나전 칠기 합, ㄴ.청자 석상(도자기), ㄷ.수월관음도, ㄹ.금동 대향로)', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 2, '미(美)·색(色) 벨기에 소장 우리 문화유산 특별전 - 우리 박물관에서는 벨기에 왕립예술역사박물관 소장 (가) 의 공예품 8점을 공개하는 특별전을 개최합니다. 이번 전시에서는 (가) 의 대표적 문화유산인 상감청자 6점을 비롯하여 청동 정병, 금동 침통 등을 자세히 감상할 수 있도록 전시 공간을 연출하였습니다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 14, '(가) 시기에 있었던 사실로 옳은 것은?', 1, '묘청이 서경에서 난을 일으켰다.', '이자겸이 척준경에 의해 축출되었다.', '강조가 정변을 일으켜 국왕을 폐위하였다.', '김윤후가 처인성에서 살리타를 사살하였다.', '다인철소의 주민들이 충주에서 항전하였다.', 3, '누가 거란 진영에 가서 담판을 벌여 군대를 물러가게 하겠는가? / 신, 서희가 폐하의 분부를 받들겠습니다. (가) 양규가 적을 무로대와 이수 등지에서 크게 무찌르고 포로를 되찾았다고 하옵니다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 15, '다음 상황이 나타난 시기의 사회 모습으로 옳은 것은?', 1, '원종과 애노가 사벌주에서 봉기하였다.', '대각국사 의천이 해동 천태종을 개창하였다.', '지배층을 중심으로 변발과 호복이 유행하였다.', '기근에 대비하기 위해 구황촬요가 간행되었다.', '국난 극복을 기원하며 초조 대장경이 조판되었다.', 3, '제국 대장 공주가 일찍이 잣과 인삼을 [원의] 강남 지역으로 보내 많은 이익을 얻었다. 나중에는 환관을 각지에 파견하여 잣과 인삼을 구하게 하였다. 비록 나오지 않는 땅이라 하더라도 강제로 거두니 백성들이 매우 괴로워하였다.', '고려', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 16, '다음 사건의 배경으로 가장 적절한 것은?', 2, '노비 만적이 반란을 모의하였다.', '정중부, 이의방 등이 정변을 일으켰다.', '신돈이 전민변정도감의 판사가 되었다.', '망이, 망소이 등이 명학소에서 봉기하였다.', '최충헌이 교정도감을 설치하여 국정을 총괄하였다.', 2, '조위총이 동·북 양계(兩界)의 여러 성에 격문을 돌려 군사를 불러 모아 말하기를, "소문에 따르면 개경의 중방(重房)에서 ''북계의 여러 성은 거칠고 사나운 무리를 많이 거느리고 있으니 토벌해야 한다.''고 논의하고 이미 많은 병력을 동원했다고 하니 어찌 가만히 앉아서 스스로 죽을 수 있겠는가? 각자 군사와 말을 규합하여 빨리 서경으로 달려와야 한다."라고 하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 17, '(가) 군사 조직에 대한 설명으로 옳은 것은?', 1, '광군사의 통제를 받았다.', '정미 7조약에 의해 해산되었다.', '4군 6진을 개척해 영토를 확장하였다.', '개경 환도 결정에 반발하여 항쟁하였다.', '유사시에 향토 방위를 담당하는 예비군이었다.', 4, '처음에 최우가 나라 안에 도적이 많음을 근심하여 용사들을 모아 매일 밤 순행하면서 포악한 짓들을 금하였는데, 이로 인하여 이름을 야별초(夜別抄)라고 하였다. 도적들이 여러 도에서도 일어났으므로 별초를 나누어 보내 이들을 잡게 하였다. 그 군사가 매우 많아 마침내 나누어 좌우로 삼았다. 또 우리나라 사람으로서 몽골로부터 도망쳐 돌아온 자들을 한 부대로 삼아 신의군(神義軍)이라고 불렀는데, 이들이 (가) 이/가 되었다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 18, '밑줄 그은 ''그''에 대한 설명으로 옳은 것은?', 3, '역옹패설과 사략을 저술하였다.', '왕명에 의해 삼국사기를 편찬하였다.', '문헌공도를 설립하여 유학 교육에 힘썼다.', '불교 개혁을 주장하며 수선사 결사를 제창하였다.', '성균관의 대사성이 되어 정몽주 등을 학관으로 천거하였다.', 5, '초상화로 보는 한국사 - 이 그림은 고려 말 삼은(三隱) 중 한 사람인 목은(牧隱)의 초상화이다. 이곡(李穀)의 아들인 그는 고려와 원의 과거에 합격했으며, 문하시중 등의 관직을 역임하였다. 고려 후기 성리학의 보급에 노력한 대표적 인물로 평가된다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 19, '(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?', 2, '최무선의 건의로 화통도감이 설치되었다.', '조선의 기본 법전인 경국대전이 완성되었다.', '국방 문제를 논의하기 위한 비변사가 설치되었다.', '세계 지도인 혼일강리역대국도지도가 제작되었다.', '한양을 기준으로 한 역법서인 칠정산이 간행되었다.', 4, '문화유산이 전하는 이야기 - 광통교. 청계천이 복원되면서 광통교도 옛 모습을 되찾았어요. 이 광통교에는 능에 썼던 석물들이 있어요. 두 차례 왕자의 난으로 즉위한 (가) 이/가 태조의 계비인 신덕 왕후의 능을 이장하고, 이전 능에 있던 병풍석과 난간석 등 석물 일부를 다리 제작에 사용하게 한 것이에요.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 20, '밑줄 그은 ''이 기구''에 대한 설명으로 옳은 것은?', 2, '왕명의 출납을 관장하였다.', '사간원, 사헌부와 함께 3사로 불렸다.', '천문 연구, 기상 관측 등의 일을 맡았다.', '실록을 보관하고 관리하는 업무를 담당하였다.', '국왕 직속 사법 기구로 강상죄, 반역죄 등을 처결하였다.', 1, '이 책은 1870년에 편찬된 은대조례입니다. 서문에서 흥선 대원군은 은대라고 불린 이 기구의 업무 처리 규정을 일목요연하게 정리하였으니 앞으로 승지들의 사무에 나침반이 될 것이라고 밝혔습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 21, '다음 검색창에 들어갈 인물의 활동으로 옳은 것은?', 3, '기해 예송에서 기년설을 주장하였다.', '반정 공신의 위훈 삭제를 건의하였다.', '향촌의 풍속 교화를 위해 예안 향약을 시행하였다.', '최초로 100리 척을 사용한 동국지도를 제작하였다.', '일본의 정치, 사회, 지리 등을 정리한 해동제국기를 저술하였다.', 5, '한국사 인물 통합 검색 - 생몰: 1417년~1475년. 호: 희현당(希賢堂), 보한재(保閑齋). 생애: 집현전 학사로 훈민정음 해례본 편찬에 참여함 / 계유정난으로 정난공신 2등에 책훈됨 / 세조 대 사대교린의 외교 정책을 주도함 / 예종 즉위 후 한명회 등과 원상(院相)으로 국정을 논의함', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 22, '(가) 왕이 추진한 정책으로 옳은 것은?', 3, '창덕궁에 신문고를 처음 설치하였다.', '삼수병으로 구성된 훈련도감을 창설하였다.', '붕당 정치의 폐단을 경계하고자 탕평비를 세웠다.', '통치 체제를 정비하기 위해 대전통편을 간행하였다.', '유교 윤리의 보급을 위해 삼강행실도를 편찬하였다.', 5, '□□신문 - 관현맹(管絃盲) 공연, 경복궁에서 재현. 조선 시대 관현맹의 공연을 재현하는 행사가 경복궁 수정전에서 개최되었다. 관현맹은 궁중 잔치에서 연주한 시각장애인 악사인데, 박연의 상소를 계기로 (가) 때 관직과 곡식을 받게 되었다. 이번 공연에서는 (가) 이/가 작곡한 여민락(與民樂)을 시작으로 여러 곡이 연주되었다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 23, '다음 상인이 등장한 배경으로 가장 적절한 것은?', 1, '관수 관급제가 시행되었다.', '금속 화폐인 건원중보가 주조되었다.', '근대적 상회사인 대동 상회가 설립되었다.', '공납의 폐단을 시정하기 위해 대동법이 실시되었다.', '육의전을 제외한 시전 상인의 금난전권이 폐지되었다.', 4, '우리 역사 속 직업의 세계 - 직업 소개: 선혜청 등에서 공가(貢價)를 받아 필요한 물품을 마련하여 궁궐과 관청에 납품하는 상인. 요구 능력: 물품을 대량으로 구입하여 기일에 맞춰 조달할 수 있는 능력.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 24, '밑줄 그은 ''이 성곽''에 대한 설명으로 옳지 않은 것은?', 2, '개국 초기 정도전 등이 설계하였다.', '도성조축도감이 축조를 관장하였다.', '후금의 침입에 맞서 정봉수가 항전한 곳이다.', '조선 시대 축성 기술의 변화 과정이 잘 나타나 있다.', '일제 강점기 도시 정비 계획을 구실로 크게 훼손되었다.', 3, '이 성곽은 한성부 도심의 경계를 표시하고 외부의 침입을 방어하기 위해 축조되었습니다. 총 둘레는 약 18km로 4대문과 4소문 및 암문, 수문, 여장, 옹성 등의 시설을 갖추고 있습니다. (북악산, 숙정문, 흥인지문, 숭례문, 돈의문 등)', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 25, '다음 전투 이후에 전개된 사실로 옳은 것은?', 2, '최영이 홍산에서 대승을 거두었다.', '이순신이 한산도 대첩에서 승리하였다.', '휴전 회담의 결렬로 정유재란이 시작되었다.', '이종무가 왜구의 근거지인 쓰시마를 정벌하였다.', '신립이 탄금대에서 배수의 진을 치고 왜군에 항전하였다.', 3, '권율이 정병 4천 명을 뽑아 행주산 위에 진을 치고는 책(柵)을 설치하여 방비하였다. …… 적은 올려다보고 공격하는 처지가 되어 탄환도 맞히지 못하는데 반해 호남의 씩씩한 군사들은 모두 활쏘기를 잘하여 쏘는 대로 적중시켰다. …… 적이 결국 패해 후퇴하였다. - 『선조수정실록』 -', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 26, '밑줄 그은 ''임금''의 재위 기간에 있었던 사실로 옳은 것은?', 3, '사림이 동인과 서인으로 나뉘었다.', '외척 간의 대립으로 을사사화가 일어났다.', '서인이 반정을 일으켜 정권을 장악하였다.', '김종직 등 사림이 중앙 정계에 진출하기 시작하였다.', '폐비 윤씨 사사 사건의 전말이 알려져 김굉필 등이 처형되었다.', 2, '감히 대비마마를 욕보이다니. 당장 이 벽서를 떼어다 임금께 올리세. / 게다가 누구나 볼 수 있는 양재역 벽에 이런 참담한 내용을 써 붙이다니 당장 고하러 가세나. (벽서: 여주(女主)가 위에서 정권을 잡고 간신 이기(李?) 등이 아래에서 권세를 제멋대로 휘두르고 있다. 나라가 장차 망할 것을 서서 기다릴 수 있게 됐다.)', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 27, '(가) 문화유산에 대한 설명으로 옳은 것을 <보기>에서 고른 것은? ㄱ.고종이 아관파천 이후 환궁한 곳이다. ㄴ.포루, 공심돈 등 방어 시설을 갖추었다. ㄷ.당백전을 발행하여 건설 비용에 충당하였다. ㄹ.정약용이 고안한 거중기 등을 이용하여 축조되었다.', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 4, '정조가 정치적 이상을 담아 축조한 (가) 안의 모습이 참 예쁘네! / 정조가 행차할 때 머물렀던 행궁과 장용영 군사를 지휘했던 서장대도 보여.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 28, '(가), (나)를 쓴 인물의 공통점으로 옳은 것은?', 2, '갑술환국으로 정계에서 축출되었다.', '양명학을 연구하여 강화학파를 형성하였다.', '서얼 출신으로 규장각 검서관에 기용되었다.', '연행사의 일원으로 청에 다녀와 연행록을 남겼다.', '농민 생활의 안정을 위하여 화폐 사용을 반대하였다.', 4, '(가) 실옹이 웃으며 말하기를, "…… 대저 땅덩이는 하루 동안에 한 바퀴를 도는데, 땅 둘레는 9만 리이고 하루는 12시이다. 9만 리 넓은 둘레를 12시간에 도니 번개나 포탄보다도 더 빠른 셈이다."라고 하였다. / (나) 허생이 말하기를, "우리 조선은 배가 외국과 통하지 못하고, 수레가 국내에 두루 다니지 못하는 까닭에 온갖 물건이 나라 안에서 생산되어 소비되곤 하지 않나. …… 어떤 물건 하나를 슬그머니 독점한다면, 그 물건은 한 곳에 갇혀서 유통되지 못하니 이는 백성을 못살게 하는 방법이야."라고 하였다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 29, '밑줄 그은 ''시기''에 볼 수 있는 모습으로 옳지 않은 것은?', 1, '판소리를 구경하는 농민', '탈춤 공연을 벌이는 광대', '장시에서 물품을 파는 보부상', '한글 소설을 읽어주는 전기수', '벽란도에서 인삼을 사는 송의 상인', 5, '이 그림은 책과 함께 도자기, 문방구 등이 놓인 책가를 그린 책가도입니다. 책가도가 유행한 시기에는 다양한 주제의 민화가 왕실과 사대부뿐만 아니라 서민들에게도 인기를 끌었습니다.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 30, '밑줄 그은 ''이 사건''이 일어난 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 4, '이곳은 강화도 광성보 끝자락 용두돈대. 광성보는 이 사건 당시 침입한 미군에 맞서 어재연 장군의 지휘 아래 조선군이 결사 항전한 곳임. (연표) 홍경래의 난 - 고종 즉위 - 제너럴 셔먼호 사건 - 오페르트 도굴 사건 - 척화비 건립 - 강화도 조약. (가)=홍경래의 난~고종 즉위, (나)=고종 즉위~제너럴 셔먼호, (다)=제너럴 셔먼호~오페르트, (라)=오페르트~척화비, (마)=척화비~강화도 조약.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 31, '밑줄 그은 ''개혁''에 해당하는 내용으로 옳은 것은?', 2, '건양이라는 연호를 사용하였다.', '신식 군대인 별기군을 창설하였다.', '관립 의학교와 광제원을 설립하였다.', '박문국을 설치하여 한성순보를 발간하였다.', '한일 관계 사료집을 편찬하고 독립 공채를 발행하였다.', 3, '삽화로 보는 한국사 - [해설] 이 그림은 프랑스 일간지에 실린 삽화로 파리 만국 박람회장에 설치된 한국관의 모습을 담고 있습니다. 경복궁 근정전을 재현한 한국관은 당시 언론의 관심을 끌었습니다. 황제로 즉위한 뒤 개혁을 추진하던 고종은 만국 박람회 참가를 통해 대한 제국을 세계에 소개하고, 서구의 산업과 기술을 받아들이고자 하였습니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 32, '(가)에 들어갈 내용으로 옳은 것은?', 2, '교정청 설치', '전봉준 체포', '13도 창의군 결성', '안핵사 이용태 파견', '남접과 북접의 연합', 5, '동학 농민 운동의 전개 과정 (지도) - 고부 농민 봉기 → 황토현 전투 → 전주 화약 체결 → 일본군의 경복궁 점령 → (가) → 우금치 전투', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 33, '밑줄 그은 ''조약''의 영향으로 가장 적절한 것은?', 2, '부산, 원산, 인천 항구가 개항되었다.', '김홍집이 국내에 조선책략을 소개하였다.', '민영익을 대표로 한 보빙사가 파견되었다.', '일본 군함 운요호가 영종도를 공격하였다.', '개화 정책을 총괄하는 통리기무아문이 설치되었다.', 3, '청의 알선으로 서양과 맺은 최초의 조약이 체결된 장소에 새로운 표석이 설치되었습니다. 기존 한글 안내판에 영어와 중국어 안내문을 추가한 이번 표석 설치는 개항기 대외 관계와 관련한 중요한 장소를 외국인에게도 널리 알리는 기회가 될 것으로 보입니다. (영어, 중국어 안내문을 추가한 표석 설치)', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 34, '교사의 질문에 대한 학생의 답변으로 옳은 것은?', 2, '민립 대학 설립 운동을 전개하였어요.', '러시아의 절영도 조차 요구를 저지하였어요.', '파리 강화 회의에 독립 청원서를 제출하였어요.', '안창호, 양기탁 등이 비밀 결사로 조직하였어요.', '국문 연구소를 세워 한글의 문자 체계를 정리하였어요.', 4, '이것은 대한매일신보에 태극 서관이 게재한 서적 할인 광고입니다. 태극 서관은 신지식 보급과 민족의식 고취를 위해 이 단체가 운영한 기관입니다. 인재 양성을 위해 대성 학교도 설립한 이 단체에 대해 말해 볼까요? (평양 종로 태극서관, 관주 이승훈)', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 35, '다음 인물의 활동으로 옳은 것은?', 3, '화폐 정리 사업을 주도하였다.', '한글로 된 교재인 사민필지를 집필하였다.', '여성 교육 기관인 이화 학당을 설립하였다.', '친일 인사 스티븐스를 샌프란시스코에서 사살하였다.', '논설 단연보국채를 써서 국채 보상 운동에 적극 참여하였다.', 2, '나는 23세 때 육영 공원의 교사로 조선에 와서 학생들을 가르쳤소. 고종의 특사가 되어 만국 평화 회의가 열린 헤이그를 방문하였고, 대한 제국 멸망사를 출간하기도 했소. 나는 한국인의 권리와 자유를 위해 싸워왔으며 한국인에 대한 사랑은 내 인생의 가장 소중한 가치라오. 나는 웨스트민스터 사원보다 한국 땅에 묻히기를 염원하오. (헐버트)', '근대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 36, '(가) 단체의 활동으로 옳은 것은?', 2, '일제의 황무지 개간권 요구를 저지하였다.', '중추원 개편을 통한 의회 설립을 추진하였다.', '농촌 계몽을 위한 브나로드 운동을 전개하였다.', '외교 활동을 펼치기 위해 구미 위원부를 설치하였다.', '여성의 평등한 권리를 주장하는 여권통문을 발표하였다.', 2, '아들아, 제중원 의학교 1회 졸업생이 된 것을 축하한다. 백정의 아들로 태어나 차별을 극복하고 의사가 된다니 정말 자랑스럽구나. / 10년 전 (가) 이/가 주관한 관민 공동회 개회식에서 당당하게 충군애국의 뜻을 밝히신 아버지의 연설에 감명을 받아 열심히 공부할 수 있었습니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 37, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '광주 학생 항일 운동이 일어났다.', '임병찬이 독립 의군부를 조직하였다.', '독립군이 봉오동에서 큰 승리를 거두었다.', '도쿄 유학생들이 2·8 독립 선언서를 발표하였다.', '조선 민족 전선 연맹 산하에 조선 의용대가 창설되었다.', 1, '(가) 조선 사회 운동 단체인 정우회는 며칠 전 선언서를 발표하였다. 선언서에서 민족주의적 세력과 과도기적 동맹자적 관계를 구축해야 한다고 밝히고 타협과 항쟁을 분리시켜 사회 운동 본래의 사명을 잊지 말자는 것을 말하였다. / (나) 조선 민족 운동의 중추 기관이 되려는 사명을 띠고 창립되었던 신간회가 비로소 첫 번째 전체 대회를 개최하였다. 그러나 간신히 열리는 전체 대회에서 해소 문제 토의를 최대 의제로 하게 된 것은 조선의 현 상황이 아니고서는 보기 어려운 기현상이다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 38, '밑줄 그은 ''이곳''에 해당하는 지역을 지도에서 옳게 고른 것은?', 1, '(가)', '(나)', '(다)', '(라)', '(마)', 4, '박용만은 1905년 국외로 떠난 이후 네브라스카주에서 대학을 다니며 독립군 양성 기관인 한인 소년병 학교를 창설하고, 국민개병설을 집필했습니다. 그후 이곳으로 건너와 대조선 국민군단을 조직하여 독립 전쟁을 준비했습니다. (지도: (가) 서간도, (나) 연해주, (다) 상하이, (라) 하와이, (마) 멕시코)', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 39, '(가), (나) 인물에 대한 설명으로 옳은 것은?', 3, '(가) - 조선 혁명 간부 학교를 설립하였다.', '(가) - 대한 광복회를 조직하여 친일파를 처단하였다.', '(나) - 대전자령 전투에서 일본군에 대승을 거두었다.', '(나) - 중광단을 중심으로 북로 군정서를 조직하였다.', '(가), (나) - 황푸 군관 학교에 입학하여 군사 훈련을 받았다.', 3, '국외 독립 전쟁을 이끈 독립운동가 - (가) 생몰 1896~1934년, 대한 통의부 의군으로 활동, 조선 혁명군 총사령관으로 항일 투쟁 전개, 일제의 밀정에 의해 사망, 1962년 건국훈장 독립장 추서 / (나) 생몰 1888~1957년, 신흥 무관 학교 교성 대장으로 독립군 양성, 한국 독립군 총사령관으로 항일 투쟁 전개, 한국광복군 총사령관에 취임, 1962년 건국훈장 대통령장 추서', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 40, '밑줄 그은 ''시기''의 일제 정책으로 옳은 것은?', 1, '치안 유지법을 공포하였다.', '토지 조사령을 제정하였다.', '헌병 경찰 제도를 실시하였다.', '식량 배급 및 미곡 공출제를 시행하였다.', '보통학교의 수업 연한을 4년으로 정하였다.', 4, '부평 공원 내에 있는 이 동상은 일제의 무기 공장인 조병창 등에 강제 동원된 노동자의 모습을 형상화한 작품입니다. 중일 전쟁 이후 침략 전쟁을 확대하던 시기에 일제는 한국인을 탄광, 군수 공장 등으로 끌고 가 열악한 환경에서 혹사시켰습니다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 41, '(가) 정부에 대한 설명으로 옳은 것은?', 2, '좌우 합작 7원칙을 발표하였다.', '한인 자치 기관인 경학사를 조직하였다.', '조선 혁명 선언을 활동 지침으로 삼았다.', '한글 맞춤법 통일안과 표준어를 제정하였다.', '삼균주의를 기초로 한 건국 강령을 선포하였다.', 5, '이것은 (가) 요인들의 가족이 중심이 되어 조직한 한국 혁명 여성 동맹의 창립 기념 사진입니다. 이 단체는 충칭에서 대일 선전 성명서를 발표한 (가) 의 독립운동을 지원하고 교육 활동 등에 주력하였습니다.', '일제', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 42, '(가) 사건에 대한 설명으로 옳은 것은?', 2, '유신 헌법의 철폐를 요구하였다.', '통일 주체 국민 회의가 설치되는 결과를 가져왔다.', '희생자들의 명예 회복을 위한 특별법이 제정되었다.', '4·13 호헌 철폐와 독재 타도 등의 구호를 내세웠다.', '귀속 재산 처리를 위한 신한 공사 설립의 계기가 되었다.', 3, '기념관에 있는 이 비석은 왜 아무 글자도 새겨져 있지 않은 걸까? / (가) 의 역사적 평가가 아직 마무리되지 못했음을 상징하는 거래. 제주도에서 일어난 (가) 은/는 남한만의 단독 선거를 반대하는 무장대와 이를 진압하는 토벌대 간의 무력 충돌이 있었고, 그 뒤 진압 과정에서 수많은 사람이 희생된 사건이야.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 43, '(가) 전쟁 중 있었던 사실로 옳은 것은?', 1, '6·3 시위가 발생하였다.', '애치슨 선언이 발표되었다.', '브라운 각서가 체결되었다.', '부마 민주 항쟁이 일어났다.', '인천 상륙 작전이 전개되었다.', 5, '국민 보도 연맹 사건은 우리 현대사의 커다란 비극입니다. 좌우 대립의 혼란 속에서 수많은 사람들이 국민 보도 연맹에 가입되었고, (가) 의 와중에 영문도 모른 채 끌려 가 죽임을 당했습니다. …… 저는 대통령으로서 국가를 대표해서 당시 국가 권력이 저지른 불법 행위에 대해 진심으로 사과드립니다. - 「울산 국민 보도 연맹 사건 희생자 추모식에 보내는 편지」 -', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 44, '밑줄 그은 ''개헌안''이 발표된 이후의 사실로 옳은 것은?', 3, '반민족 행위 처벌법이 제정되었다.', '제2차 미소 공동 위원회가 결렬되었다.', '국회가 민의원과 참의원의 양원제로 운영되었다.', '평화 통일론을 주장한 진보당의 조봉암이 구속되었다.', '유상 매수, 유상 분배 원칙의 농지 개혁법이 제정되었다.', 3, '이번에 여야 합의로 내각 책임제 개헌안이 통과되었군. / 이 개헌안에 따라 허정 과도 정부가 총선을 실시하면 정국에 많은 변화가 있을 것 같네.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 45, '다음 정부 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 2, '최저 임금법 제정으로 최저 임금을 심의하는 위원', '금융 실명제에 따라 신분증 제시를 요구하는 은행원', '한·칠레 자유 무역 협정(FTA)의 비준을 보도하는 기자', '전국 민주 노동조합 총연맹 창립 대회에 참가하는 노동자', '정부의 도시 정책에 반발해 시위를 하는 광주 대단지 이주민', 5, '실감 콘텐츠로 만나는 ○○○ 정부 - 포항 제철소 착공식, 제1차 석유 파동으로 멈춰 선 버스, 100억 불 수출 달성', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 46, '(가) 민주화 운동에 대한 설명으로 옳은 것은?', 1, '시위 도중 대학생 이한열이 희생되었다.', '경무대로 향하던 시위대가 경찰의 총격을 받았다.', '박종철 고문 치사 사건의 진상 규명을 요구하였다.', '신군부의 비상계엄 확대와 무력 진압에 저항하였다.', '3·1 민주 구국 선언을 통해 긴급 조치 철폐 등을 주장하였다.', 4, '이 곡은 (가) 기념식에서 제창하는 노래입니다. (가) 당시 계엄군에 맞서 시민군으로 활동하다 희생된 윤상원과 광주에서 야학을 운영하다 사망한 박기순의 영혼 결혼식에 헌정된 노래입니다. (임을 위한 행진곡)', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 47, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '남북 조절 위원회가 구성되었다.', '7·4 남북 공동 성명이 발표되었다.', '개성 공업 지구 건설이 착공되었다.', '남북한 비핵화 공동 선언이 채택되었다.', '남북 이산가족 고향 방문단의 교환 방문이 최초로 성사되었다.', 3, '(가) 2. 남과 북은 나라의 통일을 위한 남측의 연합제 안과 북측의 낮은 단계의 연방제 안이 서로 공통성이 있다고 인정하고, 앞으로 이 방향에서 통일을 지향시켜 나가기로 하였다. - 「6·15 남북 공동 선언」 - / (나) 4. 남과 북은 현 정전 체제를 종식시키고 항구적인 평화 체제를 구축해 나가야 한다는 데 인식을 같이하고 직접 관련된 3자 또는 4자 정상들이 한반도 지역에서 만나 종전을 선언하는 문제를 추진하기 위해 협력해 나가기로 하였다. - 「10·4 남북 정상 선언」 -', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 48, '(가) 문화유산에 대한 설명으로 옳은 것을 <보기>에서 고른 것은? ㄱ.사초와 시정기를 바탕으로 편찬되었다. ㄴ.연대순으로 기록하는 편년체로 구성되었다. ㄷ.왕의 열람을 위한 어람용이 따로 제작되었다. ㄹ.병인양요 당시 일부가 프랑스군에게 약탈되었다.', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 5, '저는 지금 파리에서 열린 한지 공예 특별전에 나와 있습니다. 이 작품은 영조와 정순 왕후의 혼례식 행렬을 1,100여 점의 닥종이 인형으로 재현한 것입니다. 조선 시대 왕실이나 국가의 큰 행사가 있을 때 일체의 관련 사실을 글과 그림으로 기록한 책인 (가) 을/를 바탕으로 제작되었습니다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 49, '(가)~(라)를 활용한 탐구 활동으로 적절한 것을 <보기>에서 고른 것은? ㄱ.(가)-최승로의 시무 28조를 받아들여 달라진 제도를 살펴본다. ㄴ.(나)-광종이 왕권 강화를 위해 추진한 정책에 대해 알아본다. ㄷ.(다)-중종 때 사림파 언관들이 제기한 주장을 조사해 본다. ㄹ.(라)-임술 농민 봉기를 수습하기 위한 정부의 대책을 파악한다.', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 3, '(가) 처음으로 독서삼품을 정하여 관리를 선발하였다. …… (나) 쌍기가 의견을 올리니 처음으로 ㉠이 제도를 마련하여 시행하였다. 시·부·송 및 시무책으로 시험하여 진사를 뽑았으며, 겸하여 명경업·의업·복업 등도 뽑았다. / (다) 조광조가 아뢰기를, "중앙에서는 홍문관·육경·대간, 지방에서는 감사와 수령이 천거한 사람들을 대궐에 모아 시험을 치르면 많은 인재를 얻을 수 있을 것입니다. ㉡이 제도는 한(漢)에서 시행한 현량방정과의 뜻을 이은 것입니다."라고 하였다. / (라) 제4조 의정부 및 각 부 판임관을 임명할 시에는 각기 관하 학도 및 외국 유학생 졸업자 중에서 시험을 거쳐 해당 주무 장관이 전권으로 임명한다.', '복합', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (62, 50, '밑줄 그은 ㉠, ㉡에 대한 설명으로 옳은 것은?', 3, '㉠ - 역분전이 제정되는 결과를 가져왔다.', '㉠ - 지공거와 합격자 사이에 좌주와 문생 관계가 형성되었다.', '㉡ - 제술과, 명경과, 잡과, 승과로 구성되었다.', '㉡ - 성균관에서 보는 관시, 한성부에서 보는 한성시, 각 지방에서 보는 향시로 나뉘었다.', '㉠, ㉡ - 홍범 14조 반포를 계기로 시행되었다.', 2, '(위 49번과 동일 자료: ㉠ 과거제(광종), ㉡ 현량과(조광조))', '복합', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 1, '(가) 시대의 생활 모습으로 가장 적절한 것은?', 1, '목책과 환호 등 방어 시설을 갖추었다.', '소를 이용한 깊이갈이가 일반화되었다.', '농경과 목축을 통해 식량을 생산하였다.', '지배층의 무덤으로 고인돌을 축조하였다.', '거푸집을 이용하여 세형 동검을 제작하였다.', 3, '올해는 서울 암사동 유적 발견 100주년입니다. 1925년 을축년 대홍수로 우연히 모습이 드러난 이 유적은 수차례 발굴 과정에서 (가) 시대의 대표적 유물인 빗살무늬 토기와 갈돌, 갈판이 출토되고, 유구인 집터가 발견되었습니다.', '선사(신석기)', '생활/경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 2, '밑줄 그은 ''이 나라''에 대한 설명으로 옳은 것은?', 2, '여러 가(加)들이 사출도를 다스렸다.', '동맹이라는 제천 행사를 개최하였다.', '민며느리제라는 혼인 풍습이 있었다.', '읍락 간의 경계를 중시하는 책화가 있었다.', '왕 아래 상가, 대부, 장군 등의 관직을 두었다.', 5, '이곳 강화 참성단은 단군왕검이 하늘에 제사를 올리던 제단이라고 전합니다. 우리 역사상 최초의 국가인 이 나라를 세운 것을 기념하는 개천절 행사가 매년 열리며, 전국체육대회 성화 채화식도 이곳에서 거행됩니다.', '선사(고조선)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 3, '(가) 국가에서 볼 수 있는 모습으로 가장 적절한 것은?', 2, '녹과전을 지급받는 관리', '경당에서 수련하는 청년', '팔만대장경판을 만드는 장인', '지방의 22담로에 파견되는 왕족', '황룡사 구층 목탑의 축조를 건의하는 승려', 2, '이번에 촉각 전시물로 새롭게 제작된 장군총은 (가) 의 대표적인 무덤입니다. 반듯하게 다듬은 돌을 계단처럼 쌓아 만든 이 무덤의 높이는 약 13미터이고, 한 변의 최대 길이는 약 31미터에 달합니다. 거대한 크기를 고려할 때 왕의 무덤일 가능성이 높습니다. 이 무덤의 주인이 누구였을지 상상하며 만져보면 어떨까요?', '고대(고구려)', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 4, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '백제가 국호를 남부여로 고쳤다.', '진흥왕이 대가야를 공격하여 복속시켰다.', '계백이 이끈 결사대가 황산벌에서 패배하였다.', '김춘추가 당으로 건너가 군사 동맹을 체결하였다.', '신라가 한강 하류를 차지하여 신주를 설치하였다.', 2, '(가) 백제왕 명농이 가야와 함께 와서 관산성을 공격하였다. [신라의] 군주(軍主)인 각간 우덕과 이찬 탐지 등이 맞서 싸웠으나 불리하였다. …… 고간 도도가 급히 쳐서 백제왕을 죽였다. (나) 8월에 [백제왕이] 장군 윤충을 보내 군사 1만을 거느리고 신라 대야성을 공격하였다. 성주 품석이 처자와 함께 나와 항복하자 윤충이 모두 죽이고 그 머리를 베어 왕도로 보냈다.', '고대(삼국)', '정치/외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 5, '(가) 국가에 대한 설명으로 옳은 것은?', 2, '일길찬, 사찬 등의 관등이 있었다.', '지방 장관으로 욕살, 처려근지 등이 있었다.', '특산물로 단궁, 과하마, 반어피가 유명하였다.', '사회 질서를 유지하기 위해 범금 8조를 두었다.', '왕족인 부여씨와 8성 귀족이 지배층을 이루었다.', 5, '여러분이 계신 곳은 (가) 의 능산리 고분군 중 동하총 증강 현실 전시실입니다. 동하총 무덤방의 벽에는 사신도가, 천장에는 연꽃과 구름무늬가 그려져 있습니다. 이는 송산리 6호분과 함께 (가) 의 고분 벽화 연구에 중요한 자료로 평가됩니다.', '고대(백제)', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 6, '밑줄 그은 ''이 왕''에 대한 설명으로 옳은 것은?', 3, '이사부를 보내 우산국을 복속하였다.', '건원이라는 독자적 연호를 사용하였다.', '관료전을 지급하고 녹읍을 폐지하였다.', '거칠부에게 명하여 국사를 편찬하였다.', '지방관을 감찰하고자 외사정을 파견하였다.', 5, 'history_♡ 감은사지, 나홀로 역사 답사 #감은사는 삼국 통일의 위업을 달성한 이 왕이 부처의 힘을 빌어 왜구의 침입을 막고자 짓기 시작한 절이야. 그 뜻을 이어받은 아들 신문왕이 완공했고, 절의 이름을 #감은사라고 지었다고 해. 나는 이제 이 왕의 수중릉인 #대왕암으로 이동.', '고대(신라)', '정치/문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 7, '(가) 국가에 대한 설명으로 옳은 것은?', 2, '왜에 칠지도를 만들어 보냈다.', '9서당 10정의 군사 조직을 운영하였다.', '광평성을 비롯한 각종 정치 기구를 마련하였다.', '제사장인 천군과 신성 지역인 소도가 존재하였다.', '서적 관리, 주요 문서 작성 등을 위해 문적원을 두었다.', 5, '이 지도는 (가) 이/가 주변 국가들과 교역하는 데 이용한 교통로를 나타낸 것입니다. 이 국가는 교통로를 통해 담비?호랑이?표범?곰 등의 가죽과 인삼?우황 등의 약재를 주요 품목으로 주변 국가들과 교역하였습니다. 또한 소그드 은화, 청동 낙타상 등 출토 유물을 통해 서역과의 교류 사실도 확인할 수 있습니다.', '고대(발해)', '경제/외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 8, '(가) 종파에 대한 설명으로 가장 적절한 것은?', 2, '하늘에 제사 지내는 초제를 거행하였다.', '참선과 수행을 통한 깨달음을 강조하였다.', '시경, 서경, 역경 등을 주요 경전으로 삼았다.', '신선 사상을 기반으로 불로장생을 추구하였다.', '인내천 사상을 내세워 인간 평등을 주장하였다.', 2, '이것은 (가) 의 9산문 중 가지산문의 대표 사찰인 보림사에 있는 철조비로자나불좌상입니다. 이 불상의 왼팔 뒤편에 헌안왕 2년 무주 장사현의 부관인 김수종이 아뢰어 만들었다는 새김글이 양각되어 있어 정확한 조성 연대를 알 수 있습니다. 이와 같은 철불은 승탑과 더불어 9세기부터 크게 유행하였습니다.', '고대(신라)', '문화(종교)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 9, '(가)에 들어갈 내용으로 가장 적절한 것은?', 1, '화왕계를 지어 국왕에게 바치다', '산둥반도에 적산 법화원을 창건하다', '외교 문서인 청방인문표를 작성하다', '격황소서를 지어 세상에 이름을 떨치다', '구법순례기인 왕오천축국전을 저술하다', 2, '한국사 동영상 제작 기획안 - ○○○, 동아시아를 무대로 활약하다. [기획 의도] 신라인으로서 동아시아를 무대로 활약한 ○○○의 생애를 다룬 동영상을 제작하여, 당시의 상황과 그의 활동을 살펴본다. [장면별 구성 내용] #1. 당으로 건너가 무령군 소장이 되다 #2. (가) #3. 청해진을 설치하고 동아시아 무역을 주도하다 #4. 왕위 쟁탈전에 휘말려 암살당하다', '고대(신라)', '인물', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 10, '다음 가상 대화 이후에 있었던 사실로 옳은 것은?', 2, '안승이 보덕국왕으로 임명되었다.', '신숭겸이 공산 전투에서 전사하였다.', '원종과 애노가 사벌주에서 반란을 일으켰다.', '왕건이 일리천에서 신검의 군대를 물리쳤다.', '견훤이 고창 전투에서 고려군에게 패배하였다.', 4, '며칠 전에 신라 왕 김부가 우리 고려에 항복하였다는군. / 전해 들었네. 우리 왕께서 신라국을 없애 경주라 하고, 그에게 식읍을 하사하셨다더군.', '고대~고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 11, '밑줄 그은 ''이 왕''이 추진한 정책으로 옳은 것은?', 1, '폐정 개혁을 목표로 정치도감을 설치하였다.', '광덕, 준풍이라는 독자적 연호를 사용하였다.', '예의상정소에서 상정고금예문을 편찬하였다.', '전국에 12목을 설치하고 지방관을 파견하였다.', '관리에게 등급에 따라 전지와 시지를 지급하였다.', 2, '스스로 탐구하는 역사 수업 - 호족 세력을 숙청하고 왕권을 강화한 이 왕에 대해 조사한 내용을 올려주세요. [정치] 억울하게 노비가 된 사람을 양인으로 풀어주는 노비안검법을 실시하였어요. [외교] 후주와의 사신 왕래로 대외 관계 안정을 꾀하였어요. [사회] 빈민을 구제하는 제위보를 설치하였어요.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 12, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '묘청이 칭제 건원을 주장하였다.', '강감찬이 흥화진 전투에서 승리하였다.', '서희의 활약으로 강동 6주를 획득하였다.', '최우가 강화도로 도읍을 옮겨 항전하였다.', '윤관이 별무반을 이끌고 동북 9성을 개척하였다.', 3, '(가) 거란에서 사신을 파견하며 낙타 50필을 보냈다. 왕은 거란이 일찍이 발해와 지속적으로 화목하다가 갑자기 의심을 일으켜 맹약을 어기고 멸망시켰으니, 이는 매우 무도하여 친선 관계를 맺을 이웃으로 삼을 수는 없다고 생각하였다. 드디어 교빙을 끊고 사신 30인을 섬으로 유배 보냈으며, 낙타는 만부교 아래에 매어두니 모두 굶어 죽었다. (나) 왕이 나주로 들어갔는데, 밤에 척후병이 잘못 보고하기를, "거란 군사들이 이르렀습니다."라고 하였다. 왕이 크게 놀라서 밖으로 달려 나오자 지채문이 아뢰어 이르기를, "주상께서 밤중에 행차하시면 백성들이 놀라 혼란하게 되니, 바라옵건대 행궁으로 돌아가십시오. 제가 염탐하여 알아보고 나서, 그 후에 움직이셔도 됩니다."라고 하였다.', '고려', '정치/외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 13, '(가) 국가의 문화유산으로 적절하지 않은 것은?', 3, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 1, '우리 모둠은 영주 부석사 소조여래좌상을 소재로 하여 열쇠고리를 제작하고자 합니다. <한국사 모둠 활동> (가) 시대 문화유산 기념품 디자인 제작 발표회', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 14, '(가)~(다)를 일어난 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (가) - (나)', 1, '(가) 김보당이 정중부?이의방을 토벌하고 의종을 다시 세우고자 …… 동북면지병마사 한언국과 군사를 일으켜 함께 하도록 했다. …… 정중부?이의방이 이 소식을 듣고 장군 이의민, 산원(散員) 박존위로 하여금 군사를 거느리고 남로로 가도록 했고, 또 군사를 서해로도 파견하여 대응하도록 했다. (나) 최충헌은 최충수와 함께 봉사를 올렸다. "…… 낡은 제도를 혁파하고 새로운 정치를 도모하심에 오로지 태조의 올바른 법을 따르시어 중흥의 길을 환히 여시길 바랍니다. 삼가 열 가지 사항을 아뢰옵니다." (다) 왕과 세자가 몽골에서 개경으로 돌아온 이후, 삼별초가 반란을 일으켜 승화후 왕온을 [왕으로] 세우고 진도에 웅거하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 15, '다음 자료에 나타난 시기의 사회 모습으로 적절한 것은?', 2, '서얼이 통청 운동을 전개하였다.', '사창절목에 따라 사창제가 시행되었다.', '왕조 교체를 예언하는 정감록이 유포되었다.', '병자에게 약을 지급하는 혜민국이 설치되었다.', '국산 약재와 치료 방법을 정리한 향약집성방이 간행되었다.', 4, '○ 7재를 설치하였다. 주역을 [공부하는 곳은] 이택재, 상서는 대빙재, 모시(毛詩)는 경덕재, 주례는 구인재, 대례는 복응재, 춘추는 양정재, 무학은 강예재라고 하였다. ○ 왕이 결정하시기를 "…… 무학이 점차 번성하여 장차 무학하는 사람들과 각을 세워 불화하게 되면 매우 편치 못하게 될 것이다. …… 무학으로 무사를 선발하는 일과 무학재의 호칭은 모두 혁파하겠다."라고 하였다.', '고려', '문화(교육)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 16, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '법화 신앙에 중점을 둔 백련 결사를 이끌었다.', '돈오점수를 바탕으로 꾸준한 수행을 강조하였다.', '승려들의 전기를 기록한 해동고승전을 저술하였다.', '선문염송집을 편찬하고 유불 일치설을 주장하였다.', '성상융회를 제창하여 교종 내 대립을 해소하고자 하였다.', 2, '이것은 ''불일보조국사''라는 시호를 받은 (가) 의 행적을 담고 있는 송광사 보조국사비입니다. 비문에는 그가 정혜결사를 조직하고, 「권수정혜결사문」을 지었다는 내용이 들어있습니다. 또한 당시 국왕이 그의 뜻을 흠모하여 그가 머물렀던 송광산 길상사(吉祥寺)를 조계산 수선사(修禪社)로 이름을 바꿔주며 직접 글씨를 써서 보냈다는 등의 내용이 기록되어 있습니다.', '고려', '인물/문화(종교)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 17, '밑줄 그은 ''이 시기''에 볼 수 있는 모습으로 적절한 것은?', 2, '농상집요를 소개하는 관리', '흑창에서 곡식을 빌리는 농민', '사섬서에서 저화를 발행하는 장인', '선혜청에서 공가(貢價)를 받는 상인', '상평통보로 물건을 거래하는 보부상', 1, '권문세족이 도평의사사를 장악하고 대농장을 경영한 이 시기에 많은 여성이 공녀로 끌려갔어. / 지배층을 중심으로 변발과 호복이 유행하였어.', '고려', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 18, '㉠~㉣에 대한 설명으로 옳은 것을 <보기>에서 고른 것은?', 2, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 4, '고려의 중앙 관제 - ⊙2성 6부(당의 영향), ⓒ중추원(송의 영향), ⓒ삼사(송의 영향) → 독자적 정치 기구 → 어사대, ⓐ도병마사, 식목도감', '고려', '정치(제도)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 19, '(가)에 해당하는 문화유산으로 옳은 것은?', 2, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 1, '□□신문 제△△호 2025년 ○○월 ○○일 - 조선 왕실의 신위 제자리로, 155년 만에 재현된 환안제 - (가) 의 보수 공사가 완료됨에 따라, 창덕궁 옛 선원전에 임시 봉안되었던 조선 왕과 왕비, 대한 제국 황제와 황후의 신위 49위를 (가) (으)로 다시 모셔오는 환안제가 155년 만에 재현되었다. 이번 의례에는 내외국인으로 구성된 시민 행렬단도 함께 참여하여 그 의미를 더했다. 환안제와 더불어 앞으로 전시와 체험 프로그램을 비롯해 다채로운 행사가 이어질 예정이다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 20, '(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?', 2, '간경도감이 설치되었다.', '조선경국전이 편찬되었다.', '국조오례의가 완성되었다.', '부민고소금지법이 제정되었다.', '혼일강리역대국도지도가 제작되었다.', 1, '이 그림은 무관 오자치를 그린 것으로, 현존하는 무관 초상화 중에서 가장 이른 시기의 작품입니다. 오자치는 (가) 이/가 호패법을 재실시하는 등 지방 세력 통제를 강화하자, 이에 반발하여 함길도에서 이시애가 일으킨 난을 평정한 공으로 적개공신에 책봉되었습니다.', '조선전기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 21, '밑줄 그은 ''이 전란'' 이후에 있었던 사실로 옳은 것은?', 2, '신숙주가 일본에 다녀와 해동제국기를 저술하였다.', '나세 등이 화포를 사용하여 진포에서 왜구를 격퇴하였다.', '포로 송환을 목적으로 회답겸쇄환사가 일본에 파견되었다.', '조선 정부의 교역 제한에 반발하여 사량진 왜변이 일어났다.', '국방 문제를 논의하기 위한 임시 기구로 비변사가 설치되었다.', 3, '이것은 강화 교섭 결렬 이후 일본의 재침으로 시작된 이 전란 당시 흥양(현재 고흥군) 현감 최희량이 작성한 전과 보고서의 일부입니다. 여기에는 흥양에 침입한 일본군을 격퇴한 사실과 새로 제작한 전선(戰船)에 대한 내용 등이 자세히 기록되어 있으며, 삼도수군통제사 이순신의 서명도 있습니다.', '조선전기', '전쟁/외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 22, '(가) 시기에 있었던 사실로 옳은 것은?', 3, '인조반정으로 북인 세력이 몰락하였다.', '기축옥사로 이발 등 동인 세력이 축출되었다.', '양재역 벽서 사건으로 이언적 등이 화를 입었다.', '인현 왕후가 폐위되고 남인이 권력을 차지하였다.', '붕당의 폐해를 경계하기 위해 탕평비가 건립되었다.', 4, '부왕께서 승하하신 기해년에는 고대 중국의 예가 아닌 경국대전에 따라 기년복으로 정했다고 기억한다. 오늘의 대공복 또한 경국대전에 따라 정한 것인가? / 성상을 시해하려는 자가 있다는 목극룡의 고변으로 조정이 큰 혼란에 휩싸였었군. / 연잉군과 노론이 곤경에 처하게 될 것 같군.', '조선후기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 23, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '최초의 서원인 백운동 서원을 건립하였다.', '명에 대한 의리를 내세운 기축봉사를 올렸다.', '동호문답을 통해 다양한 개혁 방안을 제시하였다.', '예안 향약을 시행하여 향촌의 교화를 위해 노력하였다.', '예학을 조선의 현실에 맞게 정리한 가례집람을 저술하였다.', 4, '이 그림은 강세황이 그린 도산서원도입니다. 여기에는 서원의 배치와 크기, 방향 등이 실제와 부합하게 묘사되어 있으며 건물 이름도 표기되어 있어 당시의 모습을 잘 보여줍니다. 도산 서원은 성학십도를 지어 군주의 수양을 강조하고, 기대승과 사단칠정 논쟁을 전개한 (가) 의 학문과 덕을 기리는 곳입니다.', '조선전기', '인물/문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 24, '(가) 왕이 추진한 정책으로 옳은 것은?', 1, '나선 정벌에 조총 부대를 파견하였다.', '호포제를 시행하여 양반에게도 군포를 징수하였다.', '문신을 재교육하기 위한 초계문신제를 실시하였다.', '삼정의 문란을 시정하고자 삼정이정청을 설치하였다.', '각 궁방과 중앙 관서의 공노비 6만여 명을 해방하였다.', 3, '[해설] 이것은 장용영 내영에서 수원외사와 번암 채제공에게 보낸 전령(傳令)입니다. 새롭게 마련된 장용영 절목의 문제점을 중앙에 아뢰어 고치도록 권한 내용을 담고 있습니다. 장용영은 (가) 이/가 조직한 친위 부대로 서울에 내영, 수원 화성에 외영을 두어 규장각과 함께 왕권 강화를 목적으로 운영되었습니다.', '조선후기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 25, '(가) 사건에 대한 설명으로 옳은 것은?', 3, '한성 조약이 체결되는 결과를 가져왔다.', '정부의 요청으로 출병한 청군이 진압하였다.', '사태의 수습을 위해 박규수가 안핵사로 파견되었다.', '이필제가 영해 지역에서 난을 일으키는 계기가 되었다.', '전개 과정에서 이승훈, 정약용 등이 연루되어 처벌되었다.', 5, '대한민국 방방곡곡 - 제천 배론성지 조회 수 160,514 - 제천 배론성지는 순조 1년(1801)에 일어난 (가) 당시 정부의 탄압을 피해 천주교 교인들이 모여 살던 교우촌에서 비롯되었습니다. 이 안에는 (가) 당시 황사영이 교회의 재건과 신앙의 자유를 호소하기 위해 베이징에 있는 주교에게 보낼 백서를 쓰며 은신했던 토굴이 있습니다.', '조선후기', '사회(종교)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 26, '밑줄 그은 ''이 시기''에 볼 수 있는 모습으로 적절하지 않은 것은?', 1, '판소리 흥보가를 구경하는 농민', '주자소에서 계미자를 만드는 장인', '옥계 시사에서 시를 낭송하는 중인', '세책가에서 춘향전을 빌리는 부녀자', '호랑이를 소재로 민화를 그리는 화가', 2, '모시는 글 - 초대합니다 2025 탈춤 한마당 - 우리 박물관에서는 전국의 주요 탈춤을 한자리에서 만날 수 있는 공연을 마련하였습니다. 상품 화폐 경제의 발달과 서당 교육이 확대된 이 시기에 성행한 탈춤 공연을 통해 서민들의 삶과 애환을 느껴보시기 바랍니다.', '조선후기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 27, '밑줄 그은 ''이 시기''의 경제 상황으로 옳은 것은?', 1, '백성에게 정전이 지급되었다.', '초량 왜관을 통해 일본과 교역하였다.', '주전도감에서 해동통보가 발행되었다.', '벽란도가 국제 무역항으로 번성하였다.', '시장을 관리하기 위한 동시전이 설치되었다.', 2, '이것은 한양의 모습을 그린 수선총도입니다. 지도에서 시전의 위치를 확인할 수 있습니다. 이를 통해 알 수 있는 내용에 대해 더 설명해 주시겠어요? / 지도에는 종로에 위치한 시전 외에도 도성 내 이현, 남대문 밖의 칠패와 같은 난전이 표기되어 있습니다. 이를 통해 시전이 시전 밖으로 확대되고 있던 이 시기의 모습을 확인할 수 있습니다. 당시에는 서로의 취급 물품을 두고 난전과 시전 사이의 갈등, 시전들 간의 다툼이 일어나기도 하였습니다.', '조선후기', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 28, '다음 자료에 대한 탐구 활동으로 가장 적절한 것은?', 2, '한일 의정서의 체결 과정을 파악한다.', '미쓰야 협정이 끼친 영향을 조사한다.', '강화도 조약이 체결된 계기를 알아본다.', '조미 수호 통상 조약의 내용을 분석한다.', '헤이그 특사가 파견되는 원인을 살펴본다.', 4, '왕명에 따라, 귀하가 조선 해관의 세무사로 임명되었음을 알려 드립니다. 이 자료는 조선 정부가 영국인 스트리플링을 인천 해관의 초대 세무사로 임명한다는 문서로, 당시 통리교섭통상사무아문 협판 필렌도르프가 왕명을 받아 발송하였다. 스트리플링은 임명을 받고 두 달 뒤 제물포로 입국하여 인천 해관 창설에 참여하였다. 조선 정부는 인천 해관 창설을 통해 관세 부과 업무를 공식적으로 시작하였다.', '근대(개항기)', '경제/외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 29, '(가)~(마)에 들어갈 내용으로 적절하지 않은 것은?', 2, '(가) - 북학 사상을 바탕으로 통상 개화론을 주장하다', '(나) - 영남 만인소를 주도해 개항과 통상에 반대하다', '(다) - 보빙사로 미국에 다녀와 개화 정책을 추진하다', '(라) - 서유견문을 집필하여 서양 근대 문명을 소개하다', '(마) - 백정 출신으로 관민 공동회에서 연설하다', 3, '[역사 다큐멘터리 기획안] 격랑의 시대, 그들이 걸어간 길 - [기획 의도] 개항 전후 격변하는 시대 상황 속에서 각 인물이 마주한 고민과 선택을 중심으로 그들의 활동을 살펴본다. [회차별 방송 내용] 1회. 박규수, (가) / 2회. 이만손, (나) / 3회. 김홍집, (다) / 4회. 유길준, (라) / 5회. 박성춘, (마)', '근대(개항기)', '인물', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 30, '밑줄 그은 ''개혁''의 내용으로 옳은 것은?', 2, '지계아문을 설치하여 지계를 발급하였다.', '건양이라는 독자적인 연호를 채택하였다.', '박문국을 설치하고 한성순보를 발행하였다.', '근대식 무기 제조 공장인 기기창을 설립하였다.', '개혁의 방향을 제시한 홍범 14조를 반포하였다.', 1, '이 자료는 파리 만국 박람회 당시 한국관의 모습을 담은 채색 광고 엽서이다. 고종은 황제 즉위 후 구본신참을 내세운 [개혁]을 추진하면서, 박람회를 서구 문물을 받아들이고 우리나라를 세계에 소개하는 기회로 활용하고자 했다. 이후 1902년 고종은 박람회 관련 업무를 담당할 정부 기관으로 농상공부 산하에 임시 박람회 사무소를 개설하였다.', '근대(대한제국)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 31, '(가)에 대한 탐구 활동으로 가장 적절한 것은?', 1, '삼국 간섭의 결과를 알아본다.', '척화비가 건립된 계기를 조사한다.', '전주 화약이 체결되는 과정을 살펴본다.', '영국이 거문도를 점령한 목적을 분석한다.', '외규장각 도서가 약탈된 배경을 찾아본다.', 3, '(가) 에 참여한 이름 없는 이들을 위한 위령탑. 주변 조형물에는 ''농민의 얼굴''과 ''죽창도''가 새겨져 있어 #여기는_정읍시_고부면 - 이 마을에서 전봉준 등이 고부 군수 조병갑의 횡포에 맞서 사발통문을 작성했어. 고부 농민 봉기를 시작으로 전개된 (가) 에 참여한 이들의 흔적을 찾아볼 수 있어.', '근대(개항기)', '정치/사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 32, '다음 가상 대화 이후에 전개된 사실로 옳은 것은?', 2, '최익현이 태인에서 의병을 일으켰다.', '일본이 독도를 불법적으로 편입하였다.', '스티븐스가 외교 고문으로 부임하였다.', '13도 창의군이 서울 진공 작전을 전개하였다.', '유인석이 이끄는 부대가 충주성을 점령하였다.', 4, '몇 달 전 한성에서 시위대 부대원들과 일본군 사이에 시가전이 있었어요. 애비슨 선생님께서는 이때 다친 부대원들을 치료해 주셨는데요. 기억에 남는 일이 있다면 말씀해 주세요. / 군대 해산 명령에 맞서 시위대 대대장 박승환이 자결한 후 전개된 시가전에서 부상 입은 부대원들이 실려 왔습니다. 여자 간호사가 그동안 남자 환자들의 치료를 꺼려하던 관습과 달리 헌신적으로 치료에 나섰습니다. 오래된 관습이 한순간에 깨지는 놀라운 순간이었습니다.', '근대(대한제국)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 33, '밑줄 그은 ''이곳''에서 있었던 민족 운동으로 옳은 것은?', 2, '한인 자치 기구인 경학사를 설립하였다.', '권업신문을 발간하여 민족 의식을 고취하였다.', '유학생을 중심으로 2·8 독립 선언을 발표하였다.', '신한 청년당이 파리 강화 회의에 대표를 파견하였다.', '대조선 국민군단을 결성하고 군사 훈련을 실시하였다.', 5, '첫 공식 이민. 백여 명의 이민자들이 제국이 발행한 여행권을 가슴에 품고 낯선 땅에 1903년 도착했다. 두려움과 희망이 함께했다. / 그들을 기다린 건 사탕수수 농장의 고된 노동이었다. 열악한 환경에서도 1905년까지 노동 이민으로 약 7,000명이 이곳에 이주해 묵묵히 뿌리를 내렸다. / 1910년, 일제의 국권 침탈 후 그들은 돌아갈 곳도 보호받을 나라도 없었다. 고된 환경 속에서도 그들은 한인 사회를 중심으로 스스로 길을 만들어 갔다.', '근대', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 34, '다음 기사가 보도된 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 3, '대한매일신보를 읽고 있는 청년', '경성 제국 대학에 입학하는 학생', '원각사에서 은세계 공연을 보는 여성', '통리기무아문에서 개화 정책을 논의하는 관리', '어린이날 기념 행사에 참여하는 천도교 소년회 회원', 1, '□□신문 제△△호 ○○○○년 ○○월 ○○일 - 정기 연락선 부산 입항, 경부선과 이어지다 - 시모노세키를 출발한 연락선 ''잇키마루''가 어제 부산항에 도착하며 정기 운항을 시작했다. 승객 317명, 화물 300톤을 실을 수 있는 이 배를 통해 일본에서 들어온 여객과 물자는 곧바로 경부선을 이용해 내륙으로 향하게 된다. 올해 1월 경부선이 개통된 이후 8개월 만에 해로까지 연결되면서, 한성-부산-도쿄로 연결되는 교통망이 구축되었다. 두 달 뒤 ''쓰시마마루''도 추가 투입될 예정이라, 머지않아 이 노선은 매일 운행될 것이다.', '근대', '경제/사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 35, '다음 상황이 나타난 시기를 연표에서 옳게 고른 것은?', 3, '(가)', '(나)', '(다)', '(라)', '(마)', 4, '○ 어제 러시아 공사 파블로프씨가 용천군 용암포 삼림채사의 편의를 위하여 전화와 전선을 추가로 가설할 뜻으로 외부(外部)에 조회하였으니, 외부에서 답 조회하기를 "해당 사안은 결코 인준하기 어려우니 귀 공사도 해당 회사에 훈칙하여 전신주 가설 사항은 절대 마음먹지 못하게 하라" 하였다더라. -황성신문- ○ 일본, 영국, 미국의 각 공사가 우리 정부에 의주의 개방을 권고하더니, 영국 공사가 다시 조회하기를 "의주는 육지로 연결되어 화물을 운반하기가 매우 어렵고, …… 용암포는 크고 작은 선박들이 지장 없이 왕래할 수 있으니 용암포를 개항하라"고 하였고, 일본 공사가 또 조회하기를 "용암포 개항이 합당하니 속히 타결하라" 하였더라. -황성신문- [연표] 신미양요 - 갑신정변 - 청일전쟁 발발 - 아관파천 - 러일전쟁 발발 - 국권피탈 ((가)(나)(다)(라)(마) 순서로 배치)', '근대', '외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 36, '(가) 운동에 대한 설명으로 옳은 것은?', 2, '정우회 선언의 영향을 받았다.', '통감부의 탄압과 방해로 중단되었다.', '순종의 인산일을 기회로 삼아 추진되었다.', '전개 과정에서 일제가 제암리 학살 등을 자행하였다.', '성진회와 각 학교 독서회에 의해 전국적으로 확산되었다.', 4, '한국근대 사료DB - 독립운동 관련 판결문 - [상세내용] 이름: 장석재, 나이: 23세, 판결기관: 경성복심법원, 죄명: 보안법 위반, 출판법 위반, 주문: 징역 2년. [사건설명] (가) 당시, 서울 보성고등보통학교 학생으로 독립선언서를 접어 공원과 종로 인근에 배포하고 시위에 참여하였다. 이후 ''조선은 독립국이며 자주민''이라는 요지를 담은 국민 대회 취지서를 돌려 전달하였다. 국민 대회 당시에는 남대문 앞에서 선포문과 취지서 등을 배포하고, 선두에서 태극기를 흔들며 만세를 외치다 붙잡혔다.', '일제강점기', '독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 37, '(가)에 대한 설명으로 옳은 것은?', 1, '고종 강제 퇴위 반대 운동을 전개하였다.', '일제의 황무지 개간권 요구를 저지하였다.', '영은문이 있던 자리 부근에 독립문을 건립하였다.', '독립운동 자금 마련을 위해 독립 공채를 발행하였다.', '조선 총독부에 국권 반환 요구서를 제출하려 하였다.', 4, '저희 모둠에서는 이번 체험 학습 답사지로 백산 상회 설립자 안희제를 기념하는 백산기념관을 선정하였습니다. 백산 상회는 백산 무역 주식회사로 개편된 이후 (가) 의 연통제 조직을 통해 독립운동 자금을 조달하였으며, 독립신문 보급 등의 역할도 담당하였습니다.', '일제강점기', '독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 38, '밑줄 그은 ''이 단체''에 대한 설명으로 옳은 것은?', 2, '원산 노동자 총파업을 지원하였다.', '신흥 강습소를 세워 독립군을 양성하였다.', '김익상, 김상옥 등이 단원으로 활동하였다.', '상덕태상회를 통하여 군자금을 모집하였다.', '도쿄에서 일어난 이봉창 의거를 계획하였다.', 3, '한국사 챗봇 Q: 누구의 동상인지 알려줘. A: 일제 강점기 독립운동가 박재혁입니다. Q: 그의 주요 활동에 대해 알려줘. A: 김원봉이 조직한 이 단체의 일원으로 일제에 항거하기 위해 고서상으로 위장하여 부산 경찰서에 들어가 폭탄을 터뜰렸습니다.', '일제강점기', '독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 39, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '조선불교유신론을 주장하였다.', '식민 사학의 정체성론을 반박하였다.', '조선사 편수회에 들어가 조선사 편찬에 참여하였다.', '진단 학회를 설립하여 실증주의 사학을 발전시켰다.', '민족을 역사 서술의 중심에 둔 독사신론을 집필하였다.', 2, '사료로 보는 한국사 - 조선사 연구는 과거 역사적, 사회적 발전의 변동 과정을 구체적이고 현실적으로 구명함과 동시에 이론화하는 것을 임무로 삼아야 한다. 그것을 위해서는 인류 사회의 일반적 운동 법칙인 사적 변증법으로 그 민족 생활의 계급적 제관계와 더불어 사회 체제의 역사적 변동을 구체적으로 분석하고 다시 그 법칙성을 일반적으로 추상화하는 것에 의해서만 가능하다. [해설] 이 사료는 (가) 이/가 저술한 조선사회경제사의 일부입니다. 그는 이 책에서 한국사가 세계사의 보편적인 발전 법칙에 따라 발전하였다는 주장을 펼치며 한국 고대 경제사를 원시 씨족 사회, 원시 부족 국가의 계형, 노예 국가 시대로 체계화하여 서술하였습니다.', '일제강점기', '인물/문화(역사학)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 40, '(가)에 들어갈 내용으로 적절하지 않은 것은?', 1, '잡지 신여성, 여권 신장을 주장하다', '조선 형평사, 사회적 차별 철폐를 외치다', '소설 상록수, 브나로드 운동을 널리 알리다', '경성 방직 주식회사, 광목 태극성을 광고하다', '새마을 운동, 근면·자조·협동을 기치로 내세우다', 5, '한국사 웹 드라마 기획안 - 제목: 식민지 조선인의 삶 - [구성 내용] 1화. 단성사, 영화 아리랑을 상영하다 2화. 몸뻬, 새로운 일상복으로 강요되다 3화. 목포의 눈물, 나라 잃은 설움을 노래하다 4화. (가) - [주의사항] 역사적 자료에 근거하여 각 30분 분량으로 제작함', '일제강점기', '사회/문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 41, '(가)~(마)에 들어갈 내용으로 적절하지 않은 것은?', 2, '(가) - 일본군의 보복으로 간도 참변이 일어나다', '(나) - 관동 대지진 당시 자경단에게 학살당하다', '(다) - 에네켄 농장에서 고된 노동에 시달리다', '(라) - 소련 당국에 의해 강제로 이주되어 오다', '(마) - 교민들을 중심으로 흥사단이 창립되다', 3, '모둠별 과제 안내 - 일제 강점기 국외 동포들의 삶과 시련을 주제로 보고서를 작성한 후 제목과 함께 게시판에 올려주세요. 과제 마감일은 5월 24일입니다. [번호-제목] 1모둠-만주 (가) / 2모둠-일본 (나) / 3모둠-연해주 (다) / 4모둠-중앙아시아 (라) / 5모둠-미국 (마)', '일제강점기', '독립운동/사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 42, '(가) 부대에 대한 설명으로 옳은 것은?', 2, '봉오동 전투에서 일본군을 크게 격파하였다.', '미국과 연계하여 국내 진공 작전을 계획하였다.', '중국 의용군과 연합하여 영릉가 전투에서 승리하였다.', '조선 민족 전선 연맹 산하의 군사 조직으로 결성되었다.', '한국 독립당의 군사 조직으로 북만주 지역에서 활약하였다.', 5, '【우리 고장의 독립운동가】 이름에 조국의 광복을 담다 - 오광선 (1896~1967) - 경기도 용인특례시 처인구 원삼면 출생으로 본명은 성목이다. 1915년 중국으로 망명한 후 ''조선의 광복''이라는 뜻의 광선(光鮮)으로 개명하였다. 1920년 대한독립군단 중대장으로 독립군을 지휘하였다. 만주 사변이 일어나자 (가) 의 총사령관 지청천 등과 함께 중국군과 연합하여 1933년 대전자령에서 일본군을 상대로 대승을 거두는 데 중요한 역할을 하였다. 1962년 건국훈장 독립장을 받았다.', '일제강점기', '독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 43, '밑줄 그은 ''시기''에 있었던 사실로 옳은 것은?', 1, '조선 태형령이 반포되었다.', '조선 노농 총동맹이 결성되었다.', '임시 토지 조사국이 설립되었다.', '황국 신민 서사 암송이 강요되었다.', '조선 민립 대학 기성회가 창립되었다.', 4, '이 자료는 조선어 학회가 추진하던 조선말 사전 편찬에 보탬이 되고자 함경도의 독자가 보내온 글로 ''배우리(병아리)'', ''고애양(고양이)'' 등 50여 개의 방언이 적혀 있습니다. 국가 총동원법이 시행되던 시기에 일제는 한글 연구를 민족 운동으로 간주하여 조선어 학회 회원들을 치안 유지법 위반 혐의로 대거 투옥하고 원고를 압수하였습니다.', '일제강점기', '독립운동/문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 44, '(가) 사건에 대한 설명으로 가장 적절한 것은?', 2, '대통령이 하야하는 결과를 이끌어냈다.', '호헌 철폐와 독재 타도 등의 구호를 내세웠다.', '통일 주체 국민 회의가 구성되는 배경이 되었다.', '6·3 시위의 전개와 비상계엄이 선포되는 계기가 되었다.', '진상 규명 및 희생자 명예 회복에 관한 특별법이 제정되었다.', 5, '(가) 사건에 대한 기록물이 마침내 유네스코 세계 기록 유산으로 등재되었습니다. 이 사건은 당시 남한만의 단독 선거에 반대하는 무장대와 이를 진압하는 토벌대 간의 무력 충돌, 그 뒤 토벌대의 진압 과정에서 수많은 제주도민이 희생된 비극이었습니다. 기록물에는 수형인 명부와 희생자 유족 증언 등이 포함되어 있는데, 이번 등재로 국가 폭력에 맞서 진실을 밝히려는 노력과 함께 화해와 상생, 평화와 인권의 가치가 세계의 기억으로 인정받게 되었습니다.', '현대', '정치/사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 45, '밑줄 그은 ''이 전쟁'' 중에 있었던 사실로 옳은 것은?', 2, '발췌 개헌안이 통과되었다.', '삼청 교육대가 설치되었다.', '한미 상호 방위 조약이 체결되었다.', '여수·순천 10·19 사건이 일어났다.', '국가 보위 비상 대책 위원회가 구성되었다.', 1, '사진은 이 전쟁 당시 부산의 천막 교실 중 하나입니다. 임시 수도였던 부산에는 서울을 비롯한 각지의 학교가 피란해 와 천막 교실에서 수업이 진행되었습니다. 힘든 생활 중에서도 배움이 멈추지 않았다는 사실을 기억해 주세요.', '현대', '전쟁', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 46, '(가)에 들어갈 민주화 운동에 대한 설명으로 옳은 것은?', 2, '시위 도중 대학생 이한열이 희생되었다.', '시민군이 조직되어 계엄군에 저항하였다.', '허정 과도 정부가 출범하는 계기가 되었다.', '5년 단임의 대통령 직선제 개헌을 이끌어냈다.', '야당 총재의 국회의원직 제명으로 촉발되었다.', 3, '이것은 2?28 민주 운동을 기념하는 탑입니다. 이 운동은 이승만 독재 정권이 선거를 앞두고 야당 부통령 후보 연설에 참석하는 것을 막기 위해 일요일 등교 조치를 내리자, 이에 반발한 대구 지역의 고등학생들이 시위에 나서면서 시작되었습니다. 2?28 민주 운동은 이후 대전의 3?8 민주 의거, 마산의 3?15 의거와 함께 (가) 의 도화선이 되었습니다.', '현대', '정치(민주화운동)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 47, '교사의 질문에 대한 학생의 답변으로 가장 적절한 것은?', 3, '국회 별관에서 3선 개헌안이 통과되었습니다.', '정부에 비판적인 경향신문이 폐간되었습니다.', 'YH 무역 노동자들이 야당 당사에서 농성하였습니다.', '최고 통치 기구인 국가 재건 최고 회의가 구성되었습니다.', '평화 통일론을 주장한 진보당의 조봉암이 처형되었습니다.', 3, '이 자료는 종교계와 재야 인사들이 명동 성당에서 독재 정권을 비판하며 발표한 3?1 민주 구국 선언의 일부입니다. 이 선언이 발표된 이후에 있었던 사실에 대해 말해 볼까요? [민주 구국 선언] 이 나라는 민주주의 기반 위에 서야 한다. …… 첫째로 우리는 국민의 자유를 억압하는 긴급조치를 곧 철폐하고 민주주의를 요구하다가 투옥된 민주 인사들과 학생들을 석방하라고 요구한다. 국민의 의사가 자유로이 표명될 수 있도록 언론, 집회, 출판의 자유를 국민에게 돌리라고 요구한다. 둘째로 우리는 유신 헌법으로 허울만 남은 의회 정치가 회복되어야 한다고 주장한다. ……', '현대', '정치(민주화운동)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 48, '다음 기사가 보도된 정부 시기의 경제 상황으로 적절한 것은?', 2, '경제기획원이 발족하였다.', '제4차 경제 개발 5개년 계획이 추진되었다.', '미국과 자유 무역 협정(FTA)을 체결하였다.', '저유가·저금리·저달러의 3저 호황이 있었다.', '대통령 직속 자문 기구로 노사정 위원회가 출범하였다.', 5, '□□신문 제△△호 ○○○○년 ○○월 ○○일 - IMF 구제 금융 조기 상환 - 오늘 정부는 외환 위기 당시 국제 통화 기금(IMF)으로부터 빌린 돈을 모두 갚았다고 밝혔다. 구제 금융을 신청한 지 3년 8개월 만에 전액 조기 상환하게 된 것이다. 이에 따라 우리나라는 앞으로 정책 수립 과정에서 IMF의 간섭을 받지 않아도 되며, 회원국이면 누구나 해마다 진행하는 연례 협의만 하면 된다.', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 49, '다음 연설문을 발표한 정부 시기의 통일 노력으로 옳은 것은?', 2, '판문점에서 남북 정상 회담을 개최하였다.', '남북한이 국제 연합(UN)에 동시 가입하였다.', '남북 이산가족의 고향 방문을 최초로 성사시켰다.', '평화 통일 외교 정책에 관한 6·23 특별 성명을 발표하였다.', '남북 간 경제 교류 활성화를 위한 개성 공단 착공식을 열었다.', 5, '6?15 공동 선언은 한반도의 운명을 바꾸어 놓은 역사적 전환점이었습니다. …… 남북 당국 간 회담이 100여 차례 이상 열리고, 인적?물적 교류도 크게 늘어났습니다. …… 참여 정부는 햇볕 정책과 6?15 정신을 계승, 발전시킨 ''평화번영 정책''을 추진해 나가고 있습니다. 이대로 가면 한반도에 화해와 협력의 질서가 구축되고, 평화와 번영의 새로운 동북아 시대가 열리게 될 것입니다. 무엇보다 중요한 것은 남북 간 신뢰 구축입니다. 각 분야의 교류와 협력을 활성화시키고, 북핵 문제를 평화적으로 해결해 나가야 합니다.', '현대', '외교(통일)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (74, 50, '㉠~㉤에 대한 설명으로 적절하지 않은 것은?', 3, '㉠ - 원성왕 재위 시기에 시행되었다.', '㉡ - 쌍기의 건의를 수용하여 실시하였다.', '㉢ - 식년시, 알성시, 증광시 등으로 운영되었다.', '㉣ - 중종 때 조광조를 비롯한 사림들이 실시를 주장하였다.', '㉤ - 대한 제국 수립 이후 개혁의 일환으로 처음 단행되었다.', 5, '한국사 톺아보기 - 역사 속 관리 선발 방식 - 신라는 국학 학생 등을 대상으로 유교 경전에 대한 이해 정도를 평가하여 관리로 선발하는 ⊙독서삼품과를 마련하였다. 하지만 골품제 때문에 관료제 운영에 큰 기능을 발휘하지 못하였다. 고려 시대에는 시험을 통해 인재를 등용하는 ⓒ과거가 도입되어 운영되면서 제술과, 명경과, 잡과와 승과와 함께 시행되었다. 그러나 반드시 과거로만 관직에 진출하는 것이 아니라, 음서 등으로 관직에 진출하기도 하였다. 조선 시대의 관리는 과거, 취재, 음서, 천거 등을 통해 선발되었다. 관과는 ⓒ문과, 무과, 잡과로 구성되었는데 문과와 무과를 중심으로 하여 양반 관료 체제가 갖추어졌다. 한편 조선 중기에는 ⓐ현량과를 통해서 조정에 진출한 신진 세력들이 훈구 세력의 부정과 비리를 비판하기도 하였다. 개항기에는 군국기무처의 주도로 과거를 폐지하고 별도의 ⓒ선거조례를 제정하여 과거 시험에서 평가하였던 유교 경전에 대한 지식이나 문장력보다는 실무에 적합한 재능과 능력을 갖춘 인재를 관리로 등용하고자 하였다.', '통사', '정치(제도)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 1, '(가) 시대의 생활 모습으로 가장 적절한 것은?', 1, '주먹도끼 등 뗀석기를 처음 제작하였다.', '소를 이용한 깊이갈이가 널리 보급되었다.', '주로 강가의 동굴이나 막집에 거주하였다.', '많은 인력을 동원하여 고인돌을 축조하였다.', '가락바퀴를 이용하여 실을 뽑기 시작하였다.', 4, '사유 재산과 계급이 발생한 (가) 시대의 생활 모습을 잘 보여주는 부여 송국리 유적이 발굴 50주년을 맞이하였습니다. 우리 동아리에서는 이를 기념하여 사진전을 개최합니다. 송국리형 토기, 비파형 동검 등 이 유적에서 출토된 대표적인 유물들을 사진으로 만나보세요!', '선사(청동기)', '생활/사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 2, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 2, '위만이 왕위를 찬탈하였다.', '이사부가 우산국을 복속시켰다.', '온조가 위례성에 도읍을 정하였다.', '관구검이 환도성을 침략하여 함락하였다.', '미천왕이 서안평을 공격하여 영토를 넓혔다.', 1, '(가) 진승과 항우가 군사를 일으켜 천하가 혼란해지자, 연(燕)·제(齊)·조(趙)의 백성이 괴로움을 견디다 못해 점차 준왕에게 망명해왔다. 준왕은 이들을 서쪽 지역에 거주하게 하였다. (나) 좌장군이 패수상군을 격파하고 왕검성에 이르러 그 성의 서북 방면을 포위하였다. 누선장군도 좌장군과 합세하여 성의 남쪽에 주둔하였다. 우거왕이 끝까지 성을 굳게 지키니, 수개월이 지나도 함락시킬 수 없었다.', '선사(고조선)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 3, '(가) 국가의 문화유산으로 옳은 것은?', 2, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 5, '금관 특별전 개최 - 올해 가을 아시아 태평양 경제 협력체(APEC) 정상 회의를 맞이하여 특별한 문화 행사가 경주에서 열린다. 금관총 금관, 황남대총 금관 등 현재까지 발견된 (가) 의 금관 6점이 최초로 한자리에 모이는 ''금관 특별전''은 세계 각국에 우리 문화의 우수성을 알리는 계기가 될 것으로 기대된다.', '고대(신라)', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 4, '(가) 나라에 대한 설명으로 옳은 것은?', 2, '신라 진흥왕에 의해 복속되었다.', '광평성 등의 정치 기구를 마련하였다.', '화백 회의를 통해 국정을 운영하였다.', '대가들이 사자, 조의, 선인을 거느렸다.', '박, 석, 김의 3성이 교대로 왕위를 계승하였다.', 1, '경북 고령군, 다섯 번째 고도(古都)로 지정 - 국가유산청은 (가) 의 중심지였던 경상북도 고령군을 한국의 다섯 번째 고도로 지정하였습니다. 고령에는 궁성지, 지산동 고분군, 방어성인 주산성 등 (가) 의 문화유산들이 보존되어 있어 이와 같이 지정되었습니다.', '고대(가야)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 5, '밑줄 그은 ''그 나라''의 경제 상황으로 가장 적절한 것은?', 2, '수도에 동시전이 설치되었다.', '집집마다 부경이라는 창고가 있었다.', '금속 화폐인 건원중보가 주조되었다.', '솔빈부의 말이 특산품으로 수출되었다.', '곡물을 대여하고 이자를 받은 내용을 좌관대식기에 남겼다.', 2, '그 나라는 관(官)을 세움에 9등이 있다. 첫 번째는 토졸이라 하며, 1품에 비견된다. 옛 이름은 대대로이며, 국정을 모두 맡는다. 3년마다 교대하는데, 직에 걸맞은 자가 있으면 연한에 구애받지 않는다. …… 또 여러 큰 성에는 녹살(욕살)을 두는데, 도독에 비견된다. 여러 성에는 처려근지를 두는데, 자사에 비견된다. 또한 도사라 이르기도 한다. -『한원』-', '고대(고구려)', '정치(제도)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 6, '(가)에 들어갈 내용으로 가장 적절한 것은?', 2, '김흠돌의 난이 진압되었어요.', '만적이 개경에서 봉기를 도모하였어요.', '관료전이 지급되고 녹읍이 폐지되었어요.', '김헌창이 웅천주에서 반란을 일으켰어요.', '이차돈의 순교를 계기로 불교가 공인되었어요.', 4, '혜공왕이 피살되어 무열왕계 직계 자손의 왕위 계승이 끊긴 이후, 진골 귀족들의 왕위 다툼이 치열하게 전개되던 시기에 일어났던 일을 말해 볼까요? / 양길 등 스스로 성주 또는 장군이라 칭하는 호족 세력이 성장하였어요.', '고대(신라)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 7, '다음 자료에 나타난 상황 이후에 있었던 사실로 옳은 것은?', 3, '을지문덕이 살수에서 대승을 거두었다.', '고구려가 신라에 침입한 왜를 물리쳤다.', '김무력이 관산성에서 백제군을 격파하였다.', '연개소문이 정변을 일으켜 권력을 장악하였다.', '백제가 평양성을 공격하여 고구려 왕이 전사하였다.', 4, '당(唐)이 광주사마 장손사를 보내 수(隋) 병사의 해골을 묻은 곳에 와서 제사를 지내고, 당시에 [고구려가] 세운 경관(京觀)을 허물었다. 봄 2월에 왕이 많은 사람을 동원하여 동북의 부여성에서 동남의 바다에 이르기까지 천 리 남짓에 걸쳐 장성을 쌓았다. -『삼국사기』- (경관: 승전을 기념하기 위해 적의 유해를 한곳에 모아 만든 무덤)', '고대(고구려)', '정치/외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 8, '다음 자료에 나타난 국가에 대한 설명으로 옳은 것은?', 2, '골품에 따라 관등 승진을 제한하였다.', '주자감을 설치하여 인재를 양성하였다.', '내신좌평 등 6좌평의 관제를 정비하였다.', '국경 지역인 양계에 병마사를 파견하였다.', '상수리 제도를 통해 지방 세력을 견제하였다.', 2, '○ 조영이 죽으니, 시호를 고왕이라 하였다. 아들 무예가 왕위에 올라 영토를 크게 개척하니, 동북의 모든 오랑캐들이 두려워하여 신하가 되었다. 또 연호를 인안(仁安)으로 고쳤다. ○ 무예가 죽자, 시호를 무왕이라 하였다. 아들 흠무가 왕위에 올라 연호를 대흥(大興)으로 고쳤다. ○ 인수가 왕위에 올라 연호를 건흥(建興)으로 고치니, 그의 4대조 야발은 조영의 아우이다. 인수는 바다 북쪽의 여러 부(部)를 토벌하고 영역을 크게 넓힌 공이 있다.', '고대(발해)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 9, '(가) 지역에 대한 탐구 활동으로 가장 적절한 것은?', 2, '정약전이 자산어보를 저술한 곳을 알아본다.', '비담과 염종이 반란을 일으킨 곳을 찾아본다.', '성왕이 새로운 도읍지로 정한 곳을 검색한다.', '윤충이 의자왕의 명을 받아 함락시킨 곳을 확인한다.', '신립이 배수의 진을 치고 왜군과 맞선 곳을 답사한다.', 3, '유네스코 세계유산 등재 10주년 백제역사유적지구 - 백제역사유적지구는 웅진 천도 이후의 백제 문화를 대표하는 8개 유적으로 구성되어 있습니다. (가)[공주] 공산성·송산리 고분군·관북리 유적 및 부소산성·정림사지·능산리 고분군·나성, 익산 왕궁리 유적·미륵사지', '고대(백제)', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 10, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '신숭겸이 공산 전투에서 전사하였다.', '안승이 보덕국의 왕으로 책봉되었다.', '흑치상지가 임존성에서 군사를 일으켰다.', '최치원이 왕에게 시무 10여 조를 건의하였다.', '왕건이 일리천 전투에서 신검에게 승리하였다.', 1, '(가) 견훤이 신라의 수도로 들어갔다. 포석정에서 연회를 벌이고 있던 신라 왕은 적의 병사들이 이르렀다는 말을 듣고 부인과 함께 달아나 성의 남쪽에 있는 별궁에 숨었다. 견훤은 신라 왕을 찾아내고 핍박하여 자결하게 하였다. (나) 견훤이 고창군을 포위하자 유금필이 왕에게 아뢰기를, "싸워보지도 않고 먼저 패배를 걱정하는 것은 어째서입니까? 신은 군대를 진격해 서둘러 공격하기를 바랍니다."라고 하니 왕이 허락하였다.', '고대~고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 11, '(가) 왕에 대한 설명으로 옳은 것은?', 2, '광덕, 준풍 등의 독자적 연호를 사용하였다.', '신돈을 중심으로 전민변정 사업을 추진하였다.', '청연각과 보문각을 두어 학문 연구를 장려하였다.', '정계와 계백료서를 지어 관리의 규범을 제시하였다.', '최승로의 시무 28조를 받아들여 통치 체제를 정비하였다.', 5, '사료로 만나는 한국사 - 교서를 내려 말하기를, "태학조교 송승연과 나주목(羅州牧)의 경학박사 전보인이 [학생들을] 이끌어 잘 도와서, 학문을 널리 닦으라는 공자의 뜻에 합치된다. 가르침에 게으르지 않아서 내가 학문을 권장하는 뜻에 들어맞으니 마땅히 그들을 발탁하여 특별하고 두터운 총애를 보이도록 하라."라고 하였다. [해설] 위 사료는 (가) 이/가 유학 교육에 공이 있는 태학조교와 나주목의 경학박사를 치하하는 『고려사』의 기록이다. 중앙뿐 아니라 지방의 교육도 장려했던 (가) 은/는 처음으로 12목을 설치하고 지방관에 이어 경학박사와 의학박사를 파견하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 12, '(가)의 침입에 대한 고려의 대응으로 옳은 것은?', 1, '윤관을 보내 동북 9성을 개척하였다.', '상비군으로 구성된 훈련도감을 설치하였다.', '박위로 하여금 쓰시마섬을 정벌하게 하였다.', '서희를 파견하여 소손녕과 외교 담판을 벌였다.', '대장도감을 설치하여 팔만대장경을 간행하였다.', 5, '이곳은 전라남도 진도의 용장성 유적으로, 삼별초가 조성한 궁궐의 터가 남아 있습니다. 고려 정부가 (가) 와/과 강화를 맺자, 이에 반발한 삼별초는 왕족인 승화후 온을 왕으로 삼고 이곳으로 내려와 궁궐과 성을 쌓아 항쟁을 계속하였습니다. 단기간 사용되었음에도 왕궁과 외성이 있고, 여러 개의 성문과 치(雉) 등 다양한 시설이 확인된다고 합니다.', '고려', '정치/외교', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 13, '(가)에 들어갈 내용으로 가장 적절한 것은?', 2, '불씨잡변을 지어 불교를 비판하였습니다.', '만권당에서 원의 학자들과 교유하였습니다.', '지공거 출신으로 9재 학당을 설립하였습니다.', '입학도설을 저술하여 성리학의 기본 원리를 해설하였습니다.', '성균관의 대사성이 되어 정몽주 등을 학관으로 천거하였습니다.', 3, '이 초상화 속 인물은 고려의 학자인 문헌공 최충으로, 해동공자라고 불리기도 하였습니다. 거란의 침입으로 개경이 함락되어 서적들이 소실되자 역사서 편찬을 위한 수찬관에 임명되었습니다. 유학을 보급하고 인재 양성에 힘쓴 그는 (가)', '고려', '인물/문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 14, '다음 상황이 나타난 시기를 연표에서 옳게 고른 것은?', 2, '(가)', '(나)', '(다)', '(라)', '(마)', 3, '서경 반란군이 검교첨사 최경을 개경으로 보내 표문을 올려 이르기를, "폐하께서 음양의 지극한 말을 믿으시고 도참의 비설을 고찰하시어 대화궁을 창건하시니 천제(天帝)의 도읍을 본떠 만드신 것입니다. …… 인심은 두려운 것이며 군중의 분노는 막기 어려우니 만약 폐하께서 수레를 타고 임하신다면 병란은 그칠 것입니다."라고 하였다. 표문이 도착하니 모두 말하기를, "신하가 감히 군주를 부르다니 그 사자(使者)를 베는 것이 옳습니다."라고 하였다. [연표] 918 고려 건국 - (가) - 1009 강조의 정변 - (나) - 1126 이자겸의 난 - (다) - 1170 무신 정변 - (라) - 1356 쌍성총관부 탈환 - (마) - 1392 고려 멸망', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 15, '교사의 질문에 대한 학생의 답변으로 가장 적절한 것은?', 2, '김사미가 운문을 거점으로 봉기하였어요.', '강감찬이 흥화진 전투에서 승리하였어요.', '후주 출신 쌍기가 과거제 도입을 건의하였어요.', '최충헌이 교정도감을 두어 국정을 총괄하였어요.', '이성계가 위화도에서 회군하여 정권을 장악하였어요.', 5, '자료는 ''이생규장전''의 일부입니다. 이 작품은 홍건적의 침입으로 왕이 피란하고 백성이 고통을 겪는 등 전란의 참혹했던 상황을 역사적 배경으로 하고 있습니다. 이 상황 이후에 전개된 역사적 사실에 대해 말해 볼까요? [문학으로 만나는 한국사] 신축년에 홍건적이 개경을 점거하자 임금은 복주(福州)로 피란하였다. 적들은 집을 불태워 없애버렸으며, 사람을 죽이고 가축을 잡아먹었다. 부부와 친척끼리도 서로 보호하지 못했고 동서로 달아나 숨어서 제각기 살길을 찾았다. 이생은 가족들을 데리고 외진 산골로 숨었는데, 한 도적이 칼을 빼어들고 뒤를 쫓아왔다. 이생은 달아나 목숨을 건졌지만, 그의 아내 최랑은 도적에게 사로잡혔다.', '고려', '사회/전쟁', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 16, '다음 상황이 나타난 국가의 경제 모습으로 옳은 것은?', 2, '청해진을 설치하여 해상 무역을 전개하였다.', '재정 문제를 해결하기 위한 당백전이 발행되었다.', '계해약조가 체결되어 세견선의 입항이 허가되었다.', '육의전을 제외한 시전 상인의 금난전권이 폐지되었다.', '예성강 하구의 벽란도가 국제 무역항으로 번성하였다.', 5, '○ 동소(銅所)·철소(鐵所)·자기소(瓷器所)·지소(紙所)·묵소(墨所) 등 여러 소에서 별공으로 바치는 물건들을 너무 과중하게 징수하여 장인들이 고통스러워 도망하고 있다. ○ 왕이 명령하기를, "이제 처음으로 화폐를 주조하는 법을 제정하였으니, 주조한 돈 1만 5천 관(貫)을 여러 관리와 군인들에게 나누어 주어 이를 통용의 시초로 삼고 전문(錢文)은 해동통보라 하여라."라고 하였다.', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 17, '(가)에 들어갈 내용으로 가장 적절한 것은?', 1, '의약학의 발전과 향약집성방의 편찬', '100리 척의 사용과 동국지도의 제작', '기하학적 원리와 경주 석굴암의 조성', '금속활자 기술과 직지심체요절의 간행', '농업 기술의 발달과 임원경제지의 저술', 4, '2025년 한국사 교양 강좌 - 고려의 과학 기술 - 우리 학회에서는 고려의 과학 기술에 대해 알아보는 교양 강좌를 마련하였습니다. [강의 주제] 제1강 수시력의 도입과 최성지의 활동 / 제2강 (가) / 제3강 화통도감의 설치와 화약 무기의 개발 / 제4강 고려 청자의 발달과 상감 기법의 활용', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 18, '(가) 국가의 문화유산으로 옳은 것은?', 2, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 3, '메타버스 전시관 - 은진 미륵이라고도 불리는 거대한 이 불상은 (가) 시대 초기에 만들어진 것으로, 논산 관촉사에 가면 볼 수 있어. 역사적, 예술적 가치가 재평가되어 보물에서 국보로 변경되었다고 해. 이번에는 탑을 만나러 가볼까?', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 19, '다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?', 2, '제1차 왕자의 난이 일어난 이유를 찾아본다.', '수양대군이 정권을 장악하는 과정을 조사한다.', '사림이 동인과 서인으로 나뉘게 된 계기를 파악한다.', '폐모살제 등을 구실로 반정을 일으킨 세력을 검색한다.', '허적과 윤휴 등 남인이 대거 축출되는 사건을 알아본다.', 1, '처음에 공신 배극렴·조준·정도전이 세자를 세울 것을 청하면서, 나이와 공로를 고려하여 정하기를 청하였다. 임금이 강씨를 중히 여겨 이방번에게 뜻이 있었으나, 공신들은 방번이 적합하지 않다고 생각하여 사적으로 서로 이야기하기를, "만일 강씨 소생이어야 한다면 막내가 조금 낫겠다."라고 하였다. 이후 임금이 "누가 세자가 될 만한가?"라고 물으니, 맏아들 혹은 공로가 있는 사람을 세워야만 된다고 간절히 말하는 사람이 없었다. 이에 극렴이 말하기를, "막내아들이 좋습니다."라고 하니, 임금이 마침내 뜻을 결정하여 어린 이방석을 왕세자로 삼았다.', '조선전기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 20, '(가) 기구에 대한 설명으로 옳은 것은?', 2, '수도의 행정과 치안을 담당하였다.', '을묘왜변을 계기로 상설 기구화되었다.', '서얼 출신 학자들이 검서관에 등용되었다.', '역사서를 편찬하고 사고에 보관하는 일을 맡았다.', '대사헌을 수장으로 집의, 장령 등의 관직을 두었다.', 5, '이 그림은 (가) 의 감찰인 김종한 등 23인의 계회를 기념하여 그린 이십삼상대회도입니다. ''상대''는 백관에 대한 규찰과 탄핵 등을 관장하던 (가) 의 별칭입니다. 이 계회도의 하단에는 감찰 23인의 품계와 성명, 그리고 그 부친의 관직과 성명 등이 기재되어 있어 조선 초기 계회도를 이해하는 데 큰 도움이 됩니다.', '조선전기', '정치(제도)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 21, '(가)에 대한 조선의 대응으로 옳은 것은?', 2, '사신 접대를 위해 한성에 동평관을 두었다.', '두만강 일대를 개척하여 6진을 설치하였다.', '강화도로 도읍을 옮겨 장기 항전을 준비하였다.', '철령위 설치에 반발하여 요동 정벌을 추진하였다.', '신기군, 신보군, 항마군 등으로 구성된 별무반을 조직하였다.', 2, '이 그림에는 1588년 북병사 장양공 이일이 변경을 침범하던 (가) 을/를 정벌하는 장면이 그려져 있습니다. 조선 초에는 (가) 을/를 회유하기 위해 경성과 경원에 무역소를 설치하기도 하였으나, 이들은 수시로 변경을 침범하였고 조선 정부의 토벌도 이어졌습니다.', '조선전기', '외교/전쟁', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 22, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '자의 대비의 복상 문제로 예송이 일어났다.', '외척 간의 권력 다툼으로 윤임이 제거되었다.', '세자 책봉 문제를 계기로 정철이 유배되었다.', '희빈 장씨 소생의 원자 책봉 문제로 환국이 발생하였다.', '폐비 윤씨 사사 사건의 전말이 알려져 김굉필 등이 처형되었다.', 2, '(가) 대신 등에게 전교하기를, "조광조 등의 일은 내가 늘 마음속에서 잊지 않았으나 선왕(先王)께서 전에 허락하지 않으셨으므로 감히 가벼이 고치지 못하였다. 이제는 내 병이 위독하여 비로소 유언하니 조광조 등의 벼슬을 모두 회복할 수 있으면 다행이겠다. 현량과도 회복하여 거두어 등용하도록 하라."라고 하였다. (나) 부제학 정언각이 아뢰기를, "소신이 양재역에 이르러서 벽에 써 붙인 주서(朱書)를 보았는데 국가에 관계된 내용이었으므로 지극히 놀랐습니다. …… 또 반역의 잔당들은 이미 죄를 물었습니다만, 심영은 대왕대비를 가리켜 신하로서 할 수 없는 말을 하였습니다. 신하가 그와 같은 말을 하고서 어떻게 천지 사이에 용납될 수 있겠습니까."라고 하였다.', '조선전기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 23, '(가) 전쟁 중에 있었던 사실로 옳은 것은?', 2, '송상현이 동래성에서 항전하였다.', '김준룡이 광교산 전투에서 승리하였다.', '이괄의 반란 세력이 도성을 장악하였다.', '강홍립 부대가 사르후 전투에 참전하였다.', '신류가 조총 부대를 이끌고 흑룡강에서 전투를 벌였다.', 2, '상세 정보 - 남한산성 무너진 날 죽었어야 할 몸인데 초수(楚囚)되어 아직도 못 돌아간 신하라네 / 서쪽으로 오며 형 생각에 몇 번이나 눈물 뿌렸던고 / 동녘을 바라보니 아우 그린 형이 가련하네 …… 부부 은정(恩情) 중하기도 한데 만난지 두 돌도 못 되었네그려 / 이제는 만 리 밖에 이별하여 백년 가약이 헛되구나 / 길이 멀어 편지도 못 부치고 산이 높아 꿈조차 더디 넘네 / 나의 살 길 기약할 수 없으니 뱃속의 아이나 잘 보살펴주오 (초수: 포로를 뜻함) [해설] 이 작품은 송시열이 펴낸 『삼학사전』에 수록된 시로, 오달제가 형과 아내에게 보낸 것입니다. 삼학사는 (가) 때 척화론을 주장하다가 이듬해 심양으로 잡혀가 순절한 홍익한, 윤집, 오달제를 말합니다. 『삼학사전』에는 삼학사의 절개와 비극적 최후가 묘사되어 있습니다. 인조의 뒤를 이어 즉위한 효종은 (가) 의 치욕을 씻기 위해 북벌을 추진하는 한편 순절한 인물을 기리고 그 후손을 등용하는 정책을 펼쳤습니다.', '조선전기', '전쟁', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 24, '(가) 왕에 대한 설명으로 옳은 것은?', 2, '경기도에 한하여 대동법을 시행하였다.', '수도 방어를 위하여 금위영을 창설하였다.', '탕평 교서를 반포하고 탕평비를 건립하였다.', '문신을 재교육하기 위한 초계문신제를 실시하였다.', '통치 체제를 정비하기 위해 대전회통을 편찬하였다.', 3, '이 책은 이인좌의 난을 평정한 직후 (가) 의 명으로 송인명 등이 난의 진행 과정과 원인에 대해 여러 자료를 참고해서 편찬한 것입니다. 어제(御製) 서문에는 이인좌의 난이 일어난 원인을 붕당에서 찾고 있으며, 이와 같은 변란의 재발을 막기 위하여 이 책을 편찬한다고 명시되어 있습니다.', '조선후기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 25, '밑줄 그은 ''시기''에 볼 수 있는 모습으로 가장 적절한 것은?', 1, '세책가에서 춘향전을 빌리는 부녀자', '동국정운을 편찬하는 집현전의 학자', '주자소에서 계미자를 제작하는 장인', '형평사 창립 대회 개최를 취재하는 기자', '시전의 상행위를 감독하는 경시서의 관리', 1, '이것은 장용영이 존재하던 시기 한양 도성 일대를 그린 도성도입니다. 종묘 부근에 장용영의 위치가 표시되어 있습니다. 이 지도에는 또 어떤 특징이 있을까요? / 두드러진 특징은 남쪽을 바라보며 정사를 보는 왕의 시각에 맞춰 그려, 지도의 상단이 남쪽으로 되어있다는 점입니다. 또한 산수화풍의 산세 표현은 겸재 정선의 화풍을 따른 것으로 보입니다.', '조선후기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 26, '다음 상황이 나타난 시기의 경제 모습으로 옳지 않은 것은?', 2, '염포의 왜관을 통해 일본과 교역하였다.', '상평통보를 발행하여 화폐로 사용하였다.', '관청에 물품을 조달하는 공인이 활동하였다.', '송상, 만상이 대청 무역으로 부를 축적하였다.', '덕대가 물주에게 자금을 받아 광산을 경영하였다.', 1, '비가 내리자 왕이 특별히 화성부에 이르기를, "흉년이 들었을 때 기근을 구제하는 데 서쪽 지방의 토란이나 남쪽 지방의 고구마보다 월등히 나은 것은 메밀이다. 내가 이 때문에 모내기의 시기를 놓치게 되면 반드시 메밀을 대신 파종하도록 권장하는 것이다."라고 하였다.', '조선후기', '경제/사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 27, '(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?', 2, '오페르트가 남연군 묘 도굴을 시도하였다.', '이만손이 주도하여 영남 만인소를 올렸다.', '이시애가 길주를 근거지로 난을 일으켰다.', '홍경래 등이 봉기하여 정주성을 점령하였다.', '곽재우, 고경명 등이 의병장으로 활약하였다.', 4, '이 그림은 세도 정치의 주요 인물이자 (가) 의 장인인 김조순의 별저 옥호정과 그 일대를 그린 옥호정도입니다. 삼청동 북악산 백련봉 일대에 위치한 별저의 모습을 통해 당시 세도가였던 안동 김씨의 위세를 짐작할 수 있습니다.', '조선후기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 28, '(가) 사건에 대한 설명으로 옳은 것은?', 2, '개혁 추진 기구로 교정청이 설치되었다.', '전개 과정에서 홍범 14조가 반포되었다.', '통리기무아문이 신설되는 배경이 되었다.', '김기수가 수신사로 파견되는 결과를 가져왔다.', '청일 간에 톈진 조약이 체결되는 계기가 되었다.', 5, '김옥균 등은 청이 우리 자주권을 침해하는 데 분노하여 일본 공사와 (가) 을/를 일으켜 ''일본당''으로 지목되었다. (가) 이/가 실패하자 온 나라가 그를 역적이라 하였다. 나는 조정에 몸을 담고 있어 그를 토벌하여 죽여야 한다는 것 외에 다른 목소리를 낼 수 없었다. 그러나 김옥균과 나의 마음은 그 뜻이 다른 데 있는 것이 아니라 나라를 사랑하는 데서 나온 것이었다. -『속음청사』-', '근대(개항기)', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 29, '(가) 종교에 대한 설명으로 옳은 것은?', 1, '포접제를 활용하여 교세를 확장하였다.', '배재 학당을 세워 신학문 보급에 앞장섰다.', '박중빈을 중심으로 새생활 운동을 추진하였다.', '일제의 통제에 맞서 사찰령 폐지 운동을 벌였다.', '의민단을 조직하여 항일 무장 투쟁을 전개하였다.', 1, '재판 기록으로 보는 한국사 - 판결선고서 강원도 원주군 평민 피고 최시형 [해설] 자료는 (가) 의 제2대 교주 최시형에 대한 판결 선고서이다. 교조 신원 운동을 주도했던 그는 1894년 전봉준, 김개남 등이 이끈 농민군과 합세한 일로 도망자 신세가 되었고, 결국 1898년 원주에서 체포되어 고등재판소에서 재판을 받았다. 당시 재판에는 농민 수탈로 고부 봉기를 촉발시켰던 조병갑이 판사로 참여하였고, 법부 대신 조병직이 재판장으로서 최시형에게 사형을 선고하였다.', '근대', '종교/사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 30, '밑줄 그은 ''전쟁'' 기간에 있었던 사실로 옳은 것은?', 3, '고종이 아관 파천을 단행하였다.', '일본이 독도를 불법 편입하였다.', '러시아가 절영도 조차를 요구하였다.', '조청 상민 수륙 무역 장정을 체결하였다.', '평양 관민이 대동강에 침입한 제너럴 셔먼호를 불태웠다.', 2, '미국 잡지 ''포퓰러 매거진''의 1912년 마지막 호에는 한반도를 둘러싼 대한 제국과 일본, 러시아 간의 암투를 다룬 첩보 소설(The cat and the king)이 실렸습니다. 베델, 민영환 등 당대 인물들이 등장하는 이 소설은 일제가 포츠머스 조약을 체결하여 전쟁을 끝내고 대한 제국의 외교권을 박탈하려 하는 등 긴박하게 전개되었던 당시 상황을 배경으로 하고 있습니다.', '근대', '외교/전쟁', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 31, '(가) 인물에 대한 설명으로 옳은 것은?', 3, '고종의 밀지를 받아 독립 의군부를 조직하였다.', '도쿄에서 일왕이 탄 마차를 향해 폭탄을 던졌다.', '을사늑약이 체결되자 태인에서 의병을 일으켰다.', '명동 성당 앞에서 이완용을 습격하여 중상을 입혔다.', '13도 창의군을 지휘하여 서울 진공 작전을 전개하였다.', 3, '상소문으로 보는 역사 이야기 - 「지부복궐척화의소」 - 자료는 위정척사 운동의 대표적 인물인 (가) 이/가 강화도 조약 체결에 반대하며 올린 「지부복궐척화의소」의 일부로, 『면암집』에 실려있습니다. 표시된 부분은 ''기자(箕子)의 옛 땅이며 대명(大明)의 동쪽 울타리''인 조선이 조약을 체결하게 되면 ''하루아침에 서양 오랑캐로 전락''할 수 있다는 내용으로, 화이론적 세계관에 바탕을 둔 그의 왜양일체론이 잘 드러나 있습니다.', '근대(개항기)', '인물/사상', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 32, '㉠~㉤에 대한 설명으로 옳은 것은?', 2, '㉠ - 고종 강제 퇴위 반대 운동을 전개하였다.', '㉡ - 일제의 황무지 개간권 요구를 저지시켰다.', '㉢ - 일제가 조작한 105인 사건으로 와해되었다.', '㉣ - 대성 학교를 설립하여 민족 교육을 실시하였다.', '㉤ - 조소앙의 삼균주의를 기초로 건국 강령을 발표하였다.', 2, '이준 연보 - 1859년 함경도 북청에서 출생, 1895년 법관 양성소 졸업, 1898년 ㉠독립 협회 가입, 1904년 ㉡보안회 조직(일제의 압력으로 황해도 철도(鐵島)로 유배), 1905년 ㉢헌정 연구회 조직, 1906년 ㉣대한 자강회 조직, 1907년 ㉤신민회 가입(네덜란드 헤이그 만국 평화 회의에 특사로 파견, 사망), 1962년 건국훈장 대한민국장 추서', '근대', '인물/독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 33, '다음 자료를 작성한 인물에 대한 설명으로 옳은 것은?', 1, '샌프란시스코에서 흥사단을 창립하였다.', '황준헌이 쓴 조선책략을 국내에 들여왔다.', '초대 통감이었던 이토 히로부미를 사살하였다.', '유만수 등과 함께 부민관 폭파 의거를 일으켰다.', '국권 피탈 과정을 정리한 한국통사를 저술하였다.', 3, '''동양 평화''와 ''한국 독립''에 대한 문제는 이미 세계 모든 나라 사람들이 다 아는 사실이며 당연한 일로 굳게 믿었고, 한국과 청국 사람들의 마음에 깊게 새겨졌다. …… 만일 일본이 지금의 정책을 바꾸지 않고 이웃 나라들을 나날이 억누른다면, 차라리 다른 인종에게 망할지언정 같은 인종에게 욕을 당하지는 않겠다는 생각이 한국과 청국 사람들의 마음에서 용솟음칠 것이다. …… 동양 평화를 위한 의로운 싸움을 하얼빈에서 시작하고, 옳고 그름을 가리는 자리는 뤼순으로 정하였다.', '근대', '인물/독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 34, '밑줄 그은 ''시기''에 있었던 사실로 옳은 것은?', 2, '미쓰야 협정이 체결되었다.', '조선 사상범 예방 구금령이 제정되었다.', '박문국이 설치되어 한성순보를 발행하였다.', '황국 중앙 총상회가 상권 수호 운동을 주도하였다.', '회사 설립 시 총독의 허가를 받도록 하는 회사령이 시행되었다.', 5, '법령으로 만나는 일제 강점기 - 제1조 경찰서장 또는 그 직무를 취급하는 자는 그 관할 구역 안의 다음 각호의 범죄를 즉결할 수 있다. 1. 구류·태형 또는 과료형에 해당하는 죄 3. 3월 이하의 징역·금고·금옥이나 구류·태형 또는 100원 이하의 벌금이나 과료형에 처하여야 하는 행정 법규 위반의 죄 -범죄 즉결례- / 제1조 3개월 이하의 징역 또는 구류에 처해야 하는 자는 그 상황에 따라 태형에 처할 수 있다. 제13조 본령은 조선인에 한해 적용한다. -조선 태형령- [해설] 헌병이 일반 경찰 업무를 담당하던 시기에 일제는 범죄 즉결례를 제정하여 재판 없이 체포 또는 구금하고 벌금을 물리거나 태형에 처할 수 있게 하였습니다. 시행 이듬해 일제는 범죄 즉결례에 있는 태형 규정을 삭제하고, 조선 태형령을 제정하여 태형은 오직 조선인에게만 적용하였습니다.', '일제강점기', '정치(통치정책)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 35, '다음 기사가 보도된 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 2, '영선사 일행으로 청에 가는 생도', '경성 제국 대학에서 공부하는 학생', '국채 보상 운동의 모금에 참여하는 상인', '육영 공원에서 영어를 가르치는 미국인 교사', '전차 개통식에 참여하는 한성 전기 회사 직원', 2, '[사설] 대홍수의 재난에서 조선의 형제들을 구하라 - 대홍수로 중부 지방에 엄청난 피해가 발생하였다. 7월 18일에는 용산과 뚝섬 일대가 완전 침수되었고 이튿날은 광주군 선리 주민 292명이 물에 빠져 죽었다. 경부선은 10일간 불통이었다. 그럼에도 총독부는 이와 같은 홍수 피해에 무성의하게 대처하고 있다. 재작년 일본에서 관동 대지진이 일어났을 때 조선인들이 박해를 받았음에도 불구하고 우리 조선의 형제들은 능력껏 구제의 손길을 뻗쳤었다. 그러나 지금 조선에서 홍수 피해로 각지에서 재난이 일어나고 있는데도 총독부와 일본인 거류민들은 모른 척하고 있다. 조선인이여! 조선인을 구하라. 재난을 당한 형제와 같이 울며 아프며 살 길을 구하라.', '일제강점기', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 36, '(가) 운동의 배경으로 가장 적절한 것은?', 1, '간도 참변으로 민간인이 학살되었다.', '민영익을 대표로 한 보빙사가 파견되었다.', '대한 제국의 마지막 황제 순종이 서거하였다.', '언론사의 주도로 브나로드 운동이 전개되었다.', '미국 대통령 윌슨이 민족 자결주의를 제창하였다.', 5, '파리 강화 회의가 진행되던 프랑스에서는 일제 강점기 최대 규모의 독립운동이었던 (가) 와/과 관련된 내용이 보도된 바 있습니다. 이와 관련하여 "일본 당국이 가혹한 탄압을 하고 있으며 혁명의 희생자 수가 이미 상당하다."라고 보도하며, (가) 에 대해 ''혁명''이라는 표현을 사용한 기사가 주목됩니다.', '일제강점기', '독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 37, '(가) 단체에 대한 설명으로 옳은 것은?', 2, '군대식 조직을 갖춘 비밀 결사였다.', '정우회 선언의 영향으로 결성되었다.', '조선 혁명 선언을 활동 지침으로 삼았다.', '중국군과 함께 영릉가 전투에서 큰 전과를 올렸다.', '만민 공동회를 열어 열강의 이권 침탈을 비판하였다.', 1, '【우리 고장의 독립운동가】 일우(一宇) 김한종 (1883~1921) - 충청남도 예산군 광시면 출생이다. 1915년 대구에서 박상진 등이 국권 회복을 위해 조직한 (가) 의 충청도 지부장으로, 군자금 모금과 친일 관리 처단을 주도하였다. 이후 일제에 체포되어 총사령 박상진과 함께 사형을 선고받고 대구 형무소에서 생을 마감하였다. 1963년에 건국훈장 독립장이 추서되었다.', '일제강점기', '독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 38, '(가)~(라)를 발표된 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다) - (라)', '(가) - (나) - (라) - (다)', '(나) - (가) - (라) - (다)', '(나) - (다) - (가) - (라)', '(다) - (라) - (나) - (가)', 3, '(가) 제1조 대한국은 세계 만국에 공인된 자주독립 제국이다. 제2조 대한 제국의 정치는 만세에 걸쳐 불변할 전제 정치이다. 제3조 대한국 대황제는 무한한 군권(君權)을 누린다. (나) 중추원은 아래에 열거한 사항을 심사하고 회의하여 결정하는 곳으로 할 것이다. 1. 법률, 칙령의 제정, 폐지, 개정에 관한 사항 6. …… 중추원 의관의 절반은 정부에서 나라에 공로가 있는 사람을 추천하고, 그 절반은 인민 협회 중에서 27세 이상으로 정치·법률·학식에 통달한 자를 투표해서 선거할 것이다. (다) 제1조 대한민국은 민주 공화국이다. 제2조 대한민국의 주권은 국민에게 있고 모든 권력은 국민으로부터 나온다. 제102조 이 헌법을 제정한 국회는 이 헌법에 의한 국회로서의 권한을 행하며 그 의원의 임기는 국회 개회일로부터 2년으로 한다. (라) 융희 황제가 삼보(三寶)를 포기한 8월 29일은 즉 우리 동지가 삼보를 계승한 8월 29일이니 그 사이 순간도 멈춘 적이 없다. 우리 동지는 완전한 상속자이니 저 황제권이 소멸한 시점은 즉 민권이 발생한 시점이오, 옛 한국의 마지막 1일은 즉 신한국 최초의 1일이다.', '근대~현대', '정치(제도)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 39, '(가) 지역에서 있었던 민족 운동으로 옳은 것은?', 2, '한인 자치 기구인 경학사를 조직하였다.', '권업회를 조직하고 권업신문을 발간하였다.', '중광단을 결성하여 항일 투쟁을 전개하였다.', '숭무 학교를 설립하여 독립군을 양성하였다.', '유학생들이 중심이 되어 2·8 독립 선언서를 발표하였다.', 4, '재외 동포 이민사 생방송 중 - 사진은 (가) (으)로 이주한 한인 노동자들의 모습입니다. 이민자들은 1905년 (가) 의 유카탄 반도에 도착한 뒤 에네켄 농장 20여 곳에 분산 배치되어 고된 노동에 시달렸습니다. 이들은 어려운 환경 속에서도 독립운동 자금을 모금하는 등 국권 회복을 위한 노력에 동참하였습니다.', '일제강점기', '사회/독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 40, '교사의 질문에 대한 학생의 답변으로 가장 적절한 것은?', 3, '양전 사업이 실시되어 지계가 발급되었어요.', '함경도와 황해도에서 방곡령이 선포되었어요.', '전국 단위 조직인 조선 농민 총동맹이 결성되었어요.', '일본의 토지 침탈에 맞서 농광 회사가 설립되었어요.', '기한 내에 소유지를 신고하게 하는 토지 조사령을 제정하였어요.', 3, '이 자료는 전라남도 신안군(당시 무안군)의 한 섬에서 발생한 사건의 결과로, 소작인회 대표와 지주 문재철 사이에 맺어진 화해 조건입니다. 소작인들은 고율의 소작료를 징수하는 지주에게 1년여에 걸쳐 저항하여 소작료를 낮추는 성과를 거두었습니다. 이 사건 이후의 사실에 대해 말해 볼까요? [1. 소작료를 4할로 하고, 1할은 농업 장려금으로 할 것 2. 농업 장려금은 소작인회에서 관리할 것 3. 소작인회에 지주도 참여할 것 4. 미납한 소작료는 3개년을 기한으로 분납할 것 5. 파괴하여 철거한 문태현의 비석을 복구할 것 6. 현재 조사 중인 형사 피고 사건은 양방에서 취하할 것 7. 지주가 소작인회에 기본금 2천 원을 기증할 것]', '일제강점기', '사회(농민운동)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 41, '(가) 단체에 대한 설명으로 옳은 것은?', 3, '최초로 한글에 띄어쓰기를 도입하였다.', '국어 문법서인 대한문전을 편찬하였다.', '태극 서관을 설립하여 서적을 보급하였다.', '조선말(우리말) 큰 사전 편찬을 추진하였다.', '국문 연구소를 두어 한글을 체계적으로 연구하였다.', 4, '자네 (가) 에서 발행한 잡지 ''한글'' 이번 호 보았는가? ''한글 맞춤법 통일안'' 개정 신판이 발매되었다는 소식이 실렸더군. / 읽었네. 최근 훈민정음 해례본의 발견으로 한글 창제일이 명확해졌다는군. 이제 (가) 에서는 한글날을 창제일에 맞춰 10월 9일로 시정한다고 하네.', '일제강점기', '문화/독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 42, '(가)에 들어갈 내용으로 가장 적절한 것은?', 1, '나운규의 영화 아리랑이 상영되었습니다.', '한글 신문인 제국신문이 간행되었습니다.', '정비석의 소설 자유부인이 출판되었습니다.', '잡지 사상계가 높은 판매 부수를 기록하였습니다.', '아침 이슬 등의 곡이 금지곡으로 지정되었습니다.', 1, '이것은 잡지 ''별건곤''에 실린 삽화로, 서양식 복장을 한 ''모던 걸'', ''모던 보이''를 풍자한 것입니다. 일제 강점기에는 잡지, 라디오 등의 매체를 통해 새로운 근대 문화가 소개되었습니다. 당시 나타난 문화적 현상에 대해 검색한 것을 말해 볼까요? / 자본주의적 소비 문화의 상징인 백화점이 도심에 들어섰습니다.', '일제강점기', '사회/문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 43, '(가) 부대에 대한 설명으로 옳은 것은?', 2, '청산리에서 일본군에 맞서 승리를 거두었다.', '미국과 연계하여 국내 진공 작전을 준비하였다.', '동북 항일 연군으로 개편되어 유격전을 전개하였다.', '쌍성보, 대전자령 전투 등에서 일본군에 승리하였다.', '중국 관내(關內)에서 결성된 최초의 한인 무장 부대였다.', 2, '사료로 만나는 여성 독립운동사 - 이중 삼중의 억압에 눌려 신음하던 자매들이여! 어서 빨리 일어나 이 민족 해방 운동의 뜨거운 용광로로 뛰어오라. …… 어둠 속에서 비추는 새벽빛 같은 (가) 의 자유를 쟁취하려는 봉화는 붉고 맑게 빛난다. 이미 모인 혁명 동지들은 뜨거운 손길을 내밀고 열정에 넘쳐 속히 달려옴을 기다리고 있다. 오라! [해설] 이 사료는 『광복』에 실린 지복영의 글 중 일부이다. 그녀는 1940년 9월, 충칭에서 자신의 아버지 지청천을 총사령으로 하는 (가) 이/가 창설될 때 오광심, 김정숙, 조순옥 등과 함께 참여하였다. 그녀는 대원 모집, 선전 활동 등을 이어오다 광복을 맞이하였다.', '일제강점기', '독립운동', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 44, '밑줄 그은 ''이 시기''에 시행된 일제의 정책으로 옳은 것은?', 1, '언론을 통제하기 위하여 신문지법을 제정하였다.', '애국반을 조직하여 한국인의 생활을 통제하였다.', '경복궁에서 최초로 조선 물산 공진회를 개최하였다.', '재정 고문 메가타의 주도 아래 화폐 정리 사업을 실시하였다.', '보통학교의 수업 연한을 4년으로 규정한 제1차 조선 교육령을 시행하였다.', 2, '이것은 일제가 각종 놋그릇과 생활용품들을 공출한 후 찍은 사진이야. 당시 금속류 회수령이 실시되었지. / 맞아. 중일 전쟁을 일으키고 침략 전쟁을 확대했던 이 시기 일제는 군수 물자 생산을 위해 사찰의 종까지 걷어가기도 했어.', '일제강점기', '경제(수탈정책)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 45, '다음 성명이 발표된 이후의 사실로 옳은 것은?', 3, '모스크바 3국 외상 회의가 개최되었다.', '송진우, 김성수 등이 한국 민주당을 창당하였다.', '좌우 합작 위원회에서 좌우 합작 7원칙을 발표하였다.', '우리나라 최초의 보통 선거인 5·10 총선거가 실시되었다.', '여운형이 중심이 되어 조선 건국 준비 위원회를 조직하였다.', 4, '지금 이때 나의 단일한 염원은 3천만 동포와 손을 잡고 통일된 조국, 독립된 조국의 달성을 위하여 공동 분투하는 것뿐이다. 이 육신을 조국이 요구한다면 당장에라도 제단에 바치겠다. 나는 통일된 조국을 건설하려다가 38선을 베고 쓰러질지언정 일신에 구차한 안일을 취하여 단독 정부를 세우는 데는 협력하지 아니하겠다. 나는 내 생전에 38선 이북에 가고 싶다. 그쪽 동포들도 제 집을 찾아가는 것을 보고서 죽고 싶다. 궂은 날을 당할 때마다 38선을 싸고 도는 원귀의 곡성이 내 귀에 들리는 것도 같았다. 고요한 밤에 홀로 앉으면 남북에서 헐벗고 굶주리는 동포들의 원망스런 용모가 내 앞에 나타나는 것도 같았다.', '현대', '정치(통일운동)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 46, '밑줄 그은 ''정부'' 시기에 있었던 사실로 옳은 것은?', 2, '경부 고속 도로가 개통되었다.', '한미 상호 방위 조약이 체결되었다.', '함평 고구마 피해 보상 운동이 전개되었다.', '대통령 긴급 명령으로 금융 실명제가 실시되었다.', '사회 정화를 명분으로 삼청 교육대가 설치되었다.', 2, '이 사진은 6·25 전쟁 중 부산 임시 국회에서 개헌안을 표결하는 장면입니다. 정부는 부산 일대에 계엄을 선포하고 야당 의원들이 탄 통근 버스를 강제로 연행하는 등 공포 분위기를 조성하였습니다. 개헌안은 군인과 경찰이 국회 의사당을 완전히 포위한 상태에서 토론 없이 기립 표결로 통과되었습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 47, '(가) 정부 시기에 있었던 사실로 옳은 것은?', 2, '부천 경찰서 성 고문 사건이 발생하였다.', '정부에 비판적인 경향신문이 폐간되었다.', '최저 임금 결정을 위한 최저 임금 위원회가 설치되었다.', '자치 단체장까지 선출하는 지방 자치제가 전면 시행되었다.', '긴급 조치 철폐 등을 요구하는 3·1 민주 구국 선언이 발표되었다.', 5, '(가) 정부 시기의 여성 노동 운동 - 노동조합 대의원 선거를 방해하는 어용 조합원들에 의해 인분을 뒤집어 쓴 동일방직의 여성 노동자들 / 임금 체불과 직장 폐쇄에 항의하여 신민당사에서 농성하다 끌려 나가는 YH 무역의 여성 노동자들', '현대', '사회(노동운동)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 48, '밑줄 그은 ''민주화 운동''에 대한 설명으로 옳은 것은?', 1, '유신 체제 붕괴의 배경이 되었다.', '당시 대통령이 하야하는 결과를 가져왔다.', '5년 단임의 대통령 직선제 개헌을 이끌어냈다.', '시위 과정에서 시민군이 자발적으로 조직되었다.', '굴욕적인 한일 국교 정상화에 반대하여 일어났다.', 3, '사진 속 쓰러진 인물이 대학교 정문에서 시위 도중 경찰이 쏜 최루탄에 피격된 이한열이지? / 맞아. 이 사건은 호헌 철폐와 독재 타도를 외친 민주화 운동이 확산하는 데 영향을 주었어.', '현대', '정치(민주화운동)', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 49, '다음 기사 내용이 보도된 정부 시기에 있었던 사실로 옳은 것은?', 3, '칠레와의 자유 무역 협정(FTA)이 체결되었다.', '처음으로 연간 수출액 100억 달러가 달성되었다.', '서울과 평양에서 7·4 남북 공동 성명이 발표되었다.', '북방 외교를 추진하여 사회주의 국가인 소련과 수교하였다.', '거창 사건 등 관련자의 명예 회복에 관한 특별 조치법이 제정되었다.', 5, '군대 내 사조직 ''하나회'' 청산 매듭 - 어제 단행된 군 장성 정기 인사를 통해 하나회 회원으로 알려진 중장급 이상 장성 전원이 보직 해임되었다. 이번 인사는 문민정부 출범 직후인 지난해 3월 8일 육군 참모총장과 기무사령관을 전격적으로 예편 조치함으로써 시작된 군대 내 사조직 청산 작업을 마무리한 것이다. 군 내부에서도 이번 하나회 완전 제거가 군이 정치적 중립을 확보하고 안정과 결속을 다지는 계기가 될 것으로 기대하고 있다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (75, 50, '(가) 지역에 대한 탐구 활동으로 가장 적절한 것은?', 2, '원종과 애노가 봉기한 곳을 검색한다.', '외규장각 도서의 약탈 과정을 조사한다.', '강주룡이 고공 시위를 전개한 장소를 알아본다.', '김만덕이 흉년에 굶주린 백성을 구제한 기록을 살펴본다.', '러시아의 남하를 견제한다는 구실로 영국군이 점령한 지역을 찾아본다.', 4, '(가) 여행 정보 안내 - 맞춤 여행 추천: 다양한 성향을 기반으로 개인별 최적의 여행지를 추천해 드립니다. [테마] 휴식/힐링, 역사 탐방, 액티비티 - 끔찍한 학살의 흔적 ''너븐숭이 4·3 기념관'' #역사 #4·3 #다크투어리즘 / 일제 군국주의의 흔적 ''알뜨르 비행장'' #역사 #태평양전쟁 #다크투어리즘', '현대', '사회/지역', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 1, '밑줄 그은 ''이 시대''의 생활 모습으로 옳은 것은?', 1, '민무늬 토기에 식량을 저장하였다.', '가락바퀴를 이용하여 실을 만들었다.', '명도전, 반량전 등 화폐를 사용하였다.', '철제 농기구를 사용하여 농사를 지었다.', '주로 동굴이나 강가의 막집에 거주하였다.', 5, '[해설] 내 손 안의 해설사: 연천 전곡리에서 출토된 이 주먹도끼는 찍개, 찌르개와 함께 이 시대를 대표하는 유물입니다. 양면을 가공한 날카로운 날이 특징으로, 동아시아에는 찍개 문화만 존재하였다는 기존 학설을 뒤집는 증거가 되었습니다.', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 2, '다음 검색창에 들어갈 국가에 대한 설명으로 가장 적절한 것은?', 2, '신성 구역인 소도가 존재하였다.', '10월에 동맹이라는 제천 행사를 열었다.', '읍락 간의 경계를 중시하는 책화가 있었다.', '사회 질서 유지를 위해 범금 8조를 두었다.', '화백 회의에서 국가의 중대사를 결정하였다.', 2, '국가명 검색 - 중국정사조선전 데이터베이스, 검색 결과 426건. 기사명: 5부 중 계루부에서 왕이 나오다 / 왕 아래 상가, 대로, 패자 등의 관직을 두다 / 혼인할 때 여자 집에 서옥을 짓다.', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 3, '(가)~(다)를 일어난 순서대로 옳게 나열한 것은?', 2, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (가) - (나)', 3, '(가) 고구려왕 거련이 직접 군사를 거느리고 백제를 공격하였다. 백제왕 경이 문주를 신라에 보내 도움을 요청하였다. …… 신라군이 도착하기 전에 백제가 고구려에 함락되었고 경 또한 살해되었다. (나) 백제왕이 태자와 함께 정예군 3만 명을 거느리고 고구려에 침입하여 평양성을 공격하였다. 고구려왕 사유가 힘을 다해 싸워 이를 막았으나 날아오는 화살에 맞아 죽었다. (다) 백제왕 명농이 가야와 함께 와서 관산성을 공격하였다. …… 신라군이 맞서 싸웠는데 삼년산군의 고간 도도가 급습하여 백제왕을 죽였다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 4, '(가) 국가의 문화유산으로 옳은 것은?', 1, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 1, '입체 퍼즐로 만드는 우리 문화유산 - 금동 대향로. 부여 능산리에서 발견된 금동대향로는 (가)를 대표하는 문화유산으로 국보로 지정되어 있습니다. 용이 받치고 있는 연꽃 형태의 몸체 위에 산봉우리로 둘러싸인 반원형의 뚜껑이 있고, 그 꼭대기에는 봉황이 자리 잡고 있습니다. 불교와 도교 요소가 복합적으로 표현된 걸작입니다.', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 5, '(가) 국가의 경제 상황으로 가장 적절한 것은?', 2, '경성과 경원에 무역소를 두었다.', '솔빈부의 말을 특산품으로 수출하였다.', '서적점, 다점 등의 관영 상점을 운영하였다.', '청해진을 중심으로 해상 무역이 번성하였다.', '특수 행정 구역인 소에서 여러 물품을 생산하였다.', 4, '역사 탐구 동아리 과제 - 일본 도다이사 쇼소인에서 발견된 (가) 촌락 문서의 사진입니다. 이 문서에 대해 조사한 내용을 올려주세요. 학생1: 조세 수취와 노동력 동원에 활용할 목적으로 작성되었어요. 학생2: 서원경 부근 4개 촌락의 인구 현황, 토지의 종류와 면적 등의 정보가 있어요. 학생3: 소, 말, 뽕나무, 잣나무 등의 수도 기록되어 있어요.', '고대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 6, '다음 대화에 나타난 왕에 대한 설명으로 옳은 것은?', 2, '병부를 설치하고 율령을 반포하였다.', '관료전을 지급하고 녹읍을 폐지하였다.', '화랑도를 국가적인 조직으로 개편하였다.', '관리 선발을 위해 독서삼품과를 시행하였다.', '국호를 마진으로 바꾸고 도읍을 철원으로 옮겼다.', 2, '내일 우리 모둠이 발표할 왕에 대해 조사한 내용을 말해줘. - 국학을 설치하여 유학을 보급하였어. / 전국을 9주로 나누고 행정 구역을 정비하였어. / 고구려·백제·말갈인을 포함한 군대를 만들었어.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 7, '다음 자료에 해당하는 인물에 대한 설명으로 옳은 것은?', 2, '보현십원가를 지었다.', '세속 5계를 제시하였다.', '대승기신론소를 저술하였다.', '화엄일승법계도를 작성하였다.', '신편제종교장총록을 편찬하였다.', 4, '진골 출신의 신라 승려이며, 당으로 건너가 불법을 구하고자 하였습니다. / 귀국 후 관세음보살을 뵙고자 하는 마음에서 「백화도량발원문」을 짓고 낙산사를 창건한 것으로 전해집니다. / 부석사 등 여러 절을 창건하여 불법을 전파하면서 많은 제자를 양성하였습니다.', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 8, '(가) 국가에 대한 설명으로 옳은 것은?', 2, '역사서인 유기와 신집을 편찬하였다.', '내신좌평, 내두좌평 등 6좌평이 있었다.', '5경 15부 62주의 지방 행정 제도를 갖추었다.', '도병마사에서 변경의 군사 문제 등을 논의하였다.', '골품에 따라 관등 승진, 일상생활 등을 엄격히 제한하였다.', 3, '#51. 서재 안 - 최치원이 책상 앞에 앉아 표문을 쓰고 있다. 화면이 표문을 비추며 최치원의 목소리로 내레이션이 흐른다. 내레이션: 지난날 (가)의 왕자 대봉예가 자신들의 자리를 신라 위에 있게 해 달라고 청하였습니다. 황제 폐하께서 ''나라의 순서는 원래 강약에 따라 정하는 것이 아니다.''라는 조칙을 내려 순서를 바로잡아 주셨습니다. 이에 오래된 신하가 소외되는 근심은 덜었으나, 앞으로 같은 일이 생길까 우려됩니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 9, '(가) 시기에 있었던 사실로 옳은 것은?', 3, '비담과 염종의 난이 진압되었다.', '김헌창이 웅천주에서 반란을 일으켰다.', '연개소문이 정변을 일으켜 권력을 잡았다.', '만적을 비롯한 노비들이 반란을 모의하였다.', '김춘추가 당으로 건너가 군사적 지원을 요청하였다.', 2, '지난번에 김지정 등이 일으킨 반란으로 시해된 선왕의 시호를 혜공이라 하겠노라. (가) 중앙에서 세금을 독촉해 옵니다. 그동안 시달려 온 사벌주 농민들, 우리 함께 뭉칩시다! 우리도 원종과 함께 하겠습니다!', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 10, '다음 상황 이후에 전개된 사실로 옳은 것은?', 2, '신숭겸이 공산 전투에서 전사하였다.', '신검의 군대가 일리천 전투에서 패배하였다.', '궁예가 군대를 보내 나주 일대를 점령하였다.', '김선평, 권행 등이 고창 전투에서 활약하였다.', '경애왕이 후백제군의 왕경 습격으로 사망하였다.', 2, '견훤이 금산사에 있은 지 3개월 만에 막내 아들 능예, 딸 쇠복, 총애하는 첩 고비 등과 더불어 금성으로 달아나 사람을 보내 왕에게 만나기를 청하였다. 왕이 기뻐하여 유금필, 왕만세 등을 보내 그를 위로하고 맞아오도록 하였다. 견훤이 도착하자, 두터운 예로써 대접하였다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 11, '다음 장면에 등장하는 왕에 대한 설명으로 옳은 것은?', 2, '국자감에 7재라는 전문 강좌를 개설하였다.', '지방 12목에 경학 박사를 처음 파견하였다.', '서적포를 설치하여 출판을 담당하게 하였다.', '대도에 만권당을 세워 중국 학자와 교유하였다.', '외국어 교육과 통역을 관장하는 통문관을 설치하였다.', 1, '짐은 일찍이 유학에 깊은 관심을 가져 청연각과 보문각을 설립하고, 학사를 두어 경전을 강론하게 하였다. 이번엔 양현고를 두어 선비를 양성하게 하라.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 12, '(가) 인물에 대한 설명으로 옳은 것은?', 3, '원종을 폐위하고 안경공 창을 즉위시켰다.', '9재 학당을 설립하여 유교 교육에 힘썼다.', '인사 행정 담당 기구로 정방을 설치하였다.', '전민변정도감의 책임자로서 개혁을 이끌었다.', '오월에 사신을 보내고 검교태보의 직을 받았다.', 3, '한국사 탐구 보고서 - 주제: 인물로 보는 무신 정권. 방법: 문헌 조사, 인터넷 검색 등. 조사 내용 - 정중부: 보현원에서 이의방 등과 정변을 일으킴 / 이의민: 조위총의 난을 진압하여 상장군이 됨 / 최충헌: 봉사 10조를 올려 시정 개혁을 요구함 / (가): 야별초를 좌·우별초로 나누어 편성함.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 13, '(가) 국가의 경제 상황으로 가장 적절한 것은?', 2, '초량 왜관을 통해 일본과 무역하였다.', '덕대가 광산을 전문적으로 경영하였다.', '당항성, 영암이 국제 무역항으로 번성하였다.', '거란도, 영주도를 통해 주변국과 교역하였다.', '주전도감을 설치하여 해동통보를 발행하였다.', 5, '황비창천(?比昌天) 명(銘) 거울, 무역선. 황비창천 명 거울은 (가)에서 사용했던 것으로 풍랑이 몰아치는 바다 위에 배 한 척이 돛을 펴고 나아가는 모습이 표현되어 있습니다. 이 거울에 묘사된 배를 토대로 오른쪽 사진과 같이 당시 무역선의 모습을 유추하였습니다. (가) 시대 사람들은 송, 일본뿐만 아니라 동남아시아, 아라비아 상인들과도 교역을 하였습니다. *황비창천: 밝게 빛나는 창성한 하늘', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 14, '(가)~(다)를 일어난 순서대로 옳게 나열한 것은?', 2, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (가) - (나)', 4, '(가) 이자겸과 척준경이 군사를 동원하여 궁궐을 침범하고 불태웠다. 왕을 위협하여 남궁(南宮)으로 거처를 옮기게 하고, 안보린·최탁 등 17인을 죽였다. 이외에도 죽인 군사가 헤아릴 수 없을 정도였다. (나) 왕규가 광주원군을 [왕으로] 세우고자 하였는데, 일찍이 밤에 왕이 깊이 잠든 것을 엿보고 자신의 일당을 침소에 잠입시켜 대역죄를 행하려고 하였다. 왕이 그것을 알아차리고 한주먹으로 쳐 죽인 후 좌우 시종들에게 끌어내게 하였다. (다) 강조의 군사들이 들어오자, 왕이 어쩔 수 없음을 깨닫고 태후와 함께 목 놓아 울며 법왕사로 갔다. 잠시 후 황보유의 등이 대량원군을 왕위에 올렸다. 강조는 왕을 폐위시켜 양국공으로 삼고, 군사를 보내 김치양 부자와 유행간 등 7인을 죽였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 15, '(가) 지역의 탐구 활동으로 가장 적절한 것은?', 3, '몽골의 사신 저고여가 피살된 곳을 조사한다.', '서희가 외교 담판을 통해 획득한 곳을 찾아본다.', '강감찬이 건의하여 건설된 성곽이 있는 곳을 검색한다.', '김보당이 무신 정권에 저항하여 봉기한 곳을 파악한다.', '최무선이 화포를 이용하여 왜구를 물리친 곳을 알아본다.', 3, '고지도로 보는 (가)의 역사 - 이 지도는 1872년에 제작된 (가) 전도의 일부로, 고려 왕조의 궁궐터였던 만월대와 고려 최고 교육 기관인 국자감을 계승한 성균관의 위치를 확인할 수 있다. 또한 태조 왕건과 신혜왕후가 함께 안장된 현릉, 거란이 보낸 낙타가 굶어 죽었다는 만부교, 정몽주를 기리기 위해 세운 숭양서원 등도 표시되어 있다.', '고려', '지역사', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 16, '(가)에 대한 고려의 대응으로 옳은 것은?', 2, '강화도로 도읍을 옮겨 항전하였다.', '광군을 조직하여 침입에 대비하였다.', '삼수병으로 구성된 훈련도감을 신설하였다.', '별무반을 편성하고 동북 9성을 축조하였다.', '철령위 설치에 반발하여 요동 정벌을 추진하였다.', 1, '이 탑은 방호별감 김윤후가 군인과 백성들을 이끌고 (가)을/를 상대로 충주산성에서 승리한 것을 기념하여 세운 것이야. 당시 군인과 백성이 결사 항전하는 모습이 표현되어 있어. 탑 윗 부분의 1253은 승전 연도를 의미해.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 17, '다음 특별전에 전시될 문화유산으로 가장 적절한 것은?', 1, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 1, '무한한 아름다움, 고려 상형자기 특별전 - 아름다운 비색(翡色), 빼어난 조형성, 고려 시대 공예의 높은 기술적 성취, 한국 문화의 정수 상형자기(象形磁器), 그 아름다움을 느껴 보시기 바랍니다. △△박물관 특별 전시실.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 18, '다음 가상 뉴스 이후에 있었던 사실로 옳은 것은?', 1, '쌍기의 건의로 과거제가 도입되었다.', '빈민 구제를 위해 흑창이 설립되었다.', '매를 기르고 훈련시키는 응방이 설치되었다.', '의천이 국청사를 중심으로 천태종을 개창하였다.', '망이·망소이가 가혹한 수탈에 저항하여 봉기하였다.', 3, '원의 황녀, 겁령구들과 입국하다 - 세자 시절 원의 황녀와 혼인하신 국왕께서는 오늘 고려로 들어오시는 황녀를 맞이하기 위해 서북면에 행차하셨습니다. 이 자리에서 신하들이 본인처럼 변발을 하지 않은 점을 크게 질책하셨습니다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 19, '다음 가상 대화에 등장하는 왕의 재위 시기에 있었던 사실로 옳은 것은?', 3, '훈련 교범인 무예도보통지가 간행되었다.', '전통 한의학을 정리한 동의보감이 저술되었다.', '음악 이론 등을 집대성한 악학궤범이 완성되었다.', '유교 윤리의 보급을 위해 삼강행실도가 편찬되었다.', '군정, 재정의 내용을 정리한 만기요람이 만들어졌다.', 4, '지난번 남양에서 발견된 경석으로 만든 편경이 완성되었는데요, 이와 관련하여 새로운 정책을 구상하고 계신가요? / 박연이 만든 편경은 중국의 것보다 음높이가 정확하며 그 소리가 맑고 아름다웠소. 이를 활용하여 궁중 음악인 아악을 정비해 보고자 하오.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 20, '(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?', 2, '유자광의 고변으로 남이가 처형되었다.', '기사환국으로 송시열이 죽임을 당하였다.', '외척 간의 권력 다툼으로 윤임이 제거되었다.', '위훈 삭제를 주장한 조광조 일파가 축출되었다.', '조의제문이 발단이 되어 김일손 등이 피해를 입었다.', 5, '이 노래는 백성들이 교동도로 유배된 (가)을/를 원망하며 부른 것입니다. 그는 폐비 윤씨 사사 사건을 빌미로 신하들을 숙청하는 등 폭정을 자행하다가 반정으로 폐위되었습니다. [노래] 충성이란 사모요 거동은 곧 교동일세 일만 흥청 어디 두고 석양 하늘에 뉘를 좇아 가는고 두어라 예 또한 가시의 집이니 날 새우기엔 무방하고 또 조용하지요.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 21, '밑줄 그은 ''전쟁'' 중에 있었던 사실로 옳은 것은?', 2, '정문부가 북관대첩을 이끌었다.', '정봉수가 용골산성에서 항쟁하였다.', '최윤덕이 이만주 부대를 정벌하였다.', '강홍립이 사르후 전투에 참전하였다.', '김준룡이 광교산 전투에서 항전하였다.', 1, '이치 전투, 전라도를 지켜내다 - 이치(梨峙)는 금산에서 전주로 넘어가는 길목에 위치한 요충지이다. 이곳에서 전라 절제사 권율과 동복 현감 황진이 이끄는 관군은 치열한 전투 끝에 적의 진격을 저지하였다. 그 결과 전라도의 곡창 지대와 조선 수군의 배후를 지키는 데 기여하여 전쟁 초기 적군의 전략에 타격을 입혔다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 22, '(가)에 대한 설명으로 옳은 것은?', 2, '수도의 행정과 치안을 담당하였다.', '사헌부, 사간원과 함께 3사로 불렸다.', '대사성, 좨주, 직강 등의 관직이 있었다.', '왕명 출납을 맡은 왕의 비서 기관이었다.', '사초와 시정기를 바탕으로 실록을 편찬하였다.', 2, '이것은 옥당이라고도 불린 (가)에 걸려있던 현판으로, ''십팔학사들의 서책이 있는 관부''라는 뜻의 글이 있습니다. 이 관청이 궁중의 도서를 관리하고 문한(文翰)과 왕의 자문을 담당하였기에 당나라 황제를 보좌했던 십팔학사의 고사에 빗대어 표현한 것입니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 23, '(가)에 대한 탐구 활동으로 가장 적절한 것은?', 1, '전시과에서 전지 지급 기준의 변화를 찾아본다.', '일부 상류층에게 선무군관포를 거둔 목적을 알아본다.', '과전 지급 대상을 현직 관리로 제한한 까닭을 검색한다.', '풍흉에 관계없이 전세 부담액을 고정한 이유를 분석한다.', '관청에 물품을 조달하는 공인이 등장한 배경을 조사한다.', 5, '서울에 있는 간사한 무리가 경주인(京主人)이라고 하며 각 도의 공물을 방납하면서 그 값을 두 배에서 수십 배까지 징수하였다. …… 영의정 김육이 (가)을/를 충청도에서 먼저 시험할 것을 청하였다. 왕이 여러 차례 신하들에게 의견을 물었으나 서로 엇갈렸다. 이때에 왕이 다시 김육 등 여러 신하들을 불러 그것이 편리한지 여부에 대한 의견들을 듣고 비로소 호서(湖西)에 먼저 행하기로 정하였다.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 24, '밑줄 그은 ''이 인물''에 대한 설명으로 옳은 것은?', 2, '의산문답에서 무한 우주론을 주장하였다.', '북학의에서 절약보다 적절한 소비를 권장하였다.', '열하일기에서 수레와 선박의 필요성을 서술하였다.', '성호사설에서 나라를 망치는 여섯 가지 좀을 제시하였다.', '우서에서 사농공상의 직업적 평등과 전문화를 강조하였다.', 4, '이 인물이 저술한 곽우록에 대해 말해보자. / 곽우는 벼슬이 없는 자의 걱정이란 뜻이래. / 이 책에는 영업전을 설정하고 그 매매를 금지하는 한전론에 대한 내용 등이 담겨 있어.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 25, '다음 자료에 등장하는 왕에 대한 설명으로 옳은 것은?', 2, '나선 정벌에 조총 부대를 파견하였다.', '통치 규범을 재정비한 속대전을 편찬하였다.', '청과 국경을 정한 백두산정계비를 건립하였다.', '문신을 재교육하기 위한 초계문신제를 시행하였다.', '한성 방어를 위하여 총융청과 수어청을 창설하였다.', 2, '○ 개천이 점점 막혀 …… 장마 때마다 범람할까 근심하게 되었다. 왕이 이르기를 …… 이에 준천사(濬川司)를 설치하여 병조판서와 한성부 판윤, 삼군문의 대장으로 하여금 준천 당상을 겸하도록 하고 도청, 낭청 각 1인을 두었다. 매년 개천 바닥을 파서 물이 넘치지 않도록 하였다. ○ 국초에 신문고를 설치하여 억울함을 지닌 백성들로 하여금 북을 쳐서 알리도록 하였는데, 그 법이 폐해진 지 이미 오래되었다. 왕이 …… 마침내 복구하도록 명하였다. 북을 울리는 자가 있으면 …… 해당 관청에서 아뢰도록 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 26, '다음 가상 대화가 이루어진 시기에 볼 수 있는 모습으로 적절하지 않은 것은?', 2, '상평통보로 물건을 거래하는 객주', '인삼 무역으로 크게 수익을 본 송상', '주자소에서 계미자를 주조하는 장인', '고추, 담배 등의 상품 작물을 재배하는 농민', '저잣거리에서 한글 소설을 읽어주는 전기수', 3, '지난달에 대왕대비께서 사학(邪學)에 대한 단속을 강화하라고 하교하셨다는군. / 이승훈이 잡혀가고 정약종도 죄인으로 몰려 죽었다고 하네. 우리 교인들에 대한 탄압이 점점 심해지고 있군.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 27, '(가)에 해당하는 작품으로 옳은 것은?', 1, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 3, '한국사 대화형 인공지능 - Q: 이 그림에 대해 설명해 줘. A: 이 그림은 조선 후기의 대표적인 풍속 화가인 혜원이 그린 연소답청입니다. 양반들이 봄날에 자연을 즐기고자 나들이하는 모습을 그린 작품입니다. Q: 이 화가의 다른 작품도 알려줘. A: (가)', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 28, '다음 상소가 올려진 시기를 연표에서 옳게 고른 것은?', 3, '(가)', '(나)', '(다)', '(라)', '(마)', 2, '전 호조 참판 최익현 아룁니다. …… 다행히 성상의 뜻이 척화에 있는 데 힘입어 기정진과 이항로가 상소를 하여 강화가 불가함을 말하자 전하께서 그 말을 받아들여 주셨습니다. 이런 연유로 10년 동안에는 양적들이 우리를 탐내었으나 감히 그 뜻을 펴지 못하였습니다. …… 옛날의 왜인들은 이웃 나라였으나 지금의 왜인들은 도적들이니, 강화할 수 없습니다. 왜인들이 양적들의 앞잡이가 되었기 때문입니다. [연표] 고종즉위 - (가) - 신미양요 - (나) - 갑신정변 - (다) - 을미사변 - (라) - 러일 전쟁 발발 - (마) - 국권 피탈', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 29, '밑줄 그은 ''중건'' 시기에 있었던 사실로 옳은 것은?', 2, '청일 전쟁이 발발하였다.', '삼정이정청이 설치되었다.', '영국이 거문도를 불법으로 점령하였다.', '김기수가 수신사로 일본에 파견되었다.', '한성근 부대가 문수산성에서 항전하였다.', 5, '사료로 보는 한국사 - 대원위께서 분부하신 내용, ''지금 영건할 때에 이른바 원납전은 실로 힘닿는 대로 내어 공역을 도와야 하는 것인데, …… 모두 가난하지 않은 자들인데 아직 한푼도 바친 바가 없으니 또한 무슨 까닭인가. …… 여전히 책임을 면하려고 둘러대기만 하면서, 면제되는지 한 번 시험해 보려는 계책을 펴니 매우 통탄스럽다. 모두 일일이 불러서 그 이유를 따져 묻고, 상세히 회답하여 죄를 심리하고 처리하는 바탕이 되도록 하라.'' -『영건일감』- [해설] 이 사료는 경복궁 중건을 주관한 영건도감에서 평안도에 보낸 공문의 내용을 요약한 것이다. 당시 이 중건에 필요한 비용을 마련하기 위해 원납전을 내게 하였는데, 백성들은 이를 ''원해서 납부하는 돈''이 아니라 ''원망하며 납부하는 돈''이라고 불렀다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 30, '밑줄 그은 ''이 장정''에 대한 설명으로 옳은 것은?', 2, '임오군란을 계기로 체결되었다.', '거중 조정의 조항을 포함하였다.', '방곡령을 선포할 수 있는 조건을 명시하였다.', '부산항과 원산항이 개항되는 결과를 가져왔다.', '외국인을 재정 고문으로 두도록 하는 조항을 담고 있다.', 1, '이 장정이 맺어진 이후 나타난 변화에 대해 말해보자. / 청 상인이 양화진과 한성에 점포를 열 수 있게 되었어. / 조선의 상권을 둘러싸고 청과 일본 상인의 경쟁이 치열해졌지.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 31, '(가) 운동에 대한 설명으로 옳은 것은?', 1, '일본의 황무지 개간권 요구를 저지하였다.', '조선 총독부의 방해와 탄압으로 중단되었다.', '집강소를 중심으로 폐정 개혁안을 실천하였다.', '이른바 남한 대토벌 작전으로 큰 피해를 입었다.', '상황 수습을 위해 박규수가 안핵사로 파견되었다.', 3, '특별 전시 - (가), 기록으로 되살아나다. 부패한 지배층과 외세의 침략에 맞서 새로운 세상을 꿈꾸며 봉기했던 (가) 관련 기록물이 세계 기록 유산으로 등재된 것을 기념하여 특별전을 개최합니다. 주요 전시 자료: 전봉준 공초, 갑오군정실기, 사발통문.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 32, '(가) 단체의 활동으로 옳은 것은?', 2, '고종 강제 퇴위 반대 운동을 주도하였다.', '만세보를 발행하여 민족의식을 고취하였다.', '파리 강화 회의에 독립 청원서를 제출하였다.', '관민 공동회를 개최하여 헌의 6조를 결의하였다.', '계몽 서적을 보급하기 위해 태극 서관을 운영하였다.', 4, '역사 신문 - 독립관에서 토론의 장이 열리다. 지난 일요일 오후 독립관에서 (가)의 첫 토론회가 ''조선의 급선무는 인민의 교육이다.''라는 주제로 개최되었다. 이날 토론회에는 찬반 양측의 열띤 논의가 있었고, 법부대신 한규설 등 정부 고위 인사들도 참석해 교육 문제에 대한 다양한 의견을 제시하였다. 다음 토론회에서는 ''도로를 개선하는 것이 위생을 위한 최고의 방법''이라는 주제로 (가)의 위원 이상재 씨를 포함한 4인이 열띤 토론을 벌일 예정이다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 33, '밑줄 그은 ''개혁''의 내용으로 옳은 것은?', 2, '개혁을 추진하기 위해 군국기무처를 두었다.', '행정 기구를 6조에서 8아문으로 개편하였다.', '근대식 무기 제조 공장인 기기창을 설립하였다.', '토지 소유권을 확인해 주는 지계를 발급하였다.', '개혁의 방향을 제시한 홍범 14조를 반포하였다.', 4, '이번 시간에는 구본신참을 기본 방향으로 내세워 추진한 개혁에 대한 의견을 들어보고자 합니다. / 원수부와 무관학교 설치, 상공학교와 회사, 공장 설립 등 자주 독립과 근대화에 필요한 문물을 적극적으로 도입하려 한 의미 있는 개혁이었습니다. / 하지만 체제 변화를 부르지 않는 근대적 문물 수용의 확대뿐이었습니다. 일본 등 열강의 간섭에서도 완전히 벗어나지 못하였습니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 34, '(가)~(라)에 들어갈 내용으로 옳은 것을 <보기>에서 고른 것은?', 3, 'ㄱ, ㄴ', 'ㄱ, ㄷ', 'ㄴ, ㄷ', 'ㄴ, ㄹ', 'ㄷ, ㄹ', 3, '개항 이후 도입된 근대 문물 알아보기 - 모둠별로 제시된 사진 자료에 대해 조사한 내용을 올려주세요. 1모둠(가) 배재 학당 / 2모둠(나) 광혜원 / 3모둠(다) 한성 전기 회사 / 4모둠(라) 원각사. <보기> ㄱ. (가) - 교육 입국 조서에 근거하여 설립되었어요. ㄴ. (나) - 알렌의 건의로 세워진 최초의 서양식 병원이었어요. ㄷ. (다) - 서대문과 청량리 사이를 오가는 전차를 운영하였어요. ㄹ. (라) - 나운규가 제작한 영화 아리랑을 상영하였어요.', '근대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 35, '(가)에 들어갈 내용으로 가장 적절한 것은?', 1, '김홍집, 조선책략을 가져오다', '김옥균, 개화당 정부를 수립하다', '김윤식, 영선사로 청에 다녀오다', '유길준, 조선 중립화론을 건의하다', '이상설, 고종의 특사로 헤이그에 가다', 5, '○○고 한국사 교실 - 과제 안내: 일제는 대한 제국의 외교권을 강탈하고 통감부를 설치하였어요. 이후 전개된 국권 수호 노력을 조사하여 보고서를 작성하고 제목과 함께 제출해 주세요. 목록 - 1. 신돌석, 의병장으로 활약하다 / 2. 나철, 오적 처단을 위해 자신회를 조직하다 / 3. (가) / 4. 이재명, 명동 성당 앞에서 이완용을 습격하다', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 36, '밑줄 그은 ''이 시기''에 볼 수 있는 모습으로 가장 적절한 것은?', 3, '암태도 소작 쟁의에 참여하는 농민', '제복을 입고 칼을 찬 채 수업하는 교사', '잡지 어린이에 실을 원고를 작성하는 작가', '토월회에서 연극 공연을 준비하고 있는 배우', '경성 고무 여자 직공 조합의 파업을 취재하는 기자', 5, '신문 기사로 보는 일제의 식민 통치 정책 - 볼기 다섯 개: 마차를 타고 가면서 고삐를 잡지 않아 볼기 다섯 대를 때리고 풀어줌. 솔닙 한 줌에 태 십오: 경복궁 신무문 밖 보안림 안에 들어가서 솔잎 한 움큼을 절취하다가 발견되어 열다섯 대에 처함. 조선 태형령이 시행된 이 시기에는 헌병 경찰이 재판 없이 조선인에게만 태형을 가할 수 있었다. 이를 통해 사회 전반에 공포심을 조성하고 식민 지배 질서를 강제하려 하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 37, '다음 법령이 발표된 이후의 사실로 옳은 것은?', 2, '국권 회복을 위해 해조신문이 창간되었다.', '평양 숭의 여학교에서 송죽회가 결성되었다.', '메가타의 주도로 화폐 정리 사업이 실시되었다.', '회사 설립을 허가제로 하는 회사령이 공포되었다.', '조선 민립 대학 기성회 창립을 위한 총회가 개최되었다.', 1, '이 법령은 ''내선공통(內鮮共通)''의 미명 하에 보통학교의 수업 연한을 소학교와 동일하게 적용하였습니다. 그러나 입학 자격과 학교 운영 등에서 여전히 차별적인 요소를 담고 있습니다. 제1조 조선에서의 교육은 이 영에 따른다. 제2조 국어[일본어]를 상용하는 자의 보통교육은 소학교령, 중학교령, 고등여학교령을 따른다. 제3조 국어[일본어]를 상용하지 않는 자에게 보통교육을 하는 학교는 보통학교, 고등보통학교, 여자고등보통학교로 한다. 제5조 보통학교의 수업 연한은 6년으로 한다. 단, 토지의 정황에 의하여 5년 또는 4년으로 할 수 있다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 38, '(가) 단체에 대한 설명으로 옳은 것은?', 1, '신흥 강습소를 세워 독립군을 양성하였다.', '구미 위원부를 설치하여 외교 활동을 전개하였다.', '단원인 이봉창이 일왕 행렬에 폭탄을 투척하였다.', '조선 혁명 선언을 통해 이념과 활동 방침을 밝혔다.', '조선 총독부에 국권 반환 요구서를 제출하고자 하였다.', 3, '기억해야 할 대한외국인 - 마쟈르: 행적. 제1차 세계 대전에 참전했던 헝가리인 마쟈르는 러시아군 포로가 되었다가 몽골까지 흘러들어왔다. 그곳에서 알게 된 독립운동가 이태준의 부탁으로 베이징에서 김원봉을 만났다. 김원봉은 1919년 지린성에서 일제 식민 통치 기관 파괴와 요인 처단 등을 목표로 윤세주 등과 (가)을/를 조직하였으나 당시 화약 무기 제조에 어려움을 겪고 있었다. 마쟈르는 성능 좋은 폭탄을 다수 제조하여 (가)의 활동에 도움을 주었다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 39, '밑줄 그은 ''이 운동''에 대한 설명으로 옳은 것은?', 3, '대한매일신보의 후원을 받아 확산되었다.', '순종의 인산일을 기회로 삼아 추진하였다.', '자작회, 토산 애용 부인회 등이 활동하였다.', '신간회가 진상 조사단을 파견하여 지원하였다.', '강주룡이 을밀대 지붕에서 고공 농성을 벌였다.', 4, '삽화로 보는 한국사 - 이 삽화는 평양에서 조만식 등의 주도로 시작된 이 운동을 풍자하고 있습니다. 이 운동이 ''내 살림 내 것으로'' 등의 구호를 내세워 호응을 얻자, 일제는 제2의 3·1 운동으로 확산될 것을 우려하여 탄압하였습니다. 한편 일각에서는 자본가의 이익만을 추구한다는 비판도 있었습니다.', '일제강점기', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 40, '(가) 단체에 대한 설명으로 옳은 것은?', 2, '개벽, 신여성 등의 잡지를 발행하였다.', '여성 교육을 위해 이화 학당을 설립하였다.', '좌우를 아우르는 민족 협동 전선으로 결성되었다.', '조선학 운동을 전개하여 여유당전서를 간행하였다.', '최초의 여성 권리 선언문인 여권통문을 발표하였다.', 3, '나는 1927년에 결성된 여성 운동 단체 (가)의 집행 위원으로 강령과 규약 작성에 참여한 박신우입니다. 이 강령에서 조선 여성의 공고한 단결과 정치·경제·사회 등 전반적인 이익 옹호가 이 단체의 목표임을 분명히 하였습니다.', '일제강점기', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 41, '(가)에 대한 설명으로 옳지 않은 것은?', 2, '한인 자치 기관인 경학사를 조직하였다.', '자금 마련을 위해 독립 공채를 발행하였다.', '삼균주의를 기초로 하는 건국 강령을 발표하였다.', '육군 주만 참의부를 편성하여 무장 투쟁을 펼쳤다.', '임시 사료 편찬회를 두어 한일 관계 사료집을 간행하였다.', 1, '【이달의 독립운동가】 하늘에서 땅에서 독립운동을 펼쳐나간 이상정·권기옥 부부 - 이상정과 권기옥은 중국에서 독립운동을 하던 중 부부의 연을 맺고, 함께 독립운동에 헌신하였다. 중국군에서 활동하던 이상정은 (가)의 한국광복군 창설에 기여하였고, 외무부 외교 연구 위원으로도 활동하였다. 한국 최초의 여성 비행사였던 권기옥은 대한민국 애국 부인회를 재조직하였고, 다른 한국인 비행사들과 함께 충칭에서 한국광복군 비행대 설립을 계획하던 중 해방을 맞았다. 이러한 공적을 인정하여 1977년 건국훈장 독립장을 각각 추서 및 수여하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 42, '다음 일기가 작성된 이후의 사실로 옳은 것은?', 1, '미쓰야 협정이 체결되었다.', '치안 유지법이 제정되었다.', '조선사 편수회가 조직되었다.', '여자 정신 근로령이 공표되었다.', '동양 척식 주식회사가 설립되었다.', 4, '7월 13일(화): 경성은 뉴스를 듣기에는 참으로 빠르다. …… 중·일은 전쟁을 하게 되었다. …… 아아, 슬프다. 조선에서도 만약 이러한 때 영웅 한 사람이 있었더라면 회복할 가망이 많은데, 나는 아직 지위가 그렇지 않아 가슴만 태운다. 피만 끓는다. 영웅이여 일어서라 일어서라. 우리 조선은 영원히 죽었는가. 10월 8일(금): 조회할 때 일본인들이 조선인의 심장을 자기들의 심장으로 하려는 일본의 계략에서, 총독 미나미 지로가 소위 황국신민의 서사인지 뭔지를 만들어서 각 학생에게 암송하도록 하였다. 그래서 나도 그것을 읽었다. 그러나 우리 조선혼은 영원히 변하지 않을 것이다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 43, '(가)에 들어갈 주제로 적절하지 않은 것은?', 2, '몸뻬, 전시 체제의 의생활', '라디오 방송, 연예 오락의 유행', '경평 축구 대회, 스포츠의 대중화', '새마을 운동, 농촌의 생활 환경 개선', '모던 걸, 전통적 여성상을 탈피한 신여성의 등장', 4, '<2025년 시민 강좌> 일제 강점기, 새로운 문화와 일상 - 우리 도서관에서는 일제 강점기 새로운 문화의 유입과 일상생활의 변화를 주제로 강의를 준비하였습니다. 강의 주제: [제1강] 백화점, 자본주의적 소비 문화의 공간 [제2강] 끽다점, 도시 사교 문화의 확산 [제3강] (가) [제4강] 문화 주택, 새로운 주택 양식의 수용', '일제강점기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 44, '(가)에 대한 설명으로 옳은 것은?', 3, '신한공사를 설립하였다.', '좌우 합작 7원칙을 제시하였다.', '한인 국방 경위대를 창설하였다.', '남북 협상 공동 성명서를 발표하였다.', '조선 인민 공화국 수립이 선포된 후 해산하였다.', 5, '휘문중학 운동장에서 (가)의 수반인 여운형 씨가 5천여 군중 앞에서 해방의 제일성을 힘있게 외쳤다. ''조선 민족 해방의 날은 왔다. …… 어제 15일 아침 8시에 엔도 조선 총독부 정무총감의 초청을 받아 …… 나는 다섯 가지 요구를 제안하여 무조건 승낙을 받았다. 1. 전 조선 각지에 구속되어 있는 정치, 경제범을 즉시 해방하라 …… 4. 민족 해방의 모든 원동력이 되는 학생 훈련과 청년 조직에 대하여 간섭하지 말라 …… 이것으로 우리 민족 해방의 첫걸음을 내딛게 되었으니 우리가 지난날에 아프고 쓰렸던 것은 이 자리에서 모두 잊어버리자. ……''', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 45, '밑줄 그은 ''이 사건''에 대한 설명으로 옳은 것은?', 1, '향토 예비군 창설의 계기가 되었다.', '조봉암이 간첩 혐의를 받아 사형되었다.', '유엔군이 한반도에 파병되는 원인이 되었다.', '허정 과도 정부가 구성되는 결과를 가져왔다.', '진상 규명과 희생자 명예 회복을 위한 특별법이 제정되었다.', 5, '이 비석에는 이 사건을 소재로 한 현기영의 소설 순이삼촌의 주요 내용이 새겨져 있습니다. 이곳 제주에서는 남한만의 단독 선거에 반대하는 세력을 진압한다는 명분으로 토벌대에 의해 수많은 주민들이 희생당했습니다. 비석을 세우지 않고 눕혀놓은 것은 이 비극을 표현하기 위함입니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 46, '(가)~(마)에 대한 탐구 활동으로 적절하지 않은 것은?', 3, '(가) - 오페르트 도굴 미수 사건에 대해 찾아본다.', '(나) - 한인 애국단의 활동을 조사한다.', '(다) - 고려 시대 건축물의 공포 양식을 알아본다.', '(라) - 백제 부흥 운동에 대해 파악한다.', '(마) - 이황과 사단칠정 논쟁을 한 인물을 검색한다.', 5, '답사 계획서 - 주제: 내포 지역의 문화유산을 찾아서. 경로: 남연군 묘 → 윤봉길 생가 → 수덕사 → 임존성 → 추사 고택. (가) 남연군 묘 / (나) 윤봉길 생가 / (다) 수덕사 대웅전 / (라) 임존성 / (마) 추사 고택', '복합', '지역사', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 47, '(가)~(다) 학생이 발표한 내용을 일어난 순서대로 옳게 나열한 것은?', 2, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (가) - (나)', 1, '주제: 우리나라 헌법 개정의 역사 - (가) 대통령과 부통령의 임기는 4년으로 하며, 1회로 규정한 중임 횟수를 개헌 당시 대통령에게만 적용하지 않는다는 부칙을 달았어요. (나) 대통령은 국민의 보통·평등·직접·비밀 선거에 의하여 선출하고 대통령의 임기는 5년으로 하며, 중임할 수 없도록 했어요. (다) 대통령이 통일 주체 국민 회의의 의장이 되고, 국회의원 정수의 3분의 1을 추천하도록 개정된 헌법이 만들어졌어요.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 48, '밑줄 그은 ''정부'' 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 2, '서울 지하철 1호선 개통식을 취재하는 기자', '반민족 행위 처벌법을 통과시키는 국회의원', '한·중 자유 무역 협정(FTA)에 서명하는 장관', '금융실명제 실시로 신분증을 요구하는 은행 직원', '외환 위기 극복을 위한 금 모으기 운동에 동참하는 시민', 1, '이것은 서울에 최초로 설정된 개발 제한 구역을 표시한 지도입니다. 경부 고속 국도를 준공하는 등 경제 발전에 힘쓰던 당시 정부는 도시의 무질서한 확산을 방지하고 도시 주변의 자연환경을 보전하기 위해 처음으로 개발 제한 구역을 설정하였습니다.', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 49, '다음 뉴스가 보도된 정부 시기의 통일 노력으로 옳은 것은?', 2, '남북 조절위원회가 구성되었다.', '남북한이 유엔에 동시 가입하였다.', '금강산 해로 관광 사업이 시작되었다.', '개성에 남북 경제 협력 협의 사무소가 설치되었다.', '최초로 남북 이산가족 고향 방문단 교환이 이루어졌다.', 2, '하계 올림픽을 성공적으로 마친 대통령은 오늘 한국 국가 원수로서 처음으로 헝가리를 방문하였습니다. 헝가리는 우리 정부의 북방정책에 대한 지지와 협력 의사를 함께 표명하였습니다. 이것은 정부가 발표한 7·7 선언의 성과로 평가되고 있습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (76, 50, '(가)~(마)에 대한 설명으로 옳지 않은 것은?', 3, '(가) - 군대를 보내 신라에 침입한 왜를 격퇴하였다.', '(나) - 금관가야를 복속하여 영토를 확대하였다.', '(다) - 장문휴를 보내 당의 산둥반도를 공격하였다.', '(라) - 노비안검법을 시행하여 호족 세력을 견제하였다.', '(마) - 전제 군주제를 명문화한 대한국 국제를 반포하였다.', 5, '역사 돋보기 - 우리나라의 연호(年號). 연호는 군주가 자기의 치세 연차(年次)에 붙이는 칭호이다. 중국에서 시작되었으며 그 영향으로 우리나라, 일본, 베트남 등에서도 사용되었다. 연호는 원칙적으로 황제만 사용 가능하고, 제후 왕은 독자적인 연호를 쓸 수 없었다. 우리나라에서 최초로 확인되는 연호는 고구려 (가)의 영락이다. 신라도 (나)이 건원이라는 연호를, 뒤를 이은 진흥왕은 개국·태창·홍제 등의 연호를 사용하였다. 발해 고왕은 연호를 천통으로 했으며, (다)은/는 인안, 문왕은 대흥, 선왕은 건흥이라는 연호를 사용하였다. 고려 태조는 천수를 사용하고, (라)은/는 광덕·준풍을 연호로 삼았다. 조선은 고종 대에 개국기년(開國紀年)을 공문서에 사용하다가 건양, 광무로 연호를 정하였다. 그 뒤를 이은 (마)은/는 융희라는 연호를 사용하였다.', '복합', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 1, '밑줄 그은 ''이 시대''의 생활 모습으로 가장 적절한 것은?', 1, '철제 무기로 정복 활동을 벌였다.', '소를 이용한 깊이갈이가 일반화되었다.', '많은 인력을 동원하여 고인돌을 축조하였다.', '주먹도끼, 찍개 등의 뗀석기를 처음 제작하였다.', '가락바퀴와 뼈바늘을 이용하여 옷을 만들기 시작하였다.', 3, '여주 흔암리 유적 체험 프로그램 안내 - 우리 박물관에서는 사유 재산과 계급이 발생한 이 시대의 대표적 유적지인 여주 흔암리 유적을 주제로 체험 프로그램을 마련하였습니다. 다양한 행사를 통해 당시 사람들의 생활 모습을 알아보는 시간을 가져 보시기 바랍니다. 주요 프로그램: 민무늬 토기 조각 맞추기 / 반달 돌칼로 벼 이삭 수확하기 / 흙 속에 섞여 있는 탄화미 찾아보기. 신청 기간: 2026년 ??월 ??일 ~ ??월 ??일. 신청 방법: △△ 박물관 홈페이지 공지 사항 참고', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 2, '(가) 나라에 대한 설명으로 옳은 것은?', 1, '민며느리제라는 혼인 풍습이 있었다.', '국가 중대사를 정사암에서 논의하였다.', '여러 가(加)들이 별도로 사출도를 주관하였다.', '지방의 여러 성에 욕살, 처려근지 등을 두었다.', '사회 질서를 유지하기 위해 범금 8조를 만들었다.', 4, '역사 신문 - 양국 간 외교 갈등, 전쟁으로 이어지다. 한의 사신 섭하가 자신을 송별하던 (가)의 비왕(裨王) 장(長)을 살해하는 외교적 사건이 발생하였다. 그런데 한 무제는 오히려 섭하에게 벼슬을 내렸고 우거왕은 이에 분노하여 군대를 보내 섭하를 죽였다. 그러자 한 무제가 병력을 모아 (가)을/를 침공하였고, 우거왕은 이에 맞서기로 결심한 것으로 보인다.', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 3, '밑줄 그은 ''이 나라''에 대한 탐구 활동으로 가장 적절한 것은?', 2, '진대법의 시행 목적을 파악한다.', '책화의 사회적 의미를 조사한다.', '신성 구역인 소도의 기능을 알아본다.', '화백 회의의 의사 결정 방식을 살펴본다.', '포상 8국 전쟁이 전개되는 과정을 찾아본다.', 4, '인공 지능 이미지 생성기 및 편집기 - 텍스트를 이미지로. 명령어: 『삼국지』 위서 동이전에 기록된 이 나라의 특징을 반영하여 이미지를 만들어 줘. 주요 특징은 다음과 같아. ○ 특산물로 단궁, 과하마, 반어피가 유명하였다. ○ 10월에 제천 행사인 무천이 있었다. ○ 호랑이를 신으로 여겨 제사를 지냈다. [생성 중]', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 4, '(가) 국가의 문화유산으로 옳은 것은?', 2, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 5, '이 전시실에서는 (가)의 수도에서 발굴된 경주 천마총 장니 천마도와 금령총 천마무늬 말다래 등을 통해 다양한 천마의 모습을 볼 수 있습니다. 장니는 말의 안장 양쪽에 늘어뜨려 놓은 것으로 말다래라고도 불립니다. [사진: 경주 천마총 장니 천마도]', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 5, '다음 대화에 나타난 왕에 대한 설명으로 옳은 것은?', 2, '금마저에 미륵사를 창건하였다.', '고흥에게 서기를 편찬하게 하였다.', '지방의 22담로에 왕족을 파견하였다.', '동진에서 온 마라난타를 통해 불교를 수용하였다.', '장군 달기를 보내 고구려의 도살성을 점령하였다.', 3, '내일 우리 모둠이 발표할 왕에 대해 조사한 내용을 말해줘. - 백가의 난을 평정하고 왕권을 강화하였어. / 중국 남조의 양에 고구려를 여러 차례 격파하고 다시 강국이 되었다는 내용의 국서를 보냈어. / 1971년에 발굴된 이 왕의 무덤에서 왕과 왕비의 지석, 그리고 석수 등이 출토되었어.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 6, '(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?', 3, '을지문덕이 살수에서 대승을 거두었다.', '복신과 도침이 부여풍을 왕으로 추대하였다.', '윤충이 군사를 이끌고 대야성을 함락시켰다.', '연개소문이 정변을 일으켜 영류왕을 시해하였다.', '김춘추가 당으로 건너가 군사 연합을 성사시켰다.', 2, '(가) 왕이 태자 김법민을 보내 병선 100척을 거느리고 덕물도에서 소정방을 맞이하게 하였다. 소정방이 김법민에게 말하기를, ''나는 7월 10일에 백제의 남쪽에 이르러 대왕의 군대와 만나서 의자(義慈)의 도성을 무찔러 깨뜨리고자 한다.''라고 하였다. (나) 사찬 시득이 수군을 거느리고 소부리주 기벌포에서 설인귀와 싸웠는데 연이어 패배하였다. 다시 나아가 크고 작게 22번 싸워 이기고, 4천여 명의 목을 베었다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 7, '다음 자료에 해당하는 국가에 대한 설명으로 옳은 것은?', 1, '12월에 영고라는 제천 행사를 열었다.', '주자감을 설치하여 인재를 양성하였다.', '군사 조직으로 9서당 10정을 편성하였다.', '기인 제도를 실시하여 지방 세력을 견제하였다.', '왕족인 부여씨와 8성 귀족이 지배층을 이루었다.', 2, '영역은 사방 5천 리이며, 5경과 15부를 두었다. 서쪽으로는 중국과 통하고 남쪽으로는 신라와 교빙하고 북쪽으로는 거란에 맞서고 동쪽으로는 일본에 사신을 보내어, 동북의 안쪽 지역을 압도하며 거의 3백 년 동안이나 존속하였다. - 『해동역사』 -', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 8, '(가) 국가의 경제 상황으로 가장 적절한 것은?', 2, '수도에 서시와 남시를 설치하였다.', '활구라고 불리는 은병을 주조하였다.', '집집마다 부경이라는 창고가 있었다.', '관료전을 지급하고 녹읍을 폐지하였다.', '풍흉에 따라 9등급으로 전세를 거두었다.', 3, '한국사 대화형 인공 지능 - Q: 사진 속 무덤에 대해 알려줘. A: (가)의 왕릉으로 추정되는 천추총입니다. Q: 그렇게 보는 근거가 뭐야? A: (가)의 도성이었던 국내성 지역에 위치하며, 대형 계단식 돌무지무덤이기 때문입니다. 이 무덤 주변에서 영락으로 판독되는 명문 기와 조각도 발견되었습니다. 이 기와의 탁본이 있는데 보여드릴까요? Q: 응. 영락 부분을 표시해서 보여줘. A: [기와 탁본 이미지]', '고대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 9, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '안승을 보덕왕으로 봉하였다.', '광평성 등의 정치 기구를 마련하였다.', '외교 담판으로 강동 6주를 확보하였다.', '김부를 경주의 사심관으로 임명하였다.', '신라를 공격하여 경애왕을 죽게 하였다.', 2, '○ (가)이/가 나주의 상황을 근심하여 드디어 왕건에게 가서 지키도록 명령하였다. 품계는 한찬(韓粲)으로 올리고 해군대장군으로 삼았다. ○ (가)은/는 백성을 한낱 지푸라기처럼 여기고 오직 자기의 욕심만을 따랐다. 그리고 참위설을 믿어 갑자기 송악을 버리고 부양(斧壤)*으로 돌아가 궁궐을 세우니, 백성은 공사에 시달려 농사철을 빼앗겼다. *부양(斧壤): 현재 철원의 북부', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 10, '다음 가상 뉴스에서 보도한 내용이 있었던 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 2, '계백료서를 읽고 있는 관리', '담배를 밭에 심고 있는 농민', '조위총의 난을 진압하는 군인', '진전사에서 참선하는 선종 승려', '낙랑군과 교역할 덩이쇠를 주조하는 장인', 4, '청해진, 역사 속으로 사라지다 - 청해진이 폐지되고 주민들은 벽골군으로 옮겨진다는 소식입니다. 해상 무역의 거점이었던 청해진이 장보고의 건의로 설치된 지 20여 년만의 일입니다.', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 11, '(가) 국가에 대한 고려의 대응으로 옳은 것은?', 2, '별무반을 편성하였다.', '화통도감을 설치하였다.', '진관 체제를 실시하였다.', '초조대장경을 조판하였다.', '동녕부의 반환을 요청하였다.', 4, '이것은 현화사비의 탁본입니다. 이 비석의 흥미로운 점은 앞면에는 송의 연호인 천희가, 뒷면에는 (가)의 연호인 태평이 새겨져 있다는 것입니다. 고려는 귀주 대첩에서 (가)을/를 격퇴하였지만, 오히려 조공 책봉 관계를 수용하여 다원적인 국제 질서 속에서 실리와 안정을 추구하였습니다. [탁본: 앞면 天禧, 뒷면 太平]', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 12, '(가)에 들어갈 내용으로 가장 적절한 것은?', 3, '응방의 설치와 매 서식지의 변화', '시화호의 조성과 갯벌 생태계 파괴', '수의 침략과 요하 일대 감염병의 유행', '가죽 제품 수요 증가와 독도 강치의 멸종', '을축년 대홍수의 피해와 경성부의 대응 양상', 1, '[다큐멘터리 기획안] 우리 역사 속 생태·환경 이야기 - 기획 의도: 인간과 생태·환경의 상호 관계를 시대 순으로 조망하여 한국사에 대한 새로운 시각을 제공한다. 구성: 1부. 혜공왕 대 재이(災異) 발생과 백좌법회 개최 / 2부. (가) / 3부. 『승정원일기』를 통해 본 소빙기 농업 생산과 경신대기근 발생 / 4부. 해수구제(害獸驅除) 사업의 시행과 한반도 호랑이 사냥', '고려', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 13, '(가) 국가의 문화유산으로 옳지 않은 것은?', 1, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 4, '<(가)의 문화유산 소개하기> - 제가 소개할 문화유산은 청주 명암동에서 출토된 단산오옥명 먹입니다. (가)의 먹은 주로 묵소(墨所)에서 생산되었으며 중국 사신 서긍도 언급했을 정도로 잘 알려져 있었습니다. [사진: 다인철소 유적 출토 솥단지, 나전 국화 넝쿨무늬 합]', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 14, '(가)에 들어갈 내용으로 가장 적절한 것은?', 2, '신해통공의 단행 배경', '명의 멸망과 소중화주의의 대두', '골품제가 일상생활에 끼친 영향', '울산항을 통한 아라비아 상인들과의 교류', '황제국 표방 사례를 통해 본 외왕내제 의식', 5, '한국사 탐구 계획서 - 탐구 주제: (가). 참고 자료: 태조 왕건 청동상(통천관을 쓰고 있다) / 청주 용두사지 철당간(준풍(峻豊)이라는 연호가 새겨져 있다).', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 15, '밑줄 그은 ''인물''이 활동한 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 3, '제왕운기를 읽고 있는 왕', '만동묘 복구를 건의하는 유생', '동몽선습을 공부하는 서당 학동', '독서삼품과 시행을 준비하는 관리', '주자소에서 계미자를 주조하는 장인', 1, '초상화로 보는 한국사 - 이 그림은 소수 서원에 봉안되어 있는 인물의 초상화이다. 그는 충렬왕 때 원에 갔다가 주희의 저서를 들여오면서 성리학을 본격적으로 소개하였다. 그림의 상단에는 유학 진흥에 힘쓴 공을 인정하여 충숙왕이 그의 초상화를 문묘에 모시게 하였다는 발문이 있다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 16, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '비담과 염종의 반란을 진압하였다.', '만권당에서 원의 학자들과 교유하였다.', '인사 행정을 담당하던 정방을 폐지하였다.', '봉사 10조를 올려 시정 개혁을 건의하였다.', '오월(吳越)에 사신을 보내고 검교태보의 직을 받았다.', 4, '교외 체험 학습 보고서 - 날짜: 2026년 ??월 ??일. 장소: 인천광역시 강화 석릉. 학습 내용: 강화 석릉은 고려 희종의 무덤이다. 이의민을 제거하고 집권한 (가)이/가 스스로 교정별감이 되어 전횡을 일삼자, 희종은 그를 암살하려고 하였으나 도방의 방해로 실패하였다. 그 결과 희종은 이곳 강화도로 유배되었고 이후 여러 유배지를 전전하다 고종 24년에 생을 마감하였다고 한다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 17, '(가), (나) 인물에 대한 설명으로 옳은 것은?', 1, '(가) - 관군을 이끌고 묘청의 난을 진압하였다.', '(가) - 시무 28조를 올려 국가 운영 방안을 제시하였다.', '(나) - 법화 신앙을 바탕으로 백련 결사를 이끌었다.', '(나) - 화폐 발행을 위해 주전도감 설치를 건의하였다.', '(가), (나) - 심성 도야를 강조하고 유불 일치설을 주장하였다.', 1, '홀로그램으로 만나는 역사 인물 - 오늘은 한국 고대사 연구에 중요한 사료를 남긴 두 분의 이야기를 들어 보겠습니다. (가): 나는 삼국의 역사를 기전체로 정리한 삼국사기의 편찬을 총괄하였소. (나): 나는 불교 중심의 설화와 단군의 건국 이야기 등을 담은 삼국유사를 저술하였소.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 18, '다음 상황이 나타난 시기를 연표에서 옳게 고른 것은?', 1, '(가)', '(나)', '(다)', '(라)', '(마)', 5, '위화도에서 좌·우군도통사가 글을 올려 회군을 요청하니 최영이 말하기를, ''두 도통사가 있으니 스스로 와서 아뢰는 것이 옳다. 군사를 물리자는 말을 감히 내 입으로 하지 못하겠다.''라고 하였다. …… 원의 잔당들이 사막으로 도망가서 이름뿐인 나라를 세웠는데, 최영이 배후(裴厚)를 보내어 함께 돕기로 약속하고 요동을 협공하였다. 좌·우군도통사가 다시 사람을 보내어 최영에게 나아가 속히 회군을 허락해 달라고 요청하였으나 최영은 그럴 뜻이 없었다. - 『고려사』 - [연표] 강조의 정변(1009) - (가) - 이자겸의 난(1126) - (나) - 처인성 전투(1232) - (다) - 삼별초 항쟁 진압(1273) - (라) - 공민왕 즉위(1351) - (마) - 고려 멸망(1392)', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 19, '(가) 기구에 대한 설명으로 옳은 것은?', 2, '사헌부, 홍문관과 함께 3사로 불렸다.', '국왕 직속 사법 기구로 반역죄 등을 다루었다.', '사초와 시정기를 바탕으로 실록을 편찬하였다.', '왕의 비서 기관으로 왕명의 출납을 관장하였다.', '사대교린에 관한 문서를 관장하기 위해 설치되었다.', 1, '○ 문하부 좌우 정승을 고쳐 의정부 좌우 정승으로, 문하시랑 찬성사를 의정부 찬성사로, 참찬 문하부사를 참찬 의정부사로, 정당 문학을 의정부 문학으로 하였다. …… 문하부의 이름을 혁파하고, 낭사(?舍)를 고쳐 (가)(으)로 하였다. ○ (가)의 대사간 성현(成俔) 등이 상소하였다. ''신 등이 삼가 생각건대 신하를 다루는 도리는 간사하고 올바른 것을 분별하여 올바른 신하는 마땅히 가까이하고, 간사한 신하는 마땅히 멀리하는 것에 있습니다.''', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 20, '(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?', 3, '조의제문을 빌미로 무오사화가 일어났다.', '세계 지도인 혼일강리역대국도지도가 제작되었다.', '예악 질서의 확립을 위한 악학궤범이 완성되었다.', '역대 문물 제도를 정리한 동국문헌비고가 편찬되었다.', '현직 관리에게만 수조권을 지급하는 직전법이 시행되었다.', 3, '이달의 책 - 대불정수능엄경(언해). 이 책은 중국 승려 계환(戒環)의 『대불정수능엄경요해』에 (가)이/가 훈민정음으로 구결을 달고 한계희, 김수온 등이 번역하여 편찬한 것이다. 현재 활자본과 목판본이 전하는데, 그중 목판본은 (가)이/가 만든 간경도감에서 간행한 최초의 불경 언해서이다. 이는 이후 만들어지는 언해서 편찬 체계의 본보기가 된다는 점에서 의미가 있다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 21, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '기대승과 사단칠정 논쟁을 전개하였다.', '소학의 보급과 현량과 실시를 주장하였다.', '기축봉사를 올려 명에 대한 의리를 내세웠다.', '임진왜란의 상황 등을 담은 징비록을 저술하였다.', '최초로 100리 척을 사용하여 동국지도를 제작하였다.', 1, '이곳은 안동의 병산 서원으로, (가)의 위패가 봉안되어 있습니다. (가)은/는 훈련도감 설치를 건의하고 공납의 폐단을 시정하고자 대공수미법을 제안했습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 22, '다음 시나리오의 상황 이후에 전개된 사실로 옳은 것은?', 2, '강홍립 부대가 사르후 전투에 참전하였다.', '김종서가 두만강 일대에 6진을 개척하였다.', '김시민이 진주성 전투에서 크게 승리하였다.', '이종무가 왜구의 근거지인 쓰시마섬을 정벌하였다.', '이완이 어영대장으로 임명되어 북벌을 준비하였다.', 4, '#11. 남한산성 안 - 임금이 항복하라는 내용이 담긴 칸[汗]의 서신을 읽은 후 대신들에게 말한다. 임금: 앞으로 어떤 계책을 세워야 하겠는가? 김상헌: 지금 항복한다 하더라도 어떻게 그 노여움을 풀겠습니까. 끝내는 반드시 따르기 어려운 요청을 해 올 것입니다. 적의 글을 우리 군사들에게 널리 알려 사기를 높이는 것이 마땅하겠습니다. 최명길: 칸이 직접 출병한 이상 대적하기가 더욱 어려운데, 대적할 경우 반드시 망하고 말 것입니다. 임금: 성문과 성벽을 굳게 지키면서 속히 회답해야 할 것이다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 23, '밑줄 그은 ''시기''에 볼 수 있는 모습으로 적절하지 않은 것은?', 2, '계해약조의 초안을 작성하는 관리', '까치를 소재로 민화를 그리는 화원', '세책가에서 춘향전을 빌리는 부녀자', '시사(詩社)를 조직하여 활동하는 서리', '송파장에서 산대놀이를 공연하는 광대', 1, '변박 특별전 - 왜관도. 화면을 넘기면 다른 작품을 볼 수 있습니다. 이것은 변박이 그린 초량 왜관의 전경입니다. 이 그림에는 관수가(館守家)를 중심으로 서관과 동관 구역이 나뉘어 있고, 50여 개의 건물 명칭이 표기되어 있습니다. 이를 통해 초량 왜관에서 대일 무역이 이루어지던 시기 왜관의 구성과 규모를 확인할 수 있습니다.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 24, '(가) 왕이 추진한 정책으로 옳은 것은?', 3, '문신을 재교육하기 위한 초계문신제를 실시하였다.', '각 궁방과 중앙 관서의 공노비 6만여 명을 해방하였다.', '국왕의 호위와 수도 방어를 위해 금위영을 창설하였다.', '각지의 농법을 작물별로 정리한 농사직설을 편찬하였다.', '붕당 정치의 폐해를 경계하기 위해 탕평비를 건립하였다.', 3, '이십공신회맹축 - 보사공신녹훈후. [대화] 이 자료는 개국 공신부터 보사 공신까지의 공신과 그 자손들을 모아 결속을 다지는 회맹 행사를 거행한 후 그 명단 등을 담은 문서입니다. 보사 공신이란 경신환국의 공신들을 일컫는 말이지요? / 맞습니다. 특히 이 자료에는 그들이 기사환국과 갑술환국을 거치며 공신의 지위를 박탈당했다가 회복하는 정황이 반영되어 있어, (가) 재위 시기의 급변하는 정치적 상황을 파악하는 데 도움을 줍니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 25, '다음 자료에 나타난 시기의 경제 상황으로 옳은 것은?', 1, '관리에게 전지와 시지가 지급되었다.', '솔빈부의 말이 특산품으로 수출되었다.', '관청에 물품을 조달하는 공인이 활동하였다.', '당항성, 영암이 국제 무역항으로 번성하였다.', '삼한통보, 해동통보 등의 화폐가 발행되었다.', 3, '근래 듣건대, 도고라는 방식이 새로 나와 한 사람이 물품을 독차지하면서 다른 사람은 감히 개별적으로 살 수 없게 되었다고 합니다. …… 이른바, 이익은 한 사람에게로 돌아가고 피해는 만민이 받는다는 것입니다. …… 청컨대 한성부와 평시서로 하여금 엄히 금단하게 하여 도고를 없애고 다시 각자가 매매하게 하여 전처럼 생활할 수 있게 하소서.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 26, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '양명학을 연구하여 강화학파를 형성하였다.', '기기도설을 참고하여 거중기를 설계하였다.', '역대 명필을 연구하여 추사체를 창안하였다.', '규장각 검서관으로 무예도보통지 편찬에 참여하였다.', '지부복궐척화의소를 올려 왜양일체론을 주장하였다.', 4, '□□ 신문 - 『북학의』 친필 고본(稿本), 보물로 지정. 수원 화성 박물관에 소장된 (가) 고본 『북학의』가 보물로 지정되었다. 『북학의』는 (가)이/가 청의 연경에 다녀온 후 국가 제도와 정책 등 여러 분야에 대한 개혁의 필요성과 함께 실천 방안을 제시한 책이다. 이번에 보물로 지정된 『북학의』는 저자가 원고를 직접 쓰고 엮었다는 점, 박지원의 친필 서문이 함께 남아 있다는 점에서 그 가치를 인정받았다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 27, '(가) 지역에 대한 탐구 활동으로 가장 적절한 것은?', 1, '이괄이 반란을 일으킨 근거지를 알아본다.', '김정희가 세한도를 그린 유배지를 검색한다.', '정약전이 자산어보를 저술한 곳을 조사한다.', '강주룡이 고공 농성을 벌인 을밀대의 위치를 찾아본다.', '김윤후가 노비 등을 이끌고 몽골군을 격퇴한 장소를 파악한다.', 5, '고구려비를 품은 (가)의 역사를 걷다 - 일시: 2026년 ??월 ??일 16:00~20:00. 답사 경로: 탑평리 칠층 석탑(중앙탑) → 탄금대 → 임충민공 충렬사 → 미륵 대원지', '복합', '지역사', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 28, '다음 자료에 나타난 상황 이후의 사실로 옳은 것은?', 2, '홍경래 등이 봉기하여 정주성을 점령하였다.', '신돈이 중심이 되어 전민변정 사업을 운영하였다.', '삼정의 문란을 시정하고자 삼정이정청이 설치되었다.', '기금의 이자로 빈민을 구휼하는 제위보가 만들어졌다.', '황사영이 외국 군대의 출병을 요청하는 백서를 작성하였다.', 3, '진주 안핵사 박규수가 상소하였는데 대략 이르기를, ''난민들이 스스로 죄에 빠진 것은 반드시 이유가 있을 것입니다. …… 살을 베어 내고 뼈를 깎는 것 같은 고통은 환곡과 향곡이 으뜸입니다. 진주에서 허위로 부과한 세금에 대해서는 이미 조사 결과를 임금께 아뢰었습니다. …… 병들어 가는 것은 우리 백성들뿐입니다.''라고 하였다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 29, '다음 자료에 나타난 사건의 배경으로 가장 적절한 것은?', 2, '운요호가 강화도와 영종도를 공격하였다.', '오페르트가 남연군 묘 도굴을 시도하였다.', '교조 신원을 요구하는 보은 집회가 열렸다.', '병인박해로 천주교 신부와 신자들이 처형되었다.', '김홍집이 가지고 온 조선책략이 조선에 유포되었다.', 4, '적들이 성벽 아래에 당도하였다. 우리 군사들이 일제히 총을 쏘니, 그 소리가 천지를 진동하고 탄환이 빗발치듯 쏟아졌다. 적들은 우리의 매복을 전혀 예상치 못하다가, 갑자기 쏟아지는 탄환에 맞아 쓰러지는 자가 속출하였다. 적들은 더 이상 버티지 못하고 무너져 흩어졌다. 양헌수는 즉시 순무영에 승전보를 띄워 보냈다. ''오늘 적병이 정족산성을 침범하였으나 우리 군사가 일제히 사격하여 물리쳤습니다. 적들은 사상자를 이끌고 도주하였습니다.''', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 30, '밑줄 그은 ''이 개혁''의 내용으로 옳은 것은?', 3, '박문국을 두어 한성순보를 발행하였다.', '근대식 무기 제조 시설인 기기창을 설립하였다.', '군제를 개편하여 친위대와 진위대를 설치하였다.', '공사 노비법을 혁파하고 과부의 재가를 허용하였다.', '비변사를 혁파하여 의정부와 삼군부의 기능을 회복하였다.', 3, '이 자료는 조선 정부에서 발행한 관보 제214호이다. 관보의 내부(內部) 고시는 이 개혁에 따라 시행된 단발령을 알리는 내용으로, 국왕이 먼저 단발을 행하였으니 백성에게 이를 따르라고 하고 있다. 한편, 관보에 사용된 연호인 건양은 국모 시해 사건 이후 추진된 이 개혁의 일환으로 태양력이 도입되면서 새로 정한 것이다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 31, '(가) 사건에 대한 설명으로 옳은 것은?', 2, '김옥균 등 개화파가 주도하였다.', '제물포 조약이 체결되는 계기가 되었다.', '전개 과정에서 홍범 14조가 반포되었다.', '통리기무아문이 설치되는 배경이 되었다.', '외규장각 도서가 약탈되는 결과를 가져왔다.', 2, '이 사진은 퍼시벌 로웰이 찍은 묄렌도르프의 집입니다. 본래 선혜청 당상 민겸호의 집이었으나, 그가 (가) 때 피살되자 고종이 묄렌도르프에게 하사한 것입니다. (가)을/를 진압한 청의 추천을 받아 조선의 외교 고문으로 부임한 묄렌도르프는 이 집을 서양식으로 개축하여 사용하였습니다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 32, '밑줄 그은 ''이 지역''에서 전개된 민족 운동에 대한 설명으로 옳은 것은?', 1, '한인 자치 기구인 경학사를 조직하였다.', '한인 교육을 위해 박달 학원을 설립하였다.', '무장 투쟁을 위해 대조선 국민 군단을 결성하였다.', '유학생을 중심으로 2·8 독립 선언서를 발표하였다.', '대한 광복군 정부를 중심으로 무장 독립 투쟁을 준비하였다.', 5, '포와유람기는 현순이 이 지역의 호놀룰루 등에서 체류한 경험을 바탕으로 쓴 견문록입니다. 이 책에는 20세기 초 사탕수수 농장에 도착한 초기 한인 이민자들의 생활 모습이 잘 나타나 있으며, 포와(布?)라고 불렸던 이 지역의 지리, 역사, 문화 등이 기록되어 있습니다.', '근대', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 33, '다음 자료에 나타난 조약에 대한 설명으로 옳은 것은?', 1, '청의 알선으로 체결이 추진되었다.', '통감부가 설치되는 결과를 가져왔다.', '천주교 포교를 허용하는 근거가 되었다.', '스티븐스가 외교 고문으로 부임하는 계기가 되었다.', '대한 제국 군대의 해산을 규정하는 내용이 포함되어 있다.', 2, '한국사 교실 - 수행 과제: 오늘 학습한 조약과 관련된 자료를 조사하여 사진과 설명을 올려 주세요. ○○○ 중명전: 대한 제국 시기 황실 도서관 등으로 이용되었던 곳으로 조약이 강제로 체결된 장소임. □□□ 민영환: 일제의 강요로 조약이 체결되자 이에 항거하는 뜻으로 유서를 남기고 자결함. △△△ 자신회: 나철, 오기호 등이 조약에 찬성한 다섯 명의 대신들을 처단하기 위해 조직함.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 34, '(가) 단체에 대한 설명으로 옳은 것은?', 1, '만세보를 발행하였다.', '대성 학교를 설립하였다.', '만민 공동회를 개최하였다.', '부민관 폭파 의거를 계획하였다.', '일제의 황무지 개간권 요구를 저지하였다.', 2, '특별 전시 - 국외 독립운동의 숨은 주역, 안태국을 기억하다. 우리 기념관에서는 (가)에서 운영한 태극 서관의 주임 등을 맡았던 안태국의 공훈을 기리는 특별전을 마련하였습니다. 그는 안창호, 양기탁 등을 중심으로 비밀리에 결성된 (가)에서 국외 독립군 기지 건설을 위해 군자금 모금과 이주민 모집 등에 힘썼습니다. 그의 활동을 알 수 있는 자료들을 준비하였으니 많은 관심 바랍니다. 기간: 2026년 ??월 ??일 ~??월 ??일. 장소: △△ 기념관 특별 전시실. 전시 자료: 안태국 장례식 사진 등 ??점', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 35, '밑줄 그은 ''이 학교''에 대한 설명으로 옳은 것은?', 3, '7재라는 전문 강좌가 있었다.', '덕원부 관민이 합심하여 만들었다.', '교육입국 조서에 근거하여 세워졌다.', '주요 건물로 대성전과 명륜당을 두었다.', '좌원과 우원을 구분하여 학생을 선발하였다.', 4, '주제: 근대 교육의 도입 - 사민필지는 미국인 헐버트가 이 학교의 교사 시절 한글로 지은 세계 지리서입니다. / 영어, 산학, 지리 등을 주요 과목으로 개설한 이 학교에서 사용했던 교과서입니다.', '근대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 36, '밑줄 그은 ''이 단체''에 대한 설명으로 옳은 것은?', 2, '고종의 강제 퇴위에 반대하는 시위를 주도하였다.', '조선 총독부에 국권 반환 요구서를 제출하려 하였다.', '독립운동 자금 마련을 위해 독립 공채를 발행하였다.', '신채호가 쓴 조선 혁명 선언을 활동 지침으로 삼았다.', '신규식을 중심으로 조직되어 교민들의 단결을 도모하였다.', 4, '이 자료는 나석주 의사가 조선 식산 은행과 동양 척식 주식회사에 폭탄을 던진 사건을 다룬 기사입니다. 이에 대해 설명해 주세요. / 나석주 의사는 일제의 기관 파괴와 요인 암살 등을 목적으로 조직된 이 단체의 단원으로 활동했습니다. 그는 경제 수탈의 상징인 두 기관에 폭탄을 투척하여 일제에 큰 충격을 주었습니다. 기사에는 당시 의거의 현장을 보여주는 사진과 사상자 명단 등이 담겨 있습니다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 37, '밑줄 그은 ''이 정책''이 실시된 시기에 볼 수 있는 모습으로 가장 적절한 것은?', 1, '태형을 집행하는 헌병 경찰', '원수부에서 업무를 처리하는 관리', '몸뻬 착용을 홍보하는 애국반 반장', '경인선 개통식에 참석하는 일본인 거류민', '나운규가 감독한 아리랑의 첫 상영을 준비하는 단성사 직원', 1, '사진과 함께하는 역사 - 임시 토지 조사국. 이 사진은 임시 토지 조사국 청사입니다. 임시 토지 조사국은 일제가 식민 지배를 위한 경제적 기반 마련 등을 목적으로 이 정책을 추진하면서 설치한 기구입니다. 이 기구는 토지의 조사 및 측량, 지적도와 토지 대장 작성 등을 수행하였습니다.', '일제강점기', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 38, '(가) 단체의 활동으로 옳은 것은?', 2, '개벽, 신여성 등의 잡지를 발행하였다.', '중추원 개편을 통해 의회 설립을 추진하였다.', '군사 조직으로 한인 국방 경위대를 창설하였다.', '순종의 인산일을 기회로 만세 운동을 계획하였다.', '광주 학생 항일 운동에 진상 조사단을 파견하였다.', 5, '조선인 운동은 민족 운동으로 또는 사회 운동으로 표면과 이면에서 그침 없이 계속하여 오다가, 조선 민족의 총역량을 집중하여 민족 단일당 결성을 촉진하며 (가)이/가 조직되었다. 각도 각지에서는 지회가 속속 설치되었다. …… (가)은/는 민중 대회를 준비하다가 발각되어 타격을 입은 이후 해소라는 새 기록을 남기고 5년간 걸어 온 자취를 청산하는 동시에 새로운 방향으로 걸음을 전환하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 39, '교사의 질문에 대한 학생의 답변으로 가장 적절한 것은?', 2, '조선 민립 대학 기성회가 조직되었어요.', '메가타의 주도로 화폐 정리 사업이 시행되었어요.', '귀속 재산 관리를 위해 신한 공사가 운영되었어요.', '회사 설립을 허가제로 하는 회사령이 공포되었어요.', '농민의 자력갱생을 내세운 농촌 진흥 운동이 추진되었어요.', 5, '이 기사는 일제의 정책으로 인해 피해를 입은 농촌의 모습을 다루고 있습니다. 대공황 이후 일제는 공업 원료 등을 확보하기 위해 한반도 남부 지방에 면화 재배를 확대하는 정책을 추진하였습니다. 이 정책이 시행된 시기에 있었던 사실을 말해볼까요? [신문 기사] 일제의 강압적 면화 재배 장려에 경주의 농민 수백 명이 궐기함. / 일제가 강제하여 경작한 면화 밭이 해충으로 피해를 입자 경북 농가의 민심이 악화함.', '일제강점기', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 40, '(가)에 들어갈 내용으로 옳은 것은?', 3, '김민기, 아침 이슬', '윤심덕, 사의 찬미', '현인, 굳세어라 금순아', '코리아나, 손에 손 잡고', '이해연, 단장의 미아리 고개', 2, '공연 초대장 - 대중가요의 역사를 찾아서. 일제 강점기는 라디오와 축음기가 보급되면서 대중가요가 확산된 시기였습니다. 우리 오케스트라에서는 당시 발매되었던 대중가요를 관현악으로 편곡한 공연을 준비하였습니다. 식민지 시기를 살아간 우리 민족의 다양한 감정을 느낄 수 있는 자리에 여러분을 초대합니다. 공연 작품: 이애리수, 황성옛터 - 고려의 옛 궁터 만월대의 텅 빈 밤과 서정 / (가) - 비극적인 삶으로 빚어낸 염세와 허무 / 고복수, 타향살이 - 고향을 떠나 살게 된 이들의 짙은 향수 / 이난영, 목포의 눈물 - 항구를 배경으로 그리는 이별과 눈물의 정서. 일시: 2026년 ??월 ??일 19:00. 장소: △△ 문화 예술 회관. 출연: ?? 오케스트라', '일제강점기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 41, '밑줄 그은 ''이 부대''에 대한 설명으로 옳은 것은?', 2, '흥경성 전투에서 일본군을 격퇴하였다.', '일본군의 공세를 피해 자유시로 이동하였다.', '이른바 남한 대토벌 작전으로 큰 피해를 입었다.', '영국군의 요청으로 인도·미얀마 전선에 파견되었다.', '한국인 유격대를 중심으로 조국 광복회를 조직하였다.', 1, '국민부는 중국의 반일 단체와 연락을 취하여 대규모 항일 행동을 계획하였지만, 각지의 일본 경관대에게 단원이 검거되고 무기를 압수당하여 세력이 꺾였다. 그러나 당시 이를 피한 양세봉, 양하산 등 주요 인물이 흩어졌던 단원을 모아 국민부 산하의 무장 단체를 재편하여 행동을 재개하였다. 총사령관 양세봉의 지휘 아래 이 부대는 대도회 등과 함께 한중 연합군을 편성하여 소양구에 이어 영릉가를 점령하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 42, '(가)에 들어갈 내용으로 옳은 것은?', 2, '흥사단을 창립함.', '이토 히로부미를 사살함.', '한국독립운동지혈사를 저술함.', '한국 독립군의 총사령관으로 활약함.', '김원봉 등과 함께 민족 혁명당을 결성함.', 2, '어느 독립운동가의 주요 행적 [1~4는 시간 순] 1 상하이: 주권이 국민에게 있음을 밝힌 대동단결 선언 작성에 참여함. 2 항저우: 윤봉길의 상하이 훙커우 공원 의거 이후 일제의 탄압을 피해 머무름. 3 난징: (가) 4 충칭: 삼균주의에 바탕을 둔 대한민국 임시 정부 건국 강령 초안을 작성함.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 43, '(가)에 들어갈 내용으로 가장 적절한 것은?', 2, '제헌절 - 첫 헌법 제정의 의미를 강조하다', '가갸날 - 우리 말과 글의 소중함을 되새기다', '향토 예비군의 날 - 범국민적인 안보의식을 조성하다', '은사의 날 - 스승을 향한 감사와 공경의 마음을 전하다', '이산가족의 날 - 이산가족 문제에 대한 관심을 제고하다', 2, '한국사 교양 강좌 - 기념일에 담긴 일제 강점기 사회·문화. 우리 학회에서는 일제 강점기의 힘든 현실 속에서도 우리 민족이 기리기 시작한 기념일을 중심으로 당시의 사회와 문화를 살펴보는 강연을 마련하였습니다. 많은 관심과 참여 바랍니다. [제1강] 어린이날 - 어린이에게서 민족의 미래를 보다 [제2강] 메이데이 - 고등 경찰의 경계 속에 첫 노동절 행사가 열리다 [제3강] 과학 데이 - 과학의 대중화를 촉진하다 [제4강] (가). 일시: 2026년 ??월 ??일 10:00~16:00. 장소: ?? 학회 소회의실', '일제강점기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 44, '밑줄 그은 ''시기''에 볼 수 있는 모습으로 가장 적절한 것은?', 1, '원산 총파업에 동참하는 노동자', '국채 보상 운동에 성금을 내는 상인', '원각사에서 연극 은세계를 공연하는 배우', '황국 신민 서사를 암송하는 국민학교 학생', '조선 형평사 창립 대회 현장을 취재하는 기자', 1, '이곳은 인천 부평에 위치한 일본 육군 조병창입니다. 일제가 국가 총동원법을 시행한 시기에 전쟁 무기 생산을 목적으로 설치되었습니다. 또한 학도 동원 실시 요강에 따라 학생들이 강제로 동원된 곳이기도 했습니다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 45, '다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?', 2, '농지 개혁의 전개 과정을 알아본다.', '광주 대단지 사건의 결과를 파악한다.', '개발 제한 구역 설정의 목적을 찾아본다.', '산미 증식 계획의 추진 배경을 분석한다.', '지계아문이 추진한 정책의 내용을 조사한다.', 1, '농민이나 지주나 간에 중대한 위기에 봉착하고 있다. 농민은 평년 수확의 절반가량을 세금 등으로 납부하게 됨으로써 자가에서 소비할 식량도 확보할 수 없는 지경으로 우선 굶어 죽을 수는 없으니 상환을 연기하든지 분배를 취소하여 달라고 호소하고 있다. 지주 측에서는 토지 자본을 산업 자본으로 활용하기는커녕 정조(正租) 1석당 5만 8천여 원이라는 엄청난 헐값으로 환산된 지가 증권마저 액면의 5할 또는 4할이라는 시세로 매각하거나, 전년도에 받아야 할 상환금을 다음 해가 되어도 다 받지 못하고 한 달에 60만 원씩 지불받기로 한 것마저 받지 못하고 있다.', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 46, '(가) 인물에 대한 설명으로 옳은 것은?', 2, '광복에 대비하여 조선 건국 동맹을 결성하였다.', '대한민국 임시 정부 초대 국무총리를 역임하였다.', '정읍에서 남한만의 단독 정부 수립을 주장하였다.', '헤이그에서 열린 만국 평화 회의에 특사로 파견되었다.', '민족을 역사 서술의 중심에 둔 독사신론을 발표하였다.', 1, '이 자료는 미소 공동 위원회 미국 대표단 정치고문단 소속인 L. M. 버치 중위가 좌우 합작을 주도한 (가)을/를 추모하며 남긴 연설문입니다. 엔도 정무총감과의 회담에서 사회 안정에 관한 요구 사항을 관철하는 등 해방 정국을 주도하던 (가)이/가 암살되자, 버치 중위는 존경의 의미를 담아 한국어 발음을 알파벳으로 표기한 연설문을 작성하였습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 47, '(가) 정부 시기에 있었던 사실로 옳은 것은?', 3, '최저 임금 위원회가 설치되었다.', '포항 제철소 1기 설비가 준공되었다.', '전국 민주 노동조합 총연맹이 창립되었다.', '칠레와의 자유 무역 협정(FTA)이 체결되었다.', '경제 협력 개발 기구(OECD) 회원국이 되었다.', 2, '이것은 (가) 정부가 작성한 행정 수도 건설 계획의 일부입니다. 수출 100억 달러를 처음으로 달성하는 등 경제 성장을 이룬 (가) 정부는 수도권 인구 과밀화 억제 등을 내세우며 행정 수도의 건설 계획을 발표했습니다. 당시 충남 공주시 장기면을 중심으로 연기군 일부까지 건설 대상 지역에 포함되어 있는 것을 확인할 수 있습니다.', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 48, '다음 대화에 나타난 사건 이후에 전개된 사실로 옳은 것은?', 2, '애치슨 라인이 발표되었다.', '부마 민주 항쟁이 일어났다.', '사사오입의 논리로 개헌안이 통과되었다.', '반민족 행위 특별 조사 위원회가 해체되었다.', '민의원, 참의원으로 구성된 양원제 국회가 탄생하였다.', 2, '김영삼 신민당 총재가 국회의원 최초로 제명된 사건이 있었네요. / 김영삼이 뉴욕 타임스와 인터뷰한 내용이 문제가 되었습니다. / 또한 신민당사에서 농성하던 YH 무역 노동자들을 강제로 진압한 것도 이유였습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 49, '밑줄 그은 ''이 정부'' 시기에 있었던 사실로 옳은 것은?', 2, '헝가리에 상주 대표부가 설치되었다.', '박종철 고문 치사 사건이 발생하였다.', '평화 통일을 주장한 조봉암이 처형되었다.', '대통령 긴급 명령으로 금융 실명제가 실시되었다.', '서울역에서 청량리역 간에 서울 지하철 1호선이 개통되었다.', 2, '보도 지침 - ◎ 대학생들, 주한 미상공회의소 점거. 오후 1시 8분에 경찰에 모두 연행 기사 ① 사회면 톱기사로 쓰지 말 것. ② 사진 쓰지 않도록. ◎ 기사 제목에 ''호헌'', ''개헌''이란 말은 일체 쓰지 말 것. ◎ NCC 고문대책위 구성, 보도하지 말 것. [대화] 오늘도 보도 지침이 내려왔군. 이 정부의 언론 통제는 언제까지 계속되려나.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (77, 50, '(가)~(마)에 해당하는 왕에 대한 설명으로 옳은 것은?', 2, '(가) - 서안평을 공격하여 영토를 확대하였다.', '(나) - 소지 마립간과 혼인 동맹을 맺었다.', '(다) - 국호를 남부여라 칭하였다.', '(라) - 쌍성총관부를 수복하였다.', '(마) - 경국대전을 완성하였다.', 3, '이달의 역사 용어 - 천도(遷都). 천도란 국가의 ''수도''를 다른 지역으로 옮기는 것을 뜻한다. 우리 역사에서 대표적인 천도 사례는 다음과 같다. 고구려는 427년 (가)이/가 평양으로 수도를 옮겼다. 백제는 475년 한성이 함락되자 같은 해에 (나)이/가 웅진으로 천도하였고, 538년 (다)은/는 사비로 천도하였다. 한편, 신라는 통일 후 달구벌로 천도를 계획하였으나 실행하지 못하였다. 발해는 중경 현덕부, 상경 용천부 등지로 여러 차례 천도하였다. 고려는 몽골이 침입하자 1232년 최우의 건의로 (라)이/가 강화도로 천도하여 대몽 항쟁을 벌이다가 1270년 원종 때 개경으로 환도하였다. 조선은 1394년 (마)이/가 한양으로 천도를 단행하였다. 한양은 왕자의 난 이후 개성을 수도로 삼았던 수년을 제외하고, 500여 년간 조선 왕조의 수도였다.', '복합', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 1, '(가) 시대의 생활 모습으로 가장 적절한 것은?', 1, '청동 방울 등을 의례 도구로 이용하였다.', '주먹도끼 등 뗀석기를 만들기 시작하였다.', '거푸집을 사용하여 세형 동검을 제작하였다.', '쟁기, 쇠스랑 등의 철제 농기구를 사용하였다.', '가락바퀴와 뼈바늘을 이용하여 옷을 만들었다.', 5, '오늘 소개할 곳은 여수 안도 조개더미 유적입니다. 이 유적에서는 농경과 목축이 시작된 (가) 시대의 인골과 조개팔찌 등이 출토되어 당시의 매장 풍습을 확인할 수 있습니다. 또한 이 유적에서 출토된 덧무늬 토기, 눌러찍은 무늬 토기 등을 통해 (가) 시대에는 빗살무늬 토기 이외에도 다양한 토기가 사용되었음을 알 수 있습니다. [현장으로 떠나는 역사 여행]', '선사', '생활·문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 2, '(가)~(다) 학생이 발표한 내용을 일어난 순서대로 옳게 나열한 것은?', 3, '(가) - (나) - (다)', '(가) - (다) - (나)', '(나) - (가) - (다)', '(나) - (다) - (가)', '(다) - (가) - (나)', 2, '<한국사 주제 발표> 고조선의 성장과 변천 - (가) 연의 장수 진개가 고조선을 침략하였어요. (나) 우거왕이 한 무제가 파견한 군대에 맞서 싸웠어요. (다) 위만이 진번과 임둔을 복속시키고 세력을 확장하였어요.', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 3, '(가), (나) 나라에 대한 설명으로 옳은 것은?', 2, '(가) - 신성 지역인 소도가 있었다.', '(가) - 혼인 풍습으로 민며느리제가 있었다.', '(나) - 위화부, 영객부 등의 관청이 있었다.', '(나) - 왕 아래 상가, 대로, 패자 등의 관직이 있었다.', '(가), (나) - 읍락 간의 경계를 중시하는 책화가 있었다.', 1, '(가) 해마다 5월이면 씨뿌리기를 마치고 귀신에게 제사를 지낸다. 떼를 지어 모여서 노래와 춤을 즐기며 술 마시고 노는 것을 밤낮으로 쉬지 않는다. …… 귀신을 믿기 때문에 국읍에 각각 한 사람씩을 세워서 천신에 대한 제사를 주관하니, 이를 천군이라 부른다. -『삼국지』 위서 동이전- (나) 은력(殷曆) 정월에 하늘에 제사를 지내는 국중대회에서는 날마다 마시고 먹고 노래하고 춤추는데, 이를 영고라 한다. 이때에는 형옥(刑獄)을 중단하고 죄수를 풀어 준다. -『삼국지』 위서 동이전-', '선사', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 4, '밑줄 그은 ''왕''에 대한 설명으로 옳은 것은?', 3, '수도를 웅진으로 옮겼다.', '백가의 난을 평정하였다.', '금마저에 미륵사를 창건하였다.', '고흥에게 서기를 편찬하게 하였다.', '달기를 보내 고구려의 도살성을 점령하였다.', 5, '우리 군이 관산성을 공격하여 김무력이 이끄는 신라군과 전투를 벌였다는데, 어찌 되었는지 아는가? / 왕께서 몸소 보병과 기병을 거느리고 구천에 이르렀는데, 신라군의 기습을 받아 돌아가셨다네. 결국 우리 군이 크게 패했다는군.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 5, '(가) 국가에 대한 설명으로 옳은 것은?', 2, '지방의 22담로에 왕족을 파견하였다.', '태학과 경당을 두어 인재를 양성하였다.', '10월에 무천이라는 제천 행사를 개최하였다.', '사회 질서를 유지하기 위해 범금 8조를 만들었다.', '물시계인 누각을 만들고 누각박사를 두어 시간을 측정하였다.', 2, '이것은 (가)의 쌍영총 벽화 속 공양 행렬을 모사한 것입니다. 승려를 앞세워 공양에 나서고 있는 귀족 부인의 모습에서 전진의 승려 순도를 통해 불교가 수용된 이후 (가)의 귀족 사회에 불교가 확산되었음을 확인할 수 있습니다.', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 6, '밑줄 그은 ''이 국가''의 사회 모습으로 가장 적절한 것은?', 2, '서옥제라는 혼인 풍습이 있었다.', '수도에 서시와 남시를 설치하였다.', '골품에 따라 관직 승진을 제한하였다.', '6좌평 아래에 달솔 등의 관등이 있었다.', '을파소를 등용하고 진대법을 시행하였다.', 4, '이 목간은 이 국가의 마지막 수도였던 부여의 쌍북리 유적에서 출토된 좌관대식기입니다. 관청에서 곡식을 빌리고 갚은 사람들의 이름과 곡식의 양이 기록되어 있어 당시 사람들의 생활 모습을 엿볼 수 있습니다. [목간 내용] 貸食記 - 곡식을 빌려준 기록 / 習利一石五斗上一石未一[石] - 습리가 1석 5두를 빌려 1석은 갚고 1[석]은 미납', '고대', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 7, '다음 상황 이후에 있었던 사실로 옳은 것은?', 1, '진흥왕이 대가야를 병합하였다.', '이사부가 우산국을 복속시켰다.', '을지문덕이 살수에서 대승을 거두었다.', '계백이 이끄는 군대가 황산벌에서 항전하였다.', '광개토 대왕이 신라에 침입한 왜를 격퇴하였다.', 4, '겨울에 왕이 장차 백제를 쳐서 대야성에서의 싸움을 되갚으려고 이찬 김춘추를 고구려에 보내서 군사를 청하였다. 대야성 전투에서 패하였을 때 도독인 품석의 아내도 죽었는데, 바로 춘추의 딸이었다. 춘추가 이를 듣고 기둥에 기대어 서서 하루 종일 눈도 깜박이지 않았고, 사람이나 물건이 그 앞을 지나가도 알아채지 못하였다. 이윽고 말하기를, ''아! 대장부가 되어 어찌 백제를 삼키지 못하겠는가?''라고 하고는 곧 왕에게 나아가 말하기를, ''신이 고구려에 사신으로 가서 군사를 청하여 백제에 원수를 갚고자 합니다.''라고 하자 왕이 허락하였다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 8, '밑줄 그은 ''시기''에 있었던 사실로 옳은 것은?', 2, '비담과 염종의 난이 진압되었다.', '김흠돌이 반란을 꾀하다 처형되었다.', '김헌창이 웅천주에서 반란을 일으켰다.', '원광이 왕명으로 걸사표를 작성하였다.', '이차돈의 순교를 계기로 불교가 공인되었다.', 3, '저는 경주 흥덕왕릉에 와 있습니다. 흥덕왕은 헌공왕 파살 이후 왕위 쟁탈전이 거듭되던 시기에 즉위하여 정국을 안정시키는 데 힘썼습니다. 하지만 그의 사후 또다시 진골 귀족들의 왕위 다툼이 반복되면서 혼란이 가중되었습니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 9, '(가) 국가의 문화유산으로 옳은 것은?', 2, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 3, '오늘 소개해 주실 문화유산은 무엇인가요? / 이것은 중국 지린성 룽터우산 고분군에서 출토된 (가)의 효의황후와 순목황후의 묘지(墓誌)입니다. 묘지에는 각각 보력과 건흥이라는 문양 대와 선왕 대의 독자적인 연호가 기록되어 있고, 황후라는 글자가 새겨져 있어 (가)이/가 황제국의 제도를 운용하였음을 알 수 있습니다. [사진: 효의황후 묘지, 순목황후 묘지]', '고대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 10, '밑줄 그은 ''이 전투'' 이후에 전개된 사실로 옳은 것은?', 2, '각간 대공이 반란을 일으켰다.', '안승이 보덕국왕으로 임명되었다.', '궁예가 국호를 태봉으로 바꾸었다.', '김선평, 권행 등이 고창 전투에서 활약하였다.', '대조영이 천문령에서 당의 군대를 격파하였다.', 4, '이 그림은 우리 역사 속 충신, 효자, 열녀 등의 이야기가 담긴 동국신속삼강행실도에 수록되어 있습니다. 여기에는 후삼국 통일 과정에서 벌어진 이 전투 당시 위기에 빠진 왕건을 구하기 위해 싸우다가 전사한 장절공 신숭겸이 그려져 있습니다.', '고대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 11, '(가) 왕에 대한 설명으로 옳은 것은?', 2, '외침에 대비하여 광군사를 창설하였다.', '12목을 설치하고 지방관을 파견하였다.', '관학 진흥을 위해 양현고를 설치하였다.', '노비안검법을 실시하여 호족 세력을 견제하였다.', '정계와 계백료서를 지어 관리의 규범을 제시하였다.', 4, '삼국 이전에는 아직 과거(科擧)의 법이 없었고, 고려의 태조는 먼저 학교를 세웠으나 과거로 인재를 뽑기에는 겨를이 없었다. (가)이/가 쌍기의 의견을 받아들여 과거로써 관리를 선발하였다. 이로부터 문풍(文風)이 비로소 일어났다. …… 과거에는 제술·명경 두 업(業)과 의업·복업·지리업·율업 등의 잡업이 있었다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 12, '(가)에 들어갈 내용으로 가장 적절한 것은?', 1, '덕대의 전문적인 광산 경영', '고추, 담배 등 상품 작물 재배', '벽란도를 통한 국제 무역의 양상', '덩이쇠 수출을 통해 본 낙랑과의 교역', '청해진을 거점으로 한 동아시아 해상 무역', 3, '탐구 활동 계획서 - ?학년 ?반 이름: △△△. 1. 주제: ?? 시대의 경제 활동. 2. 방법: 문헌 조사, 인터넷 검색 등. 3. 내용: - 사원 수공업의 발달 / - 해동통보의 주조와 발행 / - 다점, 주점 등 관영 상점의 운영 / - (가)', '고려', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 13, '(가)에 대한 고려의 대응으로 옳은 것은?', 1, '강화도로 도읍을 옮겨 항전하였다.', '박위가 적의 근거지를 토벌하였다.', '양규가 곽주성을 급습하여 탈환하였다.', '송문주가 죽주성에서 적군을 격퇴하였다.', '동북 9성을 축조하고 경계를 알리는 비석을 건립하였다.', 5, '(가)이/가 승세를 타고 정주의 선덕관성에 난입하여 죽이고 노략질한 것이 셀 수 없었다. 다시 윤관을 보내 임간을 대신하여 치게 하였는데, 또 패배하니 군의 기세가 진작되지 않았다. …… 숙종이 노하여 천지신명에게 고하고 신령의 도움을 빌려 적경(賊境)을 소탕할 것을 빌었다. 마침내 병사들을 훈련하고 군량을 비축하여 재반격을 도모하였다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 14, '(가) 국가의 문화유산으로 옳은 것은?', 2, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 3, '(가) 시대의 인쇄술, 메타버스 전시관 - 이것은 청주 흥덕사에서 간행된 직지심체요절입니다. 백운 화상이 부처와 여러 고승의 가르침에서 중요한 내용을 뽑아 편찬한 책으로, 현존하는 금속 활자 인쇄본 중 가장 오래된 것입니다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 15, '밑줄 그은 ''이 국가''에서 볼 수 있는 모습으로 가장 적절한 것은?', 2, '주자감에서 공부하는 학생', '구황촬요를 읽고 있는 지방관', '시장을 감독하는 동시전의 관리', '제위보에서 곡식을 지급받는 농민', '세책가에서 춘향전을 빌리는 부녀자', 4, '오늘 수업 시간에 배운 이 국가의 지방 행정 제도에 대해 말해 볼까요? / 5도와 양계를 두어 지방을 통치하였어요. / 지방관이 파견된 주현과 파견되지 않은 속현이 있었어요. / 향·부곡·소라고 불리는 특수 행정 구역이 존재하였어요.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 16, '밑줄 그은 ''임금''의 재위 시기에 있었던 사실로 옳은 것은?', 2, '배중손이 진도 용장성에서 항전하였다.', '최영이 홍산 전투에서 큰 승리를 거두었다.', '유인우, 이자춘 등이 쌍성총관부를 수복하였다.', '김방경이 이끄는 군대가 일본 원정에 참여하였다.', '만적이 개경에서 노비를 모아 반란을 모의하였다.', 3, '역적 기철이 노책·권겸과 함께 반역을 꾸며 나라의 화근이 되었습니다. 기철 등은 황후의 인척으로 상국(上國)의 위엄을 빌려서 하늘에 닿을 듯한 기세를 얻어 임금을 위협하고 억제하였습니다. …… 또한 일당 몇 명을 시켜 상국의 사신이라 속이고 조서를 가지고 있다고 사칭하면서 궁궐까지 도달하여 장차 임금과 신하들을 몰살시킴으로써 자신의 욕심을 채우려 하니, …… 역적들을 체포한 뒤, 또 다른 변란이 일어날 것을 우려하여 [황제께] 미처 보고드릴 겨를도 없이 법에 따라 그 모두를 처단하였습니다.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 17, '밑줄 그은 ''인물''의 활동으로 옳은 것은?', 2, '불교 설화를 중심으로 삼국유사를 지었다.', '법화 신앙을 바탕으로 백련 결사를 이끌었다.', '선문염송집을 편찬하고 유불 일치설을 주장하였다.', '보현십원가를 지어 불교 교리를 대중에게 전파하였다.', '이론과 수행을 함께 강조하는 교관겸수를 제시하였다.', 5, '한국사 대화형 인공 지능 - Q: 그림 속 인물에 대해 알려 주세요. A: 문종의 넷째 아들로 11세에 출가한 고려의 승려입니다. 시호는 대각국사입니다. Q: 그의 대표적인 활동에 대해 알려 주세요. A: 해동 천태종을 창시하여 교종을 중심으로 선종을 통합하려 하였습니다. 또한 송, 거란 등에서 수집한 불교 서적을 정리하여 교장(敎藏)을 간행하였습니다.', '고려', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 18, '(가), (나) 인물에 대한 설명으로 옳은 것은?', 2, '(가) - 시무 28조를 국왕에게 올렸다.', '(가) - 화통도감의 설치를 건의하였다.', '(나) - 정변을 일으켜 목종을 폐위하였다.', '(나) - 칭제 건원과 금국 정벌을 주장하였다.', '(가), (나) - 교정별감이 되어 국정을 장악하였다.', 4, '한국사 탐구 보고서 - ?학년 ?반 이름: △△△. 주제: 인물로 본 문벌 사회의 동요. 방법: 문헌 조사, 데이터베이스 활용. 탐구 내용 - 인물명 인물 소개 관련 사건: (가) 인종과 중첩된 혼인 관계를 맺어 권력을 강화한 외척 / 척준경과 함께 난을 일으키고, 왕의 거처를 남궁으로 옮김. (나) 풍수지리설을 내세워 천도를 주장한 승려 / 서경에서 반란을 일으키고 연호를 천개로 하는 대위국을 선포함. 정중부 이의방을 제거하고 최고 권력자에 등극한 무신 / 보현원에서 정변을 주도하고 왕을 폐위시킴.', '고려', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 19, '(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?', 3, '이징옥이 함길도에서 반란을 일으켰다.', '이괄이 난을 일으켜 한양을 점령하였다.', '허적과 윤휴 등 남인이 대거 축출되었다.', '위훈 삭제를 주장한 조광조 일파가 제거되었다.', '정여립 모반 사건을 계기로 기축옥사가 발생하였다.', 1, '이곳은 영주시 순흥면에 있는 금성대군 신단입니다. 금성대군은 사육신과 함께 (가)의 복위를 추진한 혐의로 순흥에 유배되었고, 이듬해 다시 지역 유생과 (가)의 복위를 모의하다가 발각되어 죽임을 당하였습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 20, '(가) 기구에 대한 설명으로 옳은 것은?', 3, '수도의 행정과 치안을 담당하였다.', '천문, 지리, 기후 등에 관한 사무를 맡았다.', '제학, 직제학 등의 관직 외에 검서관이 있었다.', '왕에게 경서 등을 강론하는 경연을 주관하였다.', '국왕 직속 사법 기구로 반역죄, 강상죄 등을 다루었다.', 5, '이 그림은 (가) 소속 관리들의 모임인 금오계를 기록한 첩(帖)의 일부입니다. 조옥(詔獄) 또는 금오(金吾)라고도 불린 (가)의 신입 도사들은 금오계첩을 제작하고 면신례를 치른 후 선배 도사들과 나누어 가졌습니다. [금오계첩]', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 21, '밑줄 그은 ''그''에 대한 설명으로 옳은 것은?', 3, '훈민정음 해례본 편찬에 참여하였다.', '최초의 서원인 백운동 서원을 건립하였다.', '기축봉사를 올려 명에 대한 의리를 내세웠다.', '해주 향약을 시행하여 향촌 교화를 위해 노력하였다.', '가례집람을 지어 예학을 조선의 현실에 맞게 정리하였다.', 1, '그가 중대한 일을 처리하고 대의(大義)를 결단함은 마치 강이 흘러가는 것과 같아서 조야(朝野)가 의지하고 중히 여겼다. 오랫동안 예조를 관장하여 사대교린을 자신의 소임으로 삼았다. …… 그는 직접 일본에 건너가 무릇 산천·관제·풍속 등을 두루 알아서 해동제국기를 지어 올렸다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 22, '다음 상황이 벌어진 전쟁 중에 있었던 사실로 옳은 것은?', 2, '정봉수가 용골산성에서 항쟁하였다.', '김준룡이 광교산 전투에서 승리하였다.', '김종서가 두만강 일대에 6진을 개척하였다.', '권율이 행주산성에서 적군을 크게 물리쳤다.', '이종무가 적의 근거지인 대마도를 정벌하였다.', 4, '지난 10월 5일에 적이 1만 명을 셋으로 나누어 곧바로 진주를 침범하였습니다. …… 김시민이 직접 전투를 독려하였는데, 철환이 그의 이마를 맞추니 성안이 소란해졌습니다. 적이 북문을 5~6척이나 뚫고 그곳으로부터 들어오려고 할 때 이광악이 다시 여러 장수들을 독려하여 화살을 쏘고 돌을 던졌습니다. 적이 개미처럼 붙어 올라오므로 불을 밝혀 끓는 물을 쏟고 혹은 진천뢰를 발사하니 죽은 자의 숫자를 헤아릴 수가 없었습니다.', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 23, '다음 상황이 나타난 시기를 연표에서 옳게 고른 것은?', 3, '(가)', '(나)', '(다)', '(라)', '(마)', 1, '청의 차사 한거원이 도성에 들어왔다. 임금이 편전에서 접견할 적에 대신들을 또한 입시(入侍)하였는데, 한거원이 예부의 외교 문서를 바쳤다. 문서에 이르기를, ''조선에서 조총을 잘 쏘는 사람 1백 명을 선발하여, 회령부를 경유해 가서 청의 대장군에게 통솔을 받아 나선(羅禪)을 정벌하되, 3월 10일에 영고탑에 도착하시오.''라고 하였다. [연표] 인조반정 - (가) - 경신환국 - (나) - 이인좌의 난 - (다) - 장용영 창설 - (라) - 홍경래의 난 - (마) - 병인양요', '조선', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 24, '밑줄 그은 ''왕''에 대한 설명으로 옳은 것은?', 1, '연잉군을 왕세제로 책봉하였다.', '청과 국경을 정한 백두산정계비를 세웠다.', '삼수병으로 구성된 훈련도감을 창설하였다.', '탕평 교서를 반포하고 탕평비를 건립하였다.', '문신을 재교육하기 위한 초계문신제를 시행하였다.', 5, '문학으로 보는 한국사 - [시] 배들을 부르니 빗살처럼 잇대 와서 / 원앙처럼 떼 지어 비늘처럼 늘어섰네 / 처음엔 조각조각 하나씩 흩어져 있더니 / 점차 구슬을 꿴 것처럼 잇대어 붙었네 / 일흔 일곱의 온갖 꽃배 늘어서서 / 밀려오는 물결 그 아래에 잠잠하네. [해설] 이 작품은 이헌경이 지은 「부교행(浮橋行)」의 일부로, 배다리의 완성을 기념하여 왕에게 지어 올린 시이다. 당시 배다리는 왕이 아버지 사도세자의 묘소를 수원부로 옮겨 현륭원을 조성할 때, 영여(靈轝)*가 안정적으로 한강을 건널 수 있도록 만들어졌다. *영여(靈轝): 혼백과 신주를 모시고 다니는 작은 가마', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 25, '다음 대화가 이루어진 시기의 경제 상황으로 적절하지 않은 것은?', 2, '활구라고 불리는 은병이 주조되었다.', '관청에 물품을 조달하는 공인이 활동하였다.', '송상, 만상이 대청 무역으로 부를 축적하였다.', '보부상이 장시를 돌아다니며 상품을 판매하였다.', '설점수세제의 시행으로 민간의 광산 개발이 허용되었다.', 1, '근래 전황(錢荒)이 매우 심합니다. 십전통보를 만들어 상평통보와 함께 유통시키면 관청과 민간 양쪽 모두 편리할 것입니다. / 그리하도록 하라.', '조선', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 26, '(가) 인물의 작품으로 옳은 것은?', 1, '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', '[IMAGE]', 5, '불이선란도(不二禪蘭圖) - 이 작품은 (가)이/가 자신의 서예 필법으로 글씨 쓰듯이 그린 것이다. 그림 속 글과 도장을 통해 그의 예술 세계와 소장자 변동 등을 확인할 수 있다. (가)은/는 독특한 제주도 유배 시절을 견디내며 추사체라는 독창적 서체를 남겼다.', '조선', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 27, '다음 자료에 나타난 시기의 사회 모습으로 가장 적절한 것은?', 2, '최충이 9재 학당을 설립하였다.', '서얼이 통청 운동을 전개하였다.', '변발과 호복이 지배층을 중심으로 유행하였다.', '망이·망소이의 난 등 하층민의 봉기가 발생하였다.', '질병에 대한 처방 등을 소개한 향약구급방이 편찬되었다.', 2, '향전은 통렬히 금해야 할 일이다. …… 그들이 향임의 권한을 빙자하여 함부로 날뛰는 조짐이 없었다면 해당 수령이 어찌 이와 같이 처결하였겠는가. …… 해당 군현 유생을 거듭 타일러서 각각 구습을 통렬히 혁파하고 기필코 화합하게 하라. 이와 같이 하교한 뒤에도 구향과 신향을 막론하고 본읍 유생의 일로 상언한다면, 이는 국법을 어지럽히는 백성이니 유생으로 대우할 수 없다. 따라서 중죄를 적용하여 단연코 용서하지 않을 것이니, 일체 엄히 경계하게 하라.', '조선', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 28, '(가) 조약에 대한 설명으로 옳은 것은?', 2, '천주교 포교 허용의 근거가 되었다.', '일본 측의 해안 측량권을 인정하였다.', '최혜국 대우를 규정한 조항을 담고 있다.', '일본 공사관의 경비병 주둔을 명시하였다.', '외국 상인의 내지 통상권을 최초로 규정하였다.', 2, '이달의 소장 유물 - 이 책은 부산에서 감리서 서기 등으로 일했던 민건호의 일기이다. 감리서는 개항장의 행정과 대외 관계 사무를 관장하는 기구로, 운요호 사건을 빌미로 (가)이/가 체결된 이후 부산 등의 개항장에 설치되었다. 『해은일록』에는 (가) 체결 이후 변화한 개항장 부산의 모습이 담겨 있다. [해은일록]', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 29, '(가) 사건에 대한 설명으로 옳은 것은?', 2, '한성 조약이 체결되는 계기가 되었다.', '외규장각 도서가 약탈되는 결과를 가져왔다.', '제너럴 셔먼호 사건이 발단이 되어 일어났다.', '전개 과정에서 흥선 대원군이 청에 납치되었다.', '홍범 14조를 개혁의 기본 방향으로 제시하였다.', 1, '답사 안내문 - 주제: (가)의 현장을 찾아서. 일시: 2026년 ??월 ??일 09:00~15:00. 개관: 김옥균을 비롯한 급진 개화파가 주도하여 일으킨 사건의 현장을 걷는 일정입니다. 경로: 우정총국 → 일본 공사관 터 → 경우궁 터 → 창덕궁 관물헌', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 30, '(가)~(마)에 들어갈 내용으로 가장 적절한 것은?', 3, '(가) - 신민회가 민족 교육을 실시하다', '(나) - 관민이 합심하여 세우다', '(다) - 교육 입국 조서 반포를 계기로 설립되다', '(라) - 최초의 여성 교육 기관으로 건립되다', '(마) - 통역관 양성을 위해 설치되다', 2, '모둠별 과제 안내 - 개항 이후 설립된 근대 교육 기관을 주제로 보고서를 작성한 후 제목과 함께 게시판에 올려 주세요. 번호/제목: 1모둠 - 동문학, (가) / 2모둠 - 원산 학사, (나) / 3모둠 - 이화 학당, (다) / 4모둠 - 오산 학교, (라) / 5모둠 - 한성 사범 학교, (마)', '근대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 31, '다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?', 2, '삼국 간섭이 발생한 원인을 분석한다.', '삼정이정청이 설치된 목적을 살펴본다.', '황국 중앙 총상회가 설립된 배경을 파악한다.', '재정 고문 메가타가 주도한 정책을 찾아본다.', '조미 수호 통상 조약이 체결되는 과정을 조사한다.', 4, '오는 7월 1일부터 경성 화폐교환소에서 구 백동화 교환 사무를 시작하니, 혼잡을 예방하고 서로의 편의를 도모하기 위하여 청원 방법을 다음과 같이 정하였다. 교환을 청구하고자 하는 자는 이 뜻을 준수하도록 한다. 광무 9년 6월 29일 탁지부 대신. 제1항 구 백동화 교환을 청구하고자 하는 자는 미리 제1호 서식의 청원서에 교환하고자 하는 액수와 청원인의 거주지·성명 및 청원 연·월·일을 기입하여 탁지부 내 화폐교환소에 제출하도록 한다. 제4항 제1항의 청원은 1일 1인에 대하여 교환 청구액이 1천 원 이상 1만 원 이하여야 한다. 단, 금년 10월 1일 이후에는 1천 원 이하인 자라도 청원할 수 있다.', '근대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 32, '다음 자료가 작성된 이후에 전개된 사실로 옳은 것은?', 2, '농민군이 황토현에서 관군에 승리하였다.', '개혁을 추진하기 위해 교정청이 설치되었다.', '남접과 북접의 농민군이 논산에 집결하였다.', '교조 신원을 요구하는 삼례 집회가 개최되었다.', '조병갑의 폭정에 항거하여 군민들이 관아를 습격하였다.', 3, '무주 집강소 - 지난달 일본군이 경복궁을 침범하였으며, 임금께서 욕을 당하셨다. …… 일본군이 바야흐로 청군과 서로 대적하여 싸우는데, 매우 날래고 민첩하다. 지금 만약 [우리가] 섣불리 맞서 싸우게 되면 그 화는 예측할 수 없어서 종사에 미칠 수 있을 듯하다. …… 시세를 본 후에 기운을 북돋아 주어 계획을 실천한다면 만전을 기하는 대책이 될 것이다. 좌우도 도집강', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 33, '다음 상황의 배경으로 가장 적절한 것은?', 2, '미쓰야 협정이 체결되었다.', '대한 제국의 군대가 해산되었다.', '영국이 거문도를 불법으로 점령하였다.', '데라우치가 초대 총독으로 부임하였다.', '기유각서가 체결되어 사법권을 박탈당하였다.', 2, '이인영이 3진(陣)의 장수로서 전국에 격문을 띄워 의병을 모집하였다. …… 허위와 이강년의 부대를 포함하여 총 48개 진, 약 1만 명에 달하는 병력을 갖추게 되었다. 이에 허위를 군사장으로 삼고 …… 서울에 들어가고자 하였다.', '근대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 34, '밑줄 그은 ''신문''에 대한 설명으로 옳은 것은?', 1, '브나로드 운동을 주도하였다.', '천도교의 기관지로 발행되었다.', '상업 광고를 처음으로 게재하였다.', '국채 보상 운동의 확산에 기여하였다.', '순한글판으로 발행된 최초의 신문이었다.', 4, '베델과 양기탁이 함께 창간한 신문에 대해 말해 보자. / 영국인이 발행인이라 상대적으로 일제의 간섭에서 자유로웠어. / 그렇기 때문에 일제의 침략상을 상세히 보도할 수 있었지.', '근대', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 35, '(가) 인물의 활동으로 옳은 것은?', 3, '대한 광복회를 조직하여 친일파를 처단하였다.', '일본의 침략 과정을 담은 한국통사를 저술하였다.', '대한민국 임시 정부에서 내무총장으로 활동하였다.', '의열단의 활동 지침인 조선 혁명 선언을 작성하였다.', '헤이그에서 열린 만국 평화 회의에 특사로 파견되었다.', 3, '한인족문화사전 - [메뉴: 소개, 확대, 이용안내] 분류: 북미. 시대: 조선, 근현대, 현대. (가) 메모리얼 인터체인지 - 2002년 미주 한인 이민 100주년을 맞아 LA 코리아타운 인근 고속 도로 인터체인지에 붙여진 이름이다. 한국, 중국, 미국 등을 오가며 독립운동에 헌신한 (가)은/는 샌프란시스코에서 공립 협회, 흥사단 등의 설립을 주도하고 대한민국 국민회 중앙총회장에 취임하였다. 그의 활동은 독립운동뿐만 아니라 한인이 미국 사회에 정착하는 데 크게 기여하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 36, '밑줄 그은 ''시기''에 있었던 사실로 옳은 것은?', 1, '헌병 경찰제가 실시되었다.', '치안 유지법이 제정되었다.', '친위대와 진위대가 설치되었다.', '조선 여성 동우회가 창립되었다.', '조선 사상범 예방 구금령이 시행되었다.', 1, '일제가 임시 토지 조사국을 설치하고 토지 조사 사업을 시행하던 시기에 작성된 지적원도, 토지 조사부 등을 공개하는 온라인 서비스가 시작됩니다. 토지 조사부는 당시의 지번, 토지 소유자 주소 및 성명 등이 기재된 문서로 조상 찾기, 학술 연구 등에 적극 활용될 것으로 기대됩니다. [토지 관련 기록물 온라인 서비스 개시]', '일제강점기', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 37, '다음 판결 이후에 있었던 사실로 옳은 것은?', 3, '지계아문이 설치되어 지계가 발급되었다.', '회사 설립을 허가제로 하는 회사령이 제정되었다.', '전국 단위 조직인 조선 농민 총동맹이 결성되었다.', '일본의 토지 침탈에 맞서 농광 회사가 설립되었다.', '경복궁에서 최초로 조선 물산 공진회가 개최되었다.', 3, '판결문 - 피고: 서태석. 주문: 피고 서태석을 징역 2년에 처한다. 이유: 피고 서태석은 전라남도 무안군 암태면의 지주 가운데 특히 문재철의 부친이자 그 토지 관리인인 문태현이 고율의 소작료를 징수하는 데 분개하였다. 이에 피고 서창석과 공모하여 불평 소작인들을 규합해 2년 전 암태소작인회라는 것을 조직하고 …… 소작료를 논 4할, 밭 3할로 저감하게 할 것, 그 요구를 수용하지 않을 때는 소작료 불납 동맹 및 폐경 동맹을 감행하고 문태현을 위해 건립된 송덕비를 넘어뜨릴 것을 논의하였다. …… 지난해 피고는 동지들과 함께 문태현을 방문하여 소작료 저감에 관한 확답을 구했지만 실패하자 송덕비를 넘어뜨렸다.', '일제강점기', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 38, '밑줄 그은 ''운동''에 대한 설명으로 옳은 것은?', 2, '김광제 등의 발의로 본격화되었다.', '보국안민, 제폭구민을 기치로 내걸었다.', '전개 과정에서 일제가 제암리 학살 등을 자행하였다.', '민족 협동 전선 단체인 신간회 결성에 영향을 끼쳤다.', '한국인 학생과 일본인 학생 간의 충돌에서 비롯되었다.', 4, '□□ 신문 - 만세를 외치기까지의 경과. 지난 6일에 모종의 계획이 발각된 이후, 이선호는 수 명의 동지를 규합하여 격문을 인쇄한 후 먼저 각 학교에 뿌려 학생들에게 독립운동의 기분을 고취하고자 하였다. 그러던 중 이선호는 경성 제국 대학의 이천진, 연희 전문 학교의 홍명식·권오상과 함께 이왕(李王) 전하의 국장일에 만세를 외치며 운동을 시작한 것이다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 39, '다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?', 2, '보안회의 활동 내용을 분석한다.', '조선 형평사의 창립 목적을 파악한다.', '군국기무처가 설치된 계기를 찾아본다.', '전주 화약이 체결되는 과정을 알아본다.', '대한 자강회가 해산된 배경을 조사한다.', 2, '백정 계급의 주위를 포위하고 이를 압박하는 계급은 결코 양반 계급의 그것뿐이 아니요. [백정 계급은] 중인 계급에게도 능욕과 천대를 받는 것이며, 오늘날 사회 제도의 결함으로부터 발생한 모든 계급(민족적 우월 계급, 경제적 우월 계급)에게 압박과 착취를 당하는 자이다. 한과 원망이 가슴에 차고 설움과 눈물이 거듭하여 어리석은 고식적 보수에 잠자오던 백정 계급은 원래의 무지와 전통을 버리고 모름지기 저 화염 속으로 그들의 이상을 관철하여야 할 것이며, 이러한 역사적 사명을 갖고 있는 것이 아닌가. -『척후대』-', '일제강점기', '사회', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 40, '밑줄 그은 ''이 시기''에 볼 수 있는 모습으로 가장 적절한 것은?', 2, '원산 총파업에 참여하는 노동자', '105인 사건으로 검거되는 애국지사', '근우회 창립 총회에서 취재하는 기자', '황국 신민 서사 암송을 강요받는 학생', '태화관에서 독립 선언식을 거행하는 민족 대표', 4, '가장 경제적이요, 활동적인 국민 표준복과 청년단복의 구매는 조선 총독부 교화 단체 연합회 및 국민 정신 총동원 조선 연맹이 지정한 화신(和信)으로! 이것은 국민 표준복과 청년단복을 홍보하는 광고이다. 일제는 국가 총동원법 제정 이후 침략 전쟁을 확대하던 이 시기에 전시 생활 체제를 강조하며 복장을 통제하고자 하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 41, '(가) 단체의 활동으로 옳은 것은?', 2, '학술지로 진단 학보를 발행하였다.', '가갸날을 제정하고 기념식을 진행하였다.', '태극 서관을 설립하여 서적을 보급하였다.', '주시경, 지석영 등이 중심이 되어 활동하였다.', '영은문이 있던 자리 부근에 독립문을 건립하였다.', 2, '이것은 이극로가 1928년 소르본 대학에서 조선의 문자와 말소리 등에 대해 녹음하고 작성한 기록 카드입니다. 이때 녹음된 음성을 통해 100여 년 전 한국어 발음과 표현을 확인할 수 있습니다. 이극로는 이듬해 고국으로 돌아와 조선어 학회의 전신인 (가)에 가입하고 한글 수호 운동을 이어 나갔습니다. [녹음 날짜: 1928.5.15. / 성명: 이극로 / 녹음 내용: 조선의 문자와 말소리]', '일제강점기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 42, '(가) 부대에 대한 설명으로 옳은 것은?', 2, '대원 일부가 한국광복군에 합류하였다.', '청산리에서 일본군에 맞서 승리를 거두었다.', '동북 항일 연군으로 개편되어 유격전을 펼쳤다.', '대전자령 전투에서 한중 연합 작전을 전개하였다.', '조선 혁명당의 군사 조직으로 남만주 지역에서 활약하였다.', 1, '이것은 (가)이/가 3·1 운동 20주년을 기념하여 창작한 연극 「조선의 여아(女兒)」의 공연 사진입니다. (가)은/는 김원봉의 주도로 중국 우한(武漢)에서 결성한 한인 부대로, 다양한 선전 활동을 전개하였으며 연극은 그 핵심 수단 중 하나였다. 일제의 압박과 착취에 신음하는 우리 민족의 고통과 저항을 담은 「조선의 여아」는 한국인과 중국인 관객들의 공감을 이끌어 내 항일 투쟁의 의지를 높이는 데 기여하였다.', '일제강점기', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 43, '교사의 질문에 대한 학생의 답변으로 적절하지 않은 것은?', 2, '텔레비전 방송이 시작되었어요.', '화학조미료를 활용한 요리법이 확산되었어요.', '새로운 주택 양식인 문화 주택이 등장하였어요.', '단성사에서 영화 임자 없는 나룻배가 상영되었어요.', '근대적 생활 양식을 받아들인 모던 걸, 모던 보이가 늘어났어요.', 1, '이것은 경성 미쓰코시 백화점의 신관 개점을 알리는 광고입니다. 당시 개점한 미쓰코시 백화점은 지하 1층부터 지상 4층까지 각종 매장을 두고, 그 위로는 옥상 정원과 결라리, 전망대를 갖춘 문화 공간이었습니다. 이처럼 일제 강점기에는 백화점 등 근대적 소비·문화 시설이 들어서면서 도시를 중심으로 의식주에 변화가 나타나고 대중문화도 확산되었습니다. 당시 달라진 사회·문화 현상에 대해 말해 볼까요? [경성 미쓰코시 신관 낙성 내일 아침 9시 개점]', '일제강점기', '문화', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 44, '(가) 선거에 대한 설명으로 옳은 것은?', 2, '6·3 시위 이후에 실시되었다.', '발췌 개헌에 따라 이루어졌다.', '신한 민주당이 제1 야당이 되는 결과를 가져왔다.', '통일 주체 국민 회의의 대의원이 투표에 참여하였다.', '김구, 김규식 등이 단독 정부 수립에 반대하며 불참하였다.', 5, '노래에 담긴 한국사 - 총선거의 노래. (1절) 이해의 국민 경사는 자유의 총선거 날로 국민은 새 결심으로 다 같이 투표합시다. 세계의 참된 평화는 조선의 독립이라오, 평화를 희망하는 이 나와서 투표합시다. (2절) 선거는 국민 경사여 투표는 남녀의 동권(同權)이라, 국민은 총진(總進)하여 다 같이 투표합시다. [해설] 이 노래는 유엔 한국 임시 위원단의 감시하에 실시된 (가)의 투표를 독려하기 위해 만들어졌다. (가)은/는 21세 이상의 국민에게 선거권이 부여된 우리나라 최초의 보통 선거로, 95.5%에 달하는 투표율을 기록하였다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 45, '밑줄 그은 ''이 전쟁'' 중에 있었던 사실로 옳은 것은?', 1, '애치슨 라인이 발표되었다.', '한미 상호 방위 조약이 체결되었다.', '여수·순천 10·19 사건이 발생하였다.', '모스크바 3국 외상 회의가 개최되었다.', '흥남에서 대규모 철수 작전이 전개되었다.', 5, '제 뒤로 보이는 장사 상륙 작전 전승 기념관은 작전 당시에 투입된 문산호를 재현하여 바다 위에 건립되었습니다. 이 전쟁 중 국군과 유엔군은 동해안 장사리에 상륙 작전을 전개하여 북한군을 교란하고 전력을 분산시키고자 했습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 46, '(가) 민주화 운동에 대한 설명으로 옳은 것은?', 2, '긴급 조치 철폐를 요구하였다.', '장면 내각이 출범하는 계기가 되었다.', '신군부의 계엄 확대에 반발하여 일어났다.', '야당 총재의 국회의원직 제명에 반대하였다.', '5년 단임의 대통령 직선제 개헌을 이끌어 냈다.', 2, '(가) 민주묘지 - 이용안내, 온라인추모, 알림마당, 참여마당. 독재와 3·15 부정 선거에 맞서 민주주의를 지키려 한 민주 영령의 추모의 글을 남기는 공간입니다. 온라인추모 소개, 개인묘역참배부, 하늘편지. 김주열 민주 열사에게 드리는 하늘편지 - 불의에 항거한 용기와 민주주의를 위한 희생에 존경을 표합니다. 부디 그곳은 고통 없는 안식처가 되길 바랍니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 47, '(가) 정부 시기의 경제 상황으로 적절하지 않은 것은?', 1, '포항 제철소 1기 설비가 착공되었다.', '국민 기초 생활 보장법이 제정되었다.', '마산이 수출 자유 지역으로 지정되었다.', '베트남 전쟁 파병에 따른 특수를 누렸다.', '제2차 경제 개발 5개년 계획이 추진되었다.', 2, '이것은 (가) 정부 당시 건설부 등이 경부 고속 도로 전 구간 개통일에 게재한 신문 광고입니다. ''뻗어가는 국력을 상징하며 조국의 중심부를 힘차게 달린다!''라는 문구가 적혀 있습니다. 경부 고속 도로 전 구간 개통일인 7월 7일은 현재 도로의 날로 지정되어 있습니다.', '현대', '경제', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 48, '밑줄 그은 ''현행 헌법''에 대한 설명으로 옳은 것은?', 3, '사사오입의 논리로 통과되었다.', '대통령의 3선 연임을 허용하였다.', '3·1 민주 구국 선언에 영향을 주었다.', '민의원과 참의원의 양원제 국회를 명시하였다.', '대통령 선거인단에 의한 간선제를 규정하였다.', 5, '대통령이 개헌은 불가능하며 현행 헌법에 따라 정부를 이양하겠다고 발표하였군. / 평화적인 정부 이양과 서울 올림픽 대회의 성공적 개최를 명분으로 내세웠지만, 결국 시민들의 기대를 외면한 것 같네.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 49, '다음 연설문을 발표한 정부의 통일 노력으로 옳은 것은?', 2, '7·4 남북 공동 성명을 발표하였다.', '평양에서 남북 정상 회담을 개최하였다.', '남북한이 국제 연합(UN)에 동시 가입하였다.', '남북 이산가족의 고향 방문을 최초로 성사시켰다.', '평창 동계 올림픽 대회에서 남북 단일팀을 구성하였다.', 2, '지난해 9·11 테러 이후 전 세계가 불안에 휩싸였지만, 한반도에서는 안정이 유지되었습니다. 이산가족의 상봉과 금강산 관광, 민간의 교류 확대가 이루어졌습니다. …… 그리고 정부는 그러한 노력을 햇볕 정책의 이름으로 실천해 온 것입니다. 한반도의 평화와 안정이 있었기에 외국인 투자도 들어오고, 우리 경제의 경쟁력도 높아졌으며, 월드컵도 안심하고 치를 수 있었던 것입니다. …… 아시안 게임은 우리에게 월드컵 못지않은 중요한 기회입니다. 행사 준비는 물론 안전 대책에 만전을 기하면서, 특히 이번 아시안 게임이 남북 화해의 마당으로 승화되도록 하겠습니다.', '현대', '정치', 0);
INSERT INTO HIST_EXAM_QUESTIONS (EXAM_ROUND, Q_NO, Q_TEXT, POINT, CHOICE1, CHOICE2, CHOICE3, CHOICE4, CHOICE5, ANSWER, Q_PASSAGE, ERA, CATEGORY, IS_DELETED) VALUES (78, 50, '(가) 지역에서 있었던 사실로 옳은 것은?', 2, '신립이 배수의 진을 치고 왜군과 싸웠다.', '학생들이 2·28 민주 운동을 주도하였다.', '김사미가 가혹한 수탈에 맞서 봉기하였다.', 'YH 무역 노동자들이 폐업에 항의하며 농성을 벌였다.', '박재혁이 경찰서에서 폭탄을 터뜨리는 의거를 일으켰다.', 5, '우리 학회는 지역사를 통해 한국사를 이해하는 교양 강좌를 운영하고 있습니다. 이번 달에는 ''(가)의 역사''를 주제로 자리를 마련하였으니, 시민 여러분의 많은 관심과 적극적인 참여를 바랍니다. 강의 주제: [제1강] 범어사와 불교문화 [제2강] 동래성 전투와 임진왜란 [제3강] 초량 왜관과 일본과의 무역 [제4강] 안희제의 백산 상회와 독립운동. 일시: 2026년 5월 매주 금요일 16시. 장소: ?? 기념관. 주관: △△ 사학회', '복합', '지역사', 0);
